// rust home: crates/compiler/deeptools/src/transform/sentient/address_pinning_and_toggle/mod.rs
// ------------------------------------------------------------------------------------------------
Value e009_createOffsetValue(Operation *curr_op, const EvaluatedValue &ev) const
{
    auto unit = curr_op->getParentOfType<dataflow::ProgramUnitOp>();
    auto parent_func = dyn_cast<func::FuncOp>(unit->getParentOp());
    DT_CHECK(parent_func);
    OpBuilder const_builder(parent_func.getBody());

    // Create QueryMapOps/DefImmutableMappingOps at the start of the curr_op's
    // parent uniformize/program_unit region.
    Region *region = dcc::uniform::utils::getLocalOrGlobalRegion(curr_op);
    OpBuilder query_map_builder(region);
    return ev.buildOffsetValue(const_builder, query_map_builder,
                               dtd_.getOperation().getLoc(),
                               mutable_addr_[0].get().getType());
  }

