// entry 016/656   level 0   scc 52   32 body lines
// unit: e016_ConditionalConstantDescriptor
// authority: dcc/src/Transform/Sentient/AddressPinningAndToggle.cpp:2744
// original: ConditionalConstantDescriptor::ConditionalConstantDescriptor( ExpressionEvaluator &evaluator, Value base_addr) : DynamicPatternDescriptorBase(PatternKind::kConditionalConstant, evaluator)
// rust home: crates/compiler/deeptools/src/transform/sentient/address_pinning_and_toggle/conditional_constant_descriptor.rs
// ------------------------------------------------------------------------------------------------
e016_ConditionalConstantDescriptor(
    ExpressionEvaluator &evaluator, Value base_addr)
    : DynamicPatternDescriptorBase(PatternKind::kConditionalConstant,
                                   evaluator)
{
  // Attempt to analyze the conditional structure returning a variety of
  // constants.
  DT_CHECK(yielded_constants_.empty());
  // For each yield save its operation pointer and result index
  std::vector<std::pair<Operation *, int>> yields;
  int result_index = dcc::utils::getIndexOfOperationResults(base_addr);
  auto if_op = dyn_cast<sentient::IfOp>(base_addr.getDefiningOp());
  if (!if_op) return;

  bool all_yield_operands_constant = true;
  dcc::utils::applyToAllYields<sentient::IfOp>(
      if_op,
      [&](Operation *yield, int index) {
        Value operand = yield->getOperand(index);
        if (dcc::utils::isConstant<sentient::ConstantOp>(operand)) {
          yielded_constants_.push_back(&evaluator_.evaluateValue(operand));
        } else {
          all_yield_operands_constant = false;
        }
      },
      result_index);

  // Invalidate if some yield operands are not constants.
  if (!all_yield_operands_constant) yielded_constants_.clear();

  if (yielded_constants_.empty()) return;
  const EvaluatedValue &first_const_ev = *yielded_constants_.front();
  setCanBeSimplified(all_of(yielded_constants_, [&](const EvaluatedValue *ev) {
    return *ev == first_const_ev;
  }));
}

