// authority: dcc/src/Transform/Sentient/AddressPinningAndToggle.cpp:2968
// original: std::tuple<sentient::ForOp, int, const EvaluatedValue *, const EvaluatedValue *> DiscreteIntegerSetDescriptor::getOutermostConstInitialization( BlockArgument iter_arg)
// rust home: crates/compiler/deeptools/src/transform/sentient/address_pinning_and_toggle/discrete_integer_set_descriptor.rs
// ------------------------------------------------------------------------------------------------
std::tuple<sentient::ForOp, int, const EvaluatedValue *, const EvaluatedValue *>
e017_getOutermostConstInitialization(
    BlockArgument iter_arg)
{
  // Iterator argument initializations may be chained, eg:
  //
  // %a:2 = sentient.for ... iter_args(%argM = %X, ...)
  //   %b:3 = sentient.for ... iter_args(..., %argN = %argM, ...)
  //     %c:2 = sentient.for ... iter_args(%argO = %argN, ...) {
  //       ...
  //       %add_c = scalar_add %argO, %w
  //       yield %add_c, ...
  //     }
  //     %add_b = scalar_add %argN, %v
  //     yield ..., %add_b, ...
  //   }
  //   %add_a = scalar_add %argM, %u
  //   yield %add_a, ...
  // }
  //
  int iter_arg_index = -1;
  BlockArgument cur_iter_arg = iter_arg;
  sentient::ForOp outer_loop;
  const EvaluatedValue *total_positive_delta = nullptr;
  const EvaluatedValue *total_negative_delta = nullptr;
  // Search from inner to outer loop
  while (iter_arg_index < 0 && cur_iter_arg) {
    int curr_it_index = dcc::utils::getIndexOfLoopRegionIterArgs(cur_iter_arg);
    Operation *outer_loop_op = cur_iter_arg.getOwner()->getParentOp();
    outer_loop = dyn_cast<sentient::ForOp>(outer_loop_op);
    int bound = 0;
    const EvaluatedValue *stride = nullptr;
    if (auto const_bound = llvm::dyn_cast_or_null<sentient::ConstantOp>(
            outer_loop.getBound().getDefiningOp())) {
      bound = const_bound.getValue();
      if (bound <= 0) {
        // dead load/stores?
        DEBUG_WITH_TYPE(VerboseDebug,
                        llvm::dbgs()
                            << "Size of discrete integer set is zero!\n");
        return std::make_tuple(nullptr, -1, nullptr, nullptr);
      }
    } else {
      DEBUG_WITH_TYPE(VerboseDebug,
                      llvm::dbgs()
                          << "Not a constant discrete integer set because "
                             "loop bound isn't constant!\n");
      return std::make_tuple(nullptr, -1, nullptr, nullptr);
    }

    // Find the sequence stride.
    Operation *add_feeding_yield =
        dcc::utils::getIterArgIncrementer<sentient::ForOp, sentient::AddOp>(
            outer_loop_op, curr_it_index);
    bool match_found = false;
    if (add_feeding_yield && dcc::utils::isConstant<sentient::ConstantOp>(
                                 add_feeding_yield->getOperand(1))) {
      stride = &evaluator_.evaluateValue(add_feeding_yield->getOperand(1));
    } else {
      DEBUG_WITH_TYPE(VerboseDebug,
                      llvm::dbgs()
                          << "Not a const discrete integer set because "
                             "stride is not computable!\n");
      return std::make_tuple(nullptr, -1, nullptr, nullptr);
    }

    // The value changes by stride * (bound-1) across the iterations of the
    // current loop.
    const EvaluatedValue &cur_loop_delta =
        evaluator_.evaluateMultiplyByConst(*stride, bound - 1);
    // Separate the positive/negative per unit deltas by taking the
    // maximum/minimum with 0. More precisely, we write
    /// cur_loop_delta = cur_loop_positive_delta + cur_loop_negative_delta
    // where cur_loop_positive_delta >= 0 and cur_loop_negative_delta <= 0
    // (per unit).
    const EvaluatedValue &zero = evaluator_.getConstant(0);
    const EvaluatedValue &cur_loop_positive_delta = evaluator_.evaluateMinMax(
        {&cur_loop_delta, &zero}, /*compute_min*/ false);
    const EvaluatedValue &cur_loop_negative_delta = evaluator_.evaluateMinMax(
        {&cur_loop_delta, &zero}, /*compute_min*/ true);

    // Increment total_positive_delta/total_negative_delta by these
    // positive/negative deltas.
    if (!total_positive_delta && !total_negative_delta) {
      total_positive_delta = &cur_loop_positive_delta;
      total_negative_delta = &cur_loop_negative_delta;
    } else {
      total_positive_delta = &evaluator_.evaluateSum(*total_positive_delta,
                                                     cur_loop_positive_delta);
      total_negative_delta = &evaluator_.evaluateSum(*total_negative_delta,
                                                     cur_loop_negative_delta);
    }

    int num_non_yield_feeding_uses =
        dcc::utils::getNumUsersExcept(cur_iter_arg, [&](Operation *op) {
          return isa<sentient::YieldOp>(op) || op == add_feeding_yield;
        });
    DT_CHECK_MSG(
        num_non_yield_feeding_uses == 1,
        "base_addr should only be used in memory op and to feed the yield "
        "op");
    Value curr_init = outer_loop.getIterOperands()[curr_it_index];
    cur_iter_arg = dyn_cast<BlockArgument>(curr_init);
    if (!cur_iter_arg &&
        dcc::utils::isConstant<sentient::ConstantOp>(curr_init))
      iter_arg_index = curr_it_index;
  }
  return std::make_tuple(outer_loop, iter_arg_index, total_positive_delta,
                         total_negative_delta);
}

