// rust home: crates/compiler/deeptools/src/transform/sentient/address_register_precision_assignment/mod.rs
// ------------------------------------------------------------------------------------------------
void e019_initializePrecision(
    Operation *op)
{
  int size = op->getNumResults();
  if (auto for_op = llvm::dyn_cast<sentient::ForOp>(op)) {
    size += (1 + for_op.getNumRegionIterArgs());
  }

  auto &assigns = assignments_[op];
  for (int i = 0; i < size; i++) {
    assigns.push_back(-1);
  }
}

