// entry 021/656   level 0   scc 106   47 body lines
// unit: e021_splitBurst
// authority: dcc/src/Transform/Sentient/BurstSplitting.cpp:112
// original: LogicalResult splitBurst(dataflow::ProgramUnitOp &unit, Operation *op, SenComponents comp)
// rust home: crates/compiler/deeptools/src/transform/sentient/burst_splitting/mod.rs
// ------------------------------------------------------------------------------------------------
LogicalResult e021_splitBurst(dataflow::ProgramUnitOp &unit, Operation *op,
                           SenComponents comp)
{
    DT_CHECK((isa<sentient::LoadAndSendOp>(op) ||
              isa<sentient::ReceiveAndStoreOp>(op) ||
              isa<sentient::LoadAndStoreOp>(op)) &&
             "Unsupported operation for burst splitting");

    // Burst splitting is guaranteed to impact IBuff so if there is no space,
    // bail out.
    InstructionEstimator &instruction_estimator =
        getChildAnalysis<InstructionEstimator>(unit);
    if (!instruction_estimator.haveIbuffSpace(dccExtContext(), unit))
      LLVM_DEBUG(llvm::dbgs()
                 << "[BurstSplittingPass][Warning] No IBuff remaining before "
                    "splitting the following op:\n"
                 << *op << "\n\n");

    int max_burst = getMaxBurstSize(unit);
    DT_CHECK_MSG(max_burst != -1, "Cannot determine max burst size!");

    int burst_size =
        mlir::cast<mlir::IntegerAttr>(op->getAttr("burst_size")).getInt();
    DT_CHECK_MSG(burst_size > max_burst,
                 "Expected burst_size to be larger than max_burst!");

    // If the number of full burst iterations is greater than 1, a ForOp is
    // required to split the burst.
    int required_ibuff = 0;
    if ((burst_size / max_burst) > 1) ++required_ibuff;
    // If there is a residual burst, an additional clone of the memory operation
    // is required to handle the remaining burst.
    if ((burst_size % max_burst) != 0) ++required_ibuff;

    auto remaining_ibuff =
        instruction_estimator.getRemainingIbuffSpace(dccExtContext(), unit);
    if (remaining_ibuff < required_ibuff)
      LLVM_DEBUG(llvm::dbgs()
                 << "[BurstSplittingPass][Warning] Burst splitting the "
                    "following op may overflow IBuff:\n"
                 << *op << "\n\n");

    // Split the burst.
    OpBuilder builder(op);
    builder.setInsertionPointAfter(op);
    SmallVector<Operation *> ops = {op};
    return dcc::burst_utils::processBurstSplitOrInterleave(
        builder, unit, comp, ops, max_burst, burst_loop_count_);
  }

// ------------------------------------------------------------------------------------------------
// entry 022/656   level 0   scc 110   27 body lines
// unit: e022_runOnOperation
// authority: dcc/src/Transform/Sentient/CFGDeepMerging.cpp:62
// original: void CFGDeepMergingPass::runOnOperation()
// rust home: crates/compiler/deeptools/src/transform/sentient/cfg_deep_merging/mod.rs
// ------------------------------------------------------------------------------------------------
void e022_runOnOperation()
{
  if (DisableThisPass) return;
  LLVM_DEBUG(llvm::dbgs() << "CFG Deep Merging Pass\n");
  ModuleOp module_op = getOperation();
  module_op.walk<WalkOrder::PreOrder>([&](dataflow::ProgramUnitOp unit_op) {
    Operation *unit = unit_op.getOperation();
    dcc::CFGDeepMergingConditionalTree tree(*unit);
    tree.compute();
    if (tree.empty()) return;
    LLVM_DEBUG(llvm::dbgs() << "Initial tree:\n");
    LLVM_DEBUG(tree.print(llvm::dbgs()));

    // Deeply merge sibling conditionals which yield values and whose
    // conditionals have no then/else blocks containing more than one
    // conditional. The latter criteria simplifies the merging.
    Operation *cur_if_op_analyzed = nullptr;
    int count = 0;
    do {
      cur_if_op_analyzed = tree.mergeConditionals(cur_if_op_analyzed);
      count++;
      DEBUG_WITH_TYPE(VerboseDebug, llvm::dbgs() << "Tree after one merge:\n");
      DEBUG_WITH_TYPE(VerboseDebug, tree.print(llvm::dbgs()));
    } while (cur_if_op_analyzed && count < MaxNumOfMerges);
    LLVM_DEBUG(llvm::dbgs() << "Tree after CFGDeepMerging Pass:\n");
    LLVM_DEBUG(tree.print(llvm::dbgs()));
  });
}

