// original: template <typename MapTy> void PatternSimplificationManager::populateTable( dcc::CFGSCondNode *n, MapTy &ivs_to_values_and_filters)
// rust home: crates/compiler/deeptools/src/transform/sentient/cfg_simplification_sentient_level/pattern_simplification_manager.rs
// ------------------------------------------------------------------------------------------------
template <typename MapTy>
void e031_populateTable(
    dcc::CFGSCondNode *n, MapTy &ivs_to_values_and_filters)
{
  Value iv = n->getLhs();
  dcc::WidestIntType rhs_val = n->getRhsVal();
  auto &tuple = lhs_to_for_op_or_null_[iv];
  dcc::WidestIntType num_iterations = std::get<4>(tuple);
  dcc::WidestIntType lb = std::get<1>(tuple);
  dcc::WidestIntType step = std::get<3>(tuple);
  DT_CHECK_MSG(step != 0, "Expect non-zero step.");
  dcc::WidestIntType idx = (rhs_val - lb) / step;

  bool is_idx_valid = idx >= 0 && idx < num_iterations;
  DT_CHECK_MSG((is_idx_valid || n->getThenNode()->isDead()),
               "Expect dead predicates to have been found already.");
  auto &iv_val_and_filter = ivs_to_values_and_filters[iv];

  // Does this iv already have a fixed value from an ancestor predicate?
  bool some_rhs_val_previously_chosen = iv_val_and_filter.first.has_value();

  // Has this value of the IV been disallowed by an ancestor predicate?
  bool this_rhs_val_previously_disallowed =
      is_idx_valid && iv_val_and_filter.second[idx];
  // Skip the true branch if either:
  // - This IV has a previous value different from the rhs value
  // - The rhs value has been previously disallowed
  // - The true branch has been marked as dead
  bool skip_true_branch = (some_rhs_val_previously_chosen &&
                           rhs_val != iv_val_and_filter.first.value()) ||
                          this_rhs_val_previously_disallowed ||
                          n->getThenNode()->isDead();
  // Skip the false branch if either:
  // - This IV is guaranteed to equal the rhs value
  // - The false branch has been marked as dead
  bool skip_false_branch = (some_rhs_val_previously_chosen &&
                            rhs_val == iv_val_and_filter.first.value()) ||
                           n->getElseNode()->isDead();

  if (skip_true_branch) {
    n->getOperation()->setAttr(DEAD_THEN_BRANCH,
                               const_builder_.getI32IntegerAttr(1));
  } else {
    // Process the TRUE subtree, updating iv_val_and_filter with the
    // assignment iv = rhs_val.
    auto orig_val = iv_val_and_filter.first;
    iv_val_and_filter.first = rhs_val;
    std::vector<dcc::WidestIntType> tuple_so_far;
    // If the child is a branch, recurse.
    // Otherwise process the leaf and note whether the leaf is dead.
    if (!n->getThenNode()->isLeaf())
      populateTable(n->getThenNode()->getFirstChild(),
                    ivs_to_values_and_filters);
    else if (!processLeaf<MapTy>(n->getThenNode(), ivs_to_values_and_filters,
                                 ivs_to_values_and_filters.begin(),
                                 tuple_so_far)) {
      n->getThenNode()->setAsDead();
      n->getOperation()->setAttr(DEAD_THEN_BRANCH,
                                 const_builder_.getI32IntegerAttr(1));
    }
    // Restore iv_val_and_filter.
    iv_val_and_filter.first = orig_val;
  }

  if (skip_false_branch) {
    n->getOperation()->setAttr(DEAD_ELSE_BRANCH,
                               const_builder_.getI32IntegerAttr(1));
  } else {
    // Process the FALSE subtree, updating iv_val_and_filter by marking
    // rhs_val as disallowed in the filter (if it has a valid index).
    bool orig_filter;
    if (is_idx_valid) {
      orig_filter = iv_val_and_filter.second[idx];
      iv_val_and_filter.second[idx] = true;
    }
    std::vector<dcc::WidestIntType> tuple_so_far;
    // If the child is a branch, recurse.
    // Otherwise process the leaf and note whether
    // the leaf is dead.
    if (!n->getElseNode()->isLeaf())
      populateTable(n->getElseNode()->getFirstChild(),
                    ivs_to_values_and_filters);
    else if (!processLeaf<MapTy>(n->getElseNode(), ivs_to_values_and_filters,
                                 ivs_to_values_and_filters.begin(),
                                 tuple_so_far)) {
      n->getElseNode()->setAsDead();
      n->getOperation()->setAttr(DEAD_ELSE_BRANCH,
                                 const_builder_.getI32IntegerAttr(1));
    }
    // Restore iv_val_and_filter.
    if (is_idx_valid) iv_val_and_filter.second[idx] = orig_filter;
  }
}

