// rust home: crates/compiler/deeptools/src/transform/sentient/cfg_simplification_sentient_level/pattern_simplification_manager.rs
// ------------------------------------------------------------------------------------------------
void e033_replaceResultByIterArg(Operation *for_op,
                                                          Value &replacement)
{
  for_op->walk([&](sentient::YieldOp yield_op) {
    if (yield_op->hasAttr(RESULT_TO_BE_REPLACED_BY_ITER_ARG)) {
      yield_op->removeAttr(RESULT_TO_BE_REPLACED_BY_ITER_ARG);
      yield_op->setOperand(0, replacement);
    }
  });
}

