// original: void CanonicalizeXRFPointersPass::replaceXRFImplicitIncrWithAdd( dataflow::ProgramUnitOp unit_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/canonicalize_xrf_pointers/mod.rs
// ------------------------------------------------------------------------------------------------
void e037_replaceXRFImplicitIncrWithAdd(
    dataflow::ProgramUnitOp unit_op)
{
  OpBuilder const_builder(unit_op);
  unit_op.walk<WalkOrder::PreOrder>([&](sentient::MacOp mac_op) {
    if (mac_op.isXrfWtRelated()) {
      DT_CHECK(mac_op->getNumResults() == 2);
      int unroll_factor = mac_op.getUnrollFactorVal();
      if (unroll_factor != mac_op.getXrfWriteIncrSigned()) {
        OpBuilder builder(mac_op);
        builder.setInsertionPointAfter(mac_op);
        auto const_increment = sentient::ConstantOp::create(
            const_builder, mac_op.getLoc(), const_builder.getIndexType(),
            mac_op.getXrfWriteIncrSigned() - unroll_factor);
        auto xrf_wrt_update = sentient::AddOp::create(
            builder, mac_op.getLoc(), builder.getIndexType(),
            mac_op.getResult(0), const_increment);
        xrf_wrt_update->setAttr(
            "regLocale", SentientRegTypeAttr::get(builder.getContext(),
                                                  SentientRegType::xrfwrptr));
        mac_op.setXrfWriteIncrAttr(
            IntegerAttr::get(mac_op.getXrfWriteIncrAttr().getType(),
                             mac_op.getUnrollFactorVal()));
        mac_op.getResult(0).replaceUsesWithIf(
            xrf_wrt_update, [&](mlir::OpOperand& operand) {
              return operand.getOwner() != xrf_wrt_update;
            });
      }
    }

    if (mac_op.isXrfRdRelated()) {
      DT_CHECK(mac_op->getNumResults() == 2);
      auto precision =
          stringifySentientPrecision(mac_op.getComputePrecision()).str();
      int required_xrf_read_incr_val =
          dccExtContext().getXrfRdPtrIncrValAfterMAC(precision);

      if (required_xrf_read_incr_val != mac_op.getXrfReadIncrSigned()) {
        OpBuilder builder(mac_op);
        builder.setInsertionPointAfter(mac_op);
        auto const_increment = sentient::ConstantOp::create(
            const_builder, mac_op.getLoc(), const_builder.getIndexType(),
            mac_op.getXrfReadIncrSigned() - required_xrf_read_incr_val);
        auto xrf_rd_update = sentient::AddOp::create(
            builder, mac_op.getLoc(), builder.getIndexType(),
            mac_op.getResult(1), const_increment);
        xrf_rd_update->setAttr(
            "regLocale", SentientRegTypeAttr::get(builder.getContext(),
                                                  SentientRegType::xrfrdptr));
        mac_op.setXrfReadIncrAttr(IntegerAttr::get(
            mac_op.getXrfReadIncrAttr().getType(), required_xrf_read_incr_val));
        mac_op.getResult(1).replaceUsesWithIf(
            xrf_rd_update, [&](mlir::OpOperand& operand) {
              return operand.getOwner() != xrf_rd_update;
            });
      }
    }
  });
}

// ------------------------------------------------------------------------------------------------
// entry 038/656   level 0   scc 147   33 body lines
// unit: e038_replaceConstXRFExpressions
// authority: dcc/src/Transform/Sentient/CanonicalizeXRFPointers.cpp:137
// original: void CanonicalizeXRFPointersPass::replaceConstXRFExpressions( dataflow::ProgramUnitOp unit_op, XRFRegisterAnalyzer& xrf_reg_analyzer)
// rust home: crates/compiler/deeptools/src/transform/sentient/canonicalize_xrf_pointers/mod.rs
// ------------------------------------------------------------------------------------------------
void e038_replaceConstXRFExpressions(
    dataflow::ProgramUnitOp unit_op, XRFRegisterAnalyzer& xrf_reg_analyzer)
{
  llvm::SmallVector<Operation*> to_delete;
  for (auto pair : xrf_reg_analyzer.getValToMinExprMap()) {
    Value val = pair.first;

    // Only replace XRF-related AddOps, as these lead to XRFACCESS
    // increment instructions.
    // NOTE: We should not replace iter args, even if they have a constant
    // value, because RegisterTypeAssignment will create a copy op inside
    // the loop to the detriment of performance.
    if (isa<BlockArgument>(val) || !isa<sentient::AddOp>(val.getDefiningOp()))
      continue;

    auto locale = sentient::getValueRegLocale(val);
    DT_CHECK(is_any_of(locale, SentientRegType::xrfrdptr,
                       SentientRegType::xrfwrptr));

    auto const_value = xrf_reg_analyzer.getValIfConstant(val);
    if (const_value.has_value()) {
      LLVM_DEBUG(llvm::dbgs()
                 << " Replacing XRF-related SSA variable " << val
                 << " with constant value: " << const_value.value() << "\n");
      Operation* owner = val.getDefiningOp();
      OpBuilder builder(owner);
      auto constant_op = sentient::ConstantOp::create(
          builder, owner->getLoc(), val.getType(), const_value.value());
      val.replaceAllUsesWith(constant_op.getResult());
      to_delete.push_back(owner);
    }
  }

  for (auto op : to_delete) op->erase();
}

