// rust home: crates/compiler/deeptools/src/transform/sentient/enhanced_dead_variable_elimination/mod.rs
// ------------------------------------------------------------------------------------------------
void e040_addToWorkListAndUpdateAssignment(
    mlir::Value val,
    EnhancedDeadVariableEliminationPass::InfluenceType influence,
    Operation *user, bool add)
{
  // Values representing the iter_arg of a ProgramUnitOp should NOT be added to
  // the worklist.
  if (isa<BlockArgument>(val) &&
      isa<dataflow::ProgramUnitOp>(
          cast<BlockArgument>(val).getOwner()->getParentOp()))
    return;

  auto record = assignments_.find(val);
  if (record == assignments_.end()) {
    assignments_[val] = influence;
    if (add) {
      worklist_.push(val);
    }
  } else {
    if (record->second != influence) {
      Operation *op;
      if (!mlir::isa<BlockArgument>(record->first)) {
        op = record->first.getDefiningOp();
      } else {
        op = mlir::cast<BlockArgument>(record->first).getOwner()->getParentOp();
      }

      if (!isa<sentient::ConstantOp, symbol::CreateSymbolOp>(op)) {
        op->dump();
        op->emitError("A SSA variable has influence over control and memory");
        signalPassFailure();
      }
    }
  }
}

