// ------------------------------------------------------------------------------------------------
void e042_printAssignments()
{
  for (auto &record : assignments_) {
    if (!mlir::isa<BlockArgument>(record.first)) {
      record.first.getDefiningOp()->dump();
    } else {
      mlir::cast<BlockArgument>(record.first).getOwner()->getParentOp()->dump();
    }

    llvm::outs() << "influence: "
                 << enum_to_strings_influences_.at(record.second) << "\n";
  }
}

