// authority: dcc/src/Transform/Sentient/EnhancedDeadVariableElimination.cpp:690
// original: void EnhancedDeadVariableEliminationPass::removeConstantIterArgs()
// rust home: crates/compiler/deeptools/src/transform/sentient/enhanced_dead_variable_elimination/mod.rs
// ------------------------------------------------------------------------------------------------
void e043_removeConstantIterArgs()
{
  current_unit_->walk<WalkOrder::PreOrder>([&](sentient::YieldOp yield_op) {
    for (int i = yield_op->getNumOperands() - 1; i >= 0; i--) {
      Operation *parent_op = yield_op->getParentOp();
      if (auto for_op = llvm::dyn_cast<sentient::ForOp>(parent_op)) {
        auto iter_arg = for_op.getRegionIterArgs()[i];
        auto yield_operand = yield_op->getOperand(i);
        auto for_op_result = for_op.getResult(i);
        if (yield_operand == iter_arg) {
          // The iterator argument is constant, so can replace it with its
          // initial value.
          auto init = for_op.getIterOperands()[i];
          iter_arg.replaceAllUsesWith(init);
          for_op_result.replaceAllUsesWith(init);
        }
      }
    }
  });
}

