// rust home: crates/compiler/deeptools/src/transform/sentient/implicit_sync_re/implicit_sync_rde_tree.rs
// ------------------------------------------------------------------------------------------------
void e045_initializeDataflowInfo(RDENode *node)
{
  // Only implicit_sync operations generate definitions, initially.
  if (!isa<sentient::SyncOp>(node->getOperation())) {
    node->setDataflowGen(new ImplicitSyncGenValue());
    return;
  }
  sentient::SyncOp sync_op = dyn_cast<sentient::SyncOp>(node->getOperation());
  DT_CHECK(sync_op.getImplicitSyncMemoryBoundary().has_value());
  node->setDataflowGen(new ImplicitSyncGenValue(
      sync_op.getImplicitSyncMemoryBoundary().value(), node->getOperation()));
  return;
}

