// rust home: crates/compiler/deeptools/src/transform/sentient/implicit_sync_re/implicit_sync_rde_tree.rs
// ------------------------------------------------------------------------------------------------
bool e046_isSimplifiable(const RDENode &node) const
{
  // We would like to remove subtrees that do not contain any implicit_sync
  // operations.
  if (getRoot() == &node) return false;
  if (isa<sentient::SyncOp>(node.getOperation())) return false;
  return node.isLeaf() || isStaticallyDeadLoop(node);
}

