// unit: e051_runOn
// authority: dcc/src/Transform/Sentient/LexicalOrdering.cpp:113
// original: void runOn(func::FuncOp func)
// rust home: crates/compiler/deeptools/src/transform/sentient/lexical_ordering/mod.rs
// ------------------------------------------------------------------------------------------------
void e051_runOn(func::FuncOp func)
{
    auto less_than = [](mlir::Operation* a, mlir::Operation* b) {
      {  // Arith constants first.
        mlir::arith::ConstantOp const_a = dyn_cast<mlir::arith::ConstantOp>(a);
        mlir::arith::ConstantOp const_b = dyn_cast<mlir::arith::ConstantOp>(b);
        if (const_a && !const_b) return true;
        if (const_b && !const_a) return false;
        if (const_a && const_b) {
          const APInt& v_a =
              mlir::cast<mlir::IntegerAttr>(const_a.getValue()).getValue();
          const APInt& v_b =
              mlir::cast<mlir::IntegerAttr>(const_b.getValue()).getValue();
          if (v_a != v_b) return v_a.slt(v_b);
          if (const_a.getType() == const_b.getType()) return false;
          // A deterministic ordering is required so use the type strings.
          // Slow path only done for constants of the same value but different
          // type.
          std::string a_str, b_str;
          llvm::raw_string_ostream a_ss(a_str), b_ss(b_str);
          a_ss << const_a.getType();
          b_ss << const_b.getType();
          return a_str < b_str;
        }
      }

      // Sentient constants second.
      sentient::ConstantOp sen_const_a = dyn_cast<sentient::ConstantOp>(a);
      sentient::ConstantOp sen_const_b = dyn_cast<sentient::ConstantOp>(b);
      if (sen_const_a && !sen_const_b) return true;
      if (sen_const_b && !sen_const_a) return false;
      if (sen_const_a && sen_const_b) {
        if (sen_const_a.getValue() != sen_const_b.getValue())
          return sen_const_a.getValue() < sen_const_b.getValue();
        if (sen_const_a.getType() == sen_const_b.getType()) return false;
        // A deterministic ordering is required so use the type strings.
        // Slow path only done for constants of the same value but different
        // type.
        std::string a_str, b_str;
        llvm::raw_string_ostream a_ss(a_str), b_ss(b_str);
        a_ss << sen_const_a.getType();
        b_ss << sen_const_b.getType();
        return a_str < b_str;
      }

      DT_ERROR("Unexpected operation comparison during lexical ordering");
    };

    bool do_transform = false;
    std::vector<mlir::Operation*> func_entry_ops;
    func->walk<WalkOrder::PreOrder>([&](mlir::Operation* op) {
      if (!mlir::isa<mlir::arith::ConstantOp>(op) &&
          !mlir::isa<sentient::ConstantOp>(op))
        return WalkResult::advance();
      // No transform if all constants are contiguous and strictly increasing.
      if (!do_transform) {
        if (func_entry_ops.empty()) {
          // If the first instruction isn't the first constant then transform.
          if (&func.getBody().front().front() != op) do_transform = true;
        } else {
          // If the next instruction isn't the next constant or the constants
          // are not in increasing order then transform.
          auto it = func_entry_ops.back()->getIterator();
          if (&*++it != op || !less_than(func_entry_ops.back(), op))
            do_transform = true;
        }
      }
      func_entry_ops.push_back(op);
      return WalkResult::advance();
    });
    if (!do_transform) return;
    std::sort(func_entry_ops.begin(), func_entry_ops.end(), less_than);
    auto I = func_entry_ops.rbegin(), prev = func_entry_ops.rbegin(),
         E = func_entry_ops.rend();
    (*I++)->moveBefore(&func.getBody().front().front());
    for (; I != E; ++I) {
      Operation* op = *I;
      Operation* prev_op = *prev;
      if (!less_than(op, prev_op) && !less_than(prev_op, op)) {
        // Replace and discard duplicates.
        DT_CHECK(op->getNumResults() == prev_op->getNumResults());
        for (unsigned i = 0; i < op->getNumResults(); ++i)
          op->getResult(i).replaceAllUsesWith(prev_op->getResult(i));
        op->erase();
        continue;
      }
      prev = I;
      (*I)->moveBefore(&func.getBody().front().front());
    }
  }

