// entry 052/656   level 0   scc 191   22 body lines
// unit: e052_addOrSubWithZeroSimplification
// authority: dcc/src/Transform/Sentient/LightweightSimplification.cpp:51
// original: static LogicalResult addOrSubWithZeroSimplification( ExpressionEvaluator& evaluator, Operation& op)
// rust home: crates/compiler/deeptools/src/transform/sentient/lightweight_simplification/mod.rs
// ------------------------------------------------------------------------------------------------
LogicalResult e052_addOrSubWithZeroSimplification(
    ExpressionEvaluator& evaluator, Operation& op)
{
  if (!isa<sentient::AddOp, sentient::SubOp>(op))
    return LogicalResult::failure();
  auto zeroOperandTransform = [&](int i) {
    const auto& v = evaluator.evaluateValue(op.getOperand(i));
    if (!v.isKnownAbsolute()) return LogicalResult::failure();
    auto au_v = dyn_cast<AllUnitEvaluatedValue>(&v);
    if (!au_v) return LogicalResult::failure();
    if (au_v->offsetValue() != 0) return LogicalResult::failure();
    Value other_operand = op.getOperand(1 - i);
    op.getResult(0).replaceAllUsesWith(other_operand);
    return LogicalResult::success();
  };
  // `a = 0 + b' || `a = b + 0` => replace uses of `a` with `b`
  if (isa<sentient::AddOp>(op) && (zeroOperandTransform(0).succeeded() ||
                                   zeroOperandTransform(1).succeeded()))
    return LogicalResult::success();
  // `a = b - 0' => replace uses of `a` with `b`
  if (isa<sentient::SubOp>(op) && zeroOperandTransform(1).succeeded())
    return LogicalResult::success();
  return LogicalResult::failure();
}

