// entry 053/656   level 0   scc 192   11 body lines
// unit: e053_constantValueSimplification
// authority: dcc/src/Transform/Sentient/LightweightSimplification.cpp:75
// original: static LogicalResult constantValueSimplification(OpBuilder& const_builder, OpBuilder& query_map_builder, ExpressionEvaluator& evaluator, Operation& op)
// rust home: crates/compiler/deeptools/src/transform/sentient/lightweight_simplification/mod.rs
// ------------------------------------------------------------------------------------------------
LogicalResult e053_constantValueSimplification(OpBuilder& const_builder,
                                                 OpBuilder& query_map_builder,
                                                 ExpressionEvaluator& evaluator,
                                                 Operation& op)
{
  if (!isa<sentient::AddOp, sentient::SubOp>(op))
    return LogicalResult::failure();
  Value result = op.getResult(0);
  const auto& v = evaluator.evaluateValue(result);
  if (!v.isKnownAbsolute()) return LogicalResult::failure();
  Value constant = v.buildOffsetValue(const_builder, query_map_builder,
                                      op.getLoc(), result.getType());
  result.replaceAllUsesWith(constant);
  return LogicalResult::success();
}

