// original: static LogicalResult coalesceScalarArithSimplification( OpBuilder& const_builder, OpBuilder& query_map_builder, ExpressionEvaluator& evaluator, llvm::SmallVector<Operation*, 4>& new_ops, Operation& op)
// rust home: crates/compiler/deeptools/src/transform/sentient/lightweight_simplification/mod.rs
// ------------------------------------------------------------------------------------------------
LogicalResult e054_coalesceScalarArithSimplification(
    OpBuilder& const_builder, OpBuilder& query_map_builder,
    ExpressionEvaluator& evaluator, llvm::SmallVector<Operation*, 4>& new_ops,
    Operation& op)
{
  //   a = ...
  //   b = a + 10
  //   x = b + 20
  // =>
  //   x2 = a + 30
  // replace x with x2 and erase x and b if no longer used.
  if (!isa<sentient::AddOp, sentient::SubOp>(op))
    return LogicalResult::failure();

  auto result = op.getResult(0);
  const auto& ev = evaluator.evaluateValue(result);
  if (!ev.baseValue().has_value()) return LogicalResult::failure();
  Value inp1 = 0, inp2 = 0;
  if (auto add_op = dyn_cast<sentient::AddOp>(op)) {
    inp1 = add_op.getInp1();
    inp2 = add_op.getInp2();
  } else {
    auto sub_op = cast<sentient::SubOp>(op);
    inp1 = sub_op.getInp1();
    inp2 = sub_op.getInp2();
  }
  // Only coalesce if the add op will have a new base.
  const BaseValue& bv = ev.baseValue().value();
  if (bv.value_ == result || bv.value_ == inp1 || bv.value_ == inp2)
    return LogicalResult::failure();

  auto isConstantOp = [](Value v) -> bool {
    Operation* def_op = v.getDefiningOp();
    return def_op && isa<sentient::ConstantOp>(def_op);
  };

  // Only transform if an op will be removed to compensate for the new add op.
  // Don't count removal of constants as compensation for adding a new add op.
  if ((!inp1.hasOneUse() || isConstantOp(inp1)) &&
      (!inp2.hasOneUse() || isConstantOp(inp2)))
    return LogicalResult::failure();

  OpBuilder builder(&op);
  Value offset = ev.buildOffsetValue(const_builder, query_map_builder,
                                     op.getLoc(), result.getType());
  if (bv.is_negated_) {
    auto sub_op = sentient::SubOp::create(builder, op.getLoc(),
                                          result.getType(), offset, bv.value_);
    new_ops.push_back(sub_op);
    sub_op->setAttrs(op.getAttrs());
    result.replaceAllUsesWith(sub_op.getResult());
  } else {
    if (dcc::utils::isTargetConstant(offset, 0)) {
      // x2 = a + 0 => replace x2 with a
      result.replaceAllUsesWith(bv.value_);
      return LogicalResult::success();
    }

    auto add_op = sentient::AddOp::create(builder, op.getLoc(),
                                          result.getType(), bv.value_, offset);
    new_ops.push_back(add_op);
    add_op->setAttrs(op.getAttrs());
    result.replaceAllUsesWith(add_op.getResult());
  }
  return LogicalResult::success();
}

