// entry 055/656   level 0   scc 194   19 body lines
// unit: e055_simplifyTrivialLoop
// authority: dcc/src/Transform/Sentient/LightweightSimplification.cpp:158
// original: static void simplifyTrivialLoop(sentient::ForOp for_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/lightweight_simplification/mod.rs
// ------------------------------------------------------------------------------------------------
void e055_simplifyTrivialLoop(sentient::ForOp for_op)
{
  int num_iter_args = for_op.getNumRegionIterArgs();
  Block* body = for_op.getBody(0);
  auto yield_op = body->getTerminator();
  // Replace the iter args by the corresponding init value and the ForOp results
  // by the corresponding YieldOp operand.
  for (unsigned i = 0; i < num_iter_args; i++) {
    for_op.getRegionIterArgs()[i].replaceAllUsesWith(for_op.getInits()[i]);
    for_op.getResult(i).replaceAllUsesWith(yield_op->getOperand(i));
  }
  for_op.getInductionVar().replaceAllUsesWith(for_op.getBound());

  // Hoist the body's operations out of the loop.
  while (!body->empty()) {
    auto& op = body->getOperations().front();
    if (isa<sentient::YieldOp>(op)) break;
    op.moveBefore(for_op);
  }
}

