bool e058_areElementSizeIdentical(Value& lhs, Value& rhs)
{
  int lhs_element_size = dcc::sentient::utils::getElementSize(lhs);
  int rhs_element_size = dcc::sentient::utils::getElementSize(rhs);
  if (rhs_element_size < 1 || lhs_element_size < 1 ||
      lhs_element_size != rhs_element_size) {
    return false;
  }
  return true;
}

