// entry 059/656   level 0   scc 219   56 body lines
// unit: e059_getFirstGlobalOrConstantAncestor
// authority: dcc/src/Transform/Sentient/LiveRangeReduction.cpp:1107
// original: Value LiveRangeReductionPass::getFirstGlobalOrConstantAncestor( Value val, Region* uniform_region)
// rust home: crates/compiler/deeptools/src/transform/sentient/live_range_reduction/mod.rs
// ------------------------------------------------------------------------------------------------
Value e059_getFirstGlobalOrConstantAncestor(
    Value val, Region* uniform_region)
{
  while (val) {
    unsigned operand_idx = 0;
    Operation* op;
    if (auto block_arg = dyn_cast<BlockArgument>(val)) {
      op = block_arg.getParentBlock()->getParentOp();
      DT_CHECK(isa<sentient::ForOp>(op));
      operand_idx = block_arg.getArgNumber();
    } else {
      op = val.getDefiningOp();
      if (auto load_and_send_op = llvm::dyn_cast<sentient::LoadAndSendOp>(op)) {
        operand_idx =
            load_and_send_op.getMutableAddrMutable().getOperandNumber();
      } else if (auto receive_and_store_op =
                     llvm::dyn_cast<sentient::ReceiveAndStoreOp>(op)) {
        operand_idx =
            receive_and_store_op.getMutableAddrMutable().getOperandNumber();
      } else if (auto load_store_op =
                     llvm::dyn_cast<sentient::LoadAndStoreOp>(op)) {
        if (val == load_store_op.getSrcMutableAddr())
          operand_idx =
              load_store_op.getSrcMutableAddrMutable().getOperandNumber();
        else
          operand_idx =
              load_store_op.getDstMutableAddrMutable().getOperandNumber();
      } else if (auto load_extract_op =
                     llvm::dyn_cast<sentient::LoadAndExtractScalarOp>(op)) {
        operand_idx =
            load_extract_op.getMutableAddrMutable().getOperandNumber();
      } else if (auto load_compute_op =
                     llvm::dyn_cast<sentient::LoadComputeAndSendOp>(op)) {
        operand_idx =
            load_compute_op.getMutableAddrMutable().getOperandNumber();
      } else if (isa<sentient::AddOp, sentient::SubOp>(op)) {
        if (!isConstant<sentient::ConstantOp>(op->getOperand(0))) {
          operand_idx = 0;
        } else {
          operand_idx = 1;
        }
      } else if (isa<sentient::ForOp>(op)) {
        operand_idx = mlir::cast<OpResult>(val).getResultNumber() + 1;
      } else if (isa<sentient::ConstantOp, uniform::QueryMapOp,
                     symbol::CreateSymbolOp>(op)) {
        return val;
      } else {
        op->emitOpError("can't find global ancestor");
        signalPassFailure();
      }
    }
    if (op->getParentRegion() != uniform_region) {
      break;
    }
    val = op->getOperand(operand_idx);
  }
  return val;
}

