// entry 062/656   level 0   scc 224   19 body lines
// unit: e062_collectUniformMaps
// authority: dcc/src/Transform/Sentient/LocalRegionSplittingForValueCommoning.cpp:308
// original: void LocalRegionSplittingForValueCommoningPass::collectUniformMaps( SmallVectorImpl<uniform::DefImmutableMappingOp> &uniform_maps, Region &local_region, const SentientRegType locale) const
// rust home: crates/compiler/deeptools/src/transform/sentient/local_region_splitting_for_value_commoning/mod.rs
// ------------------------------------------------------------------------------------------------
void e062_collectUniformMaps(
    SmallVectorImpl<uniform::DefImmutableMappingOp> &uniform_maps,
    Region &local_region, const SentientRegType locale) const
{
  for (auto &block : local_region.getBlocks()) {
    for (auto &op : block.getOperations()) {
      op.walk<WalkOrder::PreOrder>([&](sentient::CopyOp copy_op) {
        const SentientRegType this_locale =
            sentient::getValueRegLocale(copy_op);
        if (this_locale != locale) return WalkResult::advance();
        Value copy_opnd = copy_op.getInp();
        auto qmo = dyn_cast<uniform::QueryMapOp>(copy_opnd.getDefiningOp());
        if (!qmo) return WalkResult::advance();
        auto dimo = llvm::dyn_cast<mlir::uniform::DefImmutableMappingOp>(
            qmo.getMap().getDefiningOp());
        DT_CHECK(dimo);
        uniform_maps.push_back(dimo);
        return WalkResult::advance();
      });
    }
  }
}

