// rust home: crates/compiler/deeptools/src/transform/sentient/local_region_splitting_for_value_commoning/mod.rs
// ------------------------------------------------------------------------------------------------
unsigned e063_getMaxRegNum(
    const SentientRegType locale, const SenComponents comp) const
{
  switch (locale) {
    case SentientRegType::lbr: {
      if (MaxLBR.getNumOccurrences() > 0) return MaxLBR;
      break;
    }
    case SentientRegType::ebr: {
      if (MaxEBR.getNumOccurrences() > 0) return MaxEBR;
      break;
    }
    default:
      break;
  }
  return dccExtContext().getMaxRegNum(locale, comp);
}

