// entry 067/656   level 0   scc 236   48 body lines
// unit: e067_updateLoopBound
// authority: dcc/src/Transform/Sentient/LoopAbsorption.cpp:58
// original: void LoopAbsorptionManager::updateLoopBound(int64_t increment)
// rust home: crates/compiler/deeptools/src/transform/sentient/loop_absorption/loop_absorption_manager.rs
// ------------------------------------------------------------------------------------------------
void e067_updateLoopBound(int64_t increment)
{
  Value bound = anchor_for_op_.getBound();
  auto const_bound =
      llvm::dyn_cast_or_null<sentient::ConstantOp>(bound.getDefiningOp());
  auto query_map =
      llvm::dyn_cast_or_null<uniform::QueryMapOp>(bound.getDefiningOp());
  bool is_query_map_constant =
      query_map &&
      dcc::utils::isConstant<sentient::ConstantOp>(query_map.getResult());
  Type bound_type = bound.getType();
  Location loc = anchor_for_op_.getLoc();
  Operation *unit = anchor_for_op_->getParentOfType<dataflow::ProgramUnitOp>();
  DT_CHECK_MSG(unit, "expected loop to appear in dataflow.program_unit");
  OpBuilder const_builder(dyn_cast<dataflow::ProgramUnitOp>(*unit));
  auto const_increm = sentient::ConstantOp::create(
      const_builder, anchor_for_op_.getLoc(), bound_type, increment);

  if (const_bound) {
    anchor_for_op_.setBound(sentient::ConstantOp::create(
        const_builder, loc, bound_type, const_bound.getValue() + increment));
    const_increm.erase();
  } else if (is_query_map_constant) {
    dcc::utils::updateBoundToValuePlusMap(
        const_increm, query_map, const_builder, anchor_for_op_,
        /*is_constant_value_query_map = */ true);
  } else if (query_map) {
    dcc::utils::updateBoundToValuePlusMap(
        const_increm, query_map, const_builder, anchor_for_op_,
        /*is_constant_value_query_map = */ false);
  } else {
    // The incremented bound should be inserted as to avoid preventing
    // absorption opportunities. If the bound is an op, insert the new bound
    // right after. Otherwise, if it is a BlockArg, insert the new bound at
    // the start of the loop.
    OpBuilder builder(anchor_for_op_);
    if (bound.getDefiningOp()) {
      builder.setInsertionPointAfter(bound.getDefiningOp());
    } else {
      Block *bb_defining_bound = cast<BlockArgument>(bound).getOwner();
      builder.setInsertionPointToStart(bb_defining_bound);
    }
    anchor_for_op_.setBound(
        sentient::AddOp::create(builder, loc, bound_type, bound, const_increm));
  }

  if (bound.getDefiningOp() && bound.getDefiningOp()->use_empty())
    bound.getDefiningOp()->erase();
}

