// rust home: crates/compiler/deeptools/src/transform/sentient/loop_absorption/loop_absorption_manager.rs
// ------------------------------------------------------------------------------------------------
bool e068_doChildrenLeftSiblingSubtreeHeightsMatch()
{
  for (auto next_child = anchor_->getLastChild(),
            next_sibling = anchor_->getPrevSibling();
       next_child; next_child = next_child->getPrevSibling(),
            next_sibling = next_sibling->getPrevSibling()) {
    if (!next_sibling || tree_.getSubtreeHeightOf(next_child) !=
                             tree_.getSubtreeHeightOf(next_sibling)) {
      return false;
    }
  }
  return true;
}

