// entry 071/656   level 0   scc 249   27 body lines
// unit: e071_getLargestDivisor
// authority: dcc/src/Transform/Sentient/LoopCoalescing.cpp:379
// original: int64_t LoopCoalescingPass::getLargestDivisor(int64_t input, int limit)
// rust home: crates/compiler/deeptools/src/transform/sentient/loop_coalescing/mod.rs
// ------------------------------------------------------------------------------------------------
int64_t e071_getLargestDivisor(int64_t input, int limit)
{
  if (input <= limit) {
    return input;
  }

  // use prime pool to ease the check complexity
  // This assume our loop is not a single prime number
  // that is larger than limit / 2
  std::vector<int> prime_pool = {11, 7, 5, 3, 2};
  while (input > limit) {
    bool found = false;
    for (auto &p : prime_pool) {
      if (input % p == 0) {
        input /= p;
        found = true;
        break;
      }  // reduce input by a prime factor
    }  // try every element in prime_pool

    if (!found) {
      // if reaches here, something is really wrong:
      DT_ERROR("No valid prime factor but input still too large!");
    }
  }  // continuous until input meets the critieria

  return input;
}

