bool e074_checkOperandsOfComputeOp(Operation *compute_op,
                                StringRef &invalid_operand) const
{
    if (auto mac_op = llvm::dyn_cast<MacOp>(compute_op)) {
      if (mac_op.getUnrollIncrOpA() || mac_op.getUnrollIncrOpB() ||
          mac_op.getUnrollIncrOpC() || mac_op.getUnrollIncrResult() ||
          stringifySentientComputePort(mac_op.getOpA())
              .contains(invalid_operand) ||
          stringifySentientComputePort(mac_op.getOpB())
              .contains(invalid_operand) ||
          stringifySentientComputePort(mac_op.getOpC())
              .contains(invalid_operand))
        return false;
    } else if (auto bin_op = llvm::dyn_cast<BinaryOp>(compute_op)) {
      if (bin_op.getUnrollIncrOpA() || bin_op.getUnrollIncrOpB() ||
          bin_op.getUnrollIncrResult() ||
          stringifySentientComputePort(bin_op.getOpA())
              .contains(invalid_operand) ||
          stringifySentientComputePort(bin_op.getOpB())
              .contains(invalid_operand))
        return false;
    } else if (auto tern_op = llvm::dyn_cast<TernaryOp>(compute_op)) {
      if (tern_op.getUnrollIncrOpA() || tern_op.getUnrollIncrOpB() ||
          tern_op.getUnrollIncrOpC() || tern_op.getUnrollIncrResult() ||
          stringifySentientComputePort(tern_op.getOpA())
              .contains(invalid_operand) ||
          stringifySentientComputePort(tern_op.getOpB())
              .contains(invalid_operand) ||
          stringifySentientComputePort(tern_op.getOpC())
              .contains(invalid_operand))
        return false;
    } else if (auto unary_op = llvm::dyn_cast<UnaryOp>(compute_op)) {
      if (unary_op.getUnrollIncrOpA() || unary_op.getUnrollIncrResult() ||
          stringifySentientComputePort(unary_op.getOpA())
              .contains(invalid_operand))
        return false;
    } else {
      llvm_unreachable("expect a compute op");
    }
    return true;
  }

