// entry 077/656   level 0   scc 269   12 body lines
// unit: e077_isIncrementField
// authority: dcc/src/Transform/Sentient/LoopRolling.cpp:67
// original: bool isIncrementField(Operation &op, unsigned i, OpBuilder &const_builder)
// rust home: crates/compiler/deeptools/src/transform/sentient/loop_rolling/mod.rs
// ------------------------------------------------------------------------------------------------
bool e077_isIncrementField(Operation &op, unsigned i, OpBuilder &const_builder)
{
  // Note: LoadAndExtractScalarOp and LoadComputeAndSendOp ignored as they
  //       should never provide rolling opportunities.
  if (auto rs = dyn_cast<sentient::ReceiveAndStoreOp>(op))
    return rs.getIncrementMutable().getOperandNumber() == i;
  else if (auto ls = dyn_cast<sentient::LoadAndSendOp>(op))
    return ls.getIncrementMutable().getOperandNumber() == i;
  else if (auto las = dyn_cast<sentient::LoadAndStoreOp>(op))
    return las.getSrcIncMutable().getOperandNumber() == i ||
           las.getDstIncMutable().getOperandNumber() == i;
  return false;
}

