// ------------------------------------------------------------------------------------------------
bool e079_checkOpUsage(Operation &op, Window *next_window)
{
    for (auto r : op.getResults()) {
      for (auto &use : r.getUses()) {
        if ((&op != last_rollable_op_ ||
             use.getOwner() != next_window->getFirstRollableOp()) &&
            !isOpInThisWindow(use.getOwner()))
          return false;
      }
    }
    return true;
  }

