// unit: e083_computeValsIfDifferent
// authority: dcc/src/Transform/Sentient/LoopRolling.cpp:254
// original: bool computeValsIfDifferent(Value a_operand, Value b_operand, int64_t &delta)
// rust home: crates/compiler/deeptools/src/transform/sentient/loop_rolling/mod.rs
// ------------------------------------------------------------------------------------------------
bool e083_computeValsIfDifferent(Value a_operand, Value b_operand,
                              int64_t &delta)
{
    bool found_mismatch = false;
    Operation *a_operand_op = a_operand.getDefiningOp();
    Operation *b_operand_op = b_operand.getDefiningOp();

    if (a_operand != b_operand) {
      bool is_a_operand_block_arg = mlir::isa<BlockArgument>(a_operand);
      bool is_b_operand_block_arg = mlir::isa<BlockArgument>(b_operand);

      if (is_a_operand_block_arg && is_b_operand_block_arg) {
        found_mismatch = false;
      } else if (!(is_a_operand_block_arg ^ is_b_operand_block_arg)) {
        if (!oe_.operationsAreEquivalent(*a_operand_op, *b_operand_op))
          found_mismatch = true;
      } else {
        // If one is a block argument and the other is not, they are different
        // and delta cannot be computed.
        return false;
      }
    }

    if (found_mismatch) {
      auto a_const_op = dyn_cast<sentient::ConstantOp>(a_operand_op);
      auto b_const_op = dyn_cast<sentient::ConstantOp>(b_operand_op);
      auto query_map_a =
          llvm::dyn_cast<uniform::QueryMapOp>(a_operand.getDefiningOp());
      auto query_map_b =
          llvm::dyn_cast<uniform::QueryMapOp>(b_operand.getDefiningOp());

      if (a_const_op && b_const_op) {
        delta = b_const_op.getValue() - a_const_op.getValue();
      } else if (a_const_op && query_map_b) {
        std::vector<int64_t> vals_b =
            dcc::uniform::utils::getConstantOrSymbolTargetValues(query_map_b);
        if (vals_b.empty()) return false;
        int64_t unique_val_b = vals_b.front();
        for (int64_t v : vals_b)
          if (v != unique_val_b) return false;
        delta = unique_val_b - a_const_op.getValue();
      } else if (b_const_op && query_map_a) {
        std::vector<int64_t> vals_a =
            dcc::uniform::utils::getConstantOrSymbolTargetValues(query_map_a);
        if (vals_a.empty()) return false;
        int64_t unique_val_a = vals_a.front();
        for (int64_t v : vals_a)
          if (v != unique_val_a) return false;
        delta = b_const_op.getValue() - unique_val_a;
      } else if (query_map_a && query_map_b) {
        auto deltas =
            dcc::uniform::utils::getDeltasBetweenValuesOfUniformMappings(
                query_map_a, query_map_b);
        if (!deltas.has_value()) return false;
        delta = deltas.value().front();
        for (int64_t d : deltas.value()) {
          if (delta != d) return false;
        }
      } else {
        return false;
      }
    }
    return true;
  }

