// entry 085/656   level 0   scc 287   13 body lines
// unit: e085_replaceIterArgsAndYieldResults
// authority: dcc/src/Transform/Sentient/LoopSplittingAndUnrolling.cpp:132
// original: void LoopSplittingAndUnrollingPass::replaceIterArgsAndYieldResults( sentient::ForOp for_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/loop_splitting_and_unrolling/mod.rs
// ------------------------------------------------------------------------------------------------
void e085_replaceIterArgsAndYieldResults(
    sentient::ForOp for_op)
{
  // Replace uses of iter arguments with iter operands (initial values).
  auto iterOperands = for_op.getIterOperands();
  auto iterArgs = for_op.getRegionIterArgs();
  for (auto e : llvm::zip(iterOperands, iterArgs))
    std::get<1>(e).replaceAllUsesWith(std::get<0>(e));

  // Replace uses of loop results with the values yielded by the loop.
  auto outerResults = for_op.getResults();
  auto innerResults = for_op.getBody()->getTerminator()->getOperands();
  for (auto e : llvm::zip(outerResults, innerResults))
    std::get<0>(e).replaceAllUsesWith(std::get<1>(e));
}

