// entry 086/656   level 0   scc 289   47 body lines
// unit: e086_isOkToUnroll
// authority: dcc/src/Transform/Sentient/LoopSplittingAndUnrolling.cpp:159
// original: bool LoopSplittingAndUnrollingPass::isOkToUnroll(sentient::ForOp for_op0)
// rust home: crates/compiler/deeptools/src/transform/sentient/loop_splitting_and_unrolling/mod.rs
// ------------------------------------------------------------------------------------------------
bool e086_isOkToUnroll(sentient::ForOp for_op0)
{
  if (DisableLoopUnroll) return false;
  bool is_ok_to_unroll = true;
  /// when iterator arguments is used in mutable operands of
  /// load_and_store, load_and_send and receive_and_store ops and loops
  /// are fully unrolled in that case mutable operands becomes constant
  /// and requires a copy or uses any existing sentient_copy op in this
  /// case liverange conflicts increases and leads to failure of
  /// register allocation pass so we prevent this by disabling unrolling
  /// here.
  int index = 0;
  for (auto &iter_arg : for_op0.getRegionIterArgs()) {
    // now track uses, only consider the endpoint of each use.
    auto iter_op = for_op0.getIterOperands()[index];
    index++;
    if (iter_op.getDefiningOp() and
        isa<sentient::ConstantOp>(iter_op.getDefiningOp()))
      for (auto iter_arg_use : iter_arg.getUsers()) {
        if (auto las = llvm::dyn_cast<sentient::LoadAndStoreOp>(iter_arg_use)) {
          if (las.getSrcMutableAddr() == iter_arg ||
              las.getDstMutableAddr() == iter_arg)
            is_ok_to_unroll = false;
        } else if (auto las =
                       llvm::dyn_cast<sentient::LoadAndSendOp>(iter_arg_use)) {
          if (las.getMutableAddr() == iter_arg) {
            is_ok_to_unroll = false;
          }
        } else if (auto ras = llvm::dyn_cast<sentient::ReceiveAndStoreOp>(
                       iter_arg_use)) {
          if (ras.getMutableAddr() == iter_arg) {
            is_ok_to_unroll = false;
          }
        } else if (auto lae = llvm::dyn_cast<sentient::LoadAndExtractScalarOp>(
                       iter_arg_use)) {
          if (lae.getMutableAddr() == iter_arg) {
            is_ok_to_unroll = false;
          }
        } else if (auto lcas = llvm::dyn_cast<sentient::LoadComputeAndSendOp>(
                       iter_arg_use)) {
          if (lcas.getMutableAddr() == iter_arg) {
            is_ok_to_unroll = false;
          }
        }
      }
  }
  return is_ok_to_unroll;
}

