// rust home: crates/compiler/deeptools/src/transform/sentient/loop_splitting_and_unrolling/mod.rs
// ------------------------------------------------------------------------------------------------
bool e088_ifOpUsesIV(dcc::LoopNode *n)
{
  auto for_op = llvm::dyn_cast<sentient::ForOp>(n->getOperation());
  auto iv = for_op.getInductionVar();
  for (auto use : iv.getUsers()) {
    if (llvm::dyn_cast<sentient::IfOp>(use)) {
      return true;
    }
  }
  return false;
}

