// authority: dcc/src/Transform/Sentient/LoopSplittingAndUnrolling.cpp:466
// original: bool LoopSplittingAndUnrollingPass::hasIfOps(dcc::LoopNode *n)
// rust home: crates/compiler/deeptools/src/transform/sentient/loop_splitting_and_unrolling/mod.rs
// ------------------------------------------------------------------------------------------------
bool e089_hasIfOps(dcc::LoopNode *n)
{
  auto op = n->getOperation();
  bool contain_if_ops = false;
  op->walk([&](mlir::Operation *op) {
    if (llvm::dyn_cast<sentient::IfOp>(op)) {
      contain_if_ops = true;
      return WalkResult::interrupt();
    }
    return WalkResult::advance();
  });
  return contain_if_ops;
}

// ------------------------------------------------------------------------------------------------
// entry 090/656   level 0   scc 294   33 body lines
// unit: e090_evaluatePredicate
// authority: dcc/src/Transform/Sentient/LoopSplittingAndUnrolling.cpp:552
// original: bool LoopSplittingAndUnrollingPass::evaluatePredicate(int bound, sentient::IfOp &if_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/loop_splitting_and_unrolling/mod.rs
// ------------------------------------------------------------------------------------------------
bool e090_evaluatePredicate(int bound,
                                                      sentient::IfOp &if_op)
{
  auto pred = if_op.getPredicate();
  if (auto lhs = if_op.getLhs().getDefiningOp<sentient::ConstantOp>()) {
    if (pred == CmpIPredicate::sge) {
      return lhs.getValue() >= bound;
    } else if (pred == CmpIPredicate::sgt) {
      return lhs.getValue() > bound;
    } else if (pred == CmpIPredicate::slt) {
      return lhs.getValue() < bound;
    } else if (pred == CmpIPredicate::sle) {
      return lhs.getValue() <= bound;
    } else if (pred == CmpIPredicate::eq) {
      return lhs.getValue() == bound;
    } else {
      return lhs.getValue() != bound;
    }
  } else if (auto rhs = if_op.getRhs().getDefiningOp<sentient::ConstantOp>()) {
    if (pred == CmpIPredicate::sge) {
      return bound >= rhs.getValue();
    } else if (pred == CmpIPredicate::sgt) {
      return bound > rhs.getValue();
    } else if (pred == CmpIPredicate::slt) {
      return bound < rhs.getValue();
    } else if (pred == CmpIPredicate::sle) {
      return bound <= rhs.getValue();
    } else if (pred == CmpIPredicate::eq) {
      return rhs.getValue() == bound;
    } else {
      return rhs.getValue() != bound;
    }
  }
  return false;
}

