// entry 091/656   level 0   scc 296   22 body lines
// unit: e091_findAllSplitVals
// authority: dcc/src/Transform/Sentient/LoopSplittingAndUnrolling.cpp:596
// original: std::vector<std::pair<int, int>> LoopSplittingAndUnrollingPass::findAllSplitVals( std::map<int, std::vector<bool>, std::greater<>> &bound_to_all_ifops_predval)
// rust home: crates/compiler/deeptools/src/transform/sentient/loop_splitting_and_unrolling/mod.rs
// ------------------------------------------------------------------------------------------------
std::vector<std::pair<int, int>>
e091_findAllSplitVals(
    std::map<int, std::vector<bool>, std::greater<>>
        &bound_to_all_ifops_predval)
{
  std::vector<std::pair<int, int>> split_vals;
  auto start = bound_to_all_ifops_predval.begin(),
       end = bound_to_all_ifops_predval.end();
  auto first = start;
  auto second = first;
  int p_first = first->first;
  int p_second = second->first;
  while (second != end) {
    if (first->second == second->second) {
      p_second = second->first;
      second++;
    } else {
      split_vals.push_back(std::pair<int, int>(p_first, p_second));
      first = second;
      p_first = second->first;
      p_second = second->first;
    }
  }
  split_vals.push_back(std::pair<int, int>(p_first, p_second));
  return split_vals;
}

// ------------------------------------------------------------------------------------------------
// entry 092/656   level 0   scc 293   39 body lines
// unit: e092_computeReducedCost
// authority: dcc/src/Transform/Sentient/LoopSplittingAndUnrolling.cpp:649
// original: void LoopSplittingAndUnrollingPass::computeReducedCost( dcc::CondNode *n, InstructionEstimatorImpl &ie, int &cost_reduced, std::map<sentient::IfOp, bool> &if_op_to_pred_val)
// rust home: crates/compiler/deeptools/src/transform/sentient/loop_splitting_and_unrolling/mod.rs
// ------------------------------------------------------------------------------------------------
void e092_computeReducedCost(
    dcc::CondNode *n, InstructionEstimatorImpl &ie, int &cost_reduced,
    std::map<sentient::IfOp, bool> &if_op_to_pred_val)
{
  if (!n) return;
  if (n->isThenNode() || n->isElseNode() || !n->isIfNode()) {
    // For Then/Else/Root nodes simply accumulate reduced costs
    // of the children.
    for (dcc::CondNode *child = n->getFirstChild(); child;
         child = child->getNextSibling())
      computeReducedCost(child, ie, cost_reduced, if_op_to_pred_val);
    return;
  }
  sentient::IfOp if_op =
      llvm::dyn_cast_or_null<sentient::IfOp>(n->getOperation());
  DT_CHECK_MSG(if_op, "Expect valid IfNode");

  if (if_op_to_pred_val.find(if_op) == if_op_to_pred_val.end()) {
    // if_op is not in the list of IfOps to be removed by the loop splitting,
    // so simply recurse on its then/else branches.
    computeReducedCost(n->getThenNode(), ie, cost_reduced, if_op_to_pred_val);
    computeReducedCost(n->getElseNode(), ie, cost_reduced, if_op_to_pred_val);
    return;
  }

  // retrieve true/false value of predicate
  bool pred_eval = if_op_to_pred_val[if_op];
  int num_of_yield_operands =
      if_op.getThenRegion().front().getTerminator()->getNumOperands();
  cost_reduced += 1 + num_of_yield_operands;
  if (pred_eval) {
    // Else-branch is dead. Accumulate its cost, recurse on Then-branch.
    cost_reduced += ie.getEstimatedInstructionCount(dccExtContext(),
                                                    &if_op.getElseRegion());
    computeReducedCost(n->getThenNode(), ie, cost_reduced, if_op_to_pred_val);
  } else {
    // Then-branch is dead. Accumulate its cost, recurse on Else-branch.
    cost_reduced += ie.getEstimatedInstructionCount(dccExtContext(),
                                                    &if_op.getThenRegion());
    computeReducedCost(n->getElseNode(), ie, cost_reduced, if_op_to_pred_val);
  }
}

