std::string e093_stringifyPeelingType(PeelingType t) const
{
    switch (t) {
      case PeelingType::kFirstIterOnly:
        return "FirstIterOnly";
      case PeelingType::kLastIterOnly:
        return "LastIterOnly";
      case PeelingType::kFirstAndLastIter:
        return "FirstAndLastIter";
      default:
        return "NoPeeling";
    }
  }

