// original: void insertOrUpdatePeelingType(sentient::ForOp for_op, PeelingType p_type)
// rust home: crates/compiler/deeptools/src/transform/sentient/multi_dim_loop_peeling/mod.rs
// ------------------------------------------------------------------------------------------------
void e094_insertOrUpdatePeelingType(sentient::ForOp for_op, PeelingType p_type)
{
    DT_CHECK_MSG(p_type != PeelingType::kNoPeeling,
                 "Map should only contain valid peeling modes");

    auto existing_record =
        std::find_if(loop_to_peeling_type_.begin(), loop_to_peeling_type_.end(),
                     [&](std::pair<sentient::ForOp, PeelingType> record) {
                       return record.first == for_op;
                     });
    if (existing_record == loop_to_peeling_type_.end()) {
      loop_to_peeling_type_.push_back({for_op, p_type});
    } else {
      DT_CHECK_MSG(existing_record->second != PeelingType::kNoPeeling,
                   "Expect valid peeling mode in map");
      // If the current peeling type matches p_type, no change.
      // Otherwise the union of the peeling types would be kFirstAndLastIter.
      if (existing_record->second != p_type)
        existing_record->second = PeelingType::kFirstAndLastIter;
    }
  }

