// entry 095/656   level 0   scc 312   27 body lines
// unit: e095_decrementPredicatesOnIV
// authority: dcc/src/Transform/Sentient/MultiDimLoopPeeling.cpp:433
// original: void LoopPeelingManager::decrementPredicatesOnIV(Value iv)
// rust home: crates/compiler/deeptools/src/transform/sentient/multi_dim_loop_peeling/loop_peeling_manager.rs
// ------------------------------------------------------------------------------------------------
void e095_decrementPredicatesOnIV(Value iv)
{
  for (auto iv_use : iv.getUsers()) {
    if (auto if_op = llvm::dyn_cast<sentient::IfOp>(iv_use)) {
      Value const_side = nullptr;
      if (if_op.getLhs() == iv)
        const_side = if_op.getRhs();
      else if (if_op.getRhs() == iv)
        const_side = if_op.getLhs();
      else
        llvm_unreachable("expect a comparison on the IV");

      auto const_op =
          llvm::dyn_cast<sentient::ConstantOp>(const_side.getDefiningOp());
      DT_CHECK_MSG(const_op,
                   "Expect a comparison between the IV and a ConstantOp");
      // Decrement the constant side by 1.
      auto decremented_const_op = sentient::ConstantOp::create(
          const_builder_, iv.getLoc(), const_side.getType(),
          const_op.getValue() - 1);
      if (if_op.getLhs() == iv)
        if_op->setOperand(1, decremented_const_op.getResult());
      else
        if_op->setOperand(0, decremented_const_op.getResult());
    } else
      llvm_unreachable("expect iv users to be IfOps");
  }
}

