// rust home: crates/compiler/deeptools/src/transform/sentient/multi_dim_loop_peeling/loop_peeling_manager.rs
// ------------------------------------------------------------------------------------------------
void e096_simplifyConditionals(
    mlir::MLIRContext *context,
    SmallVector<Operation *, 4> if_ops_to_simplify)
{
  RewritePatternSet patterns(context);
  sentient::IfOp::getCanonicalizationPatterns(patterns, context);
  FrozenRewritePatternSet frozenPatterns(std::move(patterns));
  GreedyRewriteConfig config;
  config.setStrictness(GreedyRewriteStrictness::ExistingOps);
  bool erased;
  (void)applyOpPatternsGreedily(if_ops_to_simplify, frozenPatterns, config,
                                nullptr, &erased);
  if (erased) LLVM_DEBUG(llvm::dbgs() << "A Static IfOp Erased\n");
}

