// rust home: crates/compiler/deeptools/src/transform/sentient/multicast_canonicalization/mod.rs
// ------------------------------------------------------------------------------------------------
void e098_processDirectMulticast(
    sentient::ReceiveAndStoreOp ras,
    dataflow::CreateMulticastGroupOp multicast)
{
  // List of ReceiveAndStoreOps with multicast as the producer.
  llvm::SmallVector<sentient::ReceiveAndStoreOp> ras_list;
  for (auto &use : multicast->getUses()) {
    if (auto receive_and_store =
            llvm::dyn_cast<ReceiveAndStoreOp>(use.getOwner()))
      ras_list.push_back(receive_and_store);
  }
  for (auto receive_and_store : ras_list) {
    receive_and_store.getProducerMutable().assign(multicast.getProducer());
    receive_and_store.getMulticastInfoMutable().assign(multicast);
  }
  return;
}

