// unit: e099_createNewProducerQMap
// authority: dcc/src/Transform/Sentient/MulticastCanonicalization.cpp:299
// original: uniform::QueryMapOp MulticastCanonicalizationPass::createNewProducerQMap( uniform::QueryMapOp orig_qmap)
// rust home: crates/compiler/deeptools/src/transform/sentient/multicast_canonicalization/mod.rs
// ------------------------------------------------------------------------------------------------
uniform::QueryMapOp e099_createNewProducerQMap(
    uniform::QueryMapOp orig_qmap)
{
  auto keys = dcc::uniform::utils::getListOfKeyOpsFromUniformMapping(orig_qmap);
  auto immutable_map =
      orig_qmap.getMap().getDefiningOp<uniform::DefImmutableMappingOp>();
  auto values = immutable_map.getNonNullValuesFromKeys(keys);

  SmallVector<Value> new_values;
  for (auto &val : values) {
    if (auto tmp_multicast =
            dyn_cast<dataflow::CreateMulticastGroupOp>(val.getDefiningOp())) {
      new_values.push_back(tmp_multicast.getProducer());
    } else {
      // This is not a type of q_map we know how to process.
      return nullptr;
    }
  }

  OpBuilder tmp_builder(immutable_map);
  auto new_map = uniform::DefImmutableMappingOp::create(
      tmp_builder, immutable_map->getLoc(), tmp_builder.getIndexType(), keys,
      new_values);

  return uniform::QueryMapOp::create(tmp_builder, immutable_map->getLoc(),
                                     tmp_builder.getIndexType(), new_map,
                                     orig_qmap.getKey());
}

