// rust home: crates/compiler/deeptools/src/transform/sentient/nop_insertion_for_back_to_back_syncs/mod.rs
// ------------------------------------------------------------------------------------------------
void e100_runOn(ModuleOp module_op)
{
    module_op->walk<WalkOrder::PreOrder>([&](dataflow::ProgramUnitOp unit) {
      auto curr_unit =
          (*unit.getUnits().begin()).getDefiningOp<dataflow::GetUnitOp>();
      auto comp = dcc::getUnitType(curr_unit);
      if (!is_any_of(comp, L0SU)) return WalkResult::skip();

      // The hardware bug is only present in L0SU, hence the nop insertion
      // should be done over L0SU programs only.
      runOn(unit);

      return WalkResult::advance();
    });
  }

// ------------------------------------------------------------------------------------------------
// entry 101/656   level 0   scc 346   39 body lines
// unit: e101_runOn
// authority: dcc/src/Transform/Sentient/NOPInsertionForBackToBackSyncs.cpp:106
// original: void NOPInsertionForBackToBackSyncsPass::runOn(dataflow::ProgramUnitOp unit)
// rust home: crates/compiler/deeptools/src/transform/sentient/nop_insertion_for_back_to_back_syncs/mod.rs
// ------------------------------------------------------------------------------------------------
void e101_runOn(dataflow::ProgramUnitOp unit)
{
  sentient::SyncOp marker_sync_op = nullptr;
  std::vector<sentient::SyncOp> sync_ops_to_insert_nops;

  // step-1: identify the set of explicit syncs to insert NOP immediately before
  // to avoid back to back sync operations.
  unit->walk<WalkOrder::PreOrder>([&](Operation *op) {
    if (auto sync_op = llvm::dyn_cast<sentient::SyncOp>(op)) {
      bool is_soft = sync_op.getSoft().has_value() && sync_op.getSoft().value();
      bool is_send = is_any_of(sync_op.getMode(), SentientSyncMode::send,
                               SentientSyncMode::sendrecv);
      bool is_implicit = sync_op.getImplicitSyncMemoryBoundary().has_value() &&
                         sync_op.getImplicitSyncMemoryBoundary().value() > 0;
      if (!is_implicit && !is_soft && is_send) {
        if (marker_sync_op != nullptr) {
          sync_ops_to_insert_nops.push_back(sync_op);
        }

        marker_sync_op = sync_op;
      }
    } else if (isa<sentient::ForOp, sentient::IfOp, sentient::ReceiveAndStoreOp,
                   sentient::AddOp, sentient::SubOp, sentient::CopyOp>(op)) {
      marker_sync_op = nullptr;
    }
    // we are conservatively ignoring yield operation because we may not know
    // whether it gets manifested or not. If we do it after register allocation,
    // we may know. But, as of this moment, we are conservatively because
    // this bug doesn't happen in our real workloads.
  });

  // step-2: insert nop operations before the identified syncs.
  for (auto sync_op : sync_ops_to_insert_nops) {
    OpBuilder builder(sync_op);
    sentient::NOPOp::create(
        builder, sync_op->getLoc(),
        dcc::utils::getNewDbgNameFromOp(/*prefix*/ "NOPInsB2BS(", sync_op,
                                        /*suffix*/ ")"));
  }
}

