// entry 103/656   level 0   scc 349   15 body lines
// unit: e103_totalTripCount
// authority: dcc/src/Transform/Sentient/OldRegisterInitialization.cpp:198
// original: int RegisterInitInfo::totalTripCount(mlir::Operation *op)
// rust home: crates/compiler/deeptools/src/transform/sentient/old_register_initialization/register_init_info.rs
// ------------------------------------------------------------------------------------------------
int e103_totalTripCount(mlir::Operation *op)
{
  int total_trip_count = 1;
  mlir::Operation *parent = op->getParentOp();
  while (parent) {
    if (auto for_op = llvm::dyn_cast<sentient::ForOp>(parent)) {
      if (auto constant_bound = llvm::dyn_cast<sentient::ConstantOp>(
              for_op.getBound().getDefiningOp())) {
        total_trip_count *= static_cast<int>(constant_bound.getValue());
      }
    }
    parent = parent->getParentOp();
    if (!parent) return total_trip_count;
  }
  return total_trip_count;
}

