// entry 104/656   level 0   scc 350   36 body lines
// unit: e104_getRegisterInitPriority
// authority: dcc/src/Transform/Sentient/OldRegisterInitialization.cpp:214
// original: RegisterInitInfo::RegInitLocalePriority RegisterInitInfo::getRegisterInitPriority(mlir::Value val) const
// rust home: crates/compiler/deeptools/src/transform/sentient/old_register_initialization/register_init_info.rs
// ------------------------------------------------------------------------------------------------
RegisterInitInfo::RegInitLocalePriority
e104_getRegisterInitPriority(mlir::Value val) const
{
  SentientRegType locale = sentient::getValueRegLocale(val);
  // Promoting GTRs requires inter-unit analysis. To avoid this for now,
  // translator sets a flag to let us know when it is safe to do.
  if (locale == SentientRegType::gtr) {
    auto copy_op = dyn_cast_or_null<CopyOp>(val.getDefiningOp());
    if (DoGTRRegInit && copy_op) {
      if (auto mc = dyn_cast_or_null<CreateMulticastGroupOp>(
              copy_op.getInp().getDefiningOp())) {
        return dcc::dataflow::utils::isOptimizable(mc)
                   ? RegInitLocalePriority::kAllowed
                   : RegInitLocalePriority::kNotAllowed;
      } else if (auto mc_map = dyn_cast_or_null<uniform::QueryMapOp>(
                     copy_op.getInp().getDefiningOp())) {
        for (auto val_op :
             dcc::uniform::utils::getListOfValueOpsFromUniformMapping(mc_map)) {
          auto mc =
              dyn_cast_or_null<CreateMulticastGroupOp>(val_op.getDefiningOp());
          if (!mc || !dcc::dataflow::utils::isOptimizable(mc))
            return RegInitLocalePriority::kNotAllowed;
        }
        return RegInitLocalePriority::kAllowed;
      }
    }
    return RegInitLocalePriority::kNotAllowed;
  }
  for (unsigned int i = 0; i < MaxRequiredLocales; i++) {
    if (locale == required_reg_init_locales_[i])
      return RegInitLocalePriority::kRequired;
  }
  for (unsigned int i = 0; i < MaxAllowedLocales; i++) {
    if (locale == allowed_reg_init_locales_[i])
      return RegInitLocalePriority::kAllowed;
  }
  return RegInitLocalePriority::kNotAllowed;
}

