// original: int RegisterInitInfo::weightOfSubset(const std::vector<mlir::Value> &subset)
// rust home: crates/compiler/deeptools/src/transform/sentient/old_register_initialization/register_init_info.rs
// ------------------------------------------------------------------------------------------------
int e105_weightOfSubset(const std::vector<mlir::Value> &subset)
{
  int subset_weight = 0;
  for (auto val : subset) {
    subset_weight += ssa_weight_[val];
  }
  // weight is added twice due to above loop
  subset_weight = subset_weight / 2;
  return subset_weight;
}

