// entry 106/656   level 0   scc 355   18 body lines
// unit: e106_collectAllRegCoalescingCandidatesImpl
// authority: dcc/src/Transform/Sentient/OldRegisterInitialization.cpp:340
// original: void RegisterInitInfo::collectAllRegCoalescingCandidatesImpl( std::vector<mlir::Value> &subset, sentient::ForOp for_op, mlir::Value def)
// rust home: crates/compiler/deeptools/src/transform/sentient/old_register_initialization/register_init_info.rs
// ------------------------------------------------------------------------------------------------
void e106_collectAllRegCoalescingCandidatesImpl(
    std::vector<mlir::Value> &subset, sentient::ForOp for_op, mlir::Value def)
{
  size_t num_region_iter = for_op.getNumRegionIterArgs();
  for (size_t i = 0; i < num_region_iter; i++) {
    auto iter_arg = for_op.getRegionIterArgs()[i];
    if (iter_arg.hasOneUse() && iter_arg == def) {
      subset.push_back(iter_arg);
      auto def1 = for_op.getIterOperands()[i];
      if (auto arg0 = mlir::dyn_cast<mlir::BlockArgument>(def1)) {
        if (auto op1 = arg0.getOwner()->getParentOp()) {
          if (auto for_op1 = llvm::dyn_cast<sentient::ForOp>(op1)) {
            collectAllRegCoalescingCandidatesImpl(subset, for_op1, arg0);
          }
        }
      }
    }
  }
  return;
}

