// ------------------------------------------------------------------------------------------------
bool e107_hasUniformizeRegion(dataflow::ProgramUnitOp unit)
{
  Operation *uniform_op = nullptr;
  unit->walk<WalkOrder::PreOrder>([&uniform_op](mlir::Operation *op) {
    if (isa<uniform::UniformizeRegionsOp, uniform::EqualizePatternOp>(op)) {
      uniform_op = op;
      return WalkResult::interrupt();
    }
    return WalkResult::advance();
  });
  return uniform_op != nullptr;
}

