// entry 108/656   level 0   scc 361   19 body lines
// unit: e108_removeInitAttrFromOps
// authority: dcc/src/Transform/Sentient/OldRegisterInitialization.cpp:686
// original: static void removeInitAttrFromOps(mlir::Operation *parent)
// rust home: crates/compiler/deeptools/src/transform/sentient/old_register_initialization/mod.rs
// ------------------------------------------------------------------------------------------------
void e108_removeInitAttrFromOps(mlir::Operation *parent)
{
  parent->walk([](mlir::Operation *op) {
    if (!op->hasAttr("programHeader")) return WalkResult::advance();
    if (auto copy_op = llvm::dyn_cast_or_null<sentient::CopyOp>(op)) {
      op->setAttr("programHeader", BoolAttr::get(op->getContext(), false));
    } else if (auto for_op = llvm::dyn_cast_or_null<sentient::ForOp>(op)) {
      const auto &program_headers = for_op.getProgramHeaderAttr();
      if (program_headers.empty()) return WalkResult::advance();
      SmallVector<Attribute, 4> new_program_header;
      auto numIter = for_op.getNumIterOperands();
      while (numIter--) {
        new_program_header.push_back(BoolAttr::get(op->getContext(), false));
      }
      op->setAttr("programHeader",
                  ArrayAttr::get(op->getContext(), new_program_header));
    }
    return WalkResult::advance();
  });
}

