// unit: e112_isSameOpType
// authority: dcc/src/Transform/Sentient/OldRegisterInitialization.cpp:1087
// original: bool RegisterInitCandidatePromoter::isSameOpType(mlir::Value val1, mlir::Value val2) const
// rust home: crates/compiler/deeptools/src/transform/sentient/old_register_initialization/register_init_candidate_promoter.rs
// ------------------------------------------------------------------------------------------------
bool e112_isSameOpType(mlir::Value val1,
                                                 mlir::Value val2) const
{
  if (val1 && val2) {
    auto def1 = val1.getDefiningOp();
    auto def2 = val2.getDefiningOp();
    if (isa<sentient::ConstantOp>(def1) && isa<sentient::ConstantOp>(def2))
      return true;
    if (isa<mlir::symbol::CreateSymbolOp>(def1) &&
        isa<mlir::symbol::CreateSymbolOp>(def2))
      return true;
    if (isa<dataflow::CreateMulticastGroupOp>(def1) &&
        isa<dataflow::CreateMulticastGroupOp>(def2))
      return true;
    if (isa<dataflow::GetUnitOp>(def1) && isa<dataflow::GetUnitOp>(def2))
      return true;
    return false;
  }
  return true;
}

