// ------------------------------------------------------------------------------------------------
// entry 118/656   level 0   scc 330   59 body lines
// unit: e118_areOperandsMatching
// authority: dcc/src/Transform/Sentient/OpRerolling.cpp:668
// original: bool UnrollOperands::areOperandsMatching( const StringRef &ref_operand, const bool &is_ref_unrolled, const StringRef &curr_operand, const bool &is_curr_unrolled, const UnrollOperands &curr_operand_list, const bool is_xrf_read)
// rust home: crates/compiler/deeptools/src/transform/sentient/op_rerolling/unroll_operands.rs
// ------------------------------------------------------------------------------------------------
bool e118_areOperandsMatching(
    const StringRef &ref_operand, const bool &is_ref_unrolled,
    const StringRef &curr_operand, const bool &is_curr_unrolled,
    const UnrollOperands &curr_operand_list, const bool is_xrf_read)
{
  if (!(ref_operand.contains("lrf") || ref_operand.contains("istate")) ||
      !(curr_operand.contains("lrf") || curr_operand.contains("istate"))) {
    // for non-lrf non-istate including xrf, reg, constants, forwarding targets,
    // ref_operand and curr_operand must be the same
    if (ref_operand != curr_operand) return false;

    // match xrf incr values if applicable
    if (ref_operand.contains("xrf")) {
      if (is_xrf_read) {
        if (xrf_read_incr_ != 0) {
          // as long as the xrf read ptr increment value of the ref macOp is
          // zero, it is ok to reroll the current macOp into the ref macOp. when
          // the xrf read increment value of the current macOp is non-zero, the
          // rerolling process should terminate at the current macOp.
          return false;
        }
      } else {
        if (xrf_write_incr_ != unroll_size_ ||
            curr_operand_list.xrf_write_incr_ !=
                curr_operand_list.unroll_size_) {
          // xrf write ptr increments by 1 for each mac execution including
          // instances within unrolling factor. In order to merge 2
          // macOps, their xrfWtPtrIncr values must be equal to the
          // unrolling factor.
          return false;
        }
      }
    }
  } else {
    auto curr_unroll_size = curr_operand_list.unroll_size_;
    // for lrf/istate, matching requires either dist(curr,ref) = unroll_size_ or
    // same value for initial comparison (unroll_size_=1)
    bool is_lrf = (ref_operand.contains("lrf") && curr_operand.contains("lrf"));
    int index_gap =
        is_lrf ? getLrfIndex(curr_operand) - getLrfIndex(ref_operand)
               : getIStateIndex(curr_operand) - getIStateIndex(ref_operand);
    if (index_gap < 0) return false;
    // if the current op's operand is unrolled, index_gap must equal to
    // unroll_size to make a match and ref operand's unroll_size must equal to 1
    // if ref operand is non-unrolled.
    if (is_curr_unrolled &&
        (index_gap != unroll_size_ || (!is_ref_unrolled && unroll_size_ > 1)))
      return false;
    // if the current op's operand is not unrolled while ref op's is, index_gap
    // must equal to unroll_size and curr_op's unroll_size must equal to 1.
    if (!is_curr_unrolled && is_ref_unrolled &&
        (index_gap != unroll_size_ || curr_unroll_size > 1))
      return false;
    // if both operands are not unrolled, index_gap must equal to 0 if any
    // unroll_size > 1 and index_gap must be 1/0 if both unroll_size ==1
    if (!is_curr_unrolled && !is_ref_unrolled &&
        ((unroll_size_ * curr_unroll_size > 1 && index_gap != 0) ||
         (unroll_size_ * curr_unroll_size == 1 && index_gap > 1)))
      return false;
  }

  return true;
}

