// authority: dcc/src/Transform/Sentient/OpRerolling.cpp:926
// original: StringAttr UnrollOperands::createOperand(OperandName op_name, unsigned new_unroll_size)
// rust home: crates/compiler/deeptools/src/transform/sentient/op_rerolling/unroll_operands.rs
// ------------------------------------------------------------------------------------------------
StringAttr e119_createOperand(OperandName op_name,
                                         unsigned new_unroll_size)
{
  StringRef ret = operand_list_[op_name];
  std::string ret_str = "lrf";
  if (is_field_unroll_[op_name] && ret.contains("lrf")) {
    unsigned lrf_idx = getLrfIndex(ret) + (unroll_size_ - new_unroll_size);
    ret_str = ret_str + std::to_string(lrf_idx);
    ret = StringRef(ret_str);
  }

  return StringAttr::get(context, ret);
}

