// rust home: crates/compiler/deeptools/src/transform/sentient/op_rerolling/unroll_operands.rs
// ------------------------------------------------------------------------------------------------
SmallVector<Attribute, 4> e120_createForwardingArray(
    OperandName op_name, unsigned new_unroll_size)
{
  SmallVector<Attribute, 4> ret;
  for (auto fwd_operand : forwarding_list_[op_name]) {
    std::string tmp_str;
    if (op_name == result && is_field_unroll_[op_name] &&
        fwd_operand.contains("lrf")) {
      unsigned lrf_idx =
          getLrfIndex(fwd_operand) + (unroll_size_ - new_unroll_size);
      tmp_str = "lrf" + std::to_string(lrf_idx);
      fwd_operand = tmp_str;
    }
    ret.push_back(SentientComputePortAttr::get(
        context, symbolizeSentientComputePort(fwd_operand).value()));
  }

  return ret;
}

