// ------------------------------------------------------------------------------------------------
void e121_dump() const
{
  auto toString = [&](OperandName name) {
    switch (name) {
      case op_a:
        return "op_a";
      case op_b:
        return "op_b";
      case op_c:
        return "op_c";
      case result:
        return "result";
      case logical_result:
        return "logical_result";
      default:
        return "unknown operand name";
    }
  };

  llvm::outs() << "dumping:" << "\n";
  for (auto i : operand_list_) {
    llvm::outs() << toString(i.first) << ": " << i.second.str() << "\n";
  }

  for (auto i : is_field_unroll_) {
    llvm::outs() << toString(i.first) << ": " << i.second << "\n";
  }
}

