// entry 126/656   level 0   scc 388   29 body lines
// unit: e126_IsSwappablePerAlgebraicReassociation
// authority: dcc/src/Transform/Sentient/PortAssignment.cpp:606
// original: int PortAssignmentPass::IsSwappablePerAlgebraicReassociation(Operation *op)
// rust home: crates/compiler/deeptools/src/transform/sentient/port_assignment/mod.rs
// ------------------------------------------------------------------------------------------------
int e126_IsSwappablePerAlgebraicReassociation(Operation *op)
{
  if (auto mac_op = llvm::dyn_cast<sentient::MacOp>(op)) {
    StringRef operand_value;
    if ((mac_op.getOpA() == SentientComputePort::zero ||
         mac_op.getOpB() == SentientComputePort::zero ||
         mac_op.getOpC() == SentientComputePort::zero) &&
        (mac_op.getOpA() == SentientComputePort::one ||
         mac_op.getOpB() == SentientComputePort::one ||
         mac_op.getOpC() == SentientComputePort::one)) {
      if (mac_op.getOpA() != SentientComputePort::zero &&
          mac_op.getOpA() != SentientComputePort::one) {
        return 0;
      } else if (mac_op.getOpB() != SentientComputePort::zero &&
                 mac_op.getOpB() != SentientComputePort::one) {
        return 1;
      } else if (mac_op.getOpC() != SentientComputePort::zero &&
                 mac_op.getOpC() != SentientComputePort::one) {
        return 2;
      } else {
        // none of the input are value. thus no need to swap
        return -1;
      }
    } else {
      // the input does not have enough 0/1s to validate the swap
      return -1;
    }
  }
  return -1;
}

