// rust home: crates/compiler/deeptools/src/transform/sentient/read_only_register_renumbering/mod.rs
// ------------------------------------------------------------------------------------------------
void e128_doRenumbering()
{
    if (unsafe_to_renumber_) return;
    for (auto candidate : candidates_) {
      DT_CHECK_MSG(candidate.getOp()->getNumResults() == 1,
                   "expected a single result");
      LLVM_DEBUG({
        int old_index = getValueRegIndex(candidate.getOp()->getResult(0));
        llvm::dbgs() << "Renumbering register:" << old_index
                     << " to: " << candidate.getNewRegisterIndex()
                     << " in op:" << *candidate.getOp() << "\n";
      });
      setValueRegIndex(candidate.getOp()->getResult(0),
                       candidate.getNewRegisterIndex());
    }
  }

