// entry 130/656   level 0   scc 403   46 body lines
// unit: e130_runOn
// authority: dcc/src/Transform/Sentient/ReadOnlyRegisterRenumbering.cpp:199
// original: void ReadOnlyRegisterRenumberingPass::runOn(Operation *op)
// rust home: crates/compiler/deeptools/src/transform/sentient/read_only_register_renumbering/mod.rs
// ------------------------------------------------------------------------------------------------
void e130_runOn(Operation *op)
{
  if (unsafe_to_renumber_) return;
  if (!isa<sentient::CopyOp>(op)) return;
  sentient::CopyOp copy_op = cast<sentient::CopyOp>(op);
  if (copy_op.getRegLocale() != SentientRegType::lbr) return;
  DT_CHECK_MSG(isConstant<sentient::ConstantOp>(copy_op.getInp()),
               "LBR has to be initialized from a constant");
  AddrTy lbr_addr = -1;
  if (auto const_op = copy_op.getInp().getDefiningOp<sentient::ConstantOp>()) {
    lbr_addr = const_op.getValue();
  } else if (auto query_op =
                 copy_op.getInp().getDefiningOp<uniform::QueryMapOp>()) {
    std::vector<AddrTy> const_values =
        dcc::uniform::utils::getConstantTargetValues(query_op);
    if (isConstant<sentient::ConstantOp>(query_op) &&
        llvm::all_of(const_values,
                     [&](AddrTy val) { return val == const_values.front(); }))
      // If query map is constant and all constants match,
      // then all values assigned to this register are the same.
      lbr_addr = const_values.front();
    else {
      // Not all values assigned to this register are the same, which means we
      // cannot do value-based register renumbering.
      unsafe_to_renumber_ = true;
      LLVM_DEBUG(llvm::dbgs()
                 << "Unable to re-number LBR indices because not all query map "
                    "ops resolve to the same constant:"
                 << copy_op << "\n");
      return;
    }
  }
  DT_CHECK_MSG(lbr_addr >= 0, "unable to identify the lbr address");
  int element_size =
      copy_op->hasAttr("element_size")
          ? mlir::cast<::mlir::IntegerAttr>(copy_op->getAttr("element_size"))
                .getInt()
          : -1;
  if (element_size == -1) {
    unsafe_to_renumber_ = true;
    LLVM_DEBUG(llvm::dbgs() << "Unable to re-number LBR indices because of "
                               "indeterminate element size:"
                            << copy_op << "\n");
    return;
  }
  candidates_.emplace_back(op, lbr_addr, element_size);
}

