// entry 131/656   level 0   scc 407   21 body lines
// unit: e131_runLocalAnalysis
// authority: dcc/src/Transform/Sentient/RegisterInitialization.cpp:136
// original: void runLocalAnalysis(ListOfCandidatesRef &result)
// rust home: crates/compiler/deeptools/src/transform/sentient/register_initialization/mod.rs
// ------------------------------------------------------------------------------------------------
void e131_runLocalAnalysis(ListOfCandidatesRef &result)
{
    // First collect candidates that are already in the global region.
    SmallVector<Candidate *, kTypicalGlobalCandidates> global_candidates;
    collector_.collectGlobalCandidates(global_candidates);
    evaluator_.evaluateLocally(global_candidates);

    for (mlir::Value core : uga_.getGroupLeaders()) {
      SmallVector<Candidate *, kTypicalPerLocalCandidates> local_candidates;
      collector_.collectLocalCandidates(core, local_candidates);
      evaluator_.evaluateLocally(local_candidates);
      selector_.selectLocally(local_candidates, global_candidates, core);
      evaluator_.mergeInto(result, local_candidates);
    }
    // Insert the (potentially pruned) global candidates and sort again.
    // Note that we insert globals now (instead of earlier) since a selector may
    // choose to purge the original list of globals (for example to only keep
    // global candidates that are selected by *ALL* local region selections,
    // and thereby avoid extra colorability checks during the global analysis
    // stage).
    evaluator_.mergeInto(result, global_candidates);
  }

