// rust home: crates/compiler/deeptools/src/transform/sentient/register_packing/mod.rs
// ------------------------------------------------------------------------------------------------
std::pair<SentientRegType, int> e135_getRegTypeAndIndex(
    mlir::Operation *op, int idx)
{
  if (op->hasAttr("regIndex")) {
    DT_CHECK(op->hasAttr("regLocale"));
    auto op_reg_type_attr =
        llvm::dyn_cast<SentientRegTypeAttr>(op->getAttr("regLocale"));
    DT_CHECK(op_reg_type_attr);
    auto op_reg_index_attr =
        llvm::dyn_cast<IntegerAttr>(op->getAttr("regIndex"));
    DT_CHECK(op_reg_index_attr);
    return std::make_pair(op_reg_type_attr.getValue(),
                          op_reg_index_attr.getInt());
  }
  DT_CHECK(op->hasAttr("regIndices") && op->hasAttr("regLocales"));
  auto op_reg_index_attr = llvm::dyn_cast<IntegerAttr>(
      mlir::cast<ArrayAttr>(op->getAttr("regIndices"))[idx]);
  DT_CHECK(op_reg_index_attr);
  auto op_reg_type_attr = llvm::dyn_cast<SentientRegTypeAttr>(
      mlir::cast<ArrayAttr>(op->getAttr("regLocales"))[idx]);
  DT_CHECK(op_reg_type_attr);
  return std::make_pair(op_reg_type_attr.getValue(),
                        op_reg_index_attr.getInt());
}

