// entry 136/656   level 0   scc 418   31 body lines
// unit: e136_fillTypedRegCollection
// authority: dcc/src/Transform/Sentient/RegisterPacking.cpp:298
// original: void RegisterPackingPass::fillTypedRegCollection( TypedRegCollection *typed_reg_collec, mlir::Value init_value, mlir::Value res_value, int64_t reg_index, bool is_header_promoted)
// rust home: crates/compiler/deeptools/src/transform/sentient/register_packing/mod.rs
// ------------------------------------------------------------------------------------------------
void e136_fillTypedRegCollection(
    TypedRegCollection *typed_reg_collec, mlir::Value init_value,
    mlir::Value res_value, int64_t reg_index, bool is_header_promoted)
{
  if (is_header_promoted) {
    if (isa<sentient::ConstantOp>(init_value.getDefiningOp())) {
      typed_reg_collec->getRegistersList().push_back(
          RegIndex(res_value, reg_index, is_header_promoted,
                   /*has_same_value_in_all_units = */ true));
    } else if (isa<symbol::CreateSymbolOp>(init_value.getDefiningOp())) {
      typed_reg_collec->getRegistersList().push_back(
          RegIndex(res_value, reg_index, is_header_promoted,
                   /*has_same_value_in_all_units = */ true));
    } else if (auto query_op = llvm::dyn_cast<uniform::QueryMapOp>(
                   init_value.getDefiningOp())) {
      auto const_values =
          dcc::uniform::utils::getConstantTargetValues(query_op);
      if (llvm::all_of(const_values, [&](int64_t val) {
            return val == const_values.front();
          })) {
        typed_reg_collec->getRegistersList().push_back(
            RegIndex(res_value, reg_index, is_header_promoted,
                     /*has_same_value_in_all_units = */ true));
      } else {
        typed_reg_collec->getRegistersList().push_back(
            RegIndex(res_value, reg_index, is_header_promoted,
                     /*has_same_value_in_all_units = */ false));
      }
    }
  } else {
    typed_reg_collec->getRegistersList().push_back(
        RegIndex(res_value, reg_index));
  }
}

