// ------------------------------------------------------------------------------------------------
bool e142_isCopyNeeded(
    mlir::Value val, RegisterTypeAssignmentPass::RegisterLocales locale)
{
  if (!this->addScalarCopies || locale == Unrelated) return false;
  auto record = assignments_.find(val);
  if (record != assignments_.end() && record->second != locale) {
    DT_CHECK_MSG(record->second == IMM,
                 "multiple assignments to the same variable");
    return true;
  }
  return false;
}

