// original: bool isCandidateForRematerialization(Operation *op)
// rust home: crates/compiler/deeptools/src/transform/sentient/rematerialization_pass/mod.rs
// ------------------------------------------------------------------------------------------------
bool e145_isCandidateForRematerialization(Operation *op)
{
    if (auto add_op = llvm::dyn_cast<sentient::AddOp>(op))
      return (!isa<BlockArgument>(add_op.getInp1()) &&
              isa<sentient::ConstantOp>(add_op.getInp1().getDefiningOp())) ||
             (!isa<BlockArgument>(add_op.getInp2()) &&
              isa<sentient::ConstantOp>(add_op.getInp2().getDefiningOp()));
    else if (auto sub_op = llvm::dyn_cast<sentient::SubOp>(op))
      return (!isa<BlockArgument>(sub_op.getInp1()) &&
              isa<sentient::ConstantOp>(sub_op.getInp1().getDefiningOp())) ||
             (!isa<BlockArgument>(sub_op.getInp2()) &&
              isa<sentient::ConstantOp>(sub_op.getInp2().getDefiningOp()));
    else if (auto copy_op = llvm::dyn_cast<sentient::CopyOp>(op))
      return isa<sentient::ConstantOp>(copy_op.getInp().getDefiningOp());
    return false;
  }

