// authority: dcc/src/Transform/Sentient/RematerializationPass.cpp:82
// original: Operation *getLastUseWithinBlock(Value v, Block *bb)
// rust home: crates/compiler/deeptools/src/transform/sentient/rematerialization_pass/mod.rs
// ------------------------------------------------------------------------------------------------
Operation *e146_getLastUseWithinBlock(Value v, Block *bb)
{
    DT_CHECK_MSG(!isa<BlockArgument>(v),
                 "Function should not be called on an iter arg");
    if (v.use_empty()) return nullptr;

    Operation *last_use = nullptr;
    for (auto &use : v.getUses()) {
      Operation *use_ancestor_within_block =
          bb->findAncestorOpInBlock(*use.getOwner());
      if (!use_ancestor_within_block) continue;

      if (!last_use) {
        last_use = use_ancestor_within_block;
      } else {
        if (dom_info_->dominates(last_use, use_ancestor_within_block))
          last_use = use_ancestor_within_block;
      }
    }
    return last_use;
  }

