// entry 148/656   level 0   scc 455   19 body lines
// unit: e148_collectResultsOfNonYieldFeedingUsers
// authority: dcc/src/Transform/Sentient/ReuseLoopIteratorArguments.cpp:411
// original: llvm::SmallVector<Value> ReuseLoopIteratorArgumentsPass::collectResultsOfNonYieldFeedingUsers( BlockArgument iter_arg, sentient::YieldOp yield_op) const
// rust home: crates/compiler/deeptools/src/transform/sentient/reuse_loop_iterator_arguments/mod.rs
// ------------------------------------------------------------------------------------------------
llvm::SmallVector<Value>
e148_collectResultsOfNonYieldFeedingUsers(
    BlockArgument iter_arg, sentient::YieldOp yield_op) const
{
  llvm::SmallVector<Value> results;
  for (auto &use : iter_arg.getUses()) {
    Operation *user = use.getOwner();

    // Skip users that are Add/Sub ops feeding the yield
    if (isa<sentient::AddOp, sentient::SubOp>(user) &&
        yield_op.getOperand(iter_arg.getArgNumber() - 1) ==
            user->getResults()[0])
      continue;

    unsigned operand_num = use.getOperandNumber();
    Value user_result =
        dcc::utils::getResultCorrespondingToOperandNum(user, operand_num);
    DT_CHECK(user_result);
    results.push_back(user_result);
  }
  return results;
}

