// entry 149/656   level 0   scc 465   18 body lines
// unit: e149_collectOpsOfInterest
// authority: dcc/src/Transform/Sentient/ScalarCopyInsertionForSymbols.cpp:217
// original: void ScalarCopyInsertionForSymbolsPass::collectOpsOfInterest( dataflow::ProgramUnitOp unit)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_copy_insertion_for_symbols/mod.rs
// ------------------------------------------------------------------------------------------------
void e149_collectOpsOfInterest(
    dataflow::ProgramUnitOp unit)
{
  DT_CHECK(scalar_copy_ops_.empty());
  DT_CHECK(outermost_loops_.empty());
  unit->walk([&](Operation *op) {
    if (auto scalar_copy = dyn_cast<sentient::CopyOp>(op)) {
      scalar_copy_ops_.push_back(scalar_copy);
    } else if (auto loop = dyn_cast<sentient::ForOp>(op)) {
      if (dcc::utils::isOuterMostLoop(loop)) outermost_loops_.push_back(loop);
    } else if (isa<symbol::SymbolQueryMapOp>(op)) {
      symbol_queries_.push_back(op->getResult(0));
    } else if (auto create_sym = dyn_cast<symbol::CreateSymbolOp>(op)) {
      op->emitWarning(
          "skipping misplaced create_symbol op (should be in the function "
          "scope)");
    }
    return WalkResult::advance();
  });
}

// ------------------------------------------------------------------------------------------------
// entry 150/656   level 0   scc 460   20 body lines
// unit: e150_pessimizeLiveness
// authority: dcc/src/Transform/Sentient/ScalarCopyInsertionForSymbols.cpp:276
// original: void ScalarCopyInsertionForSymbolsPass::pessimizeLiveness(Liveness &liveness)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_copy_insertion_for_symbols/mod.rs
// ------------------------------------------------------------------------------------------------
void e150_pessimizeLiveness(Liveness &liveness)
{
  for (sentient::CopyOp copy : scalar_copy_ops_) {
    Value copy_res = copy.getResult();
    if (symbolic_locales_.contains(sentient::getValueRegLocale(copy_res)))
      liveness.updateLiveRangesForProgramHeaderPromotion(copy.getResult());
  }

  for (sentient::ForOp loop : outermost_loops_) {
    for (int i = 0; i < loop.getNumRegionIterArgs(); i++) {
      auto iter_arg_init = loop.getIterOperands()[i];
      if (!dcc::utils::isConstant<sentient::ConstantOp>(iter_arg_init) &&
          !dcc::utils::isSymbol(iter_arg_init))
        continue;
      Value iter_arg = loop.getRegionIterArgs()[i];
      if (!symbolic_locales_.contains(sentient::getValueRegLocale(iter_arg)))
        continue;
      liveness.updateLiveRangesForProgramHeaderPromotion(iter_arg);
    }
  }
}

// ------------------------------------------------------------------------------------------------
// entry 151/656   level 0   scc 462   23 body lines
// unit: e151_insertCopyOpsForJCRCandidate
// authority: dcc/src/Transform/Sentient/ScalarCopyInsertionForSymbols.cpp:416
// original: void ScalarCopyInsertionForSymbolsPass::insertCopyOpsForJCRCandidate( dataflow::ProgramUnitOp unit, const CandidateEntryTy candidate) const
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_copy_insertion_for_symbols/mod.rs
// ------------------------------------------------------------------------------------------------
void e151_insertCopyOpsForJCRCandidate(
    dataflow::ProgramUnitOp unit, const CandidateEntryTy candidate) const
{
  const Value symbol = candidate.first;
  const SentientRegType locale = candidate.second;
  DT_CHECK(locale == SentientRegType::lccr || locale == SentientRegType::jcr);
  Operation *new_copy_op = nullptr;
  for (OpOperand *opnd : symbol_to_usage_.at(symbol).at(locale)) {
    Operation *user = opnd->getOwner();
    // Create JCR scalar_copy ops at the top of the unit, since
    // RegisterInitialization does not promote JCR register inits.
    if (!new_copy_op) {
      OpBuilder builder(unit.getRegion());
      if (isa<symbol::SymbolQueryMapOp>(symbol.getDefiningOp())) {
        // hopefully symbol_query ops are positioned optimally (ie at highest
        // invariant point in the code)
        builder.setInsertionPointAfter(symbol.getDefiningOp());
      }
      new_copy_op =
          sentient::CopyOp::create(builder, user->getLoc(), symbol.getType(),
                                   symbol, SentientRegType::jcr);
    }
    opnd->assign(new_copy_op->getResult(0));
  }
}

