// ------------------------------------------------------------------------------------------------
// entry 153/656   level 0   scc 467   26 body lines
// unit: e153_getLocale
// authority: dcc/src/Transform/Sentient/ScalarCopyInsertionForSymbols.cpp:449
// original: SentientRegType ScalarCopyInsertionForSymbolsPass::getLocale(OpOperand &use)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_copy_insertion_for_symbols/mod.rs
// ------------------------------------------------------------------------------------------------
SentientRegType e153_getLocale(OpOperand &use)
{
  Operation *user_op = use.getOwner();
  if (auto for_op = dyn_cast<sentient::ForOp>(user_op)) {
    Value val = for_op.getBody()->getArgument(use.getOperandNumber());
    return sentient::getValueRegLocale(val);
  } else if (auto yield_op = dyn_cast<sentient::YieldOp>(user_op)) {
    Operation *parent_op = yield_op->getParentOp();
    DT_CHECK_MSG(parent_op->hasAttr(sentient::getRegLocalesAttrStrName()),
                 "expected locale info to be available...perhaps this pass is "
                 "being run before type assignment");
    auto attrs = mlir::cast<ArrayAttr>(
        parent_op->getAttr(sentient::getRegLocalesAttrStrName()));
    return mlir::cast<SentientRegTypeAttr>(attrs[use.getOperandNumber()])
        .getValue();
  } else if (isa<sentient::AddOp>(user_op)) {
    auto addOp = cast<sentient::AddOp>(user_op);
    return addOp.getRegLocale();
  } else if (isa<sentient::SubOp>(user_op)) {
    auto subOp = cast<sentient::SubOp>(user_op);
    return subOp.getRegLocale();
  }
  constexpr const char *msg = "unimplemented support for this type of user";
  user_op->emitError(msg);
  DT_ERROR(msg);
  return SentientRegType::unknown;
}

// ------------------------------------------------------------------------------------------------
// entry 154/656   level 0   scc 461   24 body lines
// unit: e154_propagateElementSizeToCopyOp
// authority: dcc/src/Transform/Sentient/ScalarCopyInsertionForSymbols.cpp:476
// original: bool ScalarCopyInsertionForSymbolsPass::propagateElementSizeToCopyOp( OpOperand &opnd, sentient::CopyOp copy_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_copy_insertion_for_symbols/mod.rs
// ------------------------------------------------------------------------------------------------
bool e154_propagateElementSizeToCopyOp(
    OpOperand &opnd, sentient::CopyOp copy_op)
{
  Operation *user = opnd.getOwner();
  if (user->hasAttr("element_size") || user->hasAttr("element_sizes")) {
    DT_CHECK_MSG(user->getNumResults() == 1,
                 "propagation of element size is not implemented for this use");
    copy_op->setAttr("element_size", user->getAttr("element_size"));
    return true;
  } else if (auto yield_op = dyn_cast<sentient::YieldOp>(user)) {
    Operation *parent_op = yield_op->getParentRegion()->getParentOp();
    DT_CHECK_MSG(
        isa<sentient::ForOp>(parent_op) || isa<sentient::IfOp>(parent_op),
        "propagation of element size is not implemented for this use");
    if (parent_op->hasAttr("element_sizes")) {
      const int elem_size_idx = isa<sentient::ForOp>(parent_op)
                                    ? opnd.getOperandNumber() + 1
                                    : opnd.getOperandNumber();
      copy_op->setAttr(
          "element_size",
          cast<ArrayAttr>(parent_op->getAttr("element_sizes"))[elem_size_idx]);
      return true;
    }
  }
  return false;
}

