// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/mod.rs
// ------------------------------------------------------------------------------------------------
bool e158_doesValueExceedLRFRange(const SenSystemDef &sys_def,
                                    const EvaluatedValue &value_ev,
                                    int element_size, SenComponents comp,
                                    int address_granularity_scale)
{
  // This will only be run in LX/L0 where the reg types for eligible operations
  // will always be LRF.
  DT_CHECK(is_any_of(comp, LXLU, LXSU, L0LU, L0SU));
  auto reg_bitwidth = sys_def.regInfoPerUnit.at(comp).at(RegType::LRF).bitSize;
  int min_val = -(0x1 << reg_bitwidth);
  int max_val = (0x1 << reg_bitwidth) - 1;
  if (auto *au = dyn_cast<AllUnitEvaluatedValue>(&value_ev)) {
    int new_immutable_imm = au->offsetValue() * (float)element_size / 8.0 /
                            (float)address_granularity_scale;
    if (new_immutable_imm < min_val || new_immutable_imm > max_val) return true;
  } else if (auto *pu = dyn_cast<PerUnitEvaluatedValue>(&value_ev)) {
    for (auto record : pu->offsetValuesPerUnit()) {
      int new_immutable_imm = record.second * (float)element_size / 8.0 /
                              (float)address_granularity_scale;
      if (new_immutable_imm < min_val || new_immutable_imm > max_val)
        return true;
    }
  }
  return false;
}

