// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/mod.rs
// ------------------------------------------------------------------------------------------------
int e159_computeAddressScale(SenComponents comp,
                                 const dcc::DccExtContext &dcc_ext_context)
{
    if (is_any_of(comp, LXLU, LXSU))
      return dcc_ext_context.getAddressGranularityScale({comp, LX});
    if (is_any_of(comp, L0LU, L0SU))
      return dcc_ext_context.getAddressGranularityScale({comp, L0});
    return -1;
  }

