// ------------------------------------------------------------------------------------------------
e160_MemoryOpInfo(Operation *op)
{
    if (auto las = dyn_cast<sentient::LoadAndSendOp>(op)) {
      mutable_addr_ = las.getMutableAddr();
      immutable_addr_ = las.getImmutableAddr();
      increment_ = las.getIncrement();

      int b = las.getBurstSize();
      if (b > 0) burst_ = b;

      int i = las.getInterleavedGroup();
      if (i > 0) il_ = i;

      element_size_ = las.getElementSize();
      total_elements_ = las.getTotalElements();
      chunk_size_ = las.getChunkSize();
      chunk_stride_ = las.getChunkStride();
    } else if (auto ras = dyn_cast<sentient::ReceiveAndStoreOp>(op)) {
      mutable_addr_ = ras.getMutableAddr();
      immutable_addr_ = ras.getImmutableAddr();
      increment_ = ras.getIncrement();

      int b = ras.getBurstSize();
      if (b > 0) burst_ = b;

      int i = ras.getInterleavedGroup();
      if (i > 0) il_ = i;

      element_size_ = ras.getElementSize();
      total_elements_ = ras.getTotalElements();
    } else if (auto lcas = dyn_cast<sentient::LoadComputeAndSendOp>(op)) {
      mutable_addr_ = lcas.getMutableAddr();
      immutable_addr_ = lcas.getImmutableAddr();
      increment_ = lcas.getIncrement();
      // For LoadComputeAndSendOps the dst_element_size indicates how the
      // address should be calculated.
      element_size_ = lcas.getDstElementSize();
    }
  }

