// entry 165/656   level 0   scc 491   24 body lines
// unit: e165_calculateIBuffRequired
// authority: dcc/src/Transform/Sentient/ScalarOpMergingAndHoisting.cpp:591
// original: template <class OpTy> int ScalarOpMerging::calculateIBuffRequired(Operation *op)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_merging.rs
// ------------------------------------------------------------------------------------------------
template <class OpTy>
int e165_calculateIBuffRequired(Operation *op)
{
  DT_CHECK_MSG(op && isa<OpTy>(op), "expected valid operation");
  DT_CHECK(isa<sentient::LoadAndSendOp>(op) ||
           isa<sentient::ReceiveAndStoreOp>(op) &&
               "expected load_and_send or receive_and_store");
  auto mem_op = cast<OpTy>(op);
  int additional_req_ibuff = 0;

  // Additional IBuff will equal the burst size * interleaved group.
  // Note if burst or IL are less than 1, they are set to 1 for purpose of the
  // calculation.
  int burst = (int)mem_op.getBurstSize();
  burst = (burst > 1) ? burst : 1;
  additional_req_ibuff += burst;

  int il = (int)mem_op.getInterleavedGroup();
  il = (il > 1) ? il : 1;
  additional_req_ibuff *= il;

  // Additional IBuff required is one less since the operation itself already
  // consumes one IBuff and candidates are only those that will not require a
  // copy op.
  return (additional_req_ibuff - 1);
}

// ------------------------------------------------------------------------------------------------
// entry 166/656   level 0   scc 482   29 body lines
// unit: e166_isProfitableForHoisting
// authority: dcc/src/Transform/Sentient/ScalarOpMergingAndHoisting.cpp:837
// original: bool ScalarOpMerging::isProfitableForHoisting(ScalarOpMergingBlock &block)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_merging.rs
// ------------------------------------------------------------------------------------------------
bool e166_isProfitableForHoisting(ScalarOpMergingBlock &block)
{
  // Blocks are formed in reverse order so the front of the block is closest
  // to the bottom of the containing Region. This operation will be the scalar
  // op merging candidate.
  auto &block_ops = block.getBlockOps();
  Operation *last_op_in_block = block_ops.front().getOp();

  auto for_op = dyn_cast_or_null<sentient::ForOp>(
      last_op_in_block->getParentRegion()->getParentOp());
  if (!for_op) return false;

  Value input_val = block.getInputValueToBlock();
  if (!input_val.hasOneUse()) return false;

  for (int idx = 0; idx < for_op.getNumRegionIterArgs(); ++idx) {
    auto iter_arg = for_op.getRegionIterArgs()[idx];

    if (iter_arg != input_val) continue;

    // Operations in a Scalar Op Merging block only have one use. Check the one
    // use is a yield feeding back to the iter_arg.
    Operation *last_op_user = *last_op_in_block->getUsers().begin();
    if (auto yieldOp = dyn_cast<sentient::YieldOp>(last_op_user)) {
      if (yieldOp.getOperand(idx) == last_op_in_block->getResult(0))
        return true;
    }
  }
  return false;
}

// ------------------------------------------------------------------------------------------------
// entry 167/656   level 0   scc 483   19 body lines
// unit: e167_sortBlocks
// authority: dcc/src/Transform/Sentient/ScalarOpMergingAndHoisting.cpp:910
// original: void ScalarOpMerging::sortBlocks()
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_merging.rs
// ------------------------------------------------------------------------------------------------
void e167_sortBlocks()
{
  auto GetBlockRatio = [](ScalarOpMergingBlock block) -> float {
    int required_ibuff = block.getRequiredIBuff();
    // If the block requires additional IBuff, its benefit ratio needs to be
    // calculated. The higher the ratio, the higher the benefit.
    if (required_ibuff != 0)
      return (float)block.getNumScalarOpsInBlock() / (float)required_ibuff;
    // Blocks that do not require additional IBuff have highest priority so
    // their ratio is set to a high enough value they will always beat blocks
    // that do require additional IBuff.
    // Note: Blocks that do not require IBuff will always be transformed
    //       regardless of where they are in the list.
    return 1000.0;
  };
  // Sort the blocks in descending order based on their impact ratio.
  std::sort(blocks_.begin(), blocks_.end(),
            [&](const ScalarOpMergingBlock &a, const ScalarOpMergingBlock &b)
                -> bool { return GetBlockRatio(a) > GetBlockRatio(b); });
}

