// entry 168/656   level 0   scc 492   51 body lines
// unit: e168_unrollBurstAndIL
// authority: dcc/src/Transform/Sentient/ScalarOpMergingAndHoisting.cpp:1011
// original: template <class OpTy> SmallVector<Operation *> ScalarOpMerging::unrollBurstAndIL( FieldUnrollData &unroll_candidate)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_merging.rs
// ------------------------------------------------------------------------------------------------
template <class OpTy>
SmallVector<Operation *> e168_unrollBurstAndIL(
    FieldUnrollData &unroll_candidate)
{
  Operation *candidate_op = unroll_candidate.getOp();
  DT_CHECK_MSG(candidate_op, "expecting valid op for unroll candidate");
  OpTy op = dyn_cast<OpTy>(candidate_op);
  DT_CHECK(op &&
           (isa<sentient::LoadAndSendOp>(candidate_op) ||
            isa<sentient::ReceiveAndStoreOp>(candidate_op)) &&
           "expecting a LoadAndSend/ReceiveAndStore op");
  auto immutables = unroll_candidate.getSpeculativeImmutables();

  auto parent_unit = op->template getParentOfType<dataflow::ProgramUnitOp>();
  DT_CHECK_MSG(parent_unit, "Could not determine parent program_unit!");
  sentient::ConstantOp zero_const =
      sentient::ConstantOp::create(getConstBuilder(), parent_unit.getLoc(),
                                   getConstBuilder().getIndexType(), 0);

  // Unroll the op. Ops are unrolled top down but the speculative immutables are
  // in reverse order so iterate through the immutables in reverse.
  OpBuilder builder(op);
  builder.setInsertionPointAfter(op);
  Value input_to_next_op = op.getMutableAddr();
  SmallVector<Operation *> created_ops;
  for (auto it = immutables.rbegin(); it != immutables.rend(); ++it) {
    auto cloned_op = builder.clone(*op);
    auto cloned_mem_op = cast<OpTy>(cloned_op);

    cloned_mem_op.getMutableAddrMutable().assign(input_to_next_op);

    Value new_immutable =
        (*it)->buildOffsetValue(getConstBuilder(), getQueryMapBuilder(),
                                parent_unit.getLoc(), builder.getIndexType());
    cloned_mem_op.getImmutableAddrMutable().assign(new_immutable);
    cloned_mem_op.getIncrementMutable().assign(zero_const.getResult());
    // Reset burst/IL settings.
    cloned_mem_op->setAttr(StringRef("burst_size"),
                           builder.getI32IntegerAttr(0));
    cloned_mem_op->setAttr(StringRef("interleaved_group"),
                           builder.getI32IntegerAttr(0));

    input_to_next_op = cloned_mem_op->getResult(0);
    created_ops.push_back(cloned_mem_op);
  }

  // Remove the original operation and replace it. The first op in created_ops
  // is the last op in the created ops because they are created in reverse
  // order.
  op->getResult(0).replaceAllUsesWith(created_ops.back()->getResult(0));
  op->erase();

  return created_ops;
}

