// ------------------------------------------------------------------------------------------------
std::optional<FieldUnrollData> e169_findFieldUnrollCandidate(
    Operation *op, ScalarOpMergingBlock &block)
{
  for (auto &unroll_candidate : block.getUnrollCandidates()) {
    if (unroll_candidate.getOp() == op) {
      if (unroll_candidate.isMarkedForUnrolling()) return unroll_candidate;
    }
  }
  return {};
}

