// original: void ScalarOpHoisting::addForOpResultAdjustment( sentient::ForOp *for_op, Value &result, const EvaluatedValue &adjustment_increment, int result_idx)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_hoisting.rs
// ------------------------------------------------------------------------------------------------
void e170_addForOpResultAdjustment(
    sentient::ForOp *for_op, Value &result,
    const EvaluatedValue &adjustment_increment, int result_idx)
{
  DT_CHECK(adjustment_increment.isKnownAbsolute());
  Value new_const = adjustment_increment.buildOffsetValue(
      getConstBuilder(), getQueryMapBuilder(), for_op->getLoc(),
      getConstBuilder().getIndexType());

  OpBuilder builder(*for_op);
  builder.setInsertionPointAfter(*for_op);

  auto new_add = sentient::AddOp::create(
      builder, for_op->getLoc(), builder.getIndexType(), result, new_const);
  // Ensure element_size is set as it is essential for range checks.
  // TODO: Extend to all units where we can.
  if (is_any_of(getComp(), LXLU, LXSU, L0LU, L0SU)) {
    DT_CHECK(for_op->getOperation()->hasAttr("element_sizes"));
    auto elem_sizes = mlir::cast<mlir::ArrayAttr>(
        for_op->getOperation()->getAttr("element_sizes"));
    // First element size is for the loop iterator.
    auto element_size =
        mlir::cast<mlir::IntegerAttr>(elem_sizes[result_idx + 1]).getInt();
    new_add->setAttr("element_size", builder.getI64IntegerAttr(element_size));
  }
  llvm::SmallPtrSet<Operation *, 1> exceptions{new_add};
  result.replaceAllUsesExcept(new_add, exceptions);

  --ibuff_space_;
  DT_CHECK_MSG(ibuff_space_ >= 0, "No IBUFF space!");
}

// ------------------------------------------------------------------------------------------------
// entry 171/656   level 0   scc 494   33 body lines
// unit: e171_isMergeableOpOrChain
// authority: dcc/src/Transform/Sentient/ScalarOpMergingAndHoisting.cpp:1592
// original: bool ScalarOpHoisting::isMergeableOpOrChain(Operation *input_to_chain, Operation *first_op_in_chain)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_hoisting.rs
// ------------------------------------------------------------------------------------------------
bool e171_isMergeableOpOrChain(Operation *input_to_chain,
                                            Operation *first_op_in_chain)
{
  Operation *prev_op = input_to_chain;
  Operation *op = first_op_in_chain;
  while (op) {
    if (!op->use_empty() && !op->hasOneUse()) break;
    if (isa<sentient::AddOp, sentient::SubOp>(op)) {
      int const_operand_idx = dcc::utils::getFirstConstOperandIndex(op);
      if (const_operand_idx == -1) return false;
      return true;
    } else if (isa<sentient::LoadAndSendOp, sentient::ReceiveAndStoreOp,
                   sentient::LoadComputeAndSendOp>(op)) {
      MemoryOpInfo mem_info(op);
      if (!is_any_of(getComp(), LXLU, LXSU, L0LU, L0SU)) return false;
      // TODO: Add support for burst/IL
      if (mem_info.burst_ > 1 || mem_info.il_ > 0) return false;

      // Verify the immutable_addr is a constant value and the previously
      // analyzed Operation is the mutable_addr of this memory operation.
      if (!dcc::utils::isConstant<sentient::ConstantOp>(
              mem_info.immutable_addr_) ||
          mem_info.mutable_addr_.getDefiningOp() != prev_op)
        return false;
    } else {
      return false;
    }
    if (dcc::utils::isUpdateMode(op)) return true;

    if (op->use_empty()) return false;
    prev_op = op;
    op = *op->getUsers().begin();
  }
  return false;
}

