// entry 172/656   level 0   scc 496   14 body lines
// unit: e172_addToOrReplaceOp
// authority: dcc/src/Transform/Sentient/ScalarOpMergingAndHoisting.cpp:1716
// original: Value ScalarOpHoisting::addToOrReplaceOp(Operation *op, const EvaluatedValue &modifier, bool replace_with_mod)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_hoisting.rs
// ------------------------------------------------------------------------------------------------
Value e172_addToOrReplaceOp(Operation *op,
                                         const EvaluatedValue &modifier,
                                         bool replace_with_mod)
{
  DT_CHECK_MSG(dcc::utils::isConstant<sentient::ConstantOp>(op->getResult(0)),
               "Expect op to be constant");
  if (replace_with_mod) {
    return modifier.buildOffsetValue(getConstBuilder(), getQueryMapBuilder(),
                                     op->getLoc(),
                                     getConstBuilder().getIndexType());
  }
  const EvaluatedValue &sum_ev = getEvaluator().evaluateSum(
      modifier, getEvaluator().evaluateValue(op->getResult(0)));
  return sum_ev.buildOffsetValue(getConstBuilder(), getQueryMapBuilder(),
                                 op->getLoc(),
                                 getConstBuilder().getIndexType());
}

