// original: void ScalarOpHoisting::hoistCandidateOutOfLoop(BlockArgument &main_iv, Operation *derived_iv, Value &new_add_offset)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_hoisting.rs
// ------------------------------------------------------------------------------------------------
void e173_hoistCandidateOutOfLoop(BlockArgument &main_iv,
                                               Operation *derived_iv,
                                               Value &new_add_offset)
{
  derived_iv->getResult(0).replaceAllUsesWith(main_iv);

  // Create a new add preceeding candidate ForOp and update the main_iv. This is
  // the hoisted derived_iv.
  OpBuilder builder(*for_op_);
  auto new_add = sentient::AddOp::create(
      builder, for_op_->getLoc(), builder.getIndexType(),
      for_op_->getOpOperandForRegionIterArg(main_iv).get(), new_add_offset);

  // Copy element size as well as it is needed for range checks.
  // TODO: Extend to other units.
  if (is_any_of(getComp(), LXLU, LXSU, L0LU, L0SU)) {
    DT_CHECK(derived_iv->hasAttr("element_size"));
    new_add->setAttr("element_size", derived_iv->getAttr("element_size"));
  }

  derived_iv->erase();

  int main_iv_operand_idx = main_iv.getArgNumber();
  for_op_->setOperand(main_iv_operand_idx, new_add);
}

