// ------------------------------------------------------------------------------------------------
void e175_runOn(ModuleOp module_op)
{
    // Iterate through each program unit
    module_op->walk<WalkOrder::PreOrder>([&](dataflow::ProgramUnitOp unit_op) {
      dom_info_ = new DominanceInfo(unit_op);
      runOn(unit_op);
      delete dom_info_;
      return WalkResult::skip();
    });
  }

