// ------------------------------------------------------------------------------------------------
void e176_computeOpIndexing(dataflow::ProgramUnitOp unit_op)
{
    op_to_idx_.clear();
    unsigned cur_idx = 0;
    unit_op->walk<WalkOrder::PreOrder>([&](Operation *op) {
      op_to_idx_[op] = cur_idx;
      ++cur_idx;
    });
  }

