// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_reordering/mod.rs
// ------------------------------------------------------------------------------------------------
unsigned e177_getLiverangeEndPt(Operation *op)
{
    DT_CHECK_MSG(op->getNumResults() == 1,
                 "Scalar ops expected to have one result");
    unsigned endpt_idx = 0;
    for (const auto &user : op->getResult(0).getUsers()) {
      endpt_idx = std::max(endpt_idx, op_to_idx_[user]);
    }
    return endpt_idx;
  }

