// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_reordering/mod.rs
// ------------------------------------------------------------------------------------------------
Operation *e178_findAncestorInBlock(Operation *op,
                                                       Block *bb)
{
  Operation *cur_op = op;
  while (cur_op && cur_op->getBlock() != bb) {
    cur_op = cur_op->getParentOp();
  }
  return cur_op;
}

