// rust home: crates/compiler/deeptools/src/transform/sentient/set_active_mask_value_re/set_active_mask_value_rde_tree.rs
// ------------------------------------------------------------------------------------------------
void e180_initializeDataflowInfo(RDENode *node)
{
  // Uses cannot generate definitions
  if (isOperationAUse(*node->getOperation())) return;
  // Only SAMV operations generate definitions, initially.
  if (!isa<sentient::SetActiveMaskValueOp>(node->getOperation())) {
    node->setDataflowGen(new SetActiveMaskValueGenValue());
    return;
  }
  sentient::SetActiveMaskValueOp samv_op =
      dyn_cast<sentient::SetActiveMaskValueOp>(node->getOperation());
  DT_CHECK(samv_op.getMaskValue());
  node->setDataflowGen(new SetActiveMaskValueGenValue(
      samv_op.getMaskValue(), samv_op->getAttrDictionary(),
      node->getOperation()));
  return;
}

