// ------------------------------------------------------------------------------------------------
bool e181_isSimplifiable(const RDENode &node) const
{
  // We would like to remove subtrees that do not contain any SAMV or load
  // operations.
  if (getRoot() == &node) return false;
  if (isa<sentient::SetActiveMaskValueOp, sentient::LoadAndSendOp>(
          node.getOperation()))
    return false;
  return node.isLeaf() || isStaticallyDeadLoop(node);
}

