// entry 189/656   level 0   scc 542   13 body lines
// unit: e189_maskValuesAreEquivalent
// authority: dcc/src/Transform/Sentient/SetMaskRE.cpp:258
// original: bool SetMaskGenValue::maskValuesAreEquivalent(const Value a, const Value b) const
// rust home: crates/compiler/deeptools/src/transform/sentient/set_mask_re/set_mask_gen_value.rs
// ------------------------------------------------------------------------------------------------
bool e189_maskValuesAreEquivalent(const Value a,
                                              const Value b) const
{
  if (a == b) return true;
  if (!a || !b) return false;

  // Masks may contain different SSA values but represent the same mask value.
  // In this case, both masks would have to be ConstantOps evaluating to the
  // same value.
  auto a_op = dyn_cast_or_null<sentient::ConstantOp>(a.getDefiningOp());
  auto b_op = dyn_cast_or_null<sentient::ConstantOp>(b.getDefiningOp());
  if (!a_op || !b_op) return false;
  if (a_op.getValue() == b_op.getValue()) return true;
  return false;
}

