// entry 193/656   level 0   scc 173   31 body lines
// unit: e193_deadIncrMaskOptimization
// authority: dcc/src/Transform/Sentient/SetMaskRE.cpp:346
// original: void SetMaskRDETreeOptimizer::deadIncrMaskOptimization(RDENode *node)
// rust home: crates/compiler/deeptools/src/transform/sentient/set_mask_re/set_mask_rde_tree_optimizer.rs
// ------------------------------------------------------------------------------------------------
void e193_deadIncrMaskOptimization(RDENode *node)
{
  if (!isDeadIncrMaskRemovalEnabled()) return;

  DT_CHECK_MSG(node, "expected valid node");

  // An IncrMaskGenValue node with a SetMaskGenValue immediate sibling is dead.
  for (mlir::sentient::RDENode *curr_node = node; curr_node;
       curr_node = curr_node->getNextSibling()) {
    auto curr_gen = curr_node->getDataflowGen();
    if (!curr_gen || curr_gen->isDead() || curr_gen->isOptimized()) continue;
    auto curr_incrmask_gen = dynamic_cast<IncrMaskGenValue *>(curr_gen);
    if (!curr_incrmask_gen || curr_incrmask_gen->isUnknownValue()) continue;

    for (RDENode *sib = curr_node->getNextSibling(); sib;
         sib = sib->getNextSibling()) {
      auto sib_gen = sib->getDataflowGen();
      if (!sib_gen) break;
      if (sib_gen->isDead() || sib_gen->isOptimized()) continue;
      auto sib_setmask_gen = dynamic_cast<SetMaskGenValue *>(sib_gen);
      if (!sib_setmask_gen || sib_setmask_gen->isUnknownValue()) break;

      // Mark the IncrMaskOp for deletion and mark the gen type dead.
      to_be_deleted_.push_back(curr_incrmask_gen->getOperation());
      curr_incrmask_gen->setIsDead();
      LLVM_DEBUG(llvm::dbgs() << "[SetMaskRE] deadIncrMaskOptimization(): Dead "
                                 "IncrMaskOp optimized\n");
      ++count_;
      break;
    }
  }
}

// ------------------------------------------------------------------------------------------------
// entry 194/656   level 0   scc 175   58 body lines
// unit: e194_absorbIncrMask
// authority: dcc/src/Transform/Sentient/SetMaskRE.cpp:378
// original: void SetMaskRDETreeOptimizer::absorbIncrMask(RDENode *node)
// rust home: crates/compiler/deeptools/src/transform/sentient/set_mask_re/set_mask_rde_tree_optimizer.rs
// ------------------------------------------------------------------------------------------------
void e194_absorbIncrMask(RDENode *node)
{
  if (!isIncrMaskAbsorptionEnabled()) return;

  DT_CHECK_MSG(node, "expected valid node");

  // Look for absorption opportunities to the right of the node.
  for (mlir::sentient::RDENode *curr_node = node; curr_node;
       curr_node = curr_node->getNextSibling()) {
    auto curr_gen = curr_node->getDataflowGen();
    if (!curr_gen || curr_gen->isDead() || curr_gen->isOptimized()) continue;
    auto curr_setmask_gen = dynamic_cast<SetMaskGenValue *>(curr_gen);
    if (!curr_setmask_gen || curr_setmask_gen->isUnknownValue()) continue;

    // An IncrMaskGenValue to the immediate right of a SetMaskGenValue can be
    // absorbed into the SetMaskGenValue.
    for (RDENode *sib = curr_node->getNextSibling(); sib;
         sib = sib->getNextSibling()) {
      auto sib_gen = sib->getDataflowGen();
      if (!sib_gen) break;
      if (sib_gen->isDead() || sib_gen->isOptimized()) continue;
      auto sib_incrmask_gen = dynamic_cast<IncrMaskGenValue *>(sib_gen);
      if (!sib_incrmask_gen || sib_incrmask_gen->isUnknownValue()) break;

      // Update the SetMask to absorb the IncrMask
      auto setmask_op = dyn_cast_or_null<sentient::SetMaskOp>(
          curr_setmask_gen->getOperation());
      DT_CHECK(setmask_op);
      auto mask_value_op = dyn_cast_or_null<sentient::ConstantOp>(
          setmask_op.getMaskValue().getDefiningOp());
      if (!mask_value_op) break;
      auto curr_mask = mask_value_op.getValue();

      int increment = sib_incrmask_gen->getIncrement();
      DT_CHECK_MSG(increment >= 0,
                   "Expecting valid increment value from IncrMaskGenValue");

      DT_CHECK(setmask_wrap_ != 0);
      auto new_mask = (curr_mask + increment) % setmask_wrap_;
      DT_CHECK_MSG(new_mask >= 0,
                   "New SetMaskOp mask value as result of IncrMaskOp "
                   "absorption optimization is outside expected range");
      OpBuilder builder(mask_value_op);
      auto new_mask_op = sentient::ConstantOp::create(
          builder, mask_value_op.getLoc(), mask_value_op.getType(), new_mask);

      // Update the operation and the gen type.
      setmask_op.getMaskValueMutable().assign(new_mask_op.getResult());
      curr_setmask_gen->setMaskValue(new_mask_op.getResult());

      // Mark the IncrMaskOp for deletion and mark the gen type dead.
      to_be_deleted_.push_back(sib_incrmask_gen->getOperation());
      sib_incrmask_gen->setIsDead();
      LLVM_DEBUG(llvm::dbgs() << "[SetMaskRE] absorbIncrMask(): IncrMaskOp "
                                 "absorbed into SetMaskOp\n");
      ++count_;
    }
  }
}

// ------------------------------------------------------------------------------------------------
// entry 195/656   level 0   scc 550   22 body lines
// unit: e195_determineOptimizationMode
// authority: dcc/src/Transform/Sentient/SetSendDestinationRE.cpp:184
// original: void determineOptimizationMode(dataflow::ProgramUnitOp unit)
// rust home: crates/compiler/deeptools/src/transform/sentient/set_send_destination_re/mod.rs
// ------------------------------------------------------------------------------------------------
void e195_determineOptimizationMode(dataflow::ProgramUnitOp unit)
{
    bool all_lxlu = llvm::all_of(unit.getUnits(), [&](const Value &unit) {
      dataflow::GetUnitOp get_unit =
          dyn_cast_or_null<dataflow::GetUnitOp>(unit.getDefiningOp());
      if (get_unit && get_unit.getType() == "lxlu") return true;
      return false;
    });
    bool all_sfp = llvm::all_of(unit.getUnits(), [&](const Value &unit) {
      dataflow::GetUnitOp get_unit =
          dyn_cast_or_null<dataflow::GetUnitOp>(unit.getDefiningOp());
      if (get_unit && get_unit.getType() == "sfp") return true;
      return false;
    });
    DT_CHECK_MSG(!(all_lxlu && all_sfp),
                 "it cannot be that all units are both lxlu and sfp");
    if (all_lxlu)
      opt_mode_ = SetDestREOptimizationMode::kOptimizeForLXLU;
    else if (all_sfp)
      opt_mode_ = SetDestREOptimizationMode::kOptimizeForSFP;
    else
      opt_mode_ = SetDestREOptimizationMode::kUnknown;
  }

