// original: bool SetDstGenValueLXLU::isEqual(const DataFlowDefinitionBase &rhs) const
// rust home: crates/compiler/deeptools/src/transform/sentient/set_send_destination_re/set_dst_gen_value_lxlu.rs
// ------------------------------------------------------------------------------------------------
bool e198_isEqual(const DataFlowDefinitionBase &rhs) const
{
  if (isUnknownValue() || rhs.isUnknownValue()) return false;
  auto rhs_p = dynamic_cast<const SetDstGenValueLXLU *>(&rhs);
  DT_CHECK_MSG(rhs_p,
               "invalid comparison between subclasses of dataflow definitions");
  // Notes:
  // 1. We don't have valid scenarios where we need to optimize across simple
  // and composite nodes.
  // 2. The `is_optimized` bit is intentionally left out.
  if (isSimple()) {
    if (rhs_p->isComposite()) return false;
    return gen_value_.simple_.getValue() ==
           rhs_p->gen_value_.simple_.getValue();
  }
  if (isComposite()) {
    if (rhs_p->isSimple()) return false;
    // todo: for now we establish equality based on shallow SSA value
    // comparison. If the need arises, this can be enhanced to do an indepth
    // comparison between the query maps (both keys and corresponding values).
    return gen_value_.composite_.getQueryMap() ==
           rhs_p->gen_value_.composite_.getQueryMap();
  }
  llvm_unreachable("unhandled case");
}

// ------------------------------------------------------------------------------------------------
// entry 199/656   level 0   scc 564   22 body lines
// unit: e199_copyTo
// authority: dcc/src/Transform/Sentient/SetSendDestinationRE.cpp:347
// original: void SetDstGenValueLXLU::copyTo(DataFlowDefinitionBase &lhs) const
// rust home: crates/compiler/deeptools/src/transform/sentient/set_send_destination_re/set_dst_gen_value_lxlu.rs
// ------------------------------------------------------------------------------------------------
void e199_copyTo(DataFlowDefinitionBase &lhs) const
{
  auto lhs_p = dynamic_cast<SetDstGenValueLXLU *>(&lhs);
  DT_CHECK_MSG(lhs_p, "invalid subclasses of dataflow definitions");
  // copy everything except the is_optimized_ flag.
  lhs.setOperation(getOperation());
  if (isSimple() && lhs_p->isSimple())
    lhs_p->gen_value_.simple_.setValue(gen_value_.simple_.getValue());
  else if (isComposite() && lhs_p->isComposite())
    lhs_p->gen_value_.composite_.setQueryMap(
        gen_value_.composite_.getQueryMap());
  else {
    DT_CHECK_MSG(
        lhs_p->kind_ == Kind::kUnknown,
        "mixed mode copying is currently only supported when copying into "
        "an unknown");
    lhs_p->kind_ = kind_;
    if (kind_ == Kind::kSimple)
      lhs_p->gen_value_.simple_ = gen_value_.simple_;
    else if (kind_ == Kind::kComposite)
      lhs_p->gen_value_.composite_ = gen_value_.composite_;
  }
}

