// entry 203/656   level 0   scc 565   35 body lines
// unit: e203_isEqual
// authority: dcc/src/Transform/Sentient/SetSendDestinationRE.cpp:418
// original: bool SetDstGenValueSFP::isEqual(const DataFlowDefinitionBase &rhs) const
// rust home: crates/compiler/deeptools/src/transform/sentient/set_send_destination_re/set_dst_gen_value_sfp.rs
// ------------------------------------------------------------------------------------------------
bool e203_isEqual(const DataFlowDefinitionBase &rhs) const
{
  if (isUnknownValue() || rhs.isUnknownValue()) return false;
  auto rhs_p = dynamic_cast<const SetDstGenValueSFP *>(&rhs);
  DT_CHECK_MSG(rhs_p,
               "invalid comparison between subclasses of dataflow definitions");
  // Notes:
  // 1. We don't have valid scenarios where we need to optimize across simple
  // and composite nodes.
  // 2. The `is_optimized` bit is intentionally left out.
  if (isSimple()) {
    if (rhs_p->isComposite()) return false;
    return gen_value_.simple_.getCoreId() ==
               rhs_p->gen_value_.simple_.getCoreId() &&
           gen_value_.simple_.getCoreletId() ==
               rhs_p->gen_value_.simple_.getCoreletId();
  }
  if (isComposite()) {
    if (rhs_p->isSimple()) return false;
    if (gen_value_.composite_.getQueryMap() ==
        rhs_p->gen_value_.composite_.getQueryMap())
      return true;

    // todo: for now the order of two lists are important. We can enhance this
    // by comparing all at the (key, value) pairs.
    return (dcc::uniform::utils::getListOfKeyOpsFromUniformMapping(
                gen_value_.composite_.getQueryMap()) ==
            dcc::uniform::utils::getListOfKeyOpsFromUniformMapping(
                rhs_p->gen_value_.composite_.getQueryMap())) &&
           (dcc::uniform::utils::getListOfValueOpsFromUniformMapping(
                gen_value_.composite_.getQueryMap()) ==
            dcc::uniform::utils::getListOfValueOpsFromUniformMapping(
                rhs_p->gen_value_.composite_.getQueryMap()));
  }
  llvm_unreachable("unhandled case");
}

// ------------------------------------------------------------------------------------------------
// entry 204/656   level 0   scc 566   23 body lines
// unit: e204_copyTo
// authority: dcc/src/Transform/Sentient/SetSendDestinationRE.cpp:454
// original: void SetDstGenValueSFP::copyTo(DataFlowDefinitionBase &lhs) const
// rust home: crates/compiler/deeptools/src/transform/sentient/set_send_destination_re/set_dst_gen_value_sfp.rs
// ------------------------------------------------------------------------------------------------
void e204_copyTo(DataFlowDefinitionBase &lhs) const
{
  auto lhs_p = dynamic_cast<SetDstGenValueSFP *>(&lhs);
  DT_CHECK_MSG(lhs_p, "invalid subclasses of dataflow definitions");
  // copy everything except the is_optimized_ flag.
  lhs.setOperation(getOperation());
  if (isSimple() && lhs_p->isSimple()) {
    lhs_p->gen_value_.simple_.setCoreId(gen_value_.simple_.getCoreId());
    lhs_p->gen_value_.simple_.setCoreletId(gen_value_.simple_.getCoreletId());
  } else if (isComposite() && lhs_p->isComposite())
    lhs_p->gen_value_.composite_.setQueryMap(
        gen_value_.composite_.getQueryMap());
  else {
    DT_CHECK_MSG(
        lhs_p->kind_ == Kind::kUnknown,
        "mixed mode copying is currently only supported when copying into "
        "an unknown");
    lhs_p->kind_ = kind_;
    if (kind_ == Kind::kSimple)
      lhs_p->gen_value_.simple_ = gen_value_.simple_;
    else if (kind_ == Kind::kComposite)
      lhs_p->gen_value_.composite_ = gen_value_.composite_;
  }
}

