// entry 208/656   level 0   scc 567   51 body lines
// unit: e208_runOnOperation
// authority: dcc/src/Transform/Sentient/SimplifyUniformRegions.cpp:55
// original: void SimplifyUniformRegionsPass::runOnOperation()
// rust home: crates/compiler/deeptools/src/transform/sentient/simplify_uniform_regions/mod.rs
// ------------------------------------------------------------------------------------------------
void e208_runOnOperation()
{
  ModuleOp module_op = getOperation();
  module_op.walk([&](mlir::Operation *op) {
    if (auto uniform_op = llvm::dyn_cast<uniform::UniformizeRegionsOp>(op)) {
      dcc::uniform::utils::flattenUniformRegion(uniform_op);
    }
  });
  module_op.walk([&](dataflow::ProgramUnitOp prog_unit_op) {
    // trying to merge all consecutive local operations in unit_op.
    dcc::uniform::utils::mergeAllLocalOps(prog_unit_op);

    if (!DisableThisPass) {
      prog_unit_op.walk([&](mlir::Operation *op) {
        if (isa<uniform::UniformizeRegionsOp>(op)) {
          dcc::uniform::utils::removeEmptyLocalRegions(op);
          return WalkResult::skip();
        }
        return WalkResult::advance();
      });
      prog_unit_op.walk([&](mlir::Operation *op) {
        if (isa<uniform::UniformizeRegionsOp>(op)) {
          // Trying to remove local region and promote all operations in that
          // region to global, if possible.
          dcc::uniform::utils::removeNotNecessaryLocalRegions(op);
          return WalkResult::skip();
        }
        return WalkResult::advance();
      });

      // PropagationAnalysis *expr_prop_analysis = nullptr;
      auto comp = dcc::getUnitType(prog_unit_op);
      // if (is_any_of(comp, L3LU, L3SU)) {
      //   expr_prop_analysis =
      //       &getChildAnalysis<PropagationAnalysis>(prog_unit_op);
      // }

      prog_unit_op.walk([&](mlir::Operation *op) {
        if (isa<uniform::UniformizeRegionsOp, uniform::EqualizePatternOp>(op)) {
          dcc::uniform::utils::simplifyUniformRegions(op, comp, dccExtContext(),
                                                      nullptr);
          return WalkResult::skip();
        }
        return WalkResult::advance();
      });
    }
    return WalkResult::skip();
  });
  module_op.walk([&](uniform::QueryMapOp query_map_op) {
    dcc::uniform::utils::simplifyQueryMapWithSameTarget(query_map_op);
  });
}

