// entry 213/656   level 0   scc 572   12 body lines
// unit: e213_addRegion
// authority: dcc/src/Transform/Sentient/SinkScalarCopy.cpp:125
// original: void addRegion(Region *region)
// rust home: crates/compiler/deeptools/src/transform/sentient/sink_scalar_copy/mod.rs
// ------------------------------------------------------------------------------------------------
void e213_addRegion(Region *region)
{
    auto iter = std::lower_bound(regions_.begin(), regions_.end(), region,
                                 [](const RegionInfo &a, const Region *b) {
                                   return a.getPointer() < b;
                                 });
    if (iter != regions_.end() && (*iter).getPointer() == region) return;
    regions_.emplace_back(region);
    std::sort(regions_.begin(), regions_.end(),
              [](RegionInfo &a, RegionInfo &b) {
                return a.getPointer() < b.getPointer();
              });
  }

