// entry 214/656   level 0   scc 575   16 body lines
// unit: e214_sinkCopyOps
// authority: dcc/src/Transform/Sentient/SinkScalarCopy.cpp:215
// original: void sinkCopyOps()
// rust home: crates/compiler/deeptools/src/transform/sentient/sink_scalar_copy/mod.rs
// ------------------------------------------------------------------------------------------------
void e214_sinkCopyOps()
{
    // todo: in future live range and register pressure could also be considered
    // in deciding which scalar_copys to sink.
    for (auto ui : uses_info_list_) {
      Operation &orig_op = *ui->getOperation();
      for (const RegionInfo &region : ui->getRegions()) {
        if (region.isGlobalRegion()) continue;
        OpBuilder builder(region.getPointer());
        Operation *new_op = builder.clone(orig_op);
        DT_CHECK(orig_op.getNumResults() == 1);
        replaceAllUsesInRegionWith(orig_op.getResult(0), new_op->getResult(0),
                                   *region.getPointer());
      }
      if (orig_op.getUses().empty()) orig_op.erase();
    }
  }

