// authority: dcc/src/Transform/Sentient/SmartRegisterAllocation.cpp:87
// original: bool SmartRegisterAllocationPass::isKnownToHaveSameValues(mlir::Value op_1, mlir::Value op_2)
// rust home: crates/compiler/deeptools/src/transform/sentient/smart_register_allocation/mod.rs
// ------------------------------------------------------------------------------------------------
bool e217_isKnownToHaveSameValues(mlir::Value op_1,
                                                          mlir::Value op_2)
{
  if (auto op_1_ops = op_1.getDefiningOp<sentient::LoadAndSendOp>()) {
    if (op_1_ops.getIncrement()
                .getDefiningOp<sentient::ConstantOp>()
                .getValue() == 0 and
        op_1_ops.getMutableAddr() == op_2)
      return true;
  } else if (auto op_1_ops =
                 op_1.getDefiningOp<sentient::ReceiveAndStoreOp>()) {
    if (op_1_ops.getIncrement()
                .getDefiningOp<sentient::ConstantOp>()
                .getValue() == 0 and
        op_1_ops.getMutableAddr() == op_2)
      return true;
  } else if (auto op_1_ops =
                 op_1.getDefiningOp<sentient::LoadComputeAndSendOp>()) {
    if (op_1_ops.getIncrement()
                .getDefiningOp<sentient::ConstantOp>()
                .getValue() == 0 and
        op_1_ops.getMutableAddr() == op_2)
      return true;
  }

  if (auto op_2_ops = op_2.getDefiningOp<sentient::LoadAndSendOp>()) {
    if (op_2_ops.getIncrement()
                .getDefiningOp<sentient::ConstantOp>()
                .getValue() == 0 and
        op_2_ops.getMutableAddr() == op_1)
      return true;
  } else if (auto op_2_ops =
                 op_2.getDefiningOp<sentient::ReceiveAndStoreOp>()) {
    if (op_2_ops.getIncrement()
                .getDefiningOp<sentient::ConstantOp>()
                .getValue() == 0 and
        op_2_ops.getMutableAddr() == op_1)
      return true;
  } else if (auto op_2_ops =
                 op_2.getDefiningOp<sentient::LoadComputeAndSendOp>()) {
    if (op_2_ops.getIncrement()
                .getDefiningOp<sentient::ConstantOp>()
                .getValue() == 0 and
        op_2_ops.getMutableAddr() == op_1)
      return true;
  }
  return false;
}

