// ------------------------------------------------------------------------------------------------
void e218_runOn(dataflow::GetUnitOp curr_op, const DominanceInfo &dom_info)
{
    LLVM_DEBUG(llvm::dbgs() << "Analyzing: " << curr_op << "\n");
    if (curr_op.getType() == IgnoreGetUnitType) {
      LLVM_DEBUG(llvm::dbgs().indent(2)
                 << " - Skipped because of option control\n");
      return;
    }

    if (curr_op.use_empty()) {
      LLVM_DEBUG(llvm::dbgs().indent(2) << " - Dead op being removed\n");
      to_be_deleted_.push_back(curr_op);
      return;
    }
    std::string key_str = dcc::utils::getUnitNameAsString(curr_op);
    LLVM_DEBUG(llvm::dbgs().indent(2) << " - Key: " << key_str << "\n");
    if (get_unit_map_.find(key_str) != get_unit_map_.end()) {
      dataflow::GetUnitOp gu_op = get_unit_map_[key_str];
      DT_CHECK_MSG(gu_op, "expected valid get_unit op");
      LLVM_DEBUG(llvm::dbgs().indent(2) << " - Duplicate being removed\n");
      curr_op->replaceAllUsesWith(gu_op);
      to_be_deleted_.push_back(curr_op);
    } else {
      get_unit_map_[key_str] = curr_op;
      LLVM_DEBUG(llvm::dbgs().indent(2) << " - Added to map\n");
      if (curr_op->getParentOp() == curr_func_ &&
          dom_info.dominates(&*curr_op, insert_point_)) {
        LLVM_DEBUG(llvm::dbgs().indent(2)
                   << " - Not moved because it's already in the function scope."
                   << "\n");
        return;
      }
      LLVM_DEBUG(llvm::dbgs().indent(2)
                 << " - Moved to function scope." << "\n");
      curr_op->moveBefore(insert_point_);
    }
  }

