// rust home: crates/compiler/deeptools/src/transform/sentient/specialized_canonicalization/mod.rs
// ------------------------------------------------------------------------------------------------
bool e221_initialize(func::FuncOp func)
{
    curr_func_ = func;
    for (Operation &op : func.getBody().front()) {
      if (isa<dataflow::ProgramUnitOp>(op)) {
        insert_point_ = &op;
        break;
      }
    }
    if (!insert_point_) {
      LLVM_DEBUG(
          llvm::dbgs()
          << "Unable to find starting program_unit op. "
             "Skipping this function entirely (probably a trace func?)\n.");
      return false;
    }
    DT_CHECK(get_unit_map_.empty());
    DT_CHECK(create_symbol_map_.empty());
    DT_CHECK(to_be_deleted_.empty());
    return true;
  }

