// original: mlir::Operation *StoreAndForwardFusionPass::findFusibleOp( mlir::Operation *op, std::vector<mlir::Operation *> &to_be_deleted, bool is_fold_AB_mode)
// rust home: crates/compiler/deeptools/src/transform/sentient/store_and_forward_fusion/mod.rs
// ------------------------------------------------------------------------------------------------
mlir::Operation *e224_findFusibleOp(
    mlir::Operation *op, std::vector<mlir::Operation *> &to_be_deleted,
    bool is_fold_AB_mode)
{
  mlir::Operation *fusible_op =
      (!is_fold_AB_mode ? op->getPrevNode() : op->getPrevNode()->getPrevNode());

  while (fusible_op && fusible_op->getBlock() == op->getBlock()) {
    if (isa<sentient::MacOp>(fusible_op) ||
        isa<sentient::BinaryOp>(fusible_op)) {
      return fusible_op;
    }
    if (auto unary_op = llvm::dyn_cast<sentient::UnaryOp>(fusible_op)) {
      if (!is_any_of(unary_op.getUnaryOp(), SentientUnary::reduction_abs_max,
                     SentientUnary::reduction_abs_min,
                     SentientUnary::reduction_add, SentientUnary::reduction_max,
                     SentientUnary::reduction_min)) {
        return fusible_op;
      }
    }
    if (isa<sentient::ConstantOp, dataflow::GetUnitOp>(fusible_op) ||
        std::binary_search(to_be_deleted.begin(), to_be_deleted.end(),
                           fusible_op)) {
      fusible_op =
          (!is_fold_AB_mode ? fusible_op->getPrevNode()
                            : fusible_op->getPrevNode()->getPrevNode());
    } else {
      break;
    }
  }
  return op;
}

