// authority: dcc/src/Transform/Sentient/StoreAndForwardFusion.cpp:150
// original: bool StoreAndForwardFusionPass::isOpTrivialMacOp(sentient::MacOp mac_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/store_and_forward_fusion/mod.rs
// ------------------------------------------------------------------------------------------------
bool e225_isOpTrivialMacOp(sentient::MacOp mac_op)
{
  auto opA = mac_op.getOpA();
  auto opB = mac_op.getOpB();
  auto opC = mac_op.getOpC();
  auto opA_forwarding = mac_op.getOpAForwarding();
  auto opB_forwarding = mac_op.getOpBForwarding();
  auto opC_forwarding = mac_op.getOpCForwarding();
  auto result_forwarding = mac_op.getResultForwarding();

  if (opC != SentientComputePort::zero) {
    if ((opA == SentientComputePort::zero ||
         opB == SentientComputePort::zero) &&
        (!opC_forwarding.empty() || !result_forwarding.empty()))
      return true;

    return false;
  }
  if (stringifySentientComputePort(opA).contains("lrf") &&
      opB == SentientComputePort::one &&
      (!opA_forwarding.empty() || !result_forwarding.empty()) &&
      opB_forwarding.empty()) {
    return true;
  }
  if (stringifySentientComputePort(opB).contains("lrf") &&
      opA == SentientComputePort::one &&
      (!opB_forwarding.empty() || !result_forwarding.empty()) &&
      opA_forwarding.empty()) {
    return true;
  }
  return false;
}

