// rust home: crates/compiler/deeptools/src/transform/sentient/store_and_forward_fusion/mod.rs
// ------------------------------------------------------------------------------------------------
LogicalResult e227_fillOperandForFusibleOp(
    mlir::Operation *fusible_op, mlir::ArrayAttr &opA_forwarding,
    mlir::ArrayAttr &opB_forwarding, mlir::ArrayAttr &opC_forwarding,
    mlir::ArrayAttr &result_forwarding, SentientPrecision &result_precision)
{
  auto fusible_mac_op = llvm::dyn_cast<sentient::MacOp>(fusible_op);
  auto fusible_binary_op = llvm::dyn_cast<sentient::BinaryOp>(fusible_op);
  auto fusible_unary_op = llvm::dyn_cast<sentient::UnaryOp>(fusible_op);

  if (fusible_mac_op) {
    result_forwarding = fusible_mac_op.getResultForwarding();
    opA_forwarding = fusible_mac_op.getOpAForwarding();
    opB_forwarding = fusible_mac_op.getOpBForwarding();
    opC_forwarding = fusible_mac_op.getOpCForwarding();
    result_precision = fusible_mac_op.getResultPrecision();
  } else if (fusible_binary_op) {
    result_forwarding = fusible_binary_op.getResultForwarding();
    opA_forwarding = fusible_binary_op.getOpAForwarding();
    opB_forwarding = fusible_binary_op.getOpBForwarding();
    result_precision = fusible_binary_op.getResultPrecision();
  } else if (fusible_unary_op) {
    result_forwarding = fusible_unary_op.getResultForwarding();
    result_precision = fusible_unary_op.getResultPrecision();
    opA_forwarding = fusible_unary_op.getOpAForwarding();
  } else {
    fusible_op->emitError(
        "The fusible operation has to be either MacOp, BinaryOp or UnaryOp.");
    return LogicalResult::failure();
  }
  return LogicalResult::success();
}

// ------------------------------------------------------------------------------------------------
// entry 228/656   level 0   scc 597   41 body lines
// unit: e228_updateFusibleOp
// authority: dcc/src/Transform/Sentient/StoreAndForwardFusion.cpp:387
// original: LogicalResult StoreAndForwardFusionPass::updateFusibleOp( mlir::Operation *fusible_op, std::vector<mlir::Attribute> &value_forwardings_for_trivial)
// rust home: crates/compiler/deeptools/src/transform/sentient/store_and_forward_fusion/mod.rs
// ------------------------------------------------------------------------------------------------
LogicalResult e228_updateFusibleOp(
    mlir::Operation *fusible_op,
    std::vector<mlir::Attribute> &value_forwardings_for_trivial)
{
  auto fusible_mac_op = llvm::dyn_cast<sentient::MacOp>(fusible_op);
  auto fusible_binary_op = llvm::dyn_cast<sentient::BinaryOp>(fusible_op);
  auto fusible_unary_op = llvm::dyn_cast<sentient::UnaryOp>(fusible_op);

  auto count_lrfs = [&](std::vector<mlir::Attribute> &attrs) {
    int num_lrfs_in_fusion = 0;
    for (auto &attr : attrs) {
      auto val = mlir::cast<SentientComputePortAttr>(attr).getValue();
      if (val == SentientComputePort::none) continue;

      const auto output = stringifySentientComputePort(val);
      if (output.contains("lrf")) num_lrfs_in_fusion++;
    }

    return num_lrfs_in_fusion;
  };

  // If the number of forwardings are greater than 1, then we cannot
  // generate a single instruction using the current ISA.
  int num_lrf_in_trivial = count_lrfs(value_forwardings_for_trivial);
  if (num_lrf_in_trivial > 1) {
    return LogicalResult::failure();
  }

  if (fusible_mac_op) {
    fusible_mac_op.setResultForwardingAttr(ArrayAttr::get(
        fusible_mac_op.getContext(), value_forwardings_for_trivial));
  } else if (fusible_binary_op) {
    fusible_binary_op.setResultForwardingAttr(ArrayAttr::get(
        fusible_binary_op.getContext(), value_forwardings_for_trivial));
  } else if (fusible_unary_op) {
    fusible_unary_op.setResultForwardingAttr(ArrayAttr::get(
        fusible_unary_op.getContext(), value_forwardings_for_trivial));
  } else {
    fusible_op->emitError(
        "The fusible operation has to be either MacOp, BinaryOp or UnaryOp.");
    return LogicalResult::failure();
  }
  return LogicalResult::success();
}

