// authority: dcc/src/Transform/Sentient/SyncSendRecvFusion.cpp:70
// original: LogicalResult SyncSendRecvFusionPass::FuseSyncSendRecv( mlir::Operation *op, mlir::Operation *op_next)
// rust home: crates/compiler/deeptools/src/transform/sentient/sync_send_recv_fusion/mod.rs
// ------------------------------------------------------------------------------------------------
LogicalResult e230_FuseSyncSendRecv(
    mlir::Operation *op, mlir::Operation *op_next)
{
  auto sync_op = llvm::dyn_cast<sentient::SyncOp>(op);
  if (!sync_op) return LogicalResult::failure();

  auto sync_op_next = llvm::dyn_cast<sentient::SyncOp>(op_next);
  if (!sync_op_next) return LogicalResult::failure();

  if (!(sync_op.getMode() == SentientSyncMode::send &&
        sync_op_next.getMode() == SentientSyncMode::recv))
    if (!(sync_op.getMode() == SentientSyncMode::recv &&
          sync_op_next.getMode() == SentientSyncMode::send))
      return LogicalResult::failure();

  if (sync_op.getSoft() != sync_op_next.getSoft())
    return LogicalResult::failure();

  if (!isEqualSets(sync_op.getUnits(), sync_op_next.getUnits()))
    return LogicalResult::failure();

  OpBuilder builder(op);
  auto new_sync_op = sentient::SyncOp::create(
      builder, op->getLoc(),
      dataflow::utils::getNewDbgNameFromList(/*prefix*/ "SSRF(",
                                             {sync_op, sync_op_next}),
      SentientSyncModeAttr::get(builder.getContext(),
                                SentientSyncMode::sendrecv),
      sync_op.getUnits(), builder.getBoolAttr(sync_op.getSoft().value()),
      builder.getSI32IntegerAttr(-1));
  if (!new_sync_op) return LogicalResult::failure();

  return LogicalResult::success();
}

