mlir::Operation *e231_getNextEligableNode(
    mlir::Operation *op)
{
  auto next_op = op->getNextNode();
  // clang-format off
  while (next_op &&
         (isa<mlir::dataflow::GetUnitOp,
              mlir::sentient::ConstantOp,
              mlir::symbol::CreateSymbolOp,
              mlir::uniform::DefImmutableMappingOp,
              mlir::uniform::QueryMapOp>(next_op))) {
    // clang-format on
    next_op = next_op->getNextNode();
  }
  return next_op;
}

