// unit: e232_reorderToggle
// authority: dcc/src/Transform/Sentient/ToggleReordering.cpp:104
// original: void ToggleInfo::reorderToggle()
// rust home: crates/compiler/deeptools/src/transform/sentient/toggle_reordering/toggle_info.rs
// ------------------------------------------------------------------------------------------------
void e232_reorderToggle()
{
  auto inner_loop =
      dyn_cast<mlir::sentient::ForOp>(iter_arg_.getOwner()->getParentOp());
  auto inner_yield_op =
      dyn_cast<mlir::sentient::YieldOp>(inner_loop.getBody(0)->getTerminator());

  // Replace all uses of sub_op_ except the position in the yield
  // corresponding to iter_arg_.
  Value sub_op_result = sub_op_.getResult();
  sub_op_result.replaceUsesWithIf(iter_arg_, [&](OpOperand &operand) {
    if (operand.getOwner() == inner_yield_op) {
      int idx = dcc::utils::getIndexOfLoopRegionIterArgs(iter_arg_);
      if (inner_yield_op.getOperand(idx) == sub_op_result) return false;
    }
    return true;
  });

  sub_op_->moveBefore(inner_yield_op);

  // Update the outer loop iter arg initializer.
  OpBuilder const_builder(unit_op_);
  OpBuilder query_map_builder(outer_loop_);
  const EvaluatedValue &init_ev = evaluator_.evaluateValue(
      outer_loop_.getIterOperands()[outer_loop_iter_arg_idx_]);
  const EvaluatedValue &new_init_ev =
      evaluator_.evaluateSub(minuend_ev_, init_ev);
  Value new_init =
      new_init_ev.buildOffsetValue(const_builder, query_map_builder,
                                   outer_loop_.getLoc(), sub_op_.getType());
  outer_loop_.setIterOperand(outer_loop_iter_arg_idx_, new_init);
}

// ------------------------------------------------------------------------------------------------
// entry 233/656   level 0   scc 606   39 body lines
// unit: e233_computeToggleInfoIfIsToggle
// authority: dcc/src/Transform/Sentient/ToggleReordering.cpp:222
// original: ToggleInfo *ToggleReorderingPass::computeToggleInfoIfIsToggle( dataflow::ProgramUnitOp unit_op, sentient::SubOp sub_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/toggle_reordering/mod.rs
// ------------------------------------------------------------------------------------------------
ToggleInfo *e233_computeToggleInfoIfIsToggle(
    dataflow::ProgramUnitOp unit_op, sentient::SubOp sub_op)
{
  if (!dcc::utils::isConstant<sentient::ConstantOp>(sub_op.getInp1()))
    return nullptr;

  // Get the iter arg info for sub_op's second operand
  Value sub_inp2 = sub_op.getInp2();
  int iter_arg_idx = dcc::utils::getIndexOfLoopRegionIterArgs(sub_inp2);
  if (iter_arg_idx == -1) return nullptr;

  auto iter_arg = dyn_cast<BlockArgument>(sub_inp2);
  DT_CHECK_MSG(iter_arg,
               "At this point expect second operand of sub_op to be iter arg");
  auto loop =
      dyn_cast<mlir::sentient::ForOp>(iter_arg.getOwner()->getParentOp());
  auto yield_op =
      dyn_cast<mlir::sentient::YieldOp>(loop.getBody(0)->getTerminator());

  if (!iter_arg.hasOneUse()) return nullptr;

  // The sub_op result must be yielded at the same index as iter_arg_idx
  // for this to be a toggle.
  Value sub_result = sub_op.getResult();
  if (yield_op.getOperand(iter_arg_idx) != sub_result) return nullptr;

  // Get the outer loop initializer of the iter arg chain.
  auto tuple = dcc::utils::getOutermostConstInitialization(iter_arg);
  sentient::ForOp outer_loop = std::get<0>(tuple);
  int outer_loop_iter_arg_idx = std::get<1>(tuple);
  if (!outer_loop || outer_loop_iter_arg_idx == -1) return nullptr;

  // The initializer must be constant
  if (!isa<sentient::ConstantOp>(
          outer_loop.getIterOperands()[outer_loop_iter_arg_idx]
              .getDefiningOp()))
    return nullptr;

  return new ToggleInfo(evaluator_, unit_op, sub_op, outer_loop,
                        outer_loop_iter_arg_idx);
}

