// ------------------------------------------------------------------------------------------------
// entry 236/656   level 0   scc 612   28 body lines
// unit: e236_macOpsFlowDependence
// authority: dcc/src/Transform/Sentient/TransformForExposedPipeline.cpp:100
// original: bool TransformForExposedPipelinePass::macOpsFlowDependence( const dcc::DccExtContext &dcc_ext_ctx, Operation *a, Operation *b, std::string precision)
// rust home: crates/compiler/deeptools/src/transform/sentient/transform_for_exposed_pipeline/mod.rs
// ------------------------------------------------------------------------------------------------
bool e236_macOpsFlowDependence(
    const dcc::DccExtContext &dcc_ext_ctx, Operation *a, Operation *b,
    std::string precision)
{
  if (!isa<sentient::MacOp>(a) || !isa<sentient::MacOp>(b)) {
    return true;
  }

  auto src = dyn_cast<sentient::MacOp>(a);
  auto dst = dyn_cast<sentient::MacOp>(b);
  auto src_register = src.getOutputRegister();
  if (!src_register.has_value()) {
    return false;
  }

  if (!src.getUnrollIncrResult() || !src_register.value().contains("lrf")) {
    return dcc::sentient::utils::doesMacOpUseRegister(dst, src_register.value(),
                                                      precision, dcc_ext_ctx);
  } else {
    int reg_start_index = atoi(&src_register.value().str().back());
    for (int i = 0; i < src.getUnrollFactorVal(); i++) {
      auto reg_name = "lrf" + std::to_string(reg_start_index);
      bool dependence = dcc::sentient::utils::doesMacOpUseRegister(
          dst, reg_name, precision, dcc_ext_ctx);
      if (dependence) return true;
      reg_start_index++;
    }

    return false;
  }
}

// ------------------------------------------------------------------------------------------------
// entry 237/656   level 0   scc 617   36 body lines
// unit: e237_insertNOPOperations
// authority: dcc/src/Transform/Sentient/TransformForExposedPipeline.cpp:304
// original: void TransformForExposedPipelinePass::insertNOPOperations(int cycles)
// rust home: crates/compiler/deeptools/src/transform/sentient/transform_for_exposed_pipeline/mod.rs
// ------------------------------------------------------------------------------------------------
void e237_insertNOPOperations(int cycles)
{
  std::unordered_map<mlir::Operation *, int> num_of_nop_added;
  for (auto op_gap_dep : dependencies_with_min_gap_) {
    sentient::MacOp mac_op = llvm::dyn_cast<sentient::MacOp>(op_gap_dep.src);
    int max_n_nop_insertions = cycles - mac_op.getUnrollFactorVal() + 1;
    if (op_gap_dep.gap > 1) max_n_nop_insertions -= (op_gap_dep.gap - 2);

    // Get the outermost ancestor on src's chain that is still inside the
    // common scope shared by src and dst.
    auto ancestorResult = dcc::utils::getOutermostAncestorInCommonScope(
        op_gap_dep.src, op_gap_dep.dst);

    int n_nop_insertions = max_n_nop_insertions;
    n_nop_insertions -= ancestorResult.num_for_ops_from_dst;
    n_nop_insertions -= ancestorResult.num_if_ops_from_dst;

    Operation *outermostAncestorInCommonScope = ancestorResult.ancestor;
    if (num_of_nop_added.count(outermostAncestorInCommonScope))
      n_nop_insertions -= num_of_nop_added.at(outermostAncestorInCommonScope);

    OpBuilder builder(outermostAncestorInCommonScope);
    builder.setInsertionPointAfter(outermostAncestorInCommonScope);
    for (int i = 0; i < n_nop_insertions; i++) {
      sentient::NOPOp::create(
          builder, mac_op->getLoc(),
          dcc::utils::getNewDbgNameFromOp(
              /*prefix*/ "TFEP(", mac_op,
              /*suffix*/ ", NOP #" + std::to_string(i) + ")"));
    }
    if (num_of_nop_added.count(outermostAncestorInCommonScope)) {
      num_of_nop_added.at(outermostAncestorInCommonScope) += n_nop_insertions;
    } else {
      num_of_nop_added[outermostAncestorInCommonScope] = n_nop_insertions;
    }
  }
}

