// rust home: crates/compiler/deeptools/src/transform/sentient/uniform_map_canonicalization/mod.rs
// ------------------------------------------------------------------------------------------------
void e238_cleanupConstants(ModuleOp module_op)
{
  // Simplify/canonicalize the sentient.scalar_constant ops so we don't have
  // duplicate constant values.
  RewritePatternSet patterns(&getContext());
  sentient::ConstantOp::getCanonicalizationPatterns(patterns, &getContext());
  FrozenRewritePatternSet frozen_patterns(std::move(patterns));
  GreedyRewriteConfig config;
  config.setStrictness(GreedyRewriteStrictness::ExistingOps);
  (void)applyPatternsGreedily(module_op, frozen_patterns, config);
}

