// ------------------------------------------------------------------------------------------------
Operation &e239_getOperationOfBlock(Block &block, int op_num)
{
  auto iter = block.getOperations().begin();
  while (op_num > 0) {
    iter++;
    op_num--;
  }
  return *iter;
}

