// entry 240/656   level 0   scc 197   15 body lines
// unit: e240_selectIndicesForUnits
// authority: dcc/src/Transform/Sentient/Utils.cpp:66
// original: void selectIndicesForUnits( SmallVector<Value> &units, SmallVector<unsigned> &indices, std::unordered_map<std::string, unsigned> unit_name_to_index_map)
// rust home: crates/compiler/deeptools/src/transform/sentient/utils/mod.rs
// ------------------------------------------------------------------------------------------------
void e240_selectIndicesForUnits(
    SmallVector<Value> &units, SmallVector<unsigned> &indices,
    std::unordered_map<std::string, unsigned> unit_name_to_index_map)
{
  SmallVector<Value> cleaned_units;
  while (!units.empty()) {
    auto unit = units.back();
    units.pop_back();
    if (auto group_op = unit.getDefiningOp<dataflow::CreateGroupOp>()) {
      units.append((SmallVector<Value>)group_op.getUnitIds());
      continue;
    }
    cleaned_units.push_back(unit);
    indices.push_back(
        unit_name_to_index_map.at(getFoldedUnitNameAsString(unit)));
  }
  units = cleaned_units;
}

