// original: mlir::LogicalResult moveToCommonDominator(Operation *op, Operation *new_use)
// rust home: crates/compiler/deeptools/src/transform/sentient/utils/mod.rs
// ------------------------------------------------------------------------------------------------
mlir::LogicalResult e241_moveToCommonDominator(Operation *op, Operation *new_use)
{
  DominanceInfo dom_info;
  DT_CHECK_MSG(op && new_use, "expected valid ops");
  Operation *insert_point = op;
  Operation *dummy_nop = nullptr;
  while (!dom_info.dominates(insert_point, new_use)) {
    insert_point = insert_point->getParentOp();
    if (auto prog_unit = dyn_cast<dataflow::ProgramUnitOp>(insert_point)) {
      auto first_op = &prog_unit.getBodyRegion().front().front();
      OpBuilder builder(first_op);
      insert_point = dummy_nop = mlir::sentient::NOPOp::create(
          builder, first_op->getLoc(),
          dcc::utils::getNewDbgNameFromOp(
              /*prefix*/ "DummyNOP(", op, /*suffix*/ ")"));
      if (!dom_info.dominates(insert_point, new_use))
        return failure();  // common dominator would be outside the program unit
      break;               // cannot go farther than program_unit
    } else if (auto uniform_region =
                   llvm::dyn_cast<mlir::uniform::UniformizeRegionsOp>(
                       insert_point)) {
      bool promote_above_uniform_region = false;
      if (auto scalar_copy = llvm::dyn_cast<mlir::sentient::CopyOp>(op)) {
        Operation *copy_inp_op = scalar_copy.getInp().getDefiningOp();
        if (isa<dataflow::CreateMulticastGroupOp>(copy_inp_op) ||
            isConstant<mlir::sentient::ConstantOp>(scalar_copy.getInp()) ||
            isConstant<mlir::symbol::CreateSymbolOp>(scalar_copy.getInp())) {
          promote_above_uniform_region = true;
        }
      }

      if (!promote_above_uniform_region) {
        auto [region_op, region_idx] =
            dcc::uniform::utils::getRegionOpAndIndex(new_use);
        auto first_op = &region_op->getRegion(region_idx).front().front();
        OpBuilder builder(first_op);
        insert_point = dummy_nop = mlir::sentient::NOPOp::create(
            builder, first_op->getLoc(),
            dcc::utils::getNewDbgNameFromOp(
                /*prefix*/ "DummyNOP(", op, /*suffix*/ ")"));
        break;  // do not go farther than uniform region op
      }
    }
  }
  if (insert_point == op) return success();

  // When moving an operation we need to make sure that the operands still
  // dominate it after the move, otherwise we need to recursively move their
  // operands, and operands of those operands, and so on. The following
  // algorithm uses a worklist initially populated with orignal operands of
  // the op. It moves operands as needed and puts their operands into the
  // worklist while the worklist is not empty.
  SmallVector<Value> worklist;
  llvm::copy_if(op->getOperands(), std::back_inserter(worklist),
                [](Value v) { return static_cast<bool>(v.getDefiningOp()); });
  Operation *final_insert_point = insert_point;
  while (!worklist.empty()) {
    Value curr = worklist.pop_back_val();
    DT_CHECK(!isa<BlockArgument>(curr));
    if (!dom_info.dominates(curr, insert_point)) {
      curr.getDefiningOp()->moveBefore(insert_point);
      insert_point = curr.getDefiningOp();
      llvm::copy_if(
          curr.getDefiningOp()->getOperands(), std::back_inserter(worklist),
          [](Value v) { return static_cast<bool>(v.getDefiningOp()); });
    }
  }

  op->moveBefore(final_insert_point);
  if (dummy_nop) dummy_nop->erase();
  return success();
}

