// unit: e242_getForLoopInfoIfIV
// authority: dcc/src/Transform/Sentient/Utils.cpp:156
// original: std::tuple<Operation *, int64_t, int64_t, int64_t, int64_t> getForLoopInfoIfIV( Value val, bool allow_normalized_iv)
// rust home: crates/compiler/deeptools/src/transform/sentient/utils/mod.rs
// ------------------------------------------------------------------------------------------------
std::tuple<Operation *, int64_t, int64_t, int64_t, int64_t> e242_getForLoopInfoIfIV(
    Value val, bool allow_normalized_iv)
{
  Value iv_candidate;
  int64_t constant_subtracted_from = 0;
  bool val_is_sub_op = false;
  if (isa<BlockArgument>(val))
    iv_candidate = val;
  else if (!allow_normalized_iv)
    return std::make_tuple(nullptr, 0, 0, 0, 0);
  else {
    auto sub_op = llvm::dyn_cast<mlir::sentient::SubOp>(val.getDefiningOp());
    if (!sub_op) return std::make_tuple(nullptr, 0, 0, 0, 0);
    auto const_op = llvm::dyn_cast<mlir::sentient::ConstantOp>(
        sub_op.getOperand(0).getDefiningOp());
    if (!const_op) return std::make_tuple(nullptr, 0, 0, 0, 0);
    iv_candidate = sub_op.getOperand(1);
    constant_subtracted_from = const_op.getValue();
    val_is_sub_op = true;
  }

  if (isa<BlockArgument>(iv_candidate)) {
    Operation *for_op =
        cast<BlockArgument>(iv_candidate).getOwner()->getParentOp();
    auto sentient_for_op = llvm::dyn_cast<mlir::sentient::ForOp>(for_op);
    if (sentient_for_op && sentient_for_op.getInductionVar() == iv_candidate) {
      // Sentient For-op can have non-constant bounds.
      if (auto bound_op = sentient_for_op.getBound()
                              .getDefiningOp<mlir::sentient::ConstantOp>()) {
        int64_t bound = bound_op.getValue();
        if (val_is_sub_op)
          return std::make_tuple(for_op, constant_subtracted_from - bound,
                                 constant_subtracted_from, 1, bound);
        return std::make_tuple(for_op, bound, 1, -1, bound);
      }
    }
  }
  return std::make_tuple(nullptr, 0, 0, 0, 0);
}

