// original: unsigned roundDownUnrollFactor(unsigned n, Operation *compute_op, SenTargets sen_target)
// rust home: crates/compiler/deeptools/src/transform/sentient/utils/mod.rs
// ------------------------------------------------------------------------------------------------
unsigned e243_roundDownUnrollFactor(unsigned n, Operation *compute_op,
                               SenTargets sen_target)
{
  DT_CHECK_MSG(n != 0, "Expect a positive target unroll value");
  auto unary_op = llvm::dyn_cast<mlir::sentient::UnaryOp>(compute_op);
  unsigned u;
  if (unary_op &&
      is_any_of(unary_op.getUnaryOp(), SentientUnary::reduction_abs_max,
                SentientUnary::reduction_abs_min, SentientUnary::reduction_add,
                SentientUnary::reduction_max, SentientUnary::reduction_min)) {
    if (sen_target == SenTargets::SENTIENT) {
      if (n < 2)
        u = 1;
      else if (n < 3)
        u = 2;
      else if (n < 4)
        u = 3;
      else
        u = 4;
    } else {
      u = 1;
    }
  } else {
    if (n < 2)
      u = 1;
    else if (n < 4)
      u = 2;
    else if (n < 8)
      u = 4;
    else
      u = 8;
  }
  return u;
}

