// original: CmpIPredicate negatePredicate(CmpIPredicate pred)
// rust home: crates/compiler/deeptools/src/transform/sentient/utils/mod.rs
// ------------------------------------------------------------------------------------------------
CmpIPredicate e244_negatePredicate(CmpIPredicate pred)
{
  switch (pred) {
    case CmpIPredicate::eq:
      return CmpIPredicate::ne;
    case CmpIPredicate::ne:
      return CmpIPredicate::eq;
    case CmpIPredicate::slt:
      return CmpIPredicate::sge;
    case CmpIPredicate::sle:
      return CmpIPredicate::sgt;
    case CmpIPredicate::sgt:
      return CmpIPredicate::sle;
    case CmpIPredicate::sge:
      return CmpIPredicate::slt;
    default:
      llvm_unreachable("unexpected IfOp predicate");
  }
}

