// entry 246/656   level 0   scc 624   55 body lines
// unit: e246_getOutermostConstInitialization
// authority: dcc/src/Transform/Sentient/Utils.cpp:469
// original: std::tuple<mlir::sentient::ForOp, int, int> getOutermostConstInitialization( BlockArgument iter_arg)
// rust home: crates/compiler/deeptools/src/transform/sentient/utils/mod.rs
// ------------------------------------------------------------------------------------------------
std::tuple<mlir::sentient::ForOp, int, int> e246_getOutermostConstInitialization(
    BlockArgument iter_arg)
{
  // Iterator argument initializations may be chained, eg:
  //
  // %a:2 = sentient.for ... iter_args(%argM = %X, ...)
  //   %b:3 = sentient.for ... iter_args(..., %argN = %argM, ...)
  //     %c:2 = sentient.for ... iter_args(%argO = %argN, ...) {
  //       ...
  //     }
  //     yield ..., %c#0, ...
  //   }
  //   yield %b#1, ...
  // }
  int iter_arg_index = -1;
  BlockArgument curr_iter_arg = iter_arg;
  mlir::sentient::ForOp outer_loop, prev_loop;
  int prev_it_index = -1;
  int size = 1;
  // Search from inner to outer loop
  while (iter_arg_index < 0 && curr_iter_arg) {
    int curr_it_index = dcc::utils::getIndexOfLoopRegionIterArgs(curr_iter_arg);
    outer_loop = dyn_cast<mlir::sentient::ForOp>(
        curr_iter_arg.getOwner()->getParentOp());
    int bound = 0;
    if (auto const_bound = llvm::dyn_cast_or_null<mlir::sentient::ConstantOp>(
            outer_loop.getBound().getDefiningOp())) {
      bound = const_bound.getValue();
      if (bound <= 0) {
        return std::make_tuple(nullptr, -1, -1);
      }
      size *= bound;
    } else {
      size = -1;
    }

    if (prev_loop) {
      auto yield = dyn_cast<mlir::sentient::YieldOp>(
          outer_loop.getBody(0)->getTerminator());
      DT_CHECK_MSG(yield,
                   "expected terminator of previous loop body to be a yield");
      if (!curr_iter_arg.hasOneUse() ||
          !isa<mlir::sentient::ForOp>(*curr_iter_arg.user_begin()))
        return std::make_tuple(nullptr, -1, -1);
      if (yield.getOperand(curr_it_index) != prev_loop.getResult(prev_it_index))
        break;
    }
    Value curr_init = outer_loop.getIterOperands()[curr_it_index];
    curr_iter_arg = dyn_cast<BlockArgument>(curr_init);
    if (curr_iter_arg) {
      prev_loop = outer_loop;
      prev_it_index = curr_it_index;
    } else if (isConstant<mlir::sentient::ConstantOp>(curr_init))
      iter_arg_index = curr_it_index;
  }
  return std::make_tuple(outer_loop, iter_arg_index, size);
}

