// entry 247/656   level 0   scc 427   64 body lines
// unit: e247_memoryOpRequiresImmutAddrScalarCopy
// authority: dcc/src/Transform/Sentient/Utils.cpp:526
// original: bool memoryOpRequiresImmutAddrScalarCopy(const dcc::DccExtContext &dcc_ext_ctx, SenComponents unit_type, Operation *op, bool do_range_check)
// rust home: crates/compiler/deeptools/src/transform/sentient/utils/mod.rs
// ------------------------------------------------------------------------------------------------
bool e247_memoryOpRequiresImmutAddrScalarCopy(const dcc::DccExtContext &dcc_ext_ctx,
                                         SenComponents unit_type, Operation *op,
                                         bool do_range_check)
{
  int burst_size = 0, il = 0, element_size = 0;
  Value immut_addr = nullptr;
  bool chunk_stride_present = false;
  if (auto rs = llvm::dyn_cast<mlir::sentient::ReceiveAndStoreOp>(op)) {
    burst_size = rs.getBurstSize();
    il = rs.getInterleavedGroup();
    element_size = rs.getElementSize();
    immut_addr = rs.getImmutableAddr();
  } else if (auto ls = llvm::dyn_cast<mlir::sentient::LoadAndSendOp>(op)) {
    burst_size = ls.getBurstSize();
    il = ls.getInterleavedGroup();
    element_size = ls.getElementSize();
    immut_addr = ls.getImmutableAddr();
    // In case of chunk strides, we should use LRF for offset
    chunk_stride_present = unit_type == L0LU && ls.getChunkStride() > 0;
  } else if (auto lae =
                 llvm::dyn_cast<mlir::sentient::LoadAndExtractScalarOp>(op)) {
    element_size = lae.getElementSize();
    immut_addr = lae.getImmutableAddr();
  } else if (auto lcas =
                 llvm::dyn_cast<mlir::sentient::LoadComputeAndSendOp>(op)) {
    element_size = lcas.getDstElementSize();
    immut_addr = lcas.getImmutableAddr();
  } else {
    llvm_unreachable("unexpected op type");
  }

  bool is_constant = isConstant<mlir::sentient::ConstantOp>(immut_addr);
  // Note: Range check may hit an exception while executing is_imm_size_valid if
  //       the unit is L3 as L3 doesn't have IMM for the relevant operations.
  bool is_in_range =
      is_constant && do_range_check && !is_any_of(unit_type, L3LU, L3SU)
          ? dcc_ext_ctx.is_imm_size_valid(unit_type, immut_addr, element_size)
          : true;

  if (isa<mlir::sentient::ReceiveAndStoreOp>(op) &&
      is_any_of(unit_type, L0SU, LXSU)) {
    // If the immutable address is constant and either burst is present,
    // il is present, or the constant is out of bounds if do_range_check was
    // true, we need a scalar copy.
    return is_constant && (burst_size > 1 || il > 0 || !is_in_range);
  } else if (isa<mlir::sentient::LoadAndSendOp>(op) &&
             is_any_of(unit_type, L0LU, LXLU)) {
    // If the immutable address is constant and either burst is present,
    // il is present, or the constant is out of bounds, need a scalar copy.
    return is_constant &&
           (burst_size > 1 || il > 0 || chunk_stride_present || !is_in_range);
  } else if (isa<mlir::sentient::LoadAndExtractScalarOp>(op)) {
    return is_constant && !is_in_range;
  } else if (isa<mlir::sentient::LoadComputeAndSendOp>(op)) {
    DT_CHECK(unit_type == LXLU);
    bool res = is_constant && !is_in_range;
    DT_CHECK_MSG(is_constant && is_in_range,
                 "sentient::LoadComputeAndSendOp requires immediate immutable "
                 "address in range.");
    return res;
  } else if (is_any_of(unit_type, L3LU, L3SU)) {
    // No imm in L3LU/L3SU
    return is_constant;
  } else {
    llvm_unreachable("unexpected operation or unit type");
  }
}

