// rust home: crates/compiler/deeptools/src/transform/sentient/utils/units_and_their_values.rs
// ------------------------------------------------------------------------------------------------
void e249_normalizeNullValues()
{
  mlir::Value non_null_val = nullptr;
  for (auto &val : values_) {
    if (val) {
      non_null_val = val;
      break;
    }
  }
  for (auto &val : values_) {
    if (!val) {
      val = non_null_val;
    }
  }
}

