// rust home: crates/compiler/deeptools/src/transform/sentient/utils/mod.rs
// ------------------------------------------------------------------------------------------------
bool e250_hasUniformizeRegion(dataflow::ProgramUnitOp unit)
{
  Operation *uniform_op = nullptr;
  unit->walk<WalkOrder::PreOrder>([&uniform_op](Operation *op) {
    if (isa<mlir::uniform::UniformizeRegionsOp,
            mlir::uniform::EqualizePatternOp>(op)) {
      uniform_op = op;
      return WalkResult::interrupt();
    }
    return WalkResult::advance();
  });
  return uniform_op != nullptr;
}

