// authority: dcc/src/Transform/Sentient/VectorRegisterInitialization.cpp:125
// original: bool VectorRegisterInitializationPass::isCandidate( Operation &op, const PortListTy &set_of_accessed_ports)
// rust home: crates/compiler/deeptools/src/transform/sentient/vector_register_initialization/mod.rs
// ------------------------------------------------------------------------------------------------
bool e255_isCandidate(
    Operation &op, const PortListTy &set_of_accessed_ports)
{
  if (!isa<sentient::SplatOp>(op)) return false;
  sentient::SplatOp splat_op = llvm::dyn_cast<sentient::SplatOp>(op);
  auto const_input = splat_op.getInput().getDefiningOp<sentient::ConstantOp>();
  auto vector_const =
      splat_op.getInput().getDefiningOp<sentient::VectorConstantOp>();
  auto query_map =
      splat_op.getInput().getDefiningOp<mlir::uniform::QueryMapOp>();

  if (!const_input && !vector_const && !query_map) return false;
  if (query_map) {
    auto target_map = llvm::dyn_cast<mlir::uniform::DefImmutableMappingOp>(
        query_map.getMap().getDefiningOp());
    for (auto val : target_map.getValues()) {
      if (!isa<sentient::ConstantOp, sentient::VectorConstantOp>(
              val.getDefiningOp())) {
        return false;
      }
    }
  }

  auto output_port =
      splat_op.getOutput().getDefiningOp<sentient::LogicalPortOp>();
  DT_CHECK_MSG(output_port,
               "expected output port to be specified through logical_port");
  // We take a very conservative approach here, where we check to see if the
  // port being written to by this splat has been accessed in any of the prior
  // operations, and if so disallow it. ie the candidate has to be the first
  // access through that port.
  if (set_of_accessed_ports.count(output_port.getPortName())) return false;
  return true;
}

