// ------------------------------------------------------------------------------------------------
bool e273_isHeadOfChain(const DataTransferDescriptor &desc) const
{
    if (!isPartOfSomeChain(desc)) return false;
    auto it = chaining_info_.find(&desc);
    return (it == chaining_info_.end()) ? false
                                        : (it->second & Flags::kHeadOfChain);
  }

