// entry 275/656   level 1   scc 94   59 body lines
// unit: e275_turnHBMConstantOpAddrsToQueryMapsHelper
// authority: dcc/src/Transform/Sentient/AddressPinningAndToggle.cpp:1595
// original: void AddressPinningAndTogglePass::turnHBMConstantOpAddrsToQueryMapsHelper( OpBuilder &const_builder, Operation &region_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/address_pinning_and_toggle/mod.rs
// ------------------------------------------------------------------------------------------------
void e275_turnHBMConstantOpAddrsToQueryMapsHelper(
    OpBuilder &const_builder, Operation &region_op)
{
  auto num_regions = region_op.getRegions().size();
  for (int region_idx = 0; region_idx < num_regions; region_idx++) {
    Region &curr_region = region_op.getRegion(region_idx);
    OpBuilder query_map_builder(&curr_region);

    // Get the key and unit list from the current uniformization region.
    std::vector<Value> units;
    Value key = nullptr;
    if (auto uniformize_region =
            llvm::dyn_cast<uniform::UniformizeRegionsOp>(&region_op)) {
      key = uniformize_region.getRegionArg(region_idx);
      units = dcc::uniform::utils::collectUnitVals(
          uniformize_region.getRegionUnitList(region_idx));
    } else if (auto equalize_region =
                   llvm::dyn_cast<uniform::EqualizePatternOp>(&region_op)) {
      key = equalize_region.getRegionArg(region_idx);
      units = dcc::uniform::utils::collectUnitVals(
          equalize_region.getRegionUnitList(region_idx));
    }

    // Replace any ConstantOp HBM immutable address inside the region
    // with a QueryMapOp mapping list_of_unit_ops to this ConstantOp.
    curr_region.walk<WalkOrder::PreOrder>(
        [&](sentient::LoadAndStoreOp load_and_store) {
          auto src_unit = load_and_store.getSrc().getDefiningOp();
          auto dst_unit = load_and_store.getDst().getDefiningOp();
          if (dcc::getUnitType(src_unit) == HBM) {
            if (auto const_immut_addr = llvm::dyn_cast<sentient::ConstantOp>(
                    load_and_store.getSrcImmutableAddr().getDefiningOp())) {
              // Map every unit in units to the same constant value.
              std::vector<AddrTy> const_list;
              for (auto unit_op : units)
                const_list.push_back(const_immut_addr.getValue());
              auto new_immut_addr =
                  dcc::uniform::utils::createQueryMapFromConstants(
                      query_map_builder, const_builder, load_and_store.getLoc(),
                      key, units, const_list);
              load_and_store.getSrcImmutableAddrMutable().assign(
                  new_immut_addr);
            }
          } else if (dcc::getUnitType(dst_unit) == HBM) {
            if (auto const_immut_addr = llvm::dyn_cast<sentient::ConstantOp>(
                    load_and_store.getDstImmutableAddr().getDefiningOp())) {
              // Map every unit in units to the same constant value.
              std::vector<AddrTy> const_list;
              for (auto unit_op : units)
                const_list.push_back(const_immut_addr.getValue());
              auto new_immut_addr =
                  dcc::uniform::utils::createQueryMapFromConstants(
                      query_map_builder, const_builder, load_and_store.getLoc(),
                      key, units, const_list);
              load_and_store.getDstImmutableAddrMutable().assign(
                  new_immut_addr);
            }
          }
        });
  }
}

