// authority: dcc/src/Transform/Sentient/AddressPinningAndToggle.cpp:2799
// original: IntegerSequenceDescriptor::IntegerSequenceDescriptor( ExpressionEvaluator &evaluator, Value base_addr) : DynamicPatternDescriptorBase(PatternKind::kIntegerSequence, evaluator)
// rust home: crates/compiler/deeptools/src/transform/sentient/address_pinning_and_toggle/integer_sequence_descriptor.rs
// ------------------------------------------------------------------------------------------------
e280_IntegerSequenceDescriptor(
    ExpressionEvaluator &evaluator, Value base_addr)
    : DynamicPatternDescriptorBase(PatternKind::kIntegerSequence, evaluator)
{
  // Attempt to analyze the integer sequence formed via the iter-arg
  DT_CHECK(size_ == 0 && iter_arg_index_ < 0 && !outer_loop_);
  auto iter_arg = dyn_cast<BlockArgument>(base_addr);
  if (!iter_arg) {
    DEBUG_WITH_TYPE(
        VerboseDebug,
        llvm::dbgs()
            << "Expected block argument forming the integer sequence\n");
    return;
  }
  Operation *loop_op = iter_arg.getOwner()->getParentOp();
  if (!loop_op) {
    DEBUG_WITH_TYPE(VerboseDebug, llvm::dbgs()
                                      << "Expected integer sequence, but the "
                                         "base addr is not a loop iterator\n");
    return;
  }

  std::tie(outer_loop_, iter_arg_index_, size_) =
      dcc::utils::getOutermostConstInitialization(iter_arg);

  if (!outer_loop_ || iter_arg_index_ < 0) {
    DEBUG_WITH_TYPE(VerboseDebug, llvm::dbgs()
                                      << "Not a const integer sequence because "
                                         "pattern does not match!\n");
    return;
  }

  if (size_ <= 0) {
    // dead load/stores?
    DEBUG_WITH_TYPE(VerboseDebug, llvm::dbgs()
                                      << "Size of integer sequence is unknown "
                                         "due to non-constant loop bound!\n");
    return;
  }

  Value curr_init = outer_loop_.getIterOperands()[iter_arg_index_];
  if (!dcc::utils::isConstant<sentient::ConstantOp>(curr_init)) {
    DEBUG_WITH_TYPE(VerboseDebug,
                    llvm::dbgs()
                        << "Expected integer sequence, but iter arg init "
                           "value does not resolve to a constant\n");
    invalidate();
    return;
  }
  init_ = &evaluator_.evaluateValue(curr_init);

  // Find the sequence stride.
  int inner_loop_iter_arg_index =
      dcc::utils::getIndexOfLoopRegionIterArgs(iter_arg);
  Operation *add_feeding_yield =
      dcc::utils::getIterArgIncrementer<sentient::ForOp, sentient::AddOp>(
          loop_op, inner_loop_iter_arg_index);
  if (add_feeding_yield && dcc::utils::isConstant<sentient::ConstantOp>(
                               add_feeding_yield->getOperand(1))) {
    stride_ = &evaluator_.evaluateValue(add_feeding_yield->getOperand(1));
  } else {
    DEBUG_WITH_TYPE(VerboseDebug,
                    llvm::dbgs() << "Expected integer sequence, but yield "
                                    "operand isn't a recognized pattern\n");
    invalidate();
    return;
  }

  int num_non_yield_feeding_uses =
      dcc::utils::getNumUsersExcept(base_addr, [&](Operation *op) {
        return isa<sentient::YieldOp>(op) || op == add_feeding_yield;
      });
  DT_CHECK_MSG(
      num_non_yield_feeding_uses == 1,
      "base_addr should only be used in memory op and to feed the yield op");
  const EvaluatedValue &zero_ev = evaluator_.getConstant(0);
  setCanBeSimplified((size_ == 1) || (*stride_ == zero_ev));
}

