// ------------------------------------------------------------------------------------------------
// entry 283/656   level 1   scc 100   31 body lines
// unit: e283_assignPrecision
// authority: dcc/src/Transform/Sentient/AddressRegisterPrecisionAssignment.cpp:164
// original: bool AddressRegisterPrecisionAssignmentPass::assignPrecision(Value val, int element_size, Value &new_val, Operation *user)
// rust home: crates/compiler/deeptools/src/transform/sentient/address_register_precision_assignment/mod.rs
// ------------------------------------------------------------------------------------------------
bool e283_assignPrecision(Value val,
                                                             int element_size,
                                                             Value &new_val,
                                                             Operation *user)
{
  if (mlir::isa<BlockArgument>(val)) {
    auto *def_op = mlir::cast<BlockArgument>(val).getOwner()->getParentOp();
    if (auto for_op = llvm::dyn_cast<sentient::ForOp>(def_op)) {
      for (int i = 0; i < for_op.getNumRegionIterArgs(); i++) {
        if (for_op.getRegionIterArgs()[i] == val) {
          return assignPrecisionHelper(for_op, i + 1, element_size, new_val,
                                       user);
        }
      }
    } else {
      def_op->emitError("Unknown parent op for precision calculation");
      signalPassFailure();
    }
  } else {
    int offset = 0;
    auto *def_op = val.getDefiningOp();
    if (auto for_op = llvm::dyn_cast<sentient::ForOp>(def_op)) {
      offset = (1 + for_op.getNumRegionIterArgs());
    }

    for (int i = 0; i < def_op->getNumResults(); i++) {
      if (def_op->getResults()[i] == val) {
        return assignPrecisionHelper(def_op, i + offset, element_size, new_val,
                                     user);
      }
    }
  }

  return false;
}

