    DT_CHECK_MSG(
        (is_data_weight && max_val < 64) || (!is_data_weight && max_val >= 64),
        "XRF-related SSA variable has values in both data and "
        "scale ranges");

    // Set the isDataWeight boolean attribute
    fma_op->setAttr("isDataWeight",
                    BoolAttr::get(fma_op.getContext(), is_data_weight));
