// entry 286/656   level 1   scc 117   58 body lines
// unit: e286_recomputeAsDefaultVals
// authority: dcc/src/Transform/Sentient/CFGSimplificationSentientLevel.cpp:396
// original: void recomputeAsDefaultVals()
// rust home: crates/compiler/deeptools/src/transform/sentient/cfg_simplification_sentient_level/mod.rs
// ------------------------------------------------------------------------------------------------
void e286_recomputeAsDefaultVals()
{
    std::vector<Sequence *> new_sequences;
    for (auto it_seq = sequences_.begin(); it_seq != sequences_.end();
         ++it_seq) {
      auto *seq = *it_seq;
      // Ignore "padding sequences".
      if (seq->getLength() == 0) {
        delete seq;
        continue;
      }
      // Monotone sequences of length 1 or with a stride of 0 can
      // immediately be treated as a default value sequence.
      if (seq->getKind() == Sequence::kMonotoneSequence &&
          (seq->getLength() == 1 ||
           *seq->getStride() == evaluator_.getConstant(0)))
        seq->setKind(Sequence::kDefaultValue);
      if (seq->getKind() == Sequence::kDefaultValue) {
        new_sequences.push_back(new Sequence(*seq));
      } else {
        // Treat each element of a kMonotoneSequence as a kDefaultValue.
        const EvaluatedValue *val = seq->getLB();
        const EvaluatedValue *stride = seq->getStride();
        DT_CHECK(stride &&
                 "Expect non-template sequences to have a valid stride");
        DT_CHECK(
            seq->getIntervalMarker().has_value() &&
            "Expect non-template sequences to have a valid interval marker");
        dcc::WidestIntType length_remaining = seq->getLength();
        dcc::WidestIntType interval_step = seq->getIntervalStride();
        // Compute the interval marker for the first element in the sequence:
        // initial interval_marker + interval_step * (length_remaining - 1)
        dcc::WidestIntType interval_marker =
            seq->getIntervalMarker().value() -
            interval_step * (length_remaining - 1);
        for (dcc::WidestIntType i = 0; i < length_remaining - 1;
             ++i, interval_marker += interval_step) {
          new_sequences.push_back(
              new Sequence(*val, evaluator_.getConstant(0), 1, interval_marker,
                           interval_step, Sequence::kDefaultValue, evaluator_));
          val = &evaluator_.evaluateSum(*val, *stride);
        }
        // If possible, absorb the last entry in the monotone sequence in the
        // next Default Value sequence.
        auto it_next = std::next(it_seq, 1);
        if (it_next != sequences_.end() && *val == *(*it_next)->getLB()) {
          (*it_next)->incrementLength(1);
          // Note: we do not need to update the interval marker for this
          // next default value sequence since we are extending it to the left.
        } else {
          new_sequences.push_back(
              new Sequence(*val, evaluator_.getConstant(0), 1, interval_marker,
                           interval_step, Sequence::kDefaultValue, evaluator_));
        }
      }
      delete seq;
    }
    sequences_ = new_sequences;
  }

