// authority: dcc/src/Transform/Sentient/CFGSimplificationSentientLevel.cpp:2096
// original: void PatternSimplificationManager::computeTemplateSeqAndUpdateMonotoneSeq( std::vector<TableSlice *> &table_slices)
// rust home: crates/compiler/deeptools/src/transform/sentient/cfg_simplification_sentient_level/pattern_simplification_manager.rs
// ------------------------------------------------------------------------------------------------
void e289_computeTemplateSeqAndUpdateMonotoneSeq(
    std::vector<TableSlice *> &table_slices)
{
  // Set the template sequences to be a copy of the first table slice's
  // sequences, and update the monotone sequence's LB. Store a ptr to the
  // template monotone sequence if there is any.
  dcc::WidestIntType entries_seen_so_far = 0;
  Sequence *template_monotone_seq = nullptr;
  for (auto *s : table_slices.front()->getSequences()) {
    Sequence *copy = new Sequence(*s);
    template_sequences_.push_back(copy);
    if (s->getKind() == Sequence::kMonotoneSequence) {
      template_monotone_seq = copy;
      // shifted_lb = lb - stride * entries_seen_so_far
      const EvaluatedValue &shifted_lb = evaluator_.evaluateSub(
          *s->getLB(), evaluator_.evaluateMultiplyByConst(*s->getStride(),
                                                          entries_seen_so_far));
      copy->setShiftedLB(&shifted_lb);
      // We will use the shifted LB rather than the LB.
      copy->setLB(nullptr);
      // There is at most one monotone sequence.
    }
    entries_seen_so_far += s->getLength();
  }
  // Compare all other table slices' sequences to the template and mark
  // inconsistent fields.
  for (TableSlice *table_slice : table_slices) {
    dcc::WidestIntType entries_seen_so_far = 0;
    DT_CHECK(
        table_slice->getSequences().size() == template_sequences_.size() &&
        "By this point all slices should have the same number of sequences.");
    for (auto pair :
         llvm::zip(table_slice->getSequences(), template_sequences_)) {
      auto &cur_seq = std::get<0>(pair);
      auto &template_seq = std::get<1>(pair);
      // If the LB, stride or interval markers are not consistent,
      // update the template.
      if (!cur_seq->getLB() || !template_seq->getLB() ||
          *cur_seq->getLB() != *template_seq->getLB())
        template_seq->setLB(nullptr);
      if (!cur_seq->getStride() || !template_seq->getStride() ||
          *cur_seq->getStride() != *template_seq->getStride())
        template_seq->setStride(nullptr);
      if (cur_seq->getIntervalMarker() != template_seq->getIntervalMarker())
        template_seq->setIntervalMarker(std::nullopt);

      // For a monotone sequence, we need to shift the LB by the number of
      // entries seen so far to get the starting value of the sequence.
      if (cur_seq->getKind() == Sequence::kMonotoneSequence) {
        const EvaluatedValue &shifted_val = evaluator_.evaluateSub(
            *cur_seq->getLB(), evaluator_.evaluateMultiplyByConst(
                                   *cur_seq->getStride(), entries_seen_so_far));
        cur_seq->setShiftedLB(&shifted_val);
        if (template_seq->getShiftedLB() &&
            *template_seq->getShiftedLB() != shifted_val)
          template_seq->setShiftedLB(nullptr);
      }
      entries_seen_so_far += cur_seq->getLength();
    }
  }
  // If the monotone sequence has a stride of 0 in all table slices and there is
  // either no preceeding or no succeeding default value, change it to a default
  // value.
  if (template_monotone_seq && template_sequences_.size() < 3 &&
      template_monotone_seq->getStride() &&
      *template_monotone_seq->getStride() == evaluator_.getConstant(0)) {
    // Change the kind and swap the LB and shifted LB.
    template_monotone_seq->changeToDefaultValue();
    for (TableSlice *table_slice : table_slices) {
      for (auto *s : table_slice->getSequences()) {
        if (s->getKind() == Sequence::kMonotoneSequence) {
          s->changeToDefaultValue();
        }
      }
    }
  }
}

