// rust home: crates/compiler/deeptools/src/transform/sentient/cfg_simplification_sentient_level/pattern_simplification_manager.rs
// ------------------------------------------------------------------------------------------------
void e290_insertSequence(Sequence *seq,
                                                  TableSlice *table_slice)
{
  if (abort_pattern_) return;
  auto &sequences = table_slice->getSequences();
  if (!sequences.empty() &&
      sequences.back()->getKind() == Sequence::kMonotoneSequence)
    table_slice->setHasInsertedMonotoneSeqBeforeLast();
  sequences.push_back(seq);
  if (sequences.size() > 3) {
    if (table_slice->is1DRepOfTable()) {
      DEBUG_WITH_TYPE(
          VerboseDebug,
          llvm::dbgs() << "Failed to match the contiguous sequence pattern.\n");
      table_follows_contiguous_pattern_ = false;
      abort_pattern_ = true;
    } else {
      DEBUG_WITH_TYPE(
          VerboseDebug,
          llvm::dbgs() << "Failed to match the monotone sequence pattern.\n");
      table_slices_follow_montone_pattern_ = false;
      // Note: we do not set abort_pattern_ to true, since we
      // still need the sequences to be computed for each slice.
    }
  }
}

