// entry 291/656   level 1   scc 133   49 body lines
// unit: e291_padTableSlice
// authority: dcc/src/Transform/Sentient/CFGSimplificationSentientLevel.cpp:2398
// original: void PatternSimplificationManager::padTableSlice(TableSlice *table_slice, unsigned max_num_seq)
// rust home: crates/compiler/deeptools/src/transform/sentient/cfg_simplification_sentient_level/pattern_simplification_manager.rs
// ------------------------------------------------------------------------------------------------
void e291_padTableSlice(TableSlice *table_slice,
                                                 unsigned max_num_seq)
{
  auto &sequences = table_slice->getSequences();
  DT_CHECK_MSG(sequences.size() <= 3,
               "Expect at most 3 sequences in each table_slice.\n");
  Sequence::SequenceKind next_expected = Sequence::kDefaultValue;

  auto *first_seq = sequences.front();
  // If the first sequence is the result when (IV <= m1) then
  // we need to compute m0 such that (IV <= m0) is always false.
  // m0 = m1 - first sequence stride * first sequence length
  dcc::WidestIntType prev_interval_marker =
      first_seq->getIntervalMarker().value() -
      first_seq->getIntervalStride() * first_seq->getLength();
  dcc::WidestIntType interval_stride = first_seq->getIntervalStride();
  unsigned count = 0;
  unsigned target_count =
      EnableNonZeroStrideSeqSimplifications ? 3 : max_num_seq;
  for (auto it_seq = sequences.begin(); count < target_count; ++count) {
    // If missing the expected kind of sequence, insert a
    // dummy sequence of the expected kind with the same interval
    // marker as the previous sequence (so that this new sequence is
    // is in a dead branch).
    if (it_seq == sequences.end()) {
      // Pad after the current sequences.
      Sequence *new_seq = new Sequence(
          evaluator_.getConstant(0), evaluator_.getConstant(0), 0,
          prev_interval_marker, interval_stride, next_expected, evaluator_);
      sequences.push_back(new_seq);
      it_seq = sequences.end();
    } else if ((*it_seq)->getKind() != next_expected) {
      // Pad in the middle.
      Sequence *new_seq = new Sequence(
          evaluator_.getConstant(0), evaluator_.getConstant(0), 0,
          prev_interval_marker, interval_stride, next_expected, evaluator_);
      it_seq = sequences.emplace(it_seq, new_seq);
      ++it_seq;
    } else {
      // The next sequence is of the expected kind.
      prev_interval_marker = (*it_seq)->getIntervalMarker().value();
      ++it_seq;
    }
    next_expected = (next_expected == Sequence::kDefaultValue &&
                     EnableNonZeroStrideSeqSimplifications)
                        ? Sequence::kMonotoneSequence
                        : Sequence::kDefaultValue;
  }
  DT_CHECK_MSG(sequences.size() == target_count,
               "The correct number of sequences after padding.\n");
}

