// original: llvm::SmallVector<Type> PatternSimplificationManager::generateEncodingTypes()
// rust home: crates/compiler/deeptools/src/transform/sentient/cfg_simplification_sentient_level/pattern_simplification_manager.rs
// ------------------------------------------------------------------------------------------------
llvm::SmallVector<Type> e292_generateEncodingTypes()
{
  llvm::SmallVector<Type> types;
  // Number of sequences and entries seen so far in this slice.
  dcc::WidestIntType seq_seen_so_far = 0;
  for (auto *template_s : template_sequences_) {
    // Skip the interval marker for the last sequence.
    bool skip_interval_marker =
        (seq_seen_so_far == template_sequences_.size() - 1);

    const Type table_entry_type = table_->getTableEntryType();
    // For a kMonotoneSequence, keep both the starting value and the step;
    // for a kDefaultValue only keep the value.
    if (template_s->getKind() == Sequence::kMonotoneSequence) {
      // Avoid inserting fields which appear in the template sequence (i.e.
      // are consistent across all slices).
      if (!template_s->getShiftedLB()) types.push_back(table_entry_type);
      if (!template_s->getStride()) types.push_back(table_entry_type);
    } else {
      if (!template_s->getLB()) types.push_back(table_entry_type);
    }
    if (!skip_interval_marker && !template_s->getIntervalMarker().has_value())
      types.push_back(table_->getPredicateType());
    seq_seen_so_far++;
  }
  return types;
}

