// ------------------------------------------------------------------------------------------------
llvm::SmallVector<Value> e293_generateEncodingTuple(
    Value &iv, TableSlice *cur_table_slice, OpBuilder &builder)
{
  auto &sequences = cur_table_slice->getSequences();
  DT_CHECK_MSG(sequences.size() <= 3,
               "Expect table_slices to have at most 3 sequences.");
  const Type table_entry_type = table_->getTableEntryType();

  llvm::SmallVector<Value> encoding_tuple;
  // Number of sequences and entries seen so far in this slice.
  dcc::WidestIntType seq_seen_so_far = 0;
  for (auto pair : llvm::zip(sequences, template_sequences_)) {
    Sequence *s = std::get<0>(pair);
    Sequence *template_s = std::get<1>(pair);
    // Skip the interval marker for the last sequence.
    bool skip_interval_marker = (seq_seen_so_far == sequences.size() - 1);

    // For a kMonotoneSequence, keep both the starting value and the step;
    // for a kDefaultValue only keep the value.
    if (s->getKind() == Sequence::kMonotoneSequence) {
      // Avoid inserting fields which appear in the template sequence (i.e.
      // which are consistent across all slices).
      if (!template_s->getShiftedLB()) {
        Value value = s->getShiftedLB()->buildOffsetValue(
            const_builder_, query_map_builder_, unit_op_.getLoc(),
            table_entry_type);
        encoding_tuple.push_back(value);
      }
      if (!template_s->getStride()) {
        Value stride = s->getStride()->buildOffsetValue(
            const_builder_, query_map_builder_, unit_op_.getLoc(),
            table_entry_type);
        encoding_tuple.push_back(stride);
      }
    } else {
      if (!template_s->getLB()) {
        Value value =
            s->getLB()->buildOffsetValue(const_builder_, query_map_builder_,
                                         unit_op_.getLoc(), table_entry_type);
        encoding_tuple.push_back(value);
      }
    }
    if (!skip_interval_marker && !template_s->getIntervalMarker().has_value()) {
      auto interval_marker_val =
          mlir::sentient::ConstantOp::create(const_builder_, unit_op_.getLoc(),
                                             table_->getPredicateType(),
                                             s->getIntervalMarker().value())
              .getResult();
      encoding_tuple.push_back(interval_marker_val);
    }
    seq_seen_so_far++;
  }
  return encoding_tuple;
}

