// entry 295/656   level 1   scc 125   58 body lines
// unit: e295_codeGenGenericTableSlice
// authority: dcc/src/Transform/Sentient/CFGSimplificationSentientLevel.cpp:2802
// original: Value PatternSimplificationManager::codeGenGenericTableSlice( const Value &iv, TableSlice *table_slice, OpBuilder &builder)
// rust home: crates/compiler/deeptools/src/transform/sentient/cfg_simplification_sentient_level/pattern_simplification_manager.rs
// ------------------------------------------------------------------------------------------------
Value e295_codeGenGenericTableSlice(
    const Value &iv, TableSlice *table_slice, OpBuilder &builder)
{
  auto &sequences = table_slice->getSequences();
  const Type table_entry_type = table_->getTableEntryType();

  // If there is only one sequence (i.e. the whole table_slice yields the same
  // value), no need to create an IfOp.
  if (sequences.size() == 1) {
    return sequences.front()->getLB()->buildOffsetValue(
        const_builder_, query_map_builder_, unit_op_.getLoc(),
        table_entry_type);
  }

  sentient::IfOp sentient_ifop_tmp, new_if;
  auto then_builder = builder;
  auto else_builder = builder;
  // Handle the last sequence separately, as it will correspond to the "else".
  for (auto it = sequences.begin(); it != std::prev(sequences.end(), 1); ++it) {
    Sequence *seq = *it;
    DT_CHECK_MSG(seq->getKind() == Sequence::kDefaultValue,
                 "Expect only kDefaultValue sequences.");
    dcc::WidestIntType interval_marker = seq->getIntervalMarker().value();
    Value result =
        seq->getLB()->buildOffsetValue(const_builder_, query_map_builder_,
                                       unit_op_.getLoc(), table_entry_type);
    Value rhs_val = mlir::sentient::ConstantOp::create(
                        const_builder_, unit_op_.getLoc(),
                        table_->getPredicateType(), interval_marker)
                        .getResult();
    ArrayAttr locale_attr =
        else_builder.getArrayAttr({mlir::sentient::SentientRegTypeAttr::get(
            else_builder.getContext(), SentientRegType::unknown)});
    auto comparison =
        seq->getIntervalStride() > 0 ? CmpIPredicate::sle : CmpIPredicate::sge;
    llvm::SmallVector<Type> type_vector = {table_entry_type};
    sentient_ifop_tmp = sentient::IfOp::create(
        else_builder, cur_root_->getLoc(), type_vector,
        mlir::sentient::CmpIPredicateAttr::get(else_builder.getContext(),
                                               comparison),
        iv, rhs_val, locale_attr, ArrayRef<int32_t>(), true);
    if (it == sequences.begin())
      new_if = sentient_ifop_tmp;
    else
      sentient::YieldOp::create(else_builder, sentient_ifop_tmp.getLoc(),
                                sentient_ifop_tmp.getResults()[0]);

    else_builder.createBlock(&sentient_ifop_tmp.getThenRegion());
    then_builder = sentient_ifop_tmp.getThenBodyBuilder();
    sentient::YieldOp::create(then_builder, sentient_ifop_tmp.getLoc(), result);

    else_builder.createBlock(&sentient_ifop_tmp.getElseRegion());
    else_builder = sentient_ifop_tmp.getElseBodyBuilder();
  }
  // The last sequence falls under the "else".
  Value result = sequences.back()->getLB()->buildOffsetValue(
      const_builder_, query_map_builder_, unit_op_.getLoc(), table_entry_type);
  sentient::YieldOp::create(else_builder, sentient_ifop_tmp.getLoc(), result);
  return new_if.getResults()[0];
}

