// entry 297/656   level 1   scc 152   64 body lines
// unit: e297_simplifyProgramUnitOp
// authority: dcc/src/Transform/Sentient/Deuniform.cpp:155
// original: void DeuniformPass::simplifyProgramUnitOp( mlir::dataflow::ProgramUnitOp prog_unit_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/deuniform/mod.rs
// ------------------------------------------------------------------------------------------------
void e297_simplifyProgramUnitOp(
    mlir::dataflow::ProgramUnitOp prog_unit_op)
{
  auto units = prog_unit_op.getUnits();
  auto prog_unit_arg = prog_unit_op.getBody()->getArgument(0);
  std::vector<mlir::Operation *> to_be_deleted;
  prog_unit_op.walk([&](mlir::Operation *local_op) {
    auto uniform_op =
        llvm::dyn_cast<mlir::uniform::UniformizeRegionsOp>(local_op);
    auto eq_pattern_op =
        llvm::dyn_cast<mlir::uniform::EqualizePatternOp>(local_op);
    if (eq_pattern_op || uniform_op) {
      mlir::ValueRange local_units_or_group;
      if (uniform_op) {
        local_units_or_group = uniform_op.getUnits();
      } else if (eq_pattern_op) {
        local_units_or_group = eq_pattern_op.getUnits();
      }
      std::vector<mlir::Value> local_units;
      for (auto unit : local_units_or_group) local_units.push_back(unit);
      dcc::uniform::utils::expandAllGroupsToUnits(local_units);
      bool hasIntersection = false;
      for (auto unit : local_units) {
        if (std::find(units.begin(), units.end(), unit) != units.end())
          hasIntersection = true;
      }
      if (!hasIntersection) {
        to_be_deleted.push_back(local_op);
      } else if (local_op->getNumRegions() == 1) {
        if (local_units.size() == units.size()) {
          bool perfectSubset = true;
          for (auto unit : local_units) {
            if (std::find(units.begin(), units.end(), unit) == units.end())
              perfectSubset = false;
          }
          if (perfectSubset) {
            dcc::uniform::utils::extractOpFromLocalRegion(local_op,
                                                          prog_unit_arg);
            to_be_deleted.push_back(local_op);
          }
        }
      }
    }
  });
  for (int i = to_be_deleted.size() - 1; i >= 0; i--) to_be_deleted[i]->erase();
  to_be_deleted.clear();
  prog_unit_op.walk([&](mlir::uniform::QueryMapOp query_op) {
    auto keys =
        dcc::uniform::utils::getListOfKeyOpsFromUniformMapping(query_op);
    auto values =
        dcc::uniform::utils::getListOfValueOpsFromUniformMapping(query_op);
    if (values.size() == 1) {
      if (query_op.getKey() == prog_unit_op.getBody()->getArgument(0) &&
          keys.size() <= prog_unit_op.getUnits().size()) {
        query_op.replaceAllUsesWith(values[0]);
        to_be_deleted.push_back(query_op);
      }
    }
  });
  for (auto op : to_be_deleted) op->erase();
  to_be_deleted.clear();
  prog_unit_op.walk([&](mlir::uniform::DefImmutableMappingOp mapping_op) {
    if (mapping_op.use_empty()) to_be_deleted.push_back(mapping_op);
  });
  for (auto op : to_be_deleted) op->erase();
}

