// original: mlir::uniform::QueryMapOp DeuniformPass::duplicateAndUpdateEntriesOfQueryMap( mlir::uniform::QueryMapOp query_map_op, std::vector<mlir::Value> new_units, mlir::OpBuilder builder)
// rust home: crates/compiler/deeptools/src/transform/sentient/deuniform/mod.rs
// ------------------------------------------------------------------------------------------------
mlir::uniform::QueryMapOp e298_duplicateAndUpdateEntriesOfQueryMap(
    mlir::uniform::QueryMapOp query_map_op, std::vector<mlir::Value> new_units,
    mlir::OpBuilder builder)
{
  auto keys =
      dcc::uniform::utils::getListOfKeyOpsFromUniformMapping(query_map_op);
  auto values =
      dcc::uniform::utils::getListOfValueOpsFromUniformMapping(query_map_op);
  std::vector<mlir::Value> new_keys, new_values;
  for (int i = 0; i < keys.size(); i++) {
    auto key = keys[i];
    auto value = values[i];
    if (std::find(new_units.begin(), new_units.end(), key) != new_units.end()) {
      new_keys.push_back(key);
      new_values.push_back(value);
    }
  }
  auto new_map = mlir::uniform::DefImmutableMappingOp::create(
      builder, builder.getUnknownLoc(), builder.getIndexType(), new_keys,
      new_values);
  auto new_query_map_op = mlir::uniform::QueryMapOp::create(
      builder, builder.getUnknownLoc(), builder.getIndexType(), new_map,
      query_map_op.getKey());
  return new_query_map_op;
}

// ------------------------------------------------------------------------------------------------
// entry 299/656   level 1   scc 153   35 body lines
// unit: e299_expandAllGroupsToUnitsAndUpdateSizes
// authority: dcc/src/Transform/Sentient/Deuniform.cpp:246
// original: void DeuniformPass::expandAllGroupsToUnitsAndUpdateSizes( std::vector<Value> &units, mlir::ArrayAttr &list_sizes, mlir::OpBuilder builder)
// rust home: crates/compiler/deeptools/src/transform/sentient/deuniform/mod.rs
// ------------------------------------------------------------------------------------------------
void e299_expandAllGroupsToUnitsAndUpdateSizes(
    std::vector<Value> &units, mlir::ArrayAttr &list_sizes,
    mlir::OpBuilder builder)
{
  std::vector<Value> new_units;
  std::vector<mlir::Attribute> new_list_sizes;
  for (auto unit : units) {
    std::vector<ValueRange> units_in_groups;
    if (auto group_op = llvm::dyn_cast<mlir::dataflow::CreateGroupOp>(
            unit.getDefiningOp())) {
      units_in_groups.push_back(group_op.getUnitIds());
    }
  }
  int index_of_unit = 0;
  for (int s = 0; s < list_sizes.size(); s++) {
    bool isGroup = false;
    for (int i = 0; i < mlir::cast<IntegerAttr>(list_sizes[s]).getInt(); i++) {
      if (auto group_op = llvm::dyn_cast<mlir::dataflow::CreateGroupOp>(
              units[index_of_unit].getDefiningOp())) {
        isGroup = true;
        DT_CHECK(mlir::cast<IntegerAttr>(list_sizes[s]).getInt() == 1);
        auto units_of_group = group_op.getUnitIds();
        for (auto u : units_of_group) new_units.push_back(u);
        new_list_sizes.push_back(builder.getIntegerAttr(
            builder.getIntegerType(32), units_of_group.size()));
      } else {
        new_units.push_back(units[index_of_unit]);
      }
      index_of_unit++;
    }
    if (!isGroup) {
      new_list_sizes.push_back(list_sizes[s]);
    }
  }
  units.clear();
  units = std::move(new_units);
  list_sizes = ArrayAttr::get(builder.getContext(), new_list_sizes);
}

