// entry 300/656   level 1   scc 162   53 body lines
// unit: e300_processWorkList
// authority: dcc/src/Transform/Sentient/EnhancedDeadVariableElimination.cpp:460
// original: void EnhancedDeadVariableEliminationPass::processWorkList()
// rust home: crates/compiler/deeptools/src/transform/sentient/enhanced_dead_variable_elimination/mod.rs
// ------------------------------------------------------------------------------------------------
void e300_processWorkList()
{
  while (!worklist_.empty()) {
    auto val = worklist_.front();
    auto influence_type = assignments_[val];
    worklist_.pop();

    int index = dcc::utils::getIndexOfLoopRegionIterArgs(val);
    if (index != -1) {
      auto for_op = llvm::dyn_cast<sentient::ForOp>(
          mlir::cast<BlockArgument>(val).getOwner()->getParentOp());

      // Add its iter operands
      addToWorkListAndUpdateAssignment(for_op.getIterOperands()[index],
                                       influence_type, for_op);

      // update its yield type as well
      auto *terminator = for_op.getLoopBody().front().getTerminator();
      addToWorkListAndUpdateAssignment(terminator->getOperand(index),
                                       influence_type, terminator);
    } else {
      auto *def = val.getDefiningOp();
      if (isa<sentient::AddOp, sentient::SubOp>(def)) {
        // Both inputs of add/sub operation will follow the influence
        // of its result.
        auto lhs = def->getOperand(0);
        addToWorkListAndUpdateAssignment(lhs, influence_type, def);

        auto rhs = def->getOperand(1);
        addToWorkListAndUpdateAssignment(rhs, influence_type, def);
      } else if (isa<sentient::CopyOp>(def)) {
        // The input of copy will follow the influence of its result.
        auto lhs = def->getOperand(0);
        addToWorkListAndUpdateAssignment(lhs, influence_type, def);
      } else if (isa<sentient::ForOp, sentient::IfOp,
                     uniform::UniformizeRegionsOp>(def)) {
        auto val_index = dcc::utils::getIndexOfOperationResults(val);
        DT_CHECK(val_index != -1);

        // update the yield operand type
        for (int i = 0; i < def->getNumRegions(); i++) {
          auto *terminator = def->getRegion(i).front().getTerminator();
          addToWorkListAndUpdateAssignment(terminator->getOperand(val_index),
                                           influence_type, terminator);
        }
        if (auto for_op = llvm::dyn_cast<sentient::ForOp>(def)) {
          // Add its iter operands
          addToWorkListAndUpdateAssignment(
              for_op.getRegionIterArgs()[val_index], influence_type, for_op);
        }
      }
    }
  }
}

