// ------------------------------------------------------------------------------------------------
void e303_runOn(ModuleOp module_op)
{
    llvm::SmallVector<func::FuncOp> funcs;
    module_op->walk<WalkOrder::PreOrder>([&](func::FuncOp func) {
      funcs.push_back(func);
      return WalkResult::skip();  // no nested functions
    });
    for (auto func : funcs) runOn(func);
  }

