// authority: dcc/src/Transform/Sentient/LiveRangeReduction.cpp:271
// original: LogicalResult LiveRangeReductionPass::getBaseExpr( PropagationAnalysis& expr_prop_analysis, const Value value, ExprInfo& expr_info, std::vector<int64_t>& const_val, bool& negated)
// rust home: crates/compiler/deeptools/src/transform/sentient/live_range_reduction/mod.rs
// ------------------------------------------------------------------------------------------------
LogicalResult e305_getBaseExpr(
    PropagationAnalysis& expr_prop_analysis, const Value value,
    ExprInfo& expr_info, std::vector<int64_t>& const_val, bool& negated)
{
  PropagationAnalysis::ExprInfoMap* expr_info_map =
      expr_prop_analysis.getAffineExpression(value);
  auto& affine_expressions = expr_info_map->getExprInfoList();
  bool is_expr_info_known = false;
  bool is_constant = isConstant<sentient::ConstantOp>(value);
  unsigned num_irresolvable_affine_expressions = 0;
  std::vector<int64_t> const_val_tmp;
  // Iterate through the different expressions corresponding to different units.
  // NOTE: Each affine_expression here may correspond to one or multiple units
  // (because we want to limit the number of calls to getFlattenedAffineExpr).
  for (auto affine_expression : affine_expressions) {
    // if no expression or expression is not resolved, use INT64_MAX as
    // const_val to indicate no applicable expression for this unit
    if (!affine_expression) {
      const_val_tmp.push_back(INT64_MAX);
      continue;
    }
    // for constant values, const_val needs to be filled.
    if (affine_expression->cannot_be_resolved_ && !is_constant) {
      num_irresolvable_affine_expressions++;
      // if expressions for all cores are irresolvable, return failure
      // if value is blockArgument, use itself as baseExpr
      if (num_irresolvable_affine_expressions == affine_expressions.size() &&
          isa<OpResult>(value))
        return LogicalResult::failure();
      const_val_tmp.push_back(INT64_MAX);
      continue;
    }

    // extract expression coeffs
    SmallVector<int64_t> flat_expr;
    affine::FlatAffineValueConstraints local_vars_constraints;
    auto args = affine_expression->propagated_args_;
    auto dim_num = affine_expression->propagated_map_.getNumDims();
    auto result =
        getFlattenedAffineExpr(affine_expression->propagated_map_.getResult(0),
                               dim_num, 0, &flat_expr, &local_vars_constraints);
    // TODO there is a bug in expression propagation pass which incorrectly adds
    // additional value to args_. a temporary fix to remove the first entry.
    if (args.size() > dim_num) {
      args = {args.begin() + 1, args.end()};
    }
    DT_CHECK(flat_expr.size() ==
             dim_num + local_vars_constraints.getNumLocalVars() + 1);

    // the const expr is at the back.
    const_val_tmp.push_back(flat_expr.back());
    flat_expr.pop_back();
    // normalize flat_expr to make the first non-zero value positive.
    bool temp_negated = false;
    for (auto coeff : flat_expr) {
      if (coeff == 0) {
        continue;
      } else if (coeff > 0) {
        break;
      } else {
        temp_negated = true;
        break;
      }
    }
    if (temp_negated) {
      for (int i = 0; i < flat_expr.size(); i++) {
        flat_expr[i] = -flat_expr[i];
      }
    }
    if (is_expr_info_known) {
      // compare the new expr with the existing one
      ExprInfo new_expr_info;
      new_expr_info.set(flat_expr, args, local_vars_constraints);
      if (!(new_expr_info == expr_info) || (negated != temp_negated)) {
        // If mismatching expr_info (e.g. due to different coefficients),
        // return failure.
        return LogicalResult::failure();
      }
    } else {
      // set expr_info for the first time
      expr_info.set(flat_expr, args, local_vars_constraints);
      negated = temp_negated;
      is_expr_info_known = true;
    }
  }

  // At this point const_val_tmp contain one constant per ExprInfo in the
  // ExprInfoMap. However, we need one constant per unit.
  int num_units = expr_info_map->getUnitNumber();
  const_val.resize(num_units);
  for (unsigned unit_idx = 0; unit_idx < num_units; ++unit_idx) {
    const_val[unit_idx] =
        const_val_tmp[expr_info_map->getListIdxFromUnitIdx(unit_idx)];
  }

  // if iter_arg is not resolvable for all units, copy the last entry of
  // const_val to all other units
  if (num_irresolvable_affine_expressions == affine_expressions.size() &&
      affine_expressions.size() > 1 && isa<BlockArgument>(value)) {
    for (int i = 0; i < const_val.size() - 1; i++) {
      const_val[i] = const_val.back();
    }
  }

  // uniformize_regionsOp's results are in global region, so it is necessary to
  // replace INT64_MAX entries with any valid value in the vector to improve the
  // uniformity across cores.
  if (!isa<BlockArgument>(value) &&
      isa<uniform::UniformizeRegionsOp>(value.getDefiningOp())) {
    int64_t tmp = INT64_MAX;
    for (auto item : const_val) {
      if (item != INT64_MAX) tmp = item;
    }
    for (auto& item : const_val) {
      if (item == INT64_MAX) item = tmp;
    }
  }
  return LogicalResult::success();
}

