// entry 306/656   level 1   scc 209   72 body lines
// unit: e306_getRootIterArg
// authority: dcc/src/Transform/Sentient/LiveRangeReduction.cpp:393
// original: Value LiveRangeReductionPass::getRootIterArg(Value val)
// rust home: crates/compiler/deeptools/src/transform/sentient/live_range_reduction/mod.rs
// ------------------------------------------------------------------------------------------------
Value e306_getRootIterArg(Value val)
{
  while (val && !mlir::isa<BlockArgument>(val)) {
    if (auto add_op = val.getDefiningOp<sentient::AddOp>()) {
      if (mlir::isa<BlockArgument>(add_op.getInp1()) ||
          !isConstant<sentient::ConstantOp>(add_op.getInp1())) {
        val = add_op.getInp1();
      } else {
        val = add_op.getInp2();
      }
    } else if (auto sub_op = val.getDefiningOp<sentient::SubOp>()) {
      if (mlir::isa<BlockArgument>(sub_op.getInp1()) ||
          !isConstant<sentient::ConstantOp>(sub_op.getInp1())) {
        val = sub_op.getInp1();
      } else {
        val = sub_op.getInp2();
      }
    } else if (auto for_op = val.getDefiningOp<sentient::ForOp>()) {
      auto operand_idx = mlir::cast<OpResult>(val).getResultNumber() +
                         for_op.getNumControlOperands();
      val = for_op->getOperand(operand_idx);
    } else if (auto load_and_send_op =
                   val.getDefiningOp<sentient::LoadAndSendOp>()) {
      val = load_and_send_op.getMutableAddr();
    } else if (auto receive_and_store_op =
                   val.getDefiningOp<sentient::ReceiveAndStoreOp>()) {
      val = receive_and_store_op.getMutableAddr();
    } else if (auto load_and_store_op =
                   val.getDefiningOp<sentient::LoadAndStoreOp>()) {
      int result_idx = mlir::cast<OpResult>(val).getResultNumber();
      // Set val to the correct mutable address based on which result number it
      // is.
      val = result_idx > 0 ? load_and_store_op.getDstMutableAddr()
                           : load_and_store_op.getSrcMutableAddr();
    } else if (auto load_and_extract_op =
                   dyn_cast<sentient::LoadAndExtractScalarOp>(
                       val.getDefiningOp())) {
      // Only addr results of load_and_extract_scalar operations are valid. Data
      // results don't chain or map to anything in the IR as they represent the
      // data -stored- at the address specified by mutable+immutable.
      int result_idx = mlir::cast<OpResult>(val).getResultNumber();
      if (result_idx == load_and_extract_op.getAddrResultIdx())
        val = load_and_extract_op.getMutableAddr();
      else
        break;
    } else if (auto load_compute_op =
                   val.getDefiningOp<sentient::LoadComputeAndSendOp>()) {
      val = load_compute_op.getMutableAddr();
    } else if (auto uniformize_op = dyn_cast<uniform::UniformizeRegionsOp>(
                   val.getDefiningOp())) {
      if (uniformize_op->getNumRegions() > 1) {
        DT_CHECK(uniformize_op->getNumRegions() == 2);
        DT_CHECK(uniformize_op->getRegion(1)
                     .getBlocks()
                     .front()
                     .getOperations()
                     .size() == 1);
      }
      unsigned result_idx = 0;
      for (Value result : uniformize_op->getResults()) {
        if (result == val) {
          val = uniformize_op->getRegion(0).front().getTerminator()->getOperand(
              result_idx);
          break;
        }
        result_idx++;
      }
    } else {
      break;
    }
  }
  return val;
}

