// entry 307/656   level 1   scc 217   40 body lines
// unit: e307_cloneValueToRegion
// authority: dcc/src/Transform/Sentient/LiveRangeReduction.cpp:917
// original: std::optional<Value> cloneValueToRegion(Value val, Region& region, OpBuilder& builder)
// rust home: crates/compiler/deeptools/src/transform/sentient/live_range_reduction/mod.rs
// ------------------------------------------------------------------------------------------------
std::optional<Value> e307_cloneValueToRegion(Value val, Region& region,
                                        OpBuilder& builder)
{
  DT_CHECK(region.getRegionNumber() == 1);
  // if val's definingOp is inside the first region of uniformizeRegionOp, need
  // to clone it to the region.
  if (isa<OpResult>(val) &&
      !val.getDefiningOp()->getParentRegion()->isProperAncestor(&region)) {
    DT_CHECK(isConstant<sentient::ConstantOp>(val));
    if (auto query_op = dyn_cast<uniform::QueryMapOp>(val.getDefiningOp())) {
      auto map_op =
          query_op.getMap().getDefiningOp<uniform::DefImmutableMappingOp>();
      // check if immutable map contains values for the region's units
      auto units = collectUnitVals(
          dyn_cast<uniform::UniformizeRegionsOp>(region.getParentOp())
              .getRegionUnitList(region.getRegionNumber()));
      // collect keys and maps for the new map.
      SmallVector<Value> values, keys;
      for (auto unit : units) keys.push_back(unit);
      values = map_op.getNonNullValuesFromKeys(keys);

      if (values.size() != keys.size()) {
        // if val is a queryOp which doesn't cover region's units,
        // quit adding
        return std::nullopt;
      }

      // if map is not ancestor of uniform region op, create new one inside the
      // region
      if (!query_op->isProperAncestor(region.getParentOp())) {
        map_op = uniform::DefImmutableMappingOp::create(
            builder, map_op->getLoc(), builder.getIndexType(), keys, values);
      }
      // create queryOp
      auto new_query_op = uniform::QueryMapOp::create(
          builder, query_op->getLoc(), builder.getIndexType(), map_op,
          region.getArgument(0));
      val = new_query_op.getResult();
    }
  }
  return val;
}

