// original: void LoopAbsorptionManager::absorbIntoAnchorFromLeft()
// rust home: crates/compiler/deeptools/src/transform/sentient/loop_absorption/loop_absorption_manager.rs
// ------------------------------------------------------------------------------------------------
void e309_absorbIntoAnchorFromLeft()
{
  // Update the starting values of the iteration arguments.
  for (auto pair : iter_arg_num_to_new_start_val_)
    anchor_for_op_.setOperand(std::get<0>(pair), std::get<1>(pair));
  iter_arg_num_to_new_start_val_.clear();

  // Collect the operations to be absorbed, then remove them.
  std::vector<Operation *> to_delete;
  // Don't count the yield op in the for loop.
  int count = body_bb_->getOperations().size() - 1;
  for (auto block_it = std::prev(Block::iterator(anchor_for_op_), 1); count > 0;
       --count, block_it = std::prev(block_it, 1))
    to_delete.push_back(&*block_it);
  for (auto op : to_delete) op->erase();
}

