// original: void LoopAbsorptionManager::absorbIntoAnchorFromRight()
// rust home: crates/compiler/deeptools/src/transform/sentient/loop_absorption/loop_absorption_manager.rs
// ------------------------------------------------------------------------------------------------
void e310_absorbIntoAnchorFromRight()
{
  // Update the uses of ops to the right to uses of the anchor loop.
  for (auto pair : to_update_)
    std::get<0>(pair).replaceAllUsesWith(std::get<1>(pair));
  to_update_.clear();

  // Collect the operations to be absorbed, then remove them.
  std::vector<Operation *> to_delete;
  // Don't count the yield op in the for loop.
  int count = body_bb_->getOperations().size() - 1;

  for (auto block_it = std::next(Block::iterator(anchor_for_op_), 1); count > 0;
       --count, block_it = std::next(block_it, 1))
    to_delete.push_back(&*block_it);
  for (auto rev_it = to_delete.rbegin(); rev_it != to_delete.rend(); ++rev_it)
    (*rev_it)->erase();
}

