// entry 311/656   level 1   scc 248   56 body lines
// unit: e311_getCandidateLoops
// authority: dcc/src/Transform/Sentient/LoopCoalescing.cpp:76
// original: void getCandidateLoops( SmallVectorImpl<sentient::ForOp> &band_ForOps, sentient::ForOp root_ForOp, unsigned max_loops = std::numeric_limits<unsigned>::max())
// rust home: crates/compiler/deeptools/src/transform/sentient/loop_coalescing/mod.rs
// ------------------------------------------------------------------------------------------------
void e311_getCandidateLoops(
      SmallVectorImpl<sentient::ForOp> &band_ForOps, sentient::ForOp root_ForOp,
      unsigned max_loops = std::numeric_limits<unsigned>::max())
{
    int n_loop_carried_args = root_ForOp.getNumRegionIterArgs();
    for (unsigned i = 0; i < max_loops; ++i) {
      // check if there are no uses of the loop iterator or
      // iter_arguments holds the condition to coalesce them.
      if (!root_ForOp.getInductionVar().use_empty() ||
          root_ForOp.getRegion().front().getArguments().size() !=
              1 + n_loop_carried_args ||
          root_ForOp.getNumRegionIterArgs() != n_loop_carried_args)
        return;

      // check if this is a dynamic loop
      if (!dcc::utils::isConstant<sentient::ConstantOp>(root_ForOp.getBound()))
        return;

      band_ForOps.push_back(root_ForOp);
      Block &body = root_ForOp.getRegion().front();

      // check that the loop only contains 1 op other than its yield
      if (body.begin() != std::prev(body.end(), 2)) return;

      auto root_ForOp_yield = root_ForOp.getLoopBody().front().getTerminator();
      auto tmp_ForOp = dyn_cast<sentient::ForOp>(&body.front());

      if (!tmp_ForOp) return;

      // Number of iterator arguments should match!
      if (tmp_ForOp.getNumRegionIterArgs() != n_loop_carried_args) return;

      for (unsigned j = 0; j < n_loop_carried_args; j++) {
        auto &root_ForOp_regionIterArg = root_ForOp.getRegionIterArgs()[j];
        // check validity of loop iterator arguments
        if (tmp_ForOp.getIterOperands()[j] != root_ForOp_regionIterArg) {
          return;
        }

        // check yield values
        if (tmp_ForOp.getResult(j) != root_ForOp_yield->getOperand(j)) {
          return;
        }

        // Check number of uses of that region iter argument.
        // If it has one use, that should be the tmp_ForOp iterator operands,
        // which is already checked above. If it has no uses, there is no harm
        // in coalescing them.
        bool ineligible = !(root_ForOp_regionIterArg.hasOneUse() ||
                            root_ForOp_regionIterArg.use_empty());
        if (ineligible) return;
      }

      root_ForOp = tmp_ForOp;

      // check that the only op in the loop is also a loop
      if (!root_ForOp) return;
    }
  }

