// entry 312/656   level 1   scc 250   10 body lines
// unit: e312_splitBounds
// authority: dcc/src/Transform/Sentient/LoopCoalescing.cpp:417
// original: void LoopCoalescingPass::splitBounds(std::vector<int64_t> &new_bounds, std::vector<int64_t> &new_bounds0, std::vector<int64_t> &new_bounds1)
// rust home: crates/compiler/deeptools/src/transform/sentient/loop_coalescing/mod.rs
// ------------------------------------------------------------------------------------------------
void e312_splitBounds(std::vector<int64_t> &new_bounds,
                                     std::vector<int64_t> &new_bounds0,
                                     std::vector<int64_t> &new_bounds1)
{
  for (int i = 0; i < new_bounds.size(); i++) {
    if (new_bounds[i] > MAX_LCCR_VALUE) {
      new_bounds0[i] = getLargestDivisor(new_bounds[i], (int)MAX_LCCR_VALUE);
      new_bounds1[i] = new_bounds[i] / new_bounds0[i];
    } else {
      new_bounds0[i] = new_bounds[i];
    }
  }
}

