// entry 313/656   level 1   scc 256   52 body lines
// unit: e313_isCandidate
// authority: dcc/src/Transform/Sentient/LoopEliminationViaRerolling.cpp:117
// original: bool isCandidate(Operation *for_op, SenComponents unit_comp) const
// rust home: crates/compiler/deeptools/src/transform/sentient/loop_elimination_via_rerolling/mod.rs
// ------------------------------------------------------------------------------------------------
bool e313_isCandidate(Operation *for_op, SenComponents unit_comp) const
{
    auto sentient_for = llvm::dyn_cast<sentient::ForOp>(for_op);
    DT_CHECK_MSG(sentient_for, "Expect a valid for op.");
    // A ForOp is a candidate if it satisfies the following conditions.
    // In compute units:
    // - It only contains exactly one MacOp, BinaryOp, TernaryOp, or UnaryOp,
    // and its
    //   unroll fields are zero.
    // - The loop has no iterator arguments.
    // - In PT units, xrf cannot be one of the operands of the target op.
    // - In PE/SFP units, nfwd cannot be one of the operands of the target op.
    // In memory units:
    // - It only contains exactly one LoadAndSendOp or ReceiveAndStoreOp,
    //   and its interleaved group is 0.
    // - The loop has exactly one iterator argument, namely the Mutable field of
    //   the memory op.
    // - The only other ops it may contain are ConstantOp or the yield.
    bool is_compute_unit = is_any_of(unit_comp, SenComponents::SFP,
                                     SenComponents::PE, SenComponents::PT);
    bool is_pt = (unit_comp == SenComponents::PT);

    auto nontrivial_ops_in_body = getNontrivialOpsInLoop(sentient_for);
    if ((!is_compute_unit && sentient_for.getNumRegionIterArgs() != 1) ||
        (is_compute_unit && sentient_for.getNumRegionIterArgs() != 0) ||
        nontrivial_ops_in_body.size() != 1)
      return false;

    Operation *target_op = nontrivial_ops_in_body.front();
    if (is_compute_unit) {
      if (isa<MacOp, BinaryOp, UnaryOp, TernaryOp>(target_op)) {
        StringRef invalid_operand = is_pt ? "xrf" : "nfwd";
        return checkOperandsOfComputeOp(target_op, invalid_operand);
      }
      return false;
    } else {
      // Interleaved group
      int il;
      if (auto ls = llvm::dyn_cast<LoadAndSendOp>(target_op)) {
        if (ls.getMutableAddr() != sentient_for.getRegionIterArgs()[0])
          return false;
        il = (int)ls.getInterleavedGroup();
      } else if (auto rs = llvm::dyn_cast<ReceiveAndStoreOp>(target_op)) {
        if (rs.getMutableAddr() != sentient_for.getRegionIterArgs()[0])
          return false;
        il = (int)rs.getInterleavedGroup();
      } else {
        return false;
      }
      if (il > 0) return false;
    }
    return true;
  }

