// entry 316/656   level 1   scc 265   100 body lines
// unit: e316_mergeLoops
// authority: dcc/src/Transform/Sentient/LoopMerging.cpp:179
// original: void LoopMergingPass::mergeLoops( std::pair<dcc::LoopNode *, dcc::LoopNode *> loops)
// rust home: crates/compiler/deeptools/src/transform/sentient/loop_merging/mod.rs
// ------------------------------------------------------------------------------------------------
void e316_mergeLoops(
    std::pair<dcc::LoopNode *, dcc::LoopNode *> loops)
{
  DT_CHECK_MSG(loops.first != loops.second, "loop pointers are identical");
  auto first_loop = loops.first->getOpAs<sentient::ForOp>();
  auto second_loop = loops.second->getOpAs<sentient::ForOp>();
  DT_CHECK_MSG(getNextEligibleOp(first_loop) == second_loop,
               "expected second loop to come right after the first one");

  // Compute the sum of loop bounds
  Value first_bound = first_loop.getBound();
  Value second_bound = second_loop.getBound();
  auto first_const_bound =
      llvm::dyn_cast<sentient::ConstantOp>(first_bound.getDefiningOp());
  auto second_const_bound =
      llvm::dyn_cast<sentient::ConstantOp>(second_bound.getDefiningOp());
  auto first_query_map =
      llvm::dyn_cast<uniform::QueryMapOp>(first_bound.getDefiningOp());
  auto second_query_map =
      llvm::dyn_cast<uniform::QueryMapOp>(second_bound.getDefiningOp());
  DT_CHECK_MSG(first_bound.getType() == second_bound.getType(),
               "expected loop bounds to be of the same type");
  Type bound_type = first_bound.getType();
  Location loc = first_loop.getLoc();
  Operation *unit =
      loops.first->getOperation()->getParentOfType<dataflow::ProgramUnitOp>();
  DT_CHECK_MSG(unit, "expected loop to appear in dataflow.program_unit");
  OpBuilder const_builder(dyn_cast<dataflow::ProgramUnitOp>(*unit).getRegion());

  bool is_first_query_map_constant =
      first_query_map &&
      dcc::utils::isConstant<sentient::ConstantOp>(first_query_map.getResult());
  bool is_second_query_map_constant =
      second_query_map && dcc::utils::isConstant<sentient::ConstantOp>(
                              second_query_map.getResult());

  if (first_const_bound && second_const_bound) {
    first_loop.setBound(sentient::ConstantOp::create(
        const_builder, loc, bound_type,
        first_const_bound.getValue() + second_const_bound.getValue()));
  } else if (first_const_bound && is_second_query_map_constant) {
    dcc::utils::updateBoundToValuePlusMap(
        first_const_bound.getResult(), second_query_map, const_builder,
        first_loop,
        /*is_constant_value_query_map = */ true);
  } else if (is_first_query_map_constant && second_const_bound) {
    dcc::utils::updateBoundToValuePlusMap(
        second_const_bound.getResult(), first_query_map, const_builder,
        first_loop,
        /*is_constant_value_query_map = */ true);
  } else if (is_first_query_map_constant && is_second_query_map_constant) {
    dcc::utils::updateBoundToMapPlusMap(
        first_query_map, second_query_map, const_builder, first_loop,
        /*is_constant_value_query_map = */ true);
  } else {
    if (!first_query_map && !second_query_map) {
      // Always insert the sum of trip counts before the first child in a list
      // of siblings. This is needed to avoid inserting intervening
      // instructions between otherwise mergeable loops, for example when we
      // walk in RBFS order.
      dcc::LoopNode *parent = loops.first->getParentLoop();
      DT_CHECK_MSG(parent, "did not expect root here");
      DT_CHECK_MSG(parent->getFirstChild(),
                   "expected parent to have first child");
      OpBuilder builder(parent->getFirstChild()->getOpAs<sentient::ForOp>());
      first_loop.setBound(sentient::AddOp::create(builder, loc, bound_type,
                                                  first_bound, second_bound));
    } else if (first_query_map && !second_query_map) {
      dcc::utils::updateBoundToValuePlusMap(
          second_bound, first_query_map, const_builder, first_loop,
          /*is_constant_value_query_map = */ false);
    } else if (!first_query_map && second_query_map) {
      dcc::utils::updateBoundToValuePlusMap(
          first_bound, second_query_map, const_builder, first_loop,
          /*is_constant_value_query_map = */ false);
    } else /*(first_query_map && second_query_map)*/ {
      dcc::utils::updateBoundToMapPlusMap(
          first_query_map, second_query_map, const_builder, first_loop,
          /*is_constant_value_query_map = */ false);
    }
  }

  DT_CHECK_MSG(
      first_loop.getResults().size() == second_loop.getResults().size(),
      "expected equal number of results");
  for (auto pair : llvm::zip(first_loop.getResults(), second_loop.getResults()))
    std::get<1>(pair).replaceAllUsesWith(std::get<0>(pair));

  if (StringAttr new_dbg_name = dataflow::utils::getNewDbgNameFromList(
          /*prefix*/ "LM(", {first_loop, second_loop}))
    first_loop.setDbgName(new_dbg_name);

  // Remove the second loop and clean up unused defs for the removed bounds.
  if (first_loop.getBound().getDefiningOp()->use_empty())
    first_loop.getBound().getDefiningOp()->erase();
  Operation *saved_def_op = second_bound.getDefiningOp();
  second_loop.getOperation()->erase();
  if (saved_def_op->use_empty()) saved_def_op->erase();

  LLVM_DEBUG(llvm::dbgs() << "** Merged a pair of loops!\n");
  ++loops_merged_count;
}

