// entry 318/656   level 1   scc 288   10 body lines
// unit: e318_promoteForLoopBodyAndDelete
// authority: dcc/src/Transform/Sentient/LoopSplittingAndUnrolling.cpp:147
// original: void LoopSplittingAndUnrollingPass::promoteForLoopBodyAndDelete( sentient::ForOp for_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/loop_splitting_and_unrolling/mod.rs
// ------------------------------------------------------------------------------------------------
void e318_promoteForLoopBodyAndDelete(
    sentient::ForOp for_op)
{
  auto *parent_block = for_op->getBlock();
  replaceIterArgsAndYieldResults(for_op);
  // Move the loop body operations, except for its terminator, to the loop's
  // containing block.
  for_op.getBody()->back().erase();
  parent_block->getOperations().splice(Block::iterator(for_op),
                                       for_op.getBody()->getOperations());
  for_op.erase();
}

