// rust home: crates/compiler/deeptools/src/transform/sentient/loop_splitting_and_unrolling/mod.rs
// ------------------------------------------------------------------------------------------------
void e320_subsetsImpl(std::vector<std::pair<int, int>> &split_vals,
                        std::vector<std::vector<std::pair<int, int>>> &res,
                        std::vector<std::pair<int, int>> &subset, int index)
{
  res.push_back(subset);
  for (int i = index; i < split_vals.size(); i++) {
    subset.push_back(split_vals[i]);
    subsetsImpl(split_vals, res, subset, i + 1);
    subset.pop_back();
  }
  return;
}

