// entry 322/656   level 1   scc 314   65 body lines
// unit: e322_copyOneIter
// authority: dcc/src/Transform/Sentient/MultiDimLoopPeeling.cpp:461
// original: void LoopPeelingManager::copyOneIter( sentient::ForOp for_op, llvm::SmallVector<mlir::Value, 4> &new_iter_args, int64_t iv_val, bool move_after)
// rust home: crates/compiler/deeptools/src/transform/sentient/multi_dim_loop_peeling/loop_peeling_manager.rs
// ------------------------------------------------------------------------------------------------
void e322_copyOneIter(
    sentient::ForOp for_op, llvm::SmallVector<mlir::Value, 4> &new_iter_args,
    int64_t iv_val, bool move_after)
{
  // First clone the loop so we do not modify the original one. We will
  // perform the necessary replacements, then hoist the ops out of the
  // cloned loop and finally remove the cloned loop.
  OpBuilder builder(for_op);
  if (move_after) builder.setInsertionPointAfter(for_op);
  auto cloned_for_op = llvm::dyn_cast<sentient::ForOp>(builder.clone(*for_op));

  // Keep track of IfOps with comparisons on the IV for later
  // simplification.
  SmallVector<Operation *, 4> if_ops_to_simplify;
  Value iv = cloned_for_op.getInductionVar();
  for (auto iv_use : iv.getUsers()) {
    if (auto if_op = llvm::dyn_cast<sentient::IfOp>(iv_use))
      if_ops_to_simplify.push_back(if_op);
  }

  // Replace the IV by iv_val
  auto replacement = sentient::ConstantOp::create(
      const_builder_, cloned_for_op->getLoc(), iv.getType(), iv_val);
  iv.replaceAllUsesWith(replacement.getResult());

  // Replace the uses of the original loop's results with the results of the
  // last iteration. Here we replace by cloned_for_op's results, and when
  // hoisting ops out of this loop we will replace those results' uses by the
  // yielded values. Only needed if cloned loop is placed after the original.
  // NOTE: The reason for doing this replacement in two parts is that the
  // original loop's results may be used as iter arg init values below and those
  // uses should NOT be replaced.
  if (move_after) {
    for (int i = 0; i < for_op.getNumResults(); ++i)
      for_op.getResults()[i].replaceAllUsesWith(cloned_for_op.getResults()[i]);
  }

  // Replace the iter args by the init values stored in new_iter_args.
  auto iter_args = cloned_for_op.getRegionIterArgs();
  DT_CHECK_MSG(new_iter_args.size() == cloned_for_op.getNumResults(),
               "Invalid set of iter arg init values");
  for (int i = 0; i < cloned_for_op.getNumResults(); ++i) {
    iter_args[i].replaceAllUsesWith(new_iter_args[i]);
  }

  // Simplify the conditionals
  simplifyConditionals(for_op->getContext(), if_ops_to_simplify);

  // Hoist the operations out of the cloned loop, and delete the
  // loop once empty.
  Block *body = cloned_for_op.getBody(0);
  while (!body->empty()) {
    auto &op = body->getOperations().front();
    if (isa<mlir::sentient::YieldOp>(op)) {
      // Update new_iter_args to be the values of the iter args after this
      // iteration.
      new_iter_args.clear();
      new_iter_args = op.getOperands();
      if (move_after) {
        for (int i = 0; i < cloned_for_op.getNumResults(); ++i)
          cloned_for_op.getResults()[i].replaceAllUsesWith(new_iter_args[i]);
      }
      break;
    }
    op.moveBefore(cloned_for_op);
  }
  cloned_for_op->erase();
}

