// original: void MulticastCanonicalizationPass::processQMapOfDirectMulticast( sentient::ReceiveAndStoreOp ras, uniform::QueryMapOp query_map)
// rust home: crates/compiler/deeptools/src/transform/sentient/multicast_canonicalization/mod.rs
// ------------------------------------------------------------------------------------------------
void e324_processQMapOfDirectMulticast(
    sentient::ReceiveAndStoreOp ras, uniform::QueryMapOp query_map)
{
  uniform::QueryMapOp new_query_map = createNewProducerQMap(query_map);
  DT_CHECK_MSG(new_query_map, "unable to create a query map for the producers");
  // List of ReceiveAndStoreOps with qmap as the producer.
  llvm::SmallVector<sentient::ReceiveAndStoreOp> ras_list;
  for (auto &use : query_map->getUses()) {
    if (auto receive_and_store =
            llvm::dyn_cast<ReceiveAndStoreOp>(use.getOwner()))
      ras_list.push_back(receive_and_store);
  }
  for (auto receive_and_store : ras_list) {
    receive_and_store.getProducerMutable().assign(new_query_map.getResult());
    receive_and_store.getMulticastInfoMutable().assign(query_map);
  }
  return;
}

