// rust home: crates/compiler/deeptools/src/transform/sentient/old_register_initialization/register_init_info.rs
// ------------------------------------------------------------------------------------------------
int e327_calcSSAWeight(mlir::Operation *op)
{
  auto addCandidate = [this](mlir::Value val) {
    const RegInitLocalePriority priority = getRegisterInitPriority(val);
    if (priority == RegInitLocalePriority::kRequired)
      required_reginit_candidates_.push_back(val);
    else if (priority == RegInitLocalePriority::kAllowed)
      valid_reginit_candidates_.push_back(val);
  };
  if (auto for_op = llvm::dyn_cast<sentient::ForOp>(op)) {
    size_t num_region_iter = for_op.getNumRegionIterArgs();
    for (int i = 0; i < num_region_iter; i++) {
      auto iter_arg = for_op.getIterOperands()[i];
      if (iter_arg.getDefiningOp() &&
          (isa<sentient::ConstantOp>(iter_arg.getDefiningOp()) ||
           isa<uniform::QueryMapOp>(iter_arg.getDefiningOp()))) {
        ssa_weight_[for_op.getRegionIterArgs()[i]] = totalTripCount(for_op);
        if (dcc::utils::isOuterMostLoop(for_op))
          addCandidate(for_op.getRegionIterArgs()[i]);
      }
    }
  } else if (auto copy_op = llvm::dyn_cast<sentient::CopyOp>(op)) {
    if (copy_op.getOperand().getDefiningOp()) {
      auto def_op = copy_op.getOperand().getDefiningOp();
      if (isa<sentient::ConstantOp, uniform::QueryMapOp, dataflow::GetUnitOp,
              symbol::CreateSymbolOp>(def_op)) {
        ssa_weight_[copy_op.getOut()] = totalTripCount(copy_op);
        addCandidate(copy_op.getOut());
      } else if (auto mc_op =
                     llvm::dyn_cast<dataflow::CreateMulticastGroupOp>(def_op)) {
        if (!isa<uniform::QueryMapOp>(mc_op.getProducer().getDefiningOp())) {
          ssa_weight_[copy_op.getOut()] = totalTripCount(copy_op);
          addCandidate(copy_op.getOut());
        }
      }
    }
  } else if (auto ls_op = llvm::dyn_cast<sentient::LoadAndSendOp>(op)) {
    ssa_weight_[ls_op.getResult()] = totalTripCount(ls_op);
  } else if (auto rs_op = llvm::dyn_cast<sentient::ReceiveAndStoreOp>(op)) {
    ssa_weight_[rs_op.getResult()] = totalTripCount(rs_op);
  } else if (auto ls_op = llvm::dyn_cast<sentient::LoadAndStoreOp>(op)) {
    ssa_weight_[ls_op.getResult(0)] = totalTripCount(ls_op);
    ssa_weight_[ls_op.getResult(1)] = totalTripCount(ls_op);
  } else if (auto add = llvm::dyn_cast<sentient::AddOp>(op)) {
    ssa_weight_[add.getResult()] = totalTripCount(add);
  } else if (auto sub = llvm::dyn_cast<sentient::SubOp>(op)) {
    ssa_weight_[sub.getResult()] = totalTripCount(sub);
  } else if (auto rae_op =
                 llvm::dyn_cast<sentient::ReceiveAndExtractScalarOp>(op)) {
    ssa_weight_[rae_op.getResult()] = totalTripCount(rae_op);
  } else if (auto lae_op =
                 llvm::dyn_cast<sentient::LoadAndExtractScalarOp>(op)) {
    ssa_weight_[lae_op.getResult(0)] = totalTripCount(lae_op);
    ssa_weight_[lae_op.getResult(1)] = totalTripCount(lae_op);
  } else if (auto lcas_op =
                 llvm::dyn_cast<sentient::LoadComputeAndSendOp>(op)) {
    ssa_weight_[lcas_op.getResult()] = totalTripCount(lcas_op);
  }
  return 0;
}

