// original: std::tuple<int, int, bool, std::vector<mlir::Value>> RegisterInitInfo::getNextMaxWeight(int i, int j)
// rust home: crates/compiler/deeptools/src/transform/sentient/old_register_initialization/register_init_info.rs
// ------------------------------------------------------------------------------------------------
std::tuple<int, int, bool, std::vector<mlir::Value>>
e330_getNextMaxWeight(int i, int j)
{
  if (valid_reginit_candidates_.size() <= i) {
    if (valid_reg_coalescing_candidates_.size() <= j) {
      return {i, j, false, {}};
    };
    const auto &reg_coal_val = valid_reg_coalescing_candidates_[j];
    j++;
    return {i, j, false, reg_coal_val};
  }
  if (valid_reg_coalescing_candidates_.size() <= j) {
    if (valid_reginit_candidates_.size() <= i) {
      return {i, j, false, {}};
    };
    auto reg_init_val = valid_reginit_candidates_[i];
    i++;
    return {i, j, true, std::vector<mlir::Value>{reg_init_val}};
  }
  auto reg_init_val = valid_reginit_candidates_[i];
  const auto &reg_coal_val = valid_reg_coalescing_candidates_[j];
  auto reg_init_val_wt = ssa_weight_[reg_init_val];
  auto reg_coal_val_wt = weightOfSubset(reg_coal_val);
  if (reg_init_val_wt > reg_coal_val_wt) {
    i++;
    return {i, j, true, std::vector<mlir::Value>{reg_init_val}};
  } else {
    j++;
    return {i, j, false, reg_coal_val};
  }
}

