// entry 332/656   level 1   scc 363   25 body lines
// unit: e332_moveSSAToInit
// authority: dcc/src/Transform/Sentient/OldRegisterInitialization.cpp:715
// original: static void moveSSAToInit(mlir::Value val)
// rust home: crates/compiler/deeptools/src/transform/sentient/old_register_initialization/mod.rs
// ------------------------------------------------------------------------------------------------
void e332_moveSSAToInit(mlir::Value val)
{
  mlir::Operation *op = val.getDefiningOp();
  auto *parent_region = val.getParentRegion();
  if (!op) op = parent_region->getParentOp();
  if (auto copy_op = llvm::dyn_cast_or_null<sentient::CopyOp>(op)) {
    op->setAttr("programHeader", BoolAttr::get(op->getContext(), true));
  } else if (auto for_op = llvm::dyn_cast_or_null<sentient::ForOp>(op)) {
    size_t num_region_iter = for_op.getNumRegionIterArgs();
    const auto &program_header = for_op.getProgramHeaderAttr();
    SmallVector<Attribute, 4> new_program_header;
    for (int i = 0; i < num_region_iter; i++) {
      if (for_op.getRegionIterArgs()[i] == val) {
        new_program_header.push_back(BoolAttr::get(op->getContext(), true));

      } else {
        if (program_header.size() > i)
          new_program_header.push_back(mlir::cast<BoolAttr>(program_header[i]));
        else
          new_program_header.push_back(BoolAttr::get(op->getContext(), false));
      }
    }
    op->setAttr("programHeader",
                ArrayAttr::get(op->getContext(), new_program_header));
  }
}

