// entry 333/656   level 1   scc 368   34 body lines
// unit: e333_constructValues
// authority: dcc/src/Transform/Sentient/OldRegisterInitialization.cpp:1107
// original: void RegisterInitCandidatePromoter::constructValues( mlir::Value val, mlir::Value core, dcc::utils::UnitsAndTheirValues &results) const
// rust home: crates/compiler/deeptools/src/transform/sentient/old_register_initialization/register_init_candidate_promoter.rs
// ------------------------------------------------------------------------------------------------
void e333_constructValues(
    mlir::Value val, mlir::Value core,
    dcc::utils::UnitsAndTheirValues &results) const
{
  {
    auto get_unit_op = core.getDefiningOp<dataflow::GetUnitOp>();
    if (uniform::QueryMapOp qmap =
            dyn_cast<uniform::QueryMapOp>(val.getDefiningOp())) {
      auto def_map =
          qmap.getMap().getDefiningOp<uniform::DefImmutableMappingOp>();
      SmallVector<mlir::Value> tmp_keys = get_unit_op->getResults();
      // add the keys for the non-leader group members
      if (uga_.isGroupLeader(core)) {
        const auto &followers = uga_.getGroupMembersLedBy(core);
        for (const mlir::Value follower : followers)
          if (follower.getDefiningOp<dataflow::GetUnitOp>() != get_unit_op)
            tmp_keys.push_back(follower);
      }
      auto tmp_values = def_map.getNonNullValuesFromKeys(tmp_keys);
      DT_CHECK(tmp_values.size() == tmp_keys.size());
      for (int i = 0; i < tmp_keys.size(); i++) {
        results.add(tmp_keys[i], tmp_values[i]);
      }
    } else {
      auto nfolds = get_unit_op->getNumResults();
      for (int i = 0; i < nfolds; i++) {
        results.add(get_unit_op->getResult(i), val);
      }
      if (uga_.isGroupLeader(core)) {
        for (const mlir::Value follower : uga_.getGroupMembersLedBy(core))
          // only add if member is not one of the folds added above
          if (follower.getDefiningOp<dataflow::GetUnitOp>() != get_unit_op)
            results.add(follower, val);
      }
    }
  }
}

