// entry 334/656   level 1   scc 316   57 body lines
// unit: e334_mergeScalarOpIntoMac
// authority: dcc/src/Transform/Sentient/OpRerolling.cpp:81
// original: void OpRerollingPass::mergeScalarOpIntoMac(Block *bb)
// rust home: crates/compiler/deeptools/src/transform/sentient/op_rerolling/mod.rs
// ------------------------------------------------------------------------------------------------
void e334_mergeScalarOpIntoMac(Block *bb)
{
  auto isXrfRdPtrRelated = [](sentient::MacOp mac_op) {
    if ((stringifySentientComputePort(mac_op.getOpA()).count("xrf") ||
         stringifySentientComputePort(mac_op.getOpB()).count("xrf") ||
         stringifySentientComputePort(mac_op.getOpC()).count("xrf")) &&
        mac_op.getResults().size() > 0) {
      return true;
    }
    return false;
  };
  SmallVector<Operation *> scalar_op_to_be_deleted;
  bb->walk([&](sentient::MacOp mac_op) {
    if (mac_op.isXrfRelated()) {
      XrfType xrf_type = mac_op.isXrfWtRelated() ? xrf_write : xrf_read;
      SmallVector<Operation *, 1> tmp;
      int accum_xrf_ptr_incr_value = (xrf_type == xrf_write)
                                         ? mac_op.getXrfWriteIncrSigned()
                                         : mac_op.getXrfReadIncrSigned();
      auto result =
          (xrf_type == xrf_write) ? mac_op.getResult(0) : mac_op.getResult(1);
      while (result.hasOneUse() &&
             isa<sentient::AddOp>(*result.getUsers().begin())) {
        auto add_op = *result.getUsers().begin();
        accum_xrf_ptr_incr_value += getIncrementVal(add_op);
        result = add_op->getResult(0);
        for (auto operand : add_op->getOperands()) {
          auto parent_op = operand.getDefiningOp();
          if (isa<sentient::ConstantOp>(parent_op) && parent_op->hasOneUse()) {
            tmp.push_back(parent_op);
          }
        }
        tmp.push_back(add_op);
      }

      // if AddOp is found, update the macOp.
      if (result.getDefiningOp() != mac_op) {
        if (xrf_type == xrf_read) {
          mac_op.setXrfReadIncrAttr(IntegerAttr::get(
              mac_op.getXrfReadIncrAttr().getType(), accum_xrf_ptr_incr_value));
          result.replaceAllUsesWith(mac_op.getResult(1));
        } else {
          mac_op.setXrfWriteIncrAttr(
              IntegerAttr::get(mac_op.getXrfWriteIncrAttr().getType(),
                               accum_xrf_ptr_incr_value));
          result.replaceAllUsesWith(mac_op.getResult(0));
        }
        scalar_op_to_be_deleted.append(tmp);
      }
    }
  });
  while (!scalar_op_to_be_deleted.empty()) {
    auto op = scalar_op_to_be_deleted.back();
    scalar_op_to_be_deleted.pop_back();
    op->dropAllUses();
    op->erase();
  }
}

