// entry 339/656   level 1   scc 389   131 body lines
// unit: e339_addNodesToGraph
// authority: dcc/src/Transform/Sentient/PortAssignment.cpp:473
// original: void PortAssignmentPass::addNodesToGraph(Operation *op, const SenComponents comp)
// rust home: crates/compiler/deeptools/src/transform/sentient/port_assignment/mod.rs
// ------------------------------------------------------------------------------------------------
void e339_addNodesToGraph(Operation *op,
                                         const SenComponents comp)
{
  if (auto mac_op = llvm::dyn_cast<sentient::MacOp>(op)) {
    auto nodeA = port_assignment_graph_.getOrAddNode(mac_op.getOpADataID());
    auto nodeB = port_assignment_graph_.getOrAddNode(mac_op.getOpBDataID());
    auto nodeC = port_assignment_graph_.getOrAddNode(mac_op.getOpCDataID());
    auto precision = stringifySentientPrecision(mac_op.getComputePrecision());
    nodeA->addValidValues(getValidPorts(
        op, stringifySentientComputePort(mac_op.getOpA()), comp,
        stringifySentientPrecision(mac_op.getOpAPrecision()), precision));
    nodeB->addValidValues(getValidPorts(
        op, stringifySentientComputePort(mac_op.getOpB()), comp,
        stringifySentientPrecision(mac_op.getOpBPrecision()), precision));
    int op_to_swap = IsSwappablePerAlgebraicReassociation(op);
    if (op_to_swap != -1) {
      nodeC->addValidValues(getValidPorts(
          op, stringifySentientComputePort(mac_op.getOpC()), comp,
          stringifySentientPrecision(mac_op.getOpCPrecision()), precision));
    } else {
      auto port_list = getValidPorts(
          op, stringifySentientComputePort(mac_op.getOpC()), comp,
          stringifySentientPrecision(mac_op.getOpCPrecision()), precision);
      if ((comp == PT) && (std::find(port_list.begin(), port_list.end(), 1) !=
                           port_list.end())) {
        nodeC->addValidValues({1});
      } else if (is_any_of(comp, PE, SFP) &&
                 (std::find(port_list.begin(), port_list.end(), 2) !=
                  port_list.end())) {
        nodeC->addValidValues({2});
      } else {
        op->dump();
        op->emitError("No valid port for opC in unit\n");
        signalPassFailure();
        return;
      }
    }

    bool trivial_fma_computation =
        (mac_op.getOpA() == SentientComputePort::zero) &&
        (mac_op.getOpB() == SentientComputePort::one ||
         mac_op.getOpC() == SentientComputePort::one);
    if (is_any_of(comp, PE, SFP) && trivial_fma_computation)
      nodeA->addValidValues({2});

    OpBuilder builder(op);
    if (op->hasAttr("DataTransferOnly") &&
        mlir::cast<BoolAttr>(op->getAttr("DataTransferOnly")).getValue()) {
      nodeB->addValidValues({0, 1, 2});
      nodeC->addValidValues({0, 1, 2});
      reuse_nodes_.push_back(nodeA->getIndex());
      dummy_nodes_.push_back(nodeB->getIndex());
      dummy_nodes_.push_back(nodeC->getIndex());
    }
  } else if (auto binary_op = llvm::dyn_cast<sentient::BinaryOp>(op)) {
    auto nodeA = port_assignment_graph_.getOrAddNode(binary_op.getOpADataID());
    auto nodeB = port_assignment_graph_.getOrAddNode(binary_op.getOpBDataID());
    auto precision =
        stringifySentientPrecision(binary_op.getComputePrecision());
    auto a_ports = getValidPorts(
        op, stringifySentientComputePort(binary_op.getOpA()), comp,
        stringifySentientPrecision(binary_op.getOpAPrecision()), precision);
    auto b_ports = getValidPorts(
        op, stringifySentientComputePort(binary_op.getOpB()), comp,
        stringifySentientPrecision(binary_op.getOpBPrecision()), precision);
    if (binary_op.getBinaryOp() == SentientBinaryOperator::sub) {
      if (is_any_of(2, a_ports) && is_any_of(0, b_ports)) {
        nodeA->addValidValues({2});
        nodeB->addValidValues({0});
      } else {
        op->emitError("No valid port for sub operation in unit\n");
        signalPassFailure();
        return;
      }
    } else if (stringifySentientBinaryOperator(binary_op.getBinaryOp())
                   .contains("merge") ||
               stringifySentientBinaryOperator(binary_op.getBinaryOp())
                   .contains("pack") ||
               stringifySentientBinaryOperator(binary_op.getBinaryOp())
                   .contains("gcvt") ||
               stringifySentientBinaryOperator(binary_op.getBinaryOp())
                   .contains("fcvt") ||
               is_any_of(binary_op.getBinaryOp(),
                         SentientBinaryOperator::fcmp_eq,
                         SentientBinaryOperator::fcmp_neq,
                         SentientBinaryOperator::fcmp_le,
                         SentientBinaryOperator::fcmp_lt)) {
      if (is_any_of(0, a_ports) && is_any_of(2, b_ports)) {
        nodeA->addValidValues({0});
        nodeB->addValidValues({2});
      } else {
        op->emitError("No valid port for marge/pack/fcmp operation in unit\n");
        signalPassFailure();
        return;
      }
    } else {
      nodeA->addValidValues(a_ports);
      nodeB->addValidValues(b_ports);
    }
  } else if (auto unary_op = llvm::dyn_cast<sentient::UnaryOp>(op)) {
    auto nodeA = port_assignment_graph_.getOrAddNode(unary_op.getOpADataID());
    auto precision = stringifySentientPrecision(unary_op.getComputePrecision());
    auto a_ports = getValidPorts(
        op, stringifySentientComputePort(unary_op.getOpA()), comp,
        stringifySentientPrecision(unary_op.getOpAPrecision()), precision);
    nodeA->addValidValues(a_ports);
  } else if (auto ternary_op = llvm::dyn_cast<sentient::TernaryOp>(op)) {
    DT_CHECK(ternary_op.getTernaryOp() == SentientTernaryOperator::select);
    auto precision =
        stringifySentientPrecision(ternary_op.getComputePrecision());
    if (ternary_op.getTernaryOp() == SentientTernaryOperator::select) {
      // A ? C : B --> select operation
      auto nodeB =
          port_assignment_graph_.getOrAddNode(ternary_op.getOpBDataID());
      auto nodeC =
          port_assignment_graph_.getOrAddNode(ternary_op.getOpCDataID());
      auto b_ports = getValidPorts(
          op, stringifySentientComputePort(ternary_op.getOpB()), comp,
          stringifySentientPrecision(ternary_op.getOpBPrecision()), precision);
      auto c_ports = getValidPorts(
          op, stringifySentientComputePort(ternary_op.getOpC()), comp,
          stringifySentientPrecision(ternary_op.getOpCPrecision()), precision);
      if (is_any_of(0, c_ports) && is_any_of(2, b_ports)) {
        nodeC->addValidValues({0});
        nodeB->addValidValues({2});
      } else {
        op->emitError("No valid port for select operation in unit\n");
        signalPassFailure();
        return;
      }
    }
  }
}

// ------------------------------------------------------------------------------------------------
// entry 340/656   level 1   scc 392   52 body lines
// unit: e340_updateSentientIRPorts
// authority: dcc/src/Transform/Sentient/PortAssignment.cpp:682
// original: void PortAssignmentPass::updateSentientIRPorts(dataflow::ProgramUnitOp &unit)
// rust home: crates/compiler/deeptools/src/transform/sentient/port_assignment/mod.rs
// ------------------------------------------------------------------------------------------------
void e340_updateSentientIRPorts(dataflow::ProgramUnitOp &unit)
{
  if (port_assignment_.size() == 0) return;
  Builder builder(unit);

  unit.walk<WalkOrder::PreOrder>([&](Operation *op) {
    if (auto mac_op = llvm::dyn_cast<sentient::MacOp>(op)) {
      mac_op.setOpAPortIDAttr(getPortAttr(builder, mac_op.getOpADataID()));
      mac_op.setOpBPortIDAttr(getPortAttr(builder, mac_op.getOpBDataID()));
      if (op->hasAttr("DataTransferOnly") &&
          mlir::cast<BoolAttr>(op->getAttr("DataTransferOnly")).getValue()) {
        for (auto idx :
             port_assignment_graph_.getOrAddNode(mac_op.getOpCDataID())
                 ->getValidValues()) {
          // is not port id of nodeA and nodeB then set it for nodeC
          if (builder.getSI32IntegerAttr(idx) !=
                  getPortAttr(builder, mac_op.getOpADataID()) &&
              builder.getSI32IntegerAttr(idx) !=
                  getPortAttr(builder, mac_op.getOpBDataID())) {
            mac_op.setOpCPortIDAttr(builder.getSI32IntegerAttr(idx));
          }
        }
        op->removeAttr("DataTransferOnly");
      } else {
        mac_op.setOpCPortIDAttr(getPortAttr(builder, mac_op.getOpCDataID()));
      }
      mac_op.setOpADataIDAttr(builder.getSI32IntegerAttr(-1));
      mac_op.setOpBDataIDAttr(builder.getSI32IntegerAttr(-1));
      mac_op.setOpCDataIDAttr(builder.getSI32IntegerAttr(-1));
    } else if (auto binary_op = llvm::dyn_cast<sentient::BinaryOp>(op)) {
      binary_op.setOpAPortIDAttr(
          getPortAttr(builder, binary_op.getOpADataID()));
      binary_op.setOpBPortIDAttr(
          getPortAttr(builder, binary_op.getOpBDataID()));
      binary_op.setOpADataIDAttr(builder.getSI32IntegerAttr(-1));
      binary_op.setOpBDataIDAttr(builder.getSI32IntegerAttr(-1));
    } else if (auto unary_op = llvm::dyn_cast<sentient::UnaryOp>(op)) {
      unary_op.setOpAPortIDAttr(getPortAttr(builder, unary_op.getOpADataID()));
      unary_op.setOpADataIDAttr(builder.getSI32IntegerAttr(-1));
    } else if (auto ternary_op = llvm::dyn_cast<sentient::TernaryOp>(op)) {
      DT_CHECK(ternary_op.getTernaryOp() == SentientTernaryOperator::select);
      if (ternary_op.getTernaryOp() == SentientTernaryOperator::select) {
        ternary_op.setOpBPortIDAttr(
            getPortAttr(builder, ternary_op.getOpBDataID()));
        ternary_op.setOpCPortIDAttr(
            getPortAttr(builder, ternary_op.getOpCDataID()));
        ternary_op.setOpADataIDAttr(builder.getSI32IntegerAttr(-1));
        ternary_op.setOpBDataIDAttr(builder.getSI32IntegerAttr(-1));
        ternary_op.setOpCDataIDAttr(builder.getSI32IntegerAttr(-1));
      }
    }
  });
}

