// entry 341/656   level 1   scc 393   36 body lines
// unit: e341_addReuseToDummyOperands
// authority: dcc/src/Transform/Sentient/PortAssignment.cpp:739
// original: void PortAssignmentPass::addReuseToDummyOperands()
// rust home: crates/compiler/deeptools/src/transform/sentient/port_assignment/mod.rs
// ------------------------------------------------------------------------------------------------
void e341_addReuseToDummyOperands()
{
  // iterate though "reuse_nodes_"
  // if liverange of A containing B then update the operand of MAC containing B
  // How? set the operand of that MAC which has port number the same as A to
  // "latch".
  for (auto reuse_nodes : reuse_nodes_per_op_) {
    for (int i = 0; i < reuse_nodes.size(); i++) {
      for (int j = i + 1; j < reuse_nodes.size(); j++) {
        int node1_idx = reuse_nodes[i];
        int node2_idx = reuse_nodes[j];
        if (operand_to_owners_[node1_idx][0] !=
                operand_to_owners_[node2_idx][0] &&
            operand_to_liverange_[node1_idx].getIntervals()[0].first <=
                operand_to_liverange_[node2_idx].getIntervals()[0].first) {
          auto mac_op =
              llvm::dyn_cast<sentient::MacOp>(operand_to_owners_[node2_idx][0]);
          DT_CHECK(mac_op);
          OpBuilder builder(mac_op);
          auto node1_port_attr = getPortAttr(builder, node1_idx);
          if (mac_op.getOpAPortIDAttr() == node1_port_attr) {
            DT_CHECK(mac_op.getOpA() != SentientComputePort::latch);
            mac_op.setOpA(SentientComputePort::latch);
          }
          if (mac_op.getOpBPortIDAttr() == node1_port_attr) {
            DT_CHECK(mac_op.getOpB() != SentientComputePort::latch);
            mac_op.setOpB(SentientComputePort::latch);
          }
          if (mac_op.getOpCPortIDAttr() == node1_port_attr) {
            DT_CHECK(mac_op.getOpC() != SentientComputePort::latch);
            mac_op.setOpC(SentientComputePort::latch);
          }
        }
      }
    }
  }
}

