// entry 343/656   level 1   scc 400   23 body lines
// unit: e343_computeNewRegisterIndices
// authority: dcc/src/Transform/Sentient/ReadOnlyRegisterRenumbering.cpp:117
// original: void computeNewRegisterIndices(StaticPinningSchemeManager &sps_manager, ExpressionEvaluator &evaluator)
// rust home: crates/compiler/deeptools/src/transform/sentient/read_only_register_renumbering/mod.rs
// ------------------------------------------------------------------------------------------------
void e343_computeNewRegisterIndices(StaticPinningSchemeManager &sps_manager,
                                 ExpressionEvaluator &evaluator)
{
    if (unsafe_to_renumber_) return;
    for (Candidate &candidate : candidates_) {
      const EvaluatedValue &val_ev =
          evaluator.getConstant(candidate.getValue());
      DenseMap<Value, int64_t> unit_to_index =
          sps_manager.findMatchingPinnedAddr(val_ev,
                                             candidate.getElementSize());
      DT_CHECK(!unit_to_index.empty());
      int index = unit_to_index.begin()->second;
      DT_CHECK_MSG(
          index >= 0,
          "Unable to find matching pinned address! Make sure to run this "
          "pass after the address-pinning pass.");
      DT_CHECK(
          std::all_of<>(unit_to_index.begin(), unit_to_index.end(),
                        [index](DenseMap<Value, int64_t>::value_type record) {
                          return record.second == index;
                        }) &&
          "Expecting same position index for all matching pinned addresses");
      candidate.setNewRegisterIndex(index);
    }
  }

