// entry 348/656   level 1   scc 413   16 body lines
// unit: e348_updateRegIndex
// authority: dcc/src/Transform/Sentient/RegisterPacking.cpp:162
// original: bool RegisterPackingPass::updateRegIndex(TypedRegCollection &typed_reg_collec, RegIndex &reg, int suggested_index)
// rust home: crates/compiler/deeptools/src/transform/sentient/register_packing/mod.rs
// ------------------------------------------------------------------------------------------------
bool e348_updateRegIndex(TypedRegCollection &typed_reg_collec,
                                         RegIndex &reg, int suggested_index)
{
  if (reg.getOldRegisterIndex() < 0) {
    reg.setNewRegisterIndex(reg.getOldRegisterIndex());
    return false;
  }

  for (auto &other_reg : typed_reg_collec.getRegistersList()) {
    if (other_reg.getOldRegisterIndex() == reg.getOldRegisterIndex() &&
        other_reg.isIndexUpdated()) {
      reg.setNewRegisterIndex(other_reg.getNewRegisterIndex());
      return false;
    }
  }
  reg.setNewRegisterIndex(suggested_index);
  return true;
}

