// entry 349/656   level 1   scc 415   7 body lines
// unit: e349_getRegWithType
// authority: dcc/src/Transform/Sentient/RegisterPacking.cpp:239
// original: TypedRegCollection *RegisterPackingPass::getRegWithType( std::vector<TypedRegCollection> &reg_table, SentientRegType reg_type)
// rust home: crates/compiler/deeptools/src/transform/sentient/register_packing/mod.rs
// ------------------------------------------------------------------------------------------------
TypedRegCollection *e349_getRegWithType(
    std::vector<TypedRegCollection> &reg_table, SentientRegType reg_type)
{
  for (auto it = reg_table.begin(); it != reg_table.end(); it++)
    if (it->getRegType() == reg_type) return &*it;

  reg_table.push_back(TypedRegCollection(reg_type));
  return &reg_table[reg_table.size() - 1];
}

