// unit: e350_createCopyOperationAndUpdateAssignment
// authority: dcc/src/Transform/Sentient/RegisterTypeAssignment.cpp:255
// original: Value RegisterTypeAssignmentPass::createCopyOperationAndUpdateAssignment( Value val, const RegisterLocales locale, Operation* user, const bool is_mutable_addr_or_xrf_ptr, int element_size)
// rust home: crates/compiler/deeptools/src/transform/sentient/register_type_assignment/mod.rs
// ------------------------------------------------------------------------------------------------
Value e350_createCopyOperationAndUpdateAssignment(
    Value val, const RegisterLocales locale, Operation* user,
    const bool is_mutable_addr_or_xrf_ptr, int element_size)
{
  Operation* op = val.getDefiningOp();
  DT_CHECK(op && (isa<sentient::ConstantOp, dataflow::GetUnitOp,
                      dataflow::CreateMulticastGroupOp, uniform::QueryMapOp,
                      symbol::CreateSymbolOp>(op)));
  auto const_op = llvm::dyn_cast<sentient::ConstantOp>(op);
  auto multicast_op = llvm::dyn_cast<dataflow::CreateMulticastGroupOp>(op);
  auto query_map_op = llvm::dyn_cast<uniform::QueryMapOp>(op);
  // GetUnitOp is needed for EAR optimization only
  auto get_unit_op = llvm::dyn_cast<dataflow::GetUnitOp>(op);
  auto symbol_op = llvm::dyn_cast<symbol::CreateSymbolOp>(op);

  bool is_constant = dcc::utils::isConstant<sentient::ConstantOp>(val);
  bool is_symbol = dcc::utils::isSymbol(val);
  bool is_multicast = dcc::utils::isMulticast(val);
  bool is_get_unit = dcc::utils::isGetUnit(val);
  DT_CHECK_MSG((is_constant || is_symbol || is_multicast || is_get_unit),
               "expected one of constant, symbol, multicast or get_unit op");

  int core_id = get_unit_op ? dcc::getCoreId(get_unit_op) : -1;
  int64_t const_val = const_op ? const_op.getValue() : INT64_MAX;
  int64_t sym_id = symbol_op ? symbol_op.getSymbolID() : INT64_MAX;

  Value query_map_val = query_map_op ? query_map_op.getResult() : nullptr;

  // In general we try to common scalar_copy's of same constant values, hoping
  // that the same register once initialized can be reused multiple times, but
  // in the case of mutable_addrs (especially in update mode) the register gets
  // updated so the initial value doesn't reach the second use, so there is not
  // much gain by commoning scalar_copys in such scenarios. On the other hand
  // when register pressure is low we can save cycles by using packet init and
  // avoiding regcopys. See issue 2017 for more details.
  //
  // TODO: Once issue 2050 is resolved, we should limit this to mutable_addrs in
  // update mode only, and hoist copy ops in no-update mode more aggressively
  // (ie to outer loop levels).
  // NOTE: In the case where the constant feeds a MacOp's XRF pointer or a
  // mutable address, we cannot do the commoning as it may break XRF chaining
  // which updates XRF pointers (or similarly for mutable addresses).
  bool do_const_commoning = (is_constant || is_symbol || is_get_unit) &&
                            !is_mutable_addr_or_xrf_ptr && DoConstCommoning;

  std::pair<RegisterLocales, int> locale_elem_size = {locale, element_size};

  if (do_const_commoning && const_op &&
      cst_aliases_.find(const_val) != cst_aliases_.end() &&
      cst_aliases_[const_val].find(locale_elem_size) !=
          cst_aliases_[const_val].end()) {
    if (succeeded(moveToCommonDominator(
            cst_aliases_[const_val][locale_elem_size].getDefiningOp(), user)))
      return cst_aliases_[const_val][locale_elem_size];
  } else if (do_const_commoning && symbol_op &&
             sym_aliases_.find(sym_id) != sym_aliases_.end() &&
             sym_aliases_[sym_id].find(locale_elem_size) !=
                 sym_aliases_[sym_id].end()) {
    if (succeeded(moveToCommonDominator(
            sym_aliases_[sym_id][locale_elem_size].getDefiningOp(), user)))
      return sym_aliases_[sym_id][locale_elem_size];
  } else if (do_const_commoning && get_unit_op &&
             unit_aliases_.find(core_id) != unit_aliases_.end() &&
             unit_aliases_[core_id].find(dcc::getUnitType(get_unit_op)) !=
                 unit_aliases_[core_id].end()) {
    if (succeeded(moveToCommonDominator(
            unit_aliases_[core_id][dcc::getUnitType(get_unit_op)]
                .getDefiningOp(),
            user)))
      return unit_aliases_[core_id][dcc::getUnitType(get_unit_op)];
  } else if (do_const_commoning && query_map_op) {
    bool alias_exist =
        query_map_aliases_.find(query_map_val) != query_map_aliases_.end() &&
        query_map_aliases_[query_map_val].find(locale_elem_size) !=
            query_map_aliases_[query_map_val].end();
    if (alias_exist) {
      if (succeeded(moveToCommonDominator(
              query_map_aliases_[query_map_val][locale_elem_size]
                  .getDefiningOp(),
              user)))
        return query_map_aliases_[query_map_val][locale_elem_size];
    }

    // In certain cases (after unrolling), the immutable and query maps are
    // duplicated and have different references to immutable although their
    // values look identical. We are commoning those opportunities, otherwise
    // we can lot of scalar copy operations which could result in not
    // fitting immutables (EBR/LBR) into program header.
    for (auto& record : query_map_aliases_) {
      if (record.second.find(locale_elem_size) != record.second.end()) {
        auto query_map_alias_op =
            llvm::dyn_cast<uniform::QueryMapOp>(record.first.getDefiningOp());
        if (dcc::uniform::utils::areConstantQueryMapsIdentical(
                query_map_alias_op, query_map_op)) {
          if (succeeded(moveToCommonDominator(
                  record.second.at(locale_elem_size).getDefiningOp(), user)))
            return record.second.at(locale_elem_size);
        }
      }
    }
  }

  // Set up the builder
  OpBuilder builder(user);
  // We use the original position of multicast_group ops as anchor
  // points (provided by PCFG translator).
  if (is_multicast) builder.setInsertionPointAfter(op);
  // create a scalar copy operation
  auto new_op = sentient::CopyOp::create(
      builder, op->getLoc(), op->getResult(0).getType(), op->getResult(0),
      symbolizeSentientRegType(enum_to_strings_reg_locales_.at(locale))
          .value());
  if (const_op)
    cst_aliases_[const_val][locale_elem_size] = new_op.getResult();
  else if (symbol_op)
    sym_aliases_[sym_id][locale_elem_size] = new_op.getResult();
  else if (get_unit_op)
    unit_aliases_[core_id][dcc::getUnitType(get_unit_op)] = new_op.getResult();
  else if (query_map_op)
    query_map_aliases_[query_map_val][locale_elem_size] = new_op.getResult();
  assignments_[new_op.getResult()] = locale;
  return new_op.getResult();
}

