// entry 356/656   level 1   scc 454   64 body lines
// unit: e356_reuseIdenticalIterArgs
// authority: dcc/src/Transform/Sentient/ReuseLoopIteratorArguments.cpp:345
// original: void ReuseLoopIteratorArgumentsPass::reuseIdenticalIterArgs( sentient::ForOp for_op, PropagationAnalysis &expr_prop_analysis)
// rust home: crates/compiler/deeptools/src/transform/sentient/reuse_loop_iterator_arguments/mod.rs
// ------------------------------------------------------------------------------------------------
void e356_reuseIdenticalIterArgs(
    sentient::ForOp for_op, PropagationAnalysis &expr_prop_analysis)
{
  int n_iter_args = for_op.getNumRegionIterArgs();
  if (n_iter_args == 0) return;

  auto locales = for_op.getRegLocalesAttr();
  auto element_sizes = for_op->getAttr("element_sizes");
  if (!locales || !element_sizes) return;
  DT_CHECK_MSG(for_op.getRegLocales().size() == 2 * n_iter_args + 1,
               "Register locales do not match iterator arguments of the loop");

  LLVM_DEBUG({
    llvm::dbgs() << "ReuseLoopIteratorArguments analyzing the loop\n"
                 << for_op << "\n";
  });

  // Identify groups of iterator arguments of the loop having same
  // affine expressions. This is captured by a map with key being iterator
  // index and value being the head of the group. Initially, the map contains of
  // identical key, value pairs.
  std::unordered_map<unsigned, unsigned> iter_arg_idx_to_head_idx;
  for (unsigned i = 0; i < n_iter_args; i++) {
    iter_arg_idx_to_head_idx[i] = i;
  }

  auto iter_args = for_op.getRegionIterArgs();
  for (unsigned curr_iter = 0; curr_iter < n_iter_args; curr_iter++) {
    // if curr iter is already explored, skip processing
    if (iter_arg_idx_to_head_idx[curr_iter] != curr_iter) continue;

    // If curr iter is not explored, then identify set of next iterators
    // that would be same as curr iter
    for (unsigned next_iter = curr_iter + 1; next_iter < n_iter_args;
         next_iter++) {
      // Ignore the next iters that are already explored.
      if (iter_arg_idx_to_head_idx[next_iter] != next_iter) continue;

      // Make sure the register locales and element sizes are same
      if (locales[curr_iter + 1] != locales[next_iter + 1] ||
          mlir::cast<ArrayAttr>(element_sizes)[curr_iter + 1] !=
              mlir::cast<ArrayAttr>(element_sizes)[next_iter + 1])
        continue;

      if (expr_prop_analysis.areExpressionsSame(iter_args[curr_iter],
                                                iter_args[next_iter])) {
        iter_arg_idx_to_head_idx[next_iter] = curr_iter;
      }
    }
  }

  // Start reusing the ssa variables
  for (unsigned curr_iter = 0; curr_iter < n_iter_args; curr_iter++) {
    // if curr iter is its head idx, then no reuse.
    if (iter_arg_idx_to_head_idx[curr_iter] == curr_iter) continue;

    auto curr_iter_arg = iter_args[curr_iter];
    auto replace_with_arg = iter_args[iter_arg_idx_to_head_idx[curr_iter]];
    LLVM_DEBUG({
      llvm::dbgs() << "Replace the iter arg at index " << curr_iter
                   << " with that at index "
                   << iter_arg_idx_to_head_idx[curr_iter] << "\n";
    });
    curr_iter_arg.replaceAllUsesWith(replace_with_arg);
  }
}

// ------------------------------------------------------------------------------------------------
// entry 357/656   level 1   scc 456   23 body lines
// unit: e357_areUsersLiverangesOverlapping
// authority: dcc/src/Transform/Sentient/ReuseLoopIteratorArguments.cpp:458
// original: bool ReuseLoopIteratorArgumentsPass::areUsersLiverangesOverlapping( BlockArgument iter_arg1, BlockArgument iter_arg2, const Liveness &liveness) const
// rust home: crates/compiler/deeptools/src/transform/sentient/reuse_loop_iterator_arguments/mod.rs
// ------------------------------------------------------------------------------------------------
bool e357_areUsersLiverangesOverlapping(
    BlockArgument iter_arg1, BlockArgument iter_arg2,
    const Liveness &liveness) const
{
  auto for_op = dyn_cast<sentient::ForOp>(iter_arg1.getOwner()->getParentOp());
  DT_CHECK(for_op);
  auto yield_op =
      dyn_cast<sentient::YieldOp>(for_op.getBody(0)->getTerminator());

  llvm::SmallVector<Value> non_yield_feeding_users_results_iter1 =
      collectResultsOfNonYieldFeedingUsers(iter_arg1, yield_op);

  llvm::SmallVector<Value> non_yield_feeding_users_results_iter2 =
      collectResultsOfNonYieldFeedingUsers(iter_arg2, yield_op);

  for (Value result1 : non_yield_feeding_users_results_iter1) {
    for (Value result2 : non_yield_feeding_users_results_iter2) {
      // If both results belong to the same operation, their live ranges
      // automatically overlap.
      if (result1.getDefiningOp() == result2.getDefiningOp()) return true;

      if (liveness.isLiveRangeOverlaps(result1, result2)) return true;
    }
  }
  return false;
}

