// entry 358/656   level 1   scc 466   65 body lines
// unit: e358_collectCandidates
// authority: dcc/src/Transform/Sentient/ScalarCopyInsertionForSymbols.cpp:297
// original: void ScalarCopyInsertionForSymbolsPass::collectCandidates( dataflow::ProgramUnitOp unit, CandidateListTy &candidates, RegisterPressure &rp) const
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_copy_insertion_for_symbols/mod.rs
// ------------------------------------------------------------------------------------------------
void e358_collectCandidates(
    dataflow::ProgramUnitOp unit, CandidateListTy &candidates,
    RegisterPressure &rp) const
{
  DT_CHECK(candidates.empty());
  DenseMap<SentientRegType, SmallVector<Value>> per_locale_candidates;
  for (SentientRegType locale : symbolic_locales_) {
    const unsigned num_free_registers = rp.getOrComputeRegisterPressure(
        /* our goal is to replace lccrs with jcrs */
        locale == SentientRegType::lccr ? SentientRegType::jcr : locale,
        RegisterPressure::Metric::kNumFreeRegisters);
    if (num_free_registers == 0) {
      LLVM_DEBUG(llvm::dbgs()
                 << "skip collecting candidates for locale ["
                 << dcc::sentient::utils::localeToRegisterClass(locale)
                 << "] because there are no free registers.\n");
      continue;
    }
    auto collectPerLocalCandidate = [this, locale,
                                     &per_locale_candidates](Value sym) {
      const auto sym_to_usage_it = symbol_to_usage_.find(sym);
      if (sym_to_usage_it == symbol_to_usage_.end()) return;
      const auto locale_to_use_it = sym_to_usage_it->getSecond().find(locale);
      if (locale_to_use_it == sym_to_usage_it->getSecond().end()) return;
      per_locale_candidates[locale].push_back(sym);
    };
    for (const Value sym : symbols_) collectPerLocalCandidate(sym);
    for (const Value sym : symbol_queries_) collectPerLocalCandidate(sym);
    auto plc_it = per_locale_candidates.find(locale);
    if (plc_it == per_locale_candidates.end()) continue;
    if (plc_it->getSecond().size() < 2) continue;
    // sort in descending order based on number of uses.
    std::stable_sort(plc_it->getSecond().begin(), plc_it->getSecond().end(),
                     [locale, this](const Value a, const Value b) {
                       return symbol_to_usage_.at(a).at(locale).size() >
                              symbol_to_usage_.at(b).at(locale).size();
                     });
    // todo: for candidates that have the same num uses, we can order based on
    // proximity of uses. For example we can check which two symbols have users
    // that are farther than N instructions apart (where N is the num
    // instructions fitting in a single patch flit).
  }

  // Since JCR copy_ops cannot be packet initialized, they use up ibuff space.
  // Similarly since there is no guarantee that other copy_ops will be promoted
  // to program header, we should consider ibuff impact for those as well.
  InstructionEstimator &instruction_estimator =
      const_cast<ScalarCopyInsertionForSymbolsPass *>(this)
          ->getChildAnalysis<InstructionEstimator>(unit);
  const unsigned num_free_insts =
      instruction_estimator.getRemainingIbuffSpace(dccExtContext(), unit);
  for (SentientRegType locale : symbolic_locales_) {
    auto plc_it = per_locale_candidates.find(locale);
    if (plc_it == per_locale_candidates.end()) continue;
    const unsigned num_free_registers = rp.getOrComputeRegisterPressure(
        /* our goal is to replace lccrs with jcrs */
        locale == SentientRegType::lccr ? SentientRegType::jcr : locale,
        RegisterPressure::Metric::kNumFreeRegisters);
    // Take the top N candidates where N is a function of both available
    // registers and available ibuff.
    const unsigned constraint = std::min(num_free_registers, num_free_insts);
    const unsigned N =
        std::min(constraint, static_cast<unsigned>(plc_it->getSecond().size()));
    for (unsigned i = 0; i < N; i++) {
      candidates.emplace_back(plc_it->getSecond()[i], locale);
    }
  }
}

