// entry 359/656   level 1   scc 463   49 body lines
// unit: e359_insertCopyOpsForCandidates
// authority: dcc/src/Transform/Sentient/ScalarCopyInsertionForSymbols.cpp:365
// original: void ScalarCopyInsertionForSymbolsPass::insertCopyOpsForCandidates( dataflow::ProgramUnitOp unit, const CandidateListTy &candidates)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_copy_insertion_for_symbols/mod.rs
// ------------------------------------------------------------------------------------------------
void e359_insertCopyOpsForCandidates(
    dataflow::ProgramUnitOp unit, const CandidateListTy &candidates)
{
  // skip if there is no grouping of *multiple* initializers, since there would
  // be no opportunity for patch flit reduction
  if (!ForceInsertionEvenIfOneCandidate) {
    unsigned jcr_count = 0, non_jcr_count = 0;
    for (auto entry : candidates) {
      if (entry.second == SentientRegType::lccr ||
          entry.second == SentientRegType::jcr)
        ++jcr_count;
      else
        ++non_jcr_count;
    }
    if (jcr_count < 2 && non_jcr_count < 2) {
      LLVM_DEBUG(llvm::dbgs()
                 << "Skip inserting copy op since there are not enough "
                    "candidates to create patch flit reduction opportunity\n");
      return;
    }
  }
  // Insert copy ops for candidates
  for (auto entry : candidates) {
    // todo: check instruction estimation for JCR copy ops
    const Value symbol = entry.first;
    const SentientRegType locale = entry.second;
    DT_CHECK(symbol_to_usage_.find(symbol) != symbol_to_usage_.end());
    auto usage_iter = symbol_to_usage_.at(symbol).find(locale);
    DT_CHECK(usage_iter != symbol_to_usage_.at(symbol).end());
    if (locale == SentientRegType::lccr || locale == SentientRegType::jcr) {
      insertCopyOpsForJCRCandidate(unit, entry);
      continue;
    }
    Operation *new_copy_op = nullptr;
    for (OpOperand *opnd : symbol_to_usage_.at(symbol).at(locale)) {
      Operation *user = opnd->getOwner();
      if (!new_copy_op) {
        OpBuilder builder(user);
        new_copy_op = sentient::CopyOp::create(
            builder, user->getLoc(), symbol.getType(), symbol, locale);
        propagateElementSizeToCopyOp(*opnd,
                                     cast<sentient::CopyOp>(new_copy_op));
      } else if (failed(dcc::utils::moveToCommonDominator(new_copy_op, user))) {
        user->emitError("failed to move copy op to common dominator");
        signalPassFailure();
        return;
      }
      opnd->assign(new_copy_op->getResult(0));
    }
  }
}

