// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_copy_insertion_for_symbols/mod.rs
// ------------------------------------------------------------------------------------------------
void e360_dumpSymbolUsageInfo() const
{
  llvm::dbgs() << "=== Usage Info: ===\n";
  auto dumpUsagePerSym = [this](Value sym) {
    const auto sym_to_usage_it = symbol_to_usage_.find(sym);
    if (sym_to_usage_it == symbol_to_usage_.end()) return;
    for (const SentientRegType locale : symbolic_locales_) {
      const auto locale_to_use_it = sym_to_usage_it->getSecond().find(locale);
      if (locale_to_use_it == sym_to_usage_it->getSecond().end()) continue;
      DT_CHECK(!isa<BlockArgument>(sym));
      auto sym_op = dyn_cast<symbol::CreateSymbolOp>(sym.getDefiningOp());
      auto sym_query_op =
          dyn_cast<symbol::SymbolQueryMapOp>(sym.getDefiningOp());
      DT_CHECK(static_cast<bool>(sym_op) ^ static_cast<bool>(sym_query_op));
      if (sym_op) {
        llvm::dbgs() << "Sym ID (" << sym_op.getSymbolID() << ") for locale ["
                     << dcc::sentient::utils::localeToRegisterClass(locale)
                     << "] has " << locale_to_use_it->getSecond().size()
                     << " use(s).\n";
      } else {
        llvm::dbgs() << "Symbol Query On Line ("
                     << dcc::utils::getLocation(sym_query_op).getLine()
                     << ") for locale ["
                     << dcc::sentient::utils::localeToRegisterClass(locale)
                     << "] has " << locale_to_use_it->getSecond().size()
                     << " use(s).\n";
      }
    }
  };
  for (const Value sym : symbols_) dumpUsagePerSym(sym);
  for (const Value sym : symbol_queries_) dumpUsagePerSym(sym);
  llvm::dbgs() << "=== End of Usage Info ===\n";
}

