// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/mod.rs
// ------------------------------------------------------------------------------------------------
bool e361_isImmutableValueInRange(const EvaluatedValue &new_immutable_ev,
                               const EvaluatedValue &original_immutable_ev,
                               int element_size, mlir::Operation *op) const
{
    // Check if new immutable exceeds IMM range
    if (doesImmutableImmExceedRange(new_immutable_ev, element_size,
                                    ldsti_imm_range_, scale_)) {
      // Check if original also exceeded IMM range
      if (!doesImmutableImmExceedRange(original_immutable_ev, element_size,
                                       ldsti_imm_range_, scale_)) {
        LLVM_DEBUG(llvm::dbgs() << "Op not a candidate due to immutable being "
                                   "pushed out of IMM range ("
                                << ldsti_imm_range_.first << " to "
                                << ldsti_imm_range_.second << "):\n"
                                << *op << "\n\n");
        return false;
      }

      // Both exceed IMM range, check LRF range
      if (doesValueExceedLRFRange(dcc_ext_context_.dsc_global_->sysDef,
                                  new_immutable_ev, element_size, comp_,
                                  scale_)) {
        LLVM_DEBUG(llvm::dbgs() << "Op not a candidate due to immutable being "
                                   "pushed out of LRF range:\n"
                                << *op << "\n\n");
        return false;
      }
    }

    return true;
  }

