// entry 362/656   level 1   scc 485   124 body lines
// unit: e362_isFieldUnrollCandidate
// authority: dcc/src/Transform/Sentient/ScalarOpMergingAndHoisting.cpp:1080
// original: bool ScalarOpMerging::isFieldUnrollCandidate( FieldUnrollData &candidate, const EvaluatedValue *&merging_increment)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_merging.rs
// ------------------------------------------------------------------------------------------------
bool e362_isFieldUnrollCandidate(
    FieldUnrollData &candidate, const EvaluatedValue *&merging_increment)
{
  // Collect information including burst and IL from op. If there is no burst or
  // no IL, set them to 1 and 0 respectively. This will mark the number of
  // iterations the burst and IL loops will execute to unroll the operation.
  auto op = candidate.getOp();
  DT_CHECK_MSG(is_any_of(getComp(), LXLU, LXSU, L0LU, L0SU),
               "unexpected unit encountered");

  MemoryOpInfo mem_info(op);

  if (auto immutable_addr_copy =
          dyn_cast<sentient::CopyOp>(mem_info.immutable_addr_.getDefiningOp()))
    mem_info.immutable_addr_ = immutable_addr_copy.getInp();

  DT_CHECK_MSG(
      dcc::utils::isConstant<sentient::ConstantOp>(mem_info.immutable_addr_),
      "Expect constant immutable address");
  DT_CHECK_MSG(
      dcc::utils::isConstant<sentient::ConstantOp>(mem_info.increment_),
      "Expect constant increment");
  const EvaluatedValue &immutable_addr_ev =
      getEvaluator().evaluateValue(mem_info.immutable_addr_);
  const EvaluatedValue &increment_ev =
      getEvaluator().evaluateValue(mem_info.increment_);

  // If there is IL, the result of the full IL iteration is a calculation. The
  // calculation changes depending on unit and operation attributes as follows
  // (inp = input to IL iteration):
  // LX: <inp> + ldtype
  // L0: if chunk_size == 0:
  //         <inp> + ldtype
  //     if chunk_size > 0:
  //         if not last burst:
  //             <inp> + chunk_size
  //         if last burst:
  //             <inp> + ((ldtype/chunk-size - 1) * chunk_stride) + chunk_size
  // General modifier is set here. Last burst chunk_size > 0 case is calculated
  // as needed during unrolling calculation.
  int ldsttype =
      dcc::sentient::utils::getLdTypeOrStTypeInElements(op, getComp());
  int modifier = 0;
  modifier = (mem_info.il_ > 0 && mem_info.chunk_size_ > 0 &&
              is_any_of(getComp(), L0LU, L0SU))
                 ? mem_info.chunk_size_
                 : ldsttype;
  const EvaluatedValue &modifier_ev = getEvaluator().getConstant(modifier);

  // Artificially unroll the op bottom up (in reverse), storing the speculated
  // immutables. ScalarOpMerging is executed in a bottom up fashion.
  for (unsigned b = mem_info.burst_; b > 0; --b) {
    // If there is IL, each burst will execute through a full set of IL.
    if (mem_info.il_ > 0) {
      // After every iteration of IL, there is an add to setup the next
      // iteration. This add won't be materialized in the IR, but it will impact
      // the value being merged through the operations.
      // In L0, if chunk_size != 0, the last group of the last burst has a
      // different calculation.
      if (mem_info.chunk_size_ != 0 && b == mem_info.burst_ &&
          is_any_of(getComp(), L0LU, L0SU)) {
        const EvaluatedValue &chunk_mod_ev = getEvaluator().getConstant(
            ((ldsttype / mem_info.chunk_size_ - 1) * mem_info.chunk_stride_) +
            mem_info.chunk_size_);
        merging_increment =
            &getEvaluator().evaluateSum(*merging_increment, chunk_mod_ev);
      } else {
        merging_increment =
            &getEvaluator().evaluateSum(*merging_increment, modifier_ev);
      }

      for (int i = mem_info.il_ - 1; i >= 0; --i) {
        const EvaluatedValue &unrolled_immutable_ev =
            getEvaluator().evaluateSum(
                immutable_addr_ev,
                getEvaluator().evaluateMultiplyByConst(increment_ev, i));
        // Operations are unrolled into no update mode operations.
        // speculative_immutable = immutable - increment - merging_increment
        //   where increment == 0
        const EvaluatedValue &speculative_immutable_ev =
            getEvaluator().evaluateSub(unrolled_immutable_ev,
                                       *merging_increment);

        if (doesImmutableImmExceedRange(speculative_immutable_ev,
                                        mem_info.element_size_,
                                        getLdstiImmRange(), getScale())) {
          LLVM_DEBUG(llvm::dbgs()
                     << "[FieldUnrolling] Following op not a candidate due to "
                        "immutable being pushed out of IMM range ("
                     << getLdstiImmRange().first << " to "
                     << getLdstiImmRange().second << "):\n"
                     << *op << "\n\n");
          return false;
        }
        candidate.addSpeculativeImmutable(speculative_immutable_ev);
      }
    } else {
      // Without IL, the unrolled mem op will just be repeated burst times with
      // each operation having no burst.

      // The speculative immutable will be:
      //   immutable - increment - merging_increment
      // The merging_increment will be:
      //   immutable - (immutable - increment - merging_increment)
      const EvaluatedValue &speculative_immutable_ev =
          getEvaluator().evaluateSub(
              getEvaluator().evaluateSub(immutable_addr_ev, increment_ev),
              *merging_increment);
      if (doesImmutableImmExceedRange(speculative_immutable_ev,
                                      mem_info.element_size_,
                                      getLdstiImmRange(), getScale())) {
        LLVM_DEBUG(llvm::dbgs()
                   << "[FieldUnrolling] Following op not a candidate due to "
                      "immutable being pushed out of IMM range ("
                   << getLdstiImmRange().first << " to "
                   << getLdstiImmRange().second << "):\n"
                   << *op << "\n\n");
        return false;
      }
      merging_increment = &getEvaluator().evaluateSub(immutable_addr_ev,
                                                      speculative_immutable_ev);
      candidate.addSpeculativeImmutable(speculative_immutable_ev);
    }
  }
  return true;
}

