// original: void ScalarOpMerging::doScalarOpMerging(ScalarOpMergingBlock &block)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_merging.rs
// ------------------------------------------------------------------------------------------------
void e364_doScalarOpMerging(ScalarOpMergingBlock &block)
{
  // Blocks are profitable for Scalar Op Merging if they contain more than one
  // scalar add/sub. If the block only contains 1 mergeable scalar add/sub, it
  // may still be beneficial to do Scalar Op Merging on the block if it will
  // create a candidate for Scalar Op Hoisting.
  if (block.getNumScalarOpsInBlock() <= 1)
    if (!isProfitableForHoisting(block)) return;

  auto block_data = block.getBlockOps();
  Operation *first_op = block_data.front().getOp();
  const EvaluatedValue *merging_increment = &getEvaluator().getConstant(0);

  Value input_value_to_block = block.getInputValueToBlock();
  auto unroll_candidates = block.getUnrollCandidates();
  auto zero_const = sentient::ConstantOp::create(
      getConstBuilder(), region_.getLoc(), getConstBuilder().getIndexType(), 0);

  // Cache the element size of the anchor operation in the block for range
  // checks later.
  Operation *anchor_op = block_data.back().getOp();
  DT_CHECK(anchor_op->hasAttr("element_size"));
  Attribute element_size = anchor_op->getAttr("element_size");

  // builder should point to where the new operation should be inserted.
  auto createRemainingAdd = [&](OpBuilder &builder, Value &inp,
                                const EvaluatedValue *merging_increment,
                                Operation *last_mem_op =
                                    nullptr) -> Operation * {
    auto merging_increment_const = merging_increment->buildOffsetValue(
        getConstBuilder(), getQueryMapBuilder(), region_.getLoc(),
        builder.getIndexType());
    auto new_add = sentient::AddOp::create(builder, region_.getLoc(),
                                           builder.getIndexType(), inp,
                                           merging_increment_const);
    if (last_mem_op) last_mem_op->replaceUsesOfWith(inp, new_add);
    // Ensure element_size is copied as it is essential for range checks.
    new_add->setAttr("element_size", element_size);
    return new_add;
  };

  // Traverse the block bottom up and apply the operation data from the
  // analysis. If burst/IL memory ops are encountered, they would be Field
  // Unrolling candidates. If they have been marked for unrolling unroll them.
  // If they have not been marked for unrolling, merging stops.
  auto end = block_data.end();
  for (auto it = block_data.begin(); it != end; ++it) {
    Operation *op = it->getOp();
    OpBuilder builder(op);
    const EvaluatedValue &new_immutable = *it->getMod();
    auto next_it = std::next(it);
    bool is_last_op_in_block = next_it == block_data.end();

    if (isa<sentient::AddOp, sentient::SubOp>(op)) {
      merging_increment = it->getMergingIncrement();
      if (!is_last_op_in_block)
        op->replaceAllUsesWith(next_it->getOp());
      else {
        auto new_add = createRemainingAdd(builder, input_value_to_block,
                                          merging_increment);
        op->replaceAllUsesWith(new_add);
      }
      op->erase();
    } else if (isa<sentient::LoadAndSendOp, sentient::ReceiveAndStoreOp,
                   sentient::LoadComputeAndSendOp>(op)) {
      int burst, il;
      int mutable_addr_idx, immutable_addr_idx, increment_idx;
      if (auto las = dyn_cast<sentient::LoadAndSendOp>(op)) {
        burst = las.getBurstSize();
        il = las.getInterleavedGroup();
        mutable_addr_idx = las.getMutableAddrMutable().getOperandNumber();
        immutable_addr_idx = las.getImmutableAddrMutable().getOperandNumber();
        increment_idx = las.getIncrementMutable().getOperandNumber();
      } else if (auto ras = dyn_cast<sentient::ReceiveAndStoreOp>(op)) {
        burst = ras.getBurstSize();
        il = ras.getInterleavedGroup();
        mutable_addr_idx = ras.getMutableAddrMutable().getOperandNumber();
        immutable_addr_idx = ras.getImmutableAddrMutable().getOperandNumber();
        increment_idx = ras.getIncrementMutable().getOperandNumber();
      } else {
        auto lcas = cast<LoadComputeAndSendOp>(op);
        burst = 0;
        il = 0;
        mutable_addr_idx = lcas.getMutableAddrMutable().getOperandNumber();
        immutable_addr_idx = lcas.getImmutableAddrMutable().getOperandNumber();
        increment_idx = lcas.getIncrementMutable().getOperandNumber();
      }
      if (burst > 1 || il > 0) {
        // If the op is not to be Field Unrolled, merging for this block
        // stops.
        auto unroll_candidate = findFieldUnrollCandidate(op, block);
        if (!unroll_candidate) {
          builder.setInsertionPointAfter(op);
          auto op_val = op->getResult(0);
          auto new_add = createRemainingAdd(builder, op_val, merging_increment);
          llvm::SmallPtrSet<Operation *, 1> exceptions{new_add};
          op_val.replaceAllUsesExcept(new_add->getResult(0), exceptions);
          return;
        }

        merging_increment = it->getMergingIncrement();

        // Field unroll the candidate and continue merging.
        SmallVector<Operation *> unrolled_ops;
        if (isa<sentient::LoadAndSendOp>(op))
          unrolled_ops = unrollBurstAndIL<sentient::LoadAndSendOp>(
              unroll_candidate.value());
        else
          unrolled_ops = unrollBurstAndIL<sentient::ReceiveAndStoreOp>(
              unroll_candidate.value());

        if (is_last_op_in_block) {
          builder.setInsertionPoint(unrolled_ops.front());
          (void)createRemainingAdd(builder, input_value_to_block,
                                   merging_increment, unrolled_ops.front());
          return;
        }
      } else {
        merging_increment = it->getMergingIncrement();
        auto immutable_addr = new_immutable.buildOffsetValue(
            getConstBuilder(), getQueryMapBuilder(), region_.getLoc(),
            builder.getIndexType());
        if (!is_last_op_in_block)
          op->setOperand(mutable_addr_idx, next_it->getOp()->getResult(0));
        else {
          builder.setInsertionPoint(op);
          (void)createRemainingAdd(builder, input_value_to_block,
                                   merging_increment, op);
        }
        op->setOperand(immutable_addr_idx, immutable_addr);
        op->setOperand(increment_idx, zero_const->getResult(0));
      }
    } else
      llvm_unreachable("Unsupported op found in block!");
  }
}

