// ------------------------------------------------------------------------------------------------
void e365_applyOperationData(
    SmallVector<OperationData> &ops_to_update)
{
  for (auto op_data : ops_to_update) {
    Operation *op = op_data.getOp();
    const EvaluatedValue *modifier = op_data.getMod();
    bool replace_with_mod = op_data.getReplaceWithMod();

    if (isa<sentient::AddOp>(op)) {
      int const_idx = dcc::utils::getFirstConstOperandIndex(op);
      auto operand_op = op->getOperand(const_idx).getDefiningOp();
      Value new_const =
          addToOrReplaceOp(operand_op, *modifier, replace_with_mod);
      op->setOperand(const_idx, new_const);
    } else if (isa<sentient::SubOp>(op)) {
      int const_idx = dcc::utils::getFirstConstOperandIndex(op);
      auto operand_op = op->getOperand(const_idx).getDefiningOp();

      if (!replace_with_mod) {
        modifier = &getEvaluator().evaluateMultiplyByConst(*modifier, -1);
      }
      Value new_const =
          addToOrReplaceOp(operand_op, *modifier, replace_with_mod);
      op->setOperand(const_idx, new_const);
    } else if (isa<sentient::LoadAndSendOp, sentient::ReceiveAndStoreOp,
                   sentient::LoadComputeAndSendOp>(op)) {
      DT_CHECK(is_any_of(getComp(), LXLU, LXSU, L0LU, L0SU));

      if (auto las = dyn_cast<sentient::LoadAndSendOp>(op)) {
        Operation *immutable_addr_op = las.getImmutableAddr().getDefiningOp();
        Value new_const =
            addToOrReplaceOp(immutable_addr_op, *modifier, replace_with_mod);
        las.getImmutableAddrMutable().assign(new_const);
        if (!dcc::utils::isTargetConstant(las.getIncrement(), 0))
          las.getIncrementMutable().assign(new_const);
      } else if (auto ras = dyn_cast<sentient::ReceiveAndStoreOp>(op)) {
        Operation *immutable_addr_op = ras.getImmutableAddr().getDefiningOp();
        Value new_const =
            addToOrReplaceOp(immutable_addr_op, *modifier, replace_with_mod);
        ras.getImmutableAddrMutable().assign(new_const);
        if (!dcc::utils::isTargetConstant(ras.getIncrement(), 0))
          ras.getIncrementMutable().assign(new_const);
      } else {
        auto lcas = cast<sentient::LoadComputeAndSendOp>(op);
        Operation *immutable_addr_op = lcas.getImmutableAddr().getDefiningOp();
        Value new_const =
            addToOrReplaceOp(immutable_addr_op, *modifier, replace_with_mod);
        lcas.getImmutableAddrMutable().assign(new_const);
        if (!dcc::utils::isTargetConstant(lcas.getIncrement(), 0))
          lcas.getIncrementMutable().assign(new_const);
      }
    } else {
      llvm_unreachable("Unexpected operation encountered!");
    }
  }
}

