// ------------------------------------------------------------------------------------------------
Operation *e368_getFirstUseWithinBlock(Value v)
{
  DT_CHECK_MSG(!isa<BlockArgument>(v),
               "Function should not be called on an iter arg");
  if (v.use_empty()) return nullptr;
  if (val_to_first_use_in_block_cache_.contains(v))
    return val_to_first_use_in_block_cache_[v];
  Operation *earliest_use = nullptr;
  Block *bb = v.getDefiningOp()->getBlock();
  for (auto &use : v.getUses()) {
    Operation *use_ancestor_within_block =
        findAncestorInBlock(use.getOwner(), bb);
    if (!use_ancestor_within_block) continue;

    if (!earliest_use) {
      earliest_use = use_ancestor_within_block;
    } else {
      if (dom_info_->dominates(use_ancestor_within_block, earliest_use))
        earliest_use = use_ancestor_within_block;
    }
  }
  val_to_first_use_in_block_cache_[v] = earliest_use;
  return earliest_use;
}

