// entry 370/656   level 1   scc 516   30 body lines
// unit: e370_localeHasFreeRegs
// authority: dcc/src/Transform/Sentient/ScalarOpReordering.cpp:431
// original: bool ScalarOpReorderingPass::localeHasFreeRegs(SentientRegType locale)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_reordering/mod.rs
// ------------------------------------------------------------------------------------------------
bool e370_localeHasFreeRegs(SentientRegType locale)
{
  // First check the bitvector. It might have false negatives (due to stale
  // data, as op reordering might free registers) but no false positives.
  if (is_any_of(locale, SentientRegType::imm, SentientRegType::unknown) ||
      locale_has_free_regs_.test(static_cast<uint32_t>(locale)))
    return true;
  // Check the overestimated number of registers exceeding the locale's
  // register file size.
  if (locale_to_num_regs_exceeded_[static_cast<uint32_t>(locale)] > 0) {
    // If the overestimate indicates there are no free registers, return false.
    // Reordering the current scalar op might free at most one register, so
    // decrement the overestimate.
    --locale_to_num_regs_exceeded_[static_cast<uint32_t>(locale)];
    return false;
  }
  // Data is inconclusive so recompute the register pressure info and update the
  // bitvector and overestimate.
  Liveness liveness(unit_op_);
  RegisterPressure rp(unit_op_, liveness, &dccExtContext());
  auto pu = dyn_cast<dataflow::ProgramUnitOp>(*unit_op_);
  unsigned rf_size =
      (MaxRegNum > 0) ? MaxRegNum : dccExtContext().getMaxRegNum(locale, pu);
  unsigned num_regs = rp.getOrComputeRegisterPressure(
      locale, RegisterPressure::Metric::kNumRegisters);
  bool has_free_regs = (num_regs < rf_size);
  locale_to_num_regs_exceeded_[static_cast<uint32_t>(locale)] =
      num_regs - rf_size;
  if (has_free_regs) locale_has_free_regs_.set(static_cast<uint32_t>(locale));
  return has_free_regs;
}

