// entry 372/656   level 1   scc 524   50 body lines
// unit: e372_areAllExprsValidToTransform
// authority: dcc/src/Transform/Sentient/ScalarSimplifications.cpp:716
// original: bool sentient::areAllExprsValidToTransform( std::vector<FlatExprType>& flat_exprs, SmallVector<unsigned>& indices, PropagationAnalysis::ExprInfoMap* result_info, bool is_load_store)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_simplifications/sentient.rs
// ------------------------------------------------------------------------------------------------
bool e372_areAllExprsValidToTransform(
    std::vector<FlatExprType>& flat_exprs, SmallVector<unsigned>& indices,
    PropagationAnalysis::ExprInfoMap* result_info, bool is_load_store)
{
  // use the first element of indices to find out dimension size.
  unsigned dim_size = flat_exprs[0][0].size();
  for (unsigned unit_idx = 0; unit_idx < flat_exprs.size(); ++unit_idx) {
    FlatExprType& flat_expr_at_idx = flat_exprs[unit_idx];
    // We want only one expression
    if (flat_expr_at_idx.size() > 1) return false;

    auto& expression = flat_expr_at_idx[0];
    // for load and store ops, We want only one expression. We can assume there
    // are no symbols, so the size of a 1-dim affine expr is always 2.
    if (is_load_store && expression.size() > 2) return false;

    // all exprs should have same dim size
    if (dim_size != expression.size()) return false;

    // variable dim >3 or <1 aren't handled
    if (expression.size() > 3 || expression.size() < 1) {
      return false;
    } else if (expression.size() == 2) {
      // 1 * variable + constant --> variable coefficient has to be 1.
      // Don't perform substituion if the propagation arguments
      // include loop iterators. This is a bit tight constriant to
      // skip doing register type assignment and address outputs having
      // LCCR into scalar_adds with LRF register locale.
      if (dcc::utils::isInductionVariable(
              result_info->getExprInfoAt(indices[unit_idx])
                  ->propagated_args_[0]) ||
          expression[0] != 1)
        return false;
      // identity map (ie no constant with only 1 * dim
      // Avoid using an IV as an address operand to avoid confusion in
      // register type assignment and avoid the need for LCCR copy.
      if (is_load_store && expression[1] != 0) return false;
    } else if (expression.size() == 3) {
      // 1 * variable + 1 * variable + constant --> constant has to be zero.
      // Don't perform substitution if the propagation arguments
      // include loop iterators. This is a bit tight constraint to
      // skip doing register type assignment and address outputs having
      // LCCR into scalar_adds with LRF register locale.
      PropagationAnalysis::ExprInfo* expr_info =
          result_info->getExprInfoAt(indices[unit_idx]);
      if (dcc::utils::isInductionVariable(expr_info->propagated_args_[0]) ||
          dcc::utils::isInductionVariable(expr_info->propagated_args_[1]) ||
          expression[2] != 0 || expression[0] != 1 || expression[1] != 1)
        return false;
    }
  }
  return true;
}

// ------------------------------------------------------------------------------------------------
// entry 373/656   level 1   scc 195   29 body lines
// unit: e373_areFlatExprsAndArgsIdentical
// authority: dcc/src/Transform/Sentient/ScalarSimplifications.cpp:840
// original: bool sentient::areFlatExprsAndArgsIdentical( std::vector<FlatExprType>& flat_exprs, SmallVector<unsigned>& indices, PropagationAnalysis::ExprInfoMap* result_info, unsigned dim_idx)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_simplifications/sentient.rs
// ------------------------------------------------------------------------------------------------
bool e373_areFlatExprsAndArgsIdentical(
    std::vector<FlatExprType>& flat_exprs, SmallVector<unsigned>& indices,
    PropagationAnalysis::ExprInfoMap* result_info, unsigned dim_idx)
{
  unsigned num_flat_exprs = flat_exprs.size();
  DT_CHECK(num_flat_exprs > 1);

  auto& first_flat_expr = flat_exprs[0][0];
  unsigned first_flat_expr_size = first_flat_expr.size();
  PropagationAnalysis::ExprInfo* first_expr_info =
      result_info->getExprInfoAt(indices[0]);
  for (unsigned unit_idx = 1; unit_idx < num_flat_exprs; ++unit_idx) {
    auto& flat_expr_at_idx = flat_exprs[unit_idx][0];
    unsigned flat_expr_at_idx_size = flat_expr_at_idx.size();
    // expr dims are identical
    if (flat_expr_at_idx_size != first_flat_expr_size) return false;
    // dim coeffs are identical
    if (flat_expr_at_idx[dim_idx] != first_flat_expr[dim_idx]) return false;

    PropagationAnalysis::ExprInfo* expr_info_at_idx =
        result_info->getExprInfoAt(indices[unit_idx]);

    // args are identical
    if (flat_expr_at_idx_size >= 2 && (expr_info_at_idx->propagated_args_[0] !=
                                       first_expr_info->propagated_args_[0]))
      return false;
    if (flat_expr_at_idx_size == 3 && (expr_info_at_idx->propagated_args_[1] !=
                                       first_expr_info->propagated_args_[1]))
      return false;
  }
  return true;
}

