// original: void SetMaskRDETree::initializeDataflowInfo(RDENode *node)
// rust home: crates/compiler/deeptools/src/transform/sentient/set_mask_re/set_mask_rde_tree.rs
// ------------------------------------------------------------------------------------------------
void e375_initializeDataflowInfo(RDENode *node)
{
  auto op = node->getOperation();

  if (isOperationAUse(*op) && !isOperationADef(*op)) return;

  // Only SetMask and IncrMask operations generate definitions, initially.
  if (auto setmask_op = dyn_cast<sentient::SetMaskOp>(op)) {
    assert(setmask_op.getMaskValue());
    node->setDataflowGen(
        new SetMaskGenValue(setmask_op.getMaskValue(), node->getOperation()));
  } else if (auto incrmask_op = dyn_cast<sentient::IncrMaskOp>(op)) {
    node->setDataflowGen(
        new IncrMaskGenValue(incrmask_op.getIncrement(), node->getOperation()));
  } else {
    node->setDataflowGen(new SetMaskGenValue());
  }
}

