bool e376_isEqual(const DataFlowDefinitionBase &rhs) const
{
  auto rhs_p = dynamic_cast<const SetMaskGenValue *>(&rhs);
  if (!rhs_p) return false;

  // is_optimized bit is intentionally left out.
  return maskValuesAreEquivalent(mask_value_, rhs_p->getMaskValue());
}

