// unit: e379_initializeDataflowInfoForLXLU
// authority: dcc/src/Transform/Sentient/SetSendDestinationRE.cpp:244
// original: void SetSendDstRDETree::initializeDataflowInfoForLXLU(RDENode *node)
// rust home: crates/compiler/deeptools/src/transform/sentient/set_send_destination_re/set_send_dst_rde_tree.rs
// ------------------------------------------------------------------------------------------------
void e379_initializeDataflowInfoForLXLU(RDENode *node)
{
  // Uses cannot generate definitions
  if (isOperationAUse(*node->getOperation())) return;
  // Only set_send_dst operations generate definitions, initially.
  if (!isa<sentient::SetSendDestinationOp>(node->getOperation())) {
    node->setDataflowGen(new SetDstGenValueLXLU());
    return;
  }
  sentient::SetSendDestinationOp set_dst_op =
      dyn_cast<sentient::SetSendDestinationOp>(node->getOperation());
  Operation *operand = set_dst_op.getUnits().getDefiningOp();

  if (auto qmap_op = dyn_cast<mlir::uniform::QueryMapOp>(operand)) {
    node->setDataflowGen(new SetDstGenValueLXLU(qmap_op, node->getOperation()));
    return;
  }
  SimpleSetDstGenValueLXLU::Mode gen_mode =
      SimpleSetDstGenValueLXLU::Mode::kUnknown;
  if (auto consumer_unit = dyn_cast<dataflow::GetUnitOp>(operand)) {
    std::string consumer_str = consumer_unit.getType().lower();
    // It covers crossptlink as well.
    if (consumer_str.find("pt") != consumer_str.npos) consumer_str = "pt";
    if (consumer_str == "sfp")
      gen_mode = SimpleSetDstGenValueLXLU::Mode::kSendToSFP;
    else if (consumer_str == "pt")
      gen_mode = SimpleSetDstGenValueLXLU::Mode::kSendToPT;
    else if (consumer_str == "l0su")
      gen_mode = SimpleSetDstGenValueLXLU::Mode::kSendToL0SU;
  }
  node->setDataflowGen(new SetDstGenValueLXLU(gen_mode, node->getOperation()));
  return;
}

