// ------------------------------------------------------------------------------------------------
void e383_runOn(func::FuncOp func)
{
    if (initialize(func)) {
      DominanceInfo dom_info(func);
      func->walk<WalkOrder::PreOrder>([&](Operation *op) {
        if (auto get_unit_op = dyn_cast<dataflow::GetUnitOp>(op))
          runOn(get_unit_op, dom_info);
        else if (auto create_group_op = dyn_cast<dataflow::CreateGroupOp>(op))
          // because of pre-order walk we should have seen all operands before
          // the create_group.
          runOn(create_group_op, dom_info);
        else if (auto create_symbol_op = dyn_cast<symbol::CreateSymbolOp>(op))
          runOn(create_symbol_op, dom_info);
      });
    }
    for (Operation *op : to_be_deleted_) op->erase();
    clear();
  }

