// entry 384/656   level 1   scc 587   4 body lines
// unit: e384_runOn
// authority: dcc/src/Transform/Sentient/SpecializedCanonicalization.cpp:188
// original: void runOn(ModuleOp module_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/specialized_canonicalization/mod.rs
// ------------------------------------------------------------------------------------------------
void e384_runOn(ModuleOp module_op)
{
    module_op->walk<WalkOrder::PreOrder>(
        [&](func::FuncOp func) { runOn(func); });
  }

