// rust home: crates/compiler/deeptools/src/transform/sentient/store_and_forward_fusion/mod.rs
// ------------------------------------------------------------------------------------------------
bool e387_fillOperandForTrivialOp(
    mlir::Operation *op, mlir::ArrayAttr &opA_forwarding,
    mlir::ArrayAttr &opB_forwarding, mlir::ArrayAttr &opC_forwarding,
    mlir::ArrayAttr &result_forwarding, SentientPrecision &result_precision)
{
  if (auto mac_op = llvm::dyn_cast<sentient::MacOp>(op)) {
    opA_forwarding = mac_op.getOpAForwarding();
    opB_forwarding = mac_op.getOpBForwarding();
    opC_forwarding = mac_op.getOpCForwarding();
    result_forwarding = mac_op.getResultForwarding();
    result_precision = mac_op.getResultPrecision();
    return isOpTrivialMacOp(mac_op);
  }
  if (auto binary_op = llvm::dyn_cast<sentient::BinaryOp>(op)) {
    opA_forwarding = binary_op.getOpAForwarding();
    opB_forwarding = binary_op.getOpBForwarding();
    result_forwarding = binary_op.getResultForwarding();
    result_precision = binary_op.getResultPrecision();
    return isOpTrivialBinaryOp(binary_op);
  }
  // Note that: there is no trivial UnaryOp, TernaryOp in Sentient
  return false;
}

