// entry 389/656   level 1   scc 604   26 body lines
// unit: e389_runOnOperation
// authority: dcc/src/Transform/Sentient/SyncSendRecvFusion.cpp:120
// original: void SyncSendRecvFusionPass::runOnOperation()
// rust home: crates/compiler/deeptools/src/transform/sentient/sync_send_recv_fusion/mod.rs
// ------------------------------------------------------------------------------------------------
void e389_runOnOperation()
{
  if (DisableThisPass) return;
  ModuleOp module_op = getOperation();
  std::vector<mlir::Operation *> to_be_deleted;

  module_op.walk([&](dataflow::ProgramUnitOp unit_op) {
    InstructionEstimator &instruction_estimator =
        getChildAnalysis<InstructionEstimator>(unit_op);
    if (opts_.OptLevel == 0 &&
        instruction_estimator.haveIbuffSpace(dccExtContext(), unit_op)) {
      return;
    }

    unit_op.walk([&](mlir::Operation *op) {
      if (std::find(to_be_deleted.begin(), to_be_deleted.end(), op) ==
          to_be_deleted.end()) {
        auto next_op = getNextEligableNode(op);
        if (FuseSyncSendRecv(op, next_op).succeeded()) {
          to_be_deleted.push_back(op);
          to_be_deleted.push_back(next_op);
        }
      }
    });
  });
  for (auto op : to_be_deleted) op->erase();
}

