// entry 390/656   level 1   scc 607   21 body lines
// unit: e390_runOn
// authority: dcc/src/Transform/Sentient/ToggleReordering.cpp:200
// original: void ToggleReorderingPass::runOn(dataflow::ProgramUnitOp unit_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/toggle_reordering/mod.rs
// ------------------------------------------------------------------------------------------------
void e390_runOn(dataflow::ProgramUnitOp unit_op)
{
  // Gather the candidates
  llvm::SmallVector<ToggleInfo *> candidates_for_toggle_reordering;
  unit_op->walk<WalkOrder::PreOrder>([&](sentient::SubOp sub_op) {
    if (ToggleInfo *toggle_info =
            computeToggleInfoIfIsToggle(unit_op, sub_op)) {
      // Will reorder the toggle only if it has at least one use other than in
      // the YieldOp.
      if (!sub_op.getResult().hasOneUse())
        candidates_for_toggle_reordering.push_back(toggle_info);
      else
        delete toggle_info;
    }
  });

  // Perform the reordering
  for (ToggleInfo *toggle_info : candidates_for_toggle_reordering) {
    toggle_info->reorderToggle();
    delete toggle_info;
  }
}

