// entry 392/656   level 1   scc 198   24 body lines
// unit: e392_getQueryKeyAndUnitsFromParentRegion
// authority: dcc/src/Transform/Sentient/Utils.cpp:40
// original: mlir::LogicalResult getQueryKeyAndUnitsFromParentRegion( Operation *op, Value &key, SmallVector<Value> &units)
// rust home: crates/compiler/deeptools/src/transform/sentient/utils/mod.rs
// ------------------------------------------------------------------------------------------------
mlir::LogicalResult e392_getQueryKeyAndUnitsFromParentRegion(
    Operation *op, Value &key, SmallVector<Value> &units)
{
  unsigned region_idx = 0;
  while (op->getParentRegion()) {
    region_idx = op->getParentRegion()->getRegionNumber();
    op = op->getParentOp();
    if (auto program_op = dyn_cast<dataflow::ProgramUnitOp>(op)) {
      units = program_op.getUnits();
      if (program_op.getRegion().front().getArguments().size() > 0)
        key = program_op.getRegion().front().getArgument(0);
      return LogicalResult::success();
    } else if (auto uniform_op =
                   dyn_cast<mlir::uniform::UniformizeRegionsOp>(op)) {
      units = uniform_op.getRegionUnitList(region_idx);
      key = uniform_op.getRegionArg(region_idx);
      return LogicalResult::success();
    } else if (auto equalize_op =
                   dyn_cast<mlir::uniform::EqualizePatternOp>(op)) {
      units = equalize_op.getRegionUnitList(region_idx);
      key = equalize_op.getRegionArg(region_idx);
      return LogicalResult::success();
    }
  }
  return LogicalResult::failure();
}

