// entry 393/656   level 1   scc 128   59 body lines
// unit: e393_createSentientForOpWithAdditionalIterArgs
// authority: dcc/src/Transform/Sentient/Utils.cpp:195
// original: Operation *createSentientForOpWithAdditionalIterArgs( Operation *loop_op, std::vector<std::pair<Value, Value>> &start_vals_and_steps)
// rust home: crates/compiler/deeptools/src/transform/sentient/utils/mod.rs
// ------------------------------------------------------------------------------------------------
Operation *e393_createSentientForOpWithAdditionalIterArgs(
    Operation *loop_op,
    std::vector<std::pair<Value, Value>> &start_vals_and_steps)
{
  Operation *ret_op = nullptr;
  Operation *yield_op = nullptr;
  unsigned num_values = start_vals_and_steps.size();
  unsigned orig_num_iter_args;
  // Adding exiting iterator arguments
  SmallVector<Value, 8> iter_args;
  OpBuilder builder(loop_op);
  if (auto sentient_for = dyn_cast<mlir::sentient::ForOp>(loop_op)) {
    for (auto operand : sentient_for.getInits()) iter_args.push_back(operand);

    orig_num_iter_args = iter_args.size();
    // Adding new iterator arguments
    for (auto &pair : start_vals_and_steps) iter_args.push_back(pair.first);

    SmallVector<Attribute, 4> reg_locales_vector;
    ArrayAttr reg_locales =
        ArrayAttr::get(loop_op->getContext(), reg_locales_vector);
    auto new_dbg_name = getDbgNameAttr(sentient_for);
    auto new_loop = mlir::sentient::ForOp::create(
        builder, loop_op->getLoc(), sentient_for.getBound(), new_dbg_name,
        reg_locales, llvm::ArrayRef<int>(), llvm::ArrayRef<bool>(), iter_args);

    new_loop.getRegion().push_back(new Block);
    Block &body_block = new_loop.getRegion().front();
    body_block.addArgument(builder.getIndexType(), new_loop->getLoc());
    for (auto operand : iter_args)
      body_block.addArgument(operand.getType(), operand.getLoc());
    builder.setInsertionPointToStart(&body_block);

    (void)dcc::utils::copyLoopBody(sentient_for, new_loop, builder, num_values);
    yield_op = new_loop.getBody()->getTerminator();
    ret_op = static_cast<Operation *>(new_loop);
  }

  DT_CHECK(yield_op != nullptr);
  builder.setInsertionPoint(yield_op);
  // Return the step plus the iterator argument whenever the step is non-zero.
  // Otherwise return the iterator argument.
  for (unsigned i = 0; i < num_values; ++i) {
    auto &step = start_vals_and_steps[i].second;
    auto const_step =
        llvm::dyn_cast<mlir::sentient::ConstantOp>(step.getDefiningOp());
    if (const_step && const_step.getValue() == 0) continue;
    Value operand = yield_op->getOperand(i + orig_num_iter_args);
    auto add_op = mlir::sentient::AddOp::create(
        builder, ret_op->getLoc(), operand.getType(), operand, step);
    yield_op->setOperand(i + orig_num_iter_args, add_op);
  }

  // Replace uses if exists
  for (int i = 0; i < loop_op->getNumResults(); i++) {
    loop_op->getResult(i).replaceAllUsesWith(ret_op->getResult(i));
  }

  // Erase the loop
  loop_op->erase();
  return ret_op;
}

