// entry 395/656   level 1   scc 228   55 body lines
// unit: e395_pruneOutOfScopeEntries
// authority: dcc/src/Transform/Sentient/Utils.cpp:635
// original: void pruneOutOfScopeEntries(mlir::uniform::DefImmutableMappingOp map_op, SmallVectorImpl<Operation *> &to_be_deleted)
// rust home: crates/compiler/deeptools/src/transform/sentient/utils/mod.rs
// ------------------------------------------------------------------------------------------------
void e395_pruneOutOfScopeEntries(mlir::uniform::DefImmutableMappingOp map_op,
                            SmallVectorImpl<Operation *> &to_be_deleted)
{
  Operation *parent_uro = nullptr;
  int region_index = -1;
  std::tie(parent_uro, region_index) =
      dcc::uniform::utils::getRegionOpAndIndex(map_op);
  if (!parent_uro || region_index < 0) return;
  if (isa<mlir::dataflow::ProgramUnitOp>(parent_uro)) return;
  DT_CHECK(isa<mlir::uniform::UniformizeRegionsOp>(parent_uro));
  std::vector<mlir::Value> units_of_region =
      dcc::uniform::utils::getUnitsOfRegion(parent_uro, region_index);
  auto map_keys = map_op.getKeys();
  if (map_keys.size() == units_of_region.size()) return;
  DT_CHECK_MSG(map_keys.size() > units_of_region.size(),
               "invalid map with missing keys for the units represented in "
               "this local region");
  std::sort(units_of_region.begin(), units_of_region.end(),
            [](const mlir::Value a, const mlir::Value b) {
              return a.getAsOpaquePointer() < b.getAsOpaquePointer();
            });

  auto map_values = map_op.getValues();
  std::vector<mlir::Value> keys_v, values_v;
  for (size_t value_index = 0; value_index < map_keys.size(); value_index++) {
    if (!std::binary_search(units_of_region.begin(), units_of_region.end(),
                            map_keys[value_index],
                            [](const mlir::Value a, const mlir::Value b) {
                              return a.getAsOpaquePointer() <
                                     b.getAsOpaquePointer();
                            }))
      continue;
    keys_v.push_back(map_keys[value_index]);
    values_v.push_back(map_values[value_index]);
  }
  DT_CHECK(keys_v.size() == values_v.size());
  DT_CHECK_MSG(keys_v.size() == units_of_region.size(),
               "expected the original map to contain keys that match the units "
               "in this local region!");
  // After removing out-of-scope key/value pairs, the map might become trivial
  // (ie all values are the same) in which case we can replace all uses of query
  // ops that refer to this map with the single value.
  if (llvm::all_of(values_v,
                   [&](mlir::Value v) { return v == values_v.back(); })) {
    for (Operation *user : map_op->getUsers()) {
      DT_CHECK(isa<mlir::uniform::QueryMapOp>(user));
      user->getResult(0).replaceAllUsesWith(values_v.back());
      to_be_deleted.push_back(user);
    }
  } else {
    OpBuilder builder(map_op);
    auto new_map_op = mlir::uniform::DefImmutableMappingOp::create(
        builder, map_op->getLoc(), builder.getIndexType(), keys_v, values_v);
    map_op->replaceAllUsesWith(new_map_op);
  }
  to_be_deleted.push_back(map_op);
}

