// rust home: crates/compiler/deeptools/src/transform/sentient/address_pinning_and_toggle/mod.rs
// ------------------------------------------------------------------------------------------------
void e419_turnHBMConstantOpAddrsToQueryMapsInUniformRegions(
        dataflow::ProgramUnitOp unit)
{
  auto parent_func = dyn_cast<func::FuncOp>(unit->getParentOp());
  DT_CHECK(parent_func);
  OpBuilder const_builder(parent_func.getBody());

  unit->walk<WalkOrder::PreOrder>([&](Operation *op) {
    if (!isa<uniform::UniformizeRegionsOp, uniform::EqualizePatternOp>(op))
      return WalkResult::advance();

    turnHBMConstantOpAddrsToQueryMapsHelper(const_builder, *op);
    return WalkResult::skip();
  });
}

