// original: void SimpleConstantDataTransferUpdater::updateConstantMutableAddr( const EvaluatedValue &new_immut_addr_ev)
// rust home: crates/compiler/deeptools/src/transform/sentient/address_pinning_and_toggle/simple_constant_data_transfer_updater.rs
// ------------------------------------------------------------------------------------------------
void e421_updateConstantMutableAddr(
    const EvaluatedValue &new_immut_addr_ev)
{
  DT_CHECK(
      dcc::utils::isConstant<sentient::ConstantOp>(mutable_addr_[0].get()) &&
      "Expect constant mutable addr");
  // original mutable address
  const EvaluatedValue &const_ma_ev =
      evaluator_.evaluateValue(mutable_addr_[0].get());
  DEBUG_WITH_TYPE(
      VerboseDebug,
      llvm::dbgs() << "  old_immut_addr_ev = " << dtd_.getBaseAddr()
                   << "\n  new_immut_addr_ev = " << new_immut_addr_ev << "\n");
  // new_mut_addr_ev = const_ma.getValue() + dtd_.getBaseAddr() -
  // new_immut_addr_ev
  const EvaluatedValue &new_mut_addr_ev = evaluator_.evaluateSub(
      evaluator_.evaluateSum(const_ma_ev, dtd_.getBaseAddr()),
      new_immut_addr_ev);
  DEBUG_WITH_TYPE(VerboseDebug, llvm::dbgs() << "  new_mut_addr_ev = "
                                             << new_mut_addr_ev << "\n");
  DT_CHECK_MSG(!ps_manager_.overflowsRegister(new_mut_addr_ev, element_size_),
               "LAR/EAR overflow detected");
  mutable_addr_.assign(
      createOffsetValue(&dtd_.getOperation(), new_mut_addr_ev));
}

