void e422_insert(DataTransferDescriptor *desc)
{
  validate();
  push_back(desc);
  sorted_list_.push_back(desc);
  std::sort(sorted_list_.begin(), sorted_list_.end(),
            [](DataTransferDescriptor *a, DataTransferDescriptor *b) {
              return &a->getOperation() < &b->getOperation();
            });
}

// ------------------------------------------------------------------------------------------------
// entry 423/656   level 2   scc 64   11 body lines
// unit: e423_lookup
// authority: dcc/src/Transform/Sentient/AddressPinningAndToggle.cpp:2179
// original: DataTransferDescriptor *DataTransferDescriptorContainer::lookup( const Operation *op) const
// rust home: crates/compiler/deeptools/src/transform/sentient/address_pinning_and_toggle/data_transfer_descriptor_container.rs
// ------------------------------------------------------------------------------------------------
DataTransferDescriptor *e423_lookup(
    const Operation *op) const
{
  DT_CHECK(op);
  validate();
  auto iter =
      std::lower_bound(sorted_list_.begin(), sorted_list_.end(), op,
                       [](const DataTransferDescriptor *a, const Operation *b) {
                         return &a->getOperation() < b;
                       });
  if (iter == sorted_list_.end()) return nullptr;
  return &(*iter)->getOperation() == op ? *iter : nullptr;
}

