void e436_duplicateAndUpdateEntriesOfQueryMapInLocalRegions(
    mlir::Operation *local_region_op, std::vector<mlir::Value> &new_units,
    std::vector<mlir::Operation *> &to_be_deleted)
{
  for (int i = 0; i < local_region_op->getNumRegions(); ++i) {
    OpBuilder builder_region(local_region_op->getRegion(i));
    for (auto &it : local_region_op->getRegion(i).getOps()) {
      if (auto query_map_op = llvm::dyn_cast<mlir::uniform::QueryMapOp>(&it)) {
        auto new_query_map_op = duplicateAndUpdateEntriesOfQueryMap(
            query_map_op, new_units, builder_region);
        query_map_op.replaceAllUsesWith(new_query_map_op.getOperation());
        to_be_deleted.push_back(query_map_op);
      }
    }
  }
}

