void e439_runOnOperation()
{
    if (DisableThisPass) return;
    ModuleOp module_op = getOperation();
    // Order the keys of def_immutable_mapping ops.
    RewritePatternSet patterns(&getContext());
    patterns.add<OrderDefImmutableMapKeys>(&getContext());
    FrozenRewritePatternSet patternSet(std::move(patterns));
    if (failed(applyPatternsGreedily(module_op, patternSet)))
      signalPassFailure();
    // Move constants to the beginning of the function, sort and uniq.
    runOn(module_op);
  }

