// rust home: crates/compiler/deeptools/src/transform/sentient/live_range_reduction/mod.rs
// ------------------------------------------------------------------------------------------------
LogicalResult e441_findDominantValue(
    SmallVector<Value> ssa_list, const int current_value_index,
    int& dominant_value_index, const DominanceInfo& dominance_info)
{
  // start scanning from the closest to find the dominant SSA
  auto current_op = ssa_list[current_value_index].getDefiningOp();
  for (int scanner = current_value_index - 1; scanner >= 0; scanner--) {
    // 1. use properlyDominates() to avoid within-op substitution.
    // 2. check to avoid chaining SSAs with different precisions. This
    // conservative restriction is necessary because sentientIR uses #elements
    // as unit for address offsets and without the check, liveRangeReduction may
    // chain SSAs of data structures with same offset but different precisions.
    // 3. need to check SSA's reglocale. This is especially necessary when
    // constantOp is involved in SSA's definition. for example
    // %0 = constantOp
    // %1 = ...
    // %2 = ... %0
    // assume %0 in %2 operation can be substituted by %1. Since %0 is a
    // constant value which can be equal to %1's exprInfo's constant term. The
    // substitution is legit only if %1 and %2 share the same reglocale.
    if (dominance_info.properlyDominates(ssa_list[scanner], current_op) &&
        (skip_elem_size_ ||
         areElementSizeIdentical(ssa_list[scanner],
                                 ssa_list[current_value_index])) &&
        areReglocalesMatching(ssa_list[scanner],
                              ssa_list[current_value_index])) {
      if (isa<sentient::AddOp, sentient::SubOp>(current_op) &&
          (getRootIterArg(ssa_list[current_value_index]) !=
           getRootIterArg(ssa_list[scanner]))) {
        // for scalar_add/sub, search dominant ssa having the same def-use
        // chain. This check is necessary to avoid unnecessary SSA substitution
        // for AddOps when merging registers is impossible, e.g. test case:
        // int8-kg3-l0lu.mlir.
        continue;
      }
      dominant_value_index = scanner;
      return LogicalResult::success();
    }
  }
  return LogicalResult::failure();
}

