// original: Operation* LiveRangeReductionPass::createMapAndQuery( OpBuilder& builder, std::vector<int64_t>& new_const_val, Operation* op)
// rust home: crates/compiler/deeptools/src/transform/sentient/live_range_reduction/mod.rs
// ------------------------------------------------------------------------------------------------
Operation* e443_createMapAndQuery(
    OpBuilder& builder, std::vector<int64_t>& new_const_val, Operation* op)
{
  // create const_ops for all new constants
  std::vector<Operation*> const_ops;
  for (int idx = 0; idx < new_const_val.size(); idx++) {
    if (new_const_val[idx] == INT64_MAX) {
      const_ops.push_back(nullptr);
    } else {
      auto const_op = sentient::ConstantOp::create(builder, op->getLoc(),
                                                   op->getResult(0).getType(),
                                                   new_const_val[idx]);
      const_ops.push_back(const_op);
    }
  }
  // create immutable map for all const_ops
  // first, find the parent program_unit or uniform region op
  SmallVector<Value> units;
  Value query_key;
  if (getQueryKeyAndUnitsFromParentRegion(op, query_key, units).failed()) {
    op->emitOpError("can't find parentOp");
    signalPassFailure();
  }
  // second, create an immutable map mapping getUnitOp to constOp
  SmallVector<Value> keys, values;
  while (!units.empty()) {
    auto unit = units.back();
    units.pop_back();
    if (auto group_op = unit.getDefiningOp<dataflow::CreateGroupOp>()) {
      units.append((SmallVector<Value>)group_op.getUnitIds());
      continue;
    }
    keys.push_back(unit);
    values.push_back(
        const_ops.at(getUnitIndex(getFoldedUnitNameAsString(unit)))
            ->getResult(0));
  }
  auto map_op = uniform::DefImmutableMappingOp::create(
      builder, op->getLoc(), builder.getIndexType(), keys, values);

  // create queryOp
  auto query_op = uniform::QueryMapOp::create(
      builder, op->getLoc(), builder.getIndexType(), map_op, query_key);
  return query_op;
}

