// entry 444/656   level 2   scc 227   32 body lines
// unit: e444_analyze
// authority: dcc/src/Transform/Sentient/LocalRegionSplittingForValueCommoning.cpp:273
// original: bool LocalRegionSplittingForValueCommoningPass::analyze( lrs::UniformRegion &ur, const SentientRegType locale, const SenComponents comp)
// rust home: crates/compiler/deeptools/src/transform/sentient/local_region_splitting_for_value_commoning/mod.rs
// ------------------------------------------------------------------------------------------------
bool e444_analyze(
    lrs::UniformRegion &ur, const SentientRegType locale,
    const SenComponents comp)
{
  const unsigned kMaxRegNum = getMaxRegNum(locale, comp);
  uniform::UniformizeRegionsOp orig_ur = ur.getOriginalOp();
  bool need_to_transform = false;
  for (int region_index = 0; region_index < orig_ur.getRegions().size();
       region_index++) {
    Region &local_region = orig_ur.getRegion(region_index);
    SmallVector<uniform::DefImmutableMappingOp> uniform_maps;
    collectUniformMaps(uniform_maps, local_region, locale);
    LLVM_DEBUG(llvm::dbgs() << "found " << uniform_maps.size() << " in region "
                            << region_index << " with locale "
                            << stringifySentientRegType(locale)
                            << "(Max Register Num:" << kMaxRegNum << ")\n");
    // heuristic: Since this analysis is purely local, I use < instead of <= to
    // give room for one globally shared lbr uniform map.
    if (uniform_maps.size() < kMaxRegNum) {
      ur.addLocalRegion(
          dcc::uniform::utils::getUnitsOfRegion(orig_ur, region_index),
          local_region);
      continue;
    }
    need_to_transform = true;
    std::vector<Value> units =
        dcc::uniform::utils::getUnitsOfRegion(orig_ur, region_index);
    SmallVector<SmallVector<Value>> clustered_units;
    cluster(clustered_units, units, uniform_maps);
    for (const auto &unit_group : clustered_units) {
      ur.addLocalRegion(unit_group, local_region);
    }
  }
  return need_to_transform;
}

