        splitBounds(new_bounds, new_bounds0, new_bounds1);

        auto new_query_map_bound0 =
            dcc::uniform::utils::createQueryMapFromConstants(
                builder, const_builder, loc, query_map_key, bound_keys,
                new_bounds0);
        auto new_query_map_bound1 =
            dcc::uniform::utils::createQueryMapFromConstants(
                builder, const_builder, loc, query_map_key, bound_keys,
                new_bounds1);

        outermost.setBound(new_query_map_bound0);
        second.setBound(new_query_map_bound1);
        // change the definition of outermost and second for the rest of the
        // logic
        outermost = second;
