// unit: e448_performLoopPeeling
// authority: dcc/src/Transform/Sentient/MultiDimLoopPeeling.cpp:543
// original: void LoopPeelingManager::performLoopPeeling()
// rust home: crates/compiler/deeptools/src/transform/sentient/multi_dim_loop_peeling/loop_peeling_manager.rs
// ------------------------------------------------------------------------------------------------
void e448_performLoopPeeling()
{
  // Peel the loops from the innermost out. This ensures that
  // when peeling a loop (by cloning its body), any candidate
  // loops within have already been peeled.
  for (auto it = loop_to_peeling_type_.rbegin();
       it != loop_to_peeling_type_.rend(); ++it) {
    sentient::ForOp for_op = it->first;
    PeelingType p_type = it->second;
    DT_CHECK(p_type != PeelingType::kNoPeeling);
    bool peel_first_iter = is_any_of(p_type, PeelingType::kFirstIterOnly,
                                     PeelingType::kFirstAndLastIter);
    bool peel_last_iter = is_any_of(p_type, PeelingType::kLastIterOnly,
                                    PeelingType::kFirstAndLastIter);

    // Track the current values of the iterator arguments.
    llvm::SmallVector<Value, 4> new_iter_args = for_op.getIterOperands();

    Value orig_bound = for_op.getBound();
    auto const_bound_op =
        llvm::dyn_cast<sentient::ConstantOp>(orig_bound.getDefiningOp());
    DT_CHECK_MSG(const_bound_op, "Expect ForOp with constant bound");
    int64_t orig_bound_val = const_bound_op.getValue();

    // Peel the first iteration, where the IV will be replaced by
    // orig_bound_val. This iteration will go before for_op.
    if (peel_first_iter)
      copyOneIter(for_op, new_iter_args, orig_bound_val, /*move_after*/ false);

    // Determine the new bound of the loop.
    int64_t new_bound_val =
        orig_bound_val - (peel_first_iter ? 1 : 0) - (peel_last_iter ? 1 : 0);
    auto new_bound_op = sentient::ConstantOp::create(
        const_builder_, for_op->getLoc(), orig_bound.getType(), new_bound_val);
    for_op.setBound(new_bound_op);
    dcc::utils::updateDbgName(/*prefix*/ "MDLP(", for_op,
                              /*suffix*/ stringifyPeelingType(p_type) + ")");

    // Set the init values of the loop, and update new_iter_args
    // to be the loop results.
    for_op.getInitArgsMutable().assign(new_iter_args);
    new_iter_args.clear();
    new_iter_args = for_op.getResults();

    if (peel_last_iter) {
      // Peel the last iteration, where the IV will be replaced by 1.
      // This iteration will go after for_op.
      copyOneIter(for_op, new_iter_args, 1, /*move_after*/ true);

      // After peeling the last iteration, the loop's bound is decremented
      // by one (done above) and the constant side of comparisons on
      // the IV must also be decremented by one.
      decrementPredicatesOnIV(for_op.getInductionVar());
    }

    // The IfOps may be simplified since the range of the IV has been
    // reduced and since some IfOps feeding into other IfOps have been replaced
    // by a ConstantOp.
    SmallVector<Operation *, 4> if_ops_to_simplify;
    for_op->getParentOp()->walk<WalkOrder::PostOrder>(
        [&](sentient::IfOp if_op) { if_ops_to_simplify.push_back(if_op); });
    simplifyConditionals(for_op->getContext(), if_ops_to_simplify);
  }
}

