// rust home: crates/compiler/deeptools/src/transform/sentient/old_register_initialization/register_init_info.rs
// ------------------------------------------------------------------------------------------------
int e449_calcSSAWeight(Region &reg)
{
  for (auto &block : reg.getBlocks()) {
    for (auto &op : block.getOperations()) {
      op.walk<WalkOrder::PreOrder>(
          [this](mlir::Operation *op1) { calcSSAWeight(op1); });
    }
  }
  return 0;
}

