// entry 451/656   level 2   scc 360   114 body lines
// unit: e451_collectRegInitAndRegCoalescingCandidateFast
// authority: dcc/src/Transform/Sentient/OldRegisterInitialization.cpp:548
// original: void RegisterInitInfo::collectRegInitAndRegCoalescingCandidateFast( dataflow::ProgramUnitOp &unit, mlir::Value u)
// rust home: crates/compiler/deeptools/src/transform/sentient/old_register_initialization/register_init_info.rs
// ------------------------------------------------------------------------------------------------
void e451_collectRegInitAndRegCoalescingCandidateFast(
    dataflow::ProgramUnitOp &unit, mlir::Value u)
{
  auto get_unit = u.getDefiningOp<dataflow::GetUnitOp>();
  SenComponents comp = dcc::getUnitType(get_unit);
  std::vector<mlir::Value> final_reginit_candidates;
  // Each locale can not have more candidates for reg init than number of
  // registers
  std::array<unsigned int, getMaxEnumValForSentientRegType() + 1>
      locale_to_num_reginit_candidates{0};
  // First handle required register init candidates.
  for (const auto &req : required_reginit_candidates_) {
    SentientRegType locale = sentient::getValueRegLocale(req);
    auto locale_count =
        locale_to_num_reginit_candidates[static_cast<size_t>(locale)]++;
    DT_CHECK_MSG(locale_count < dccExtContext().getMaxRegNum(locale, comp),
                 "There are more required candidates than there are registers "
                 "available for this locale");
    final_reginit_candidates.push_back(req);
  }

  // Now vet register init candidates against coalescing candidates
  DEBUG_WITH_TYPE(VerboseDebug, {
    llvm::dbgs() << "num reg init candidates: "
                 << valid_reginit_candidates_.size() << "\n";
    llvm::dbgs() << "num reg coalescing candidates: "
                 << valid_reg_coalescing_candidates_.size() << "\n";
  });
  std::stable_sort(valid_reginit_candidates_.begin(),
                   valid_reginit_candidates_.end(),
                   [this](const mlir::Value &l, const mlir::Value &r) {
                     return ssa_weight_[l] > ssa_weight_[r];
                   });
  int reg_init_index = 0, reg_coal_index = 0;
  bool is_reginit = false;
  std::vector<mlir::Value> val_with_max_weight;
  std::vector<std::vector<mlir::Value>> final_regcoalescing_candidates;
  int graph_coloring_iter_count = 0;
  while (true) {
    std::tie(reg_init_index, reg_coal_index, is_reginit, val_with_max_weight) =
        getNextMaxWeight(reg_init_index, reg_coal_index);
    if (val_with_max_weight.empty()) {
      break;
    }
    SentientRegType locale =
        sentient::getValueRegLocale(val_with_max_weight[0]);
    if (is_reginit) {
      auto locale_count =
          locale_to_num_reginit_candidates[static_cast<size_t>(locale)]++;
      if (locale_count >= dccExtContext().getMaxRegNum(locale, comp))
        continue;  // not colorable anymore.
      final_reginit_candidates.push_back(val_with_max_weight[0]);
    } else {
      final_regcoalescing_candidates.push_back(val_with_max_weight);
    }
    ++graph_coloring_iter_count;
    Liveness liveness_copy0 = liveness_;  // this copy is expensive!
    liveness_copy0.updateLiveRangesForProgramHeaderPromotion(
        final_reginit_candidates);
    // for (auto val : final_reginit_candidates) {
    //   liveness_copy0.dumpLiveRangeOf(val);
    // }
    liveness_copy0.addVirtualAssignOptional(final_regcoalescing_candidates);
    liveness_copy0.addVirtualAssignEnforced(enforced_virtual_assign_);
    RegisterGraphs gc;  // destructing this is expensive!
    if (hasUniformizeRegion(unit))
      gc.buildGraphs(dccExtContext(), liveness_copy0, unit, locale, u);
    else
      gc.buildGraphs(dccExtContext(), liveness_copy0, unit, locale, nullptr);
    gc.createSameColorEdgeEqClasses(liveness_copy0, locale);
    gc.buildHyperGraph(locale);
    // this is last resort where we check colorability by actualy doing it
    // only attemp greedy coloring for conservative approach
    int maxRegNum = dccExtContext().getMaxRegNum(locale, comp);
    if (!gc.fastCheckColorability(maxRegNum, locale)) {
      if (is_reginit) {
        final_reginit_candidates.pop_back();
      } else {
        final_regcoalescing_candidates.pop_back();
      }
    }
    // stop search after N% of high-weight candidates
    // have been processed. todo: N can be a function of opt level (ie -O).
    if (NPercentTopRegCoalescingCandidates < 100) {
      const unsigned int total_initial =
          valid_reg_coalescing_candidates_.size();
      const unsigned int total_accepted = final_regcoalescing_candidates.size();
      if ((total_accepted * 100 / total_initial) >=
          NPercentTopRegCoalescingCandidates)
        reg_coal_index = valid_reg_coalescing_candidates_.size();
    }
    if (NPercentTopRegInitCandidates < 100) {
      const unsigned int total_initial = valid_reginit_candidates_.size();
      const unsigned int total_accepted =
          final_reginit_candidates.size() - required_reginit_candidates_.size();
      if ((total_accepted * 100 / total_initial) >=
          NPercentTopRegInitCandidates)
        reg_init_index = valid_reginit_candidates_.size();
    }
  }

  DEBUG_WITH_TYPE(VerboseDebug, {
    llvm::dbgs() << "graph_coloring_iter_count = " << graph_coloring_iter_count
                 << "\n";
    llvm::dbgs() << "ratio of accepted vs initial reg init candidates: "
                 << final_reginit_candidates.size() * 1.0 /
                        valid_reginit_candidates_.size()
                 << "\n";
    llvm::dbgs() << "ratio of accepted vs initla reg coalescing candidates: "
                 << final_regcoalescing_candidates.size() * 1.0 /
                        valid_reg_coalescing_candidates_.size()
                 << "\n";
  });
  for (auto val : final_reginit_candidates) final_reginit_candidates_.push(val);
  final_reg_coalescing_candidates_ = final_regcoalescing_candidates;
}

