// original: void OpRerollingPass::updateRefOpUnrollInfo( mlir::Operation *curr_op, mlir::Operation *ref_op, mlir::Operation *prev_op, mlir::Operation *last_op, sentient::UnrollOperands &ref_operand_list, sentient::UnrollOperands &curr_operand_list, llvm::SmallVector<mlir::Operation *> &ops_to_be_deleted, SenComponents type)
// rust home: crates/compiler/deeptools/src/transform/sentient/op_rerolling/mod.rs
// ------------------------------------------------------------------------------------------------
void e453_updateRefOpUnrollInfo(
    mlir::Operation *curr_op, mlir::Operation *ref_op, mlir::Operation *prev_op,
    mlir::Operation *last_op, sentient::UnrollOperands &ref_operand_list,
    sentient::UnrollOperands &curr_operand_list,
    llvm::SmallVector<mlir::Operation *> &ops_to_be_deleted,
    SenComponents type)
{
  // need to update is_field_unroll_. only do this once at the
  // beginning.
  ref_operand_list.updateUnrollInfo(curr_operand_list);

  ref_operand_list.incrementUnrollSize(curr_operand_list.getUnrollSize());
  if (ref_operand_list.isXrfWtOp()) {
    ref_operand_list.setXrfWtIncrVal(ref_operand_list.getXrfWtIncrVal() +
                                     curr_operand_list.getXrfWtIncrVal());
  }
  // update the curr_op's uses with ref op
  for (uint i = 0; i < curr_op->getNumResults(); i++) {
    curr_op->getResult(i).replaceAllUsesWith(ref_op->getResult(i));
  }
  // delete curr_op
  ops_to_be_deleted.push_back(curr_op);
  if (auto splat_op = llvm::dyn_cast<sentient::SplatOp>(curr_op)) {
    // delete the input/output logical ports
    Operation *input = splat_op.getInput().getDefiningOp();
    Operation *output = splat_op.getOutput().getDefiningOp();
    if (isa<sentient::LogicalPortOp>(input) && input->hasOneUse())
      ops_to_be_deleted.push_back(input);
    if (isa<sentient::LogicalPortOp>(output) && output->hasOneUse())
      ops_to_be_deleted.push_back(output);
  }
  // is the curr_op last op in the region?
  if (curr_op == last_op || (curr_operand_list.isXrfRdOp() &&
                             curr_operand_list.getXrfRdIncrVal() != 0)) {
    ref_operand_list.setXrfRdIncrVal(curr_operand_list.getXrfRdIncrVal());
    // unroll size can be 1,2,4,8..
    setUnrollFieldsInStmt(ref_op, ref_operand_list, type);
    ref_op = nullptr;
    ref_operand_list.reset();
  }
  prev_op = curr_op;
}

