// ------------------------------------------------------------------------------------------------
void e456_runOn(dataflow::ProgramUnitOp unit)
{
  initialize(unit);
  dataflow::GetUnitOp curr_unit =
      (*unit.getUnits().begin()).getDefiningOp<dataflow::GetUnitOp>();
  auto comp = dcc::getUnitType(curr_unit);
  if (!is_any_of(comp, L3LU, L3SU)) return;
  auto &sps_manager = getChildAnalysis<StaticPinningSchemeManager>(unit);
  ExpressionEvaluator evaluator;
  sps_manager.eval(dccExtContext(), evaluator, LX);
  LLVM_DEBUG(sps_manager.dump(llvm::dbgs()));
  unit->walk<WalkOrder::PreOrder>([&](Operation *op) { runOn(op); });
  computeNewRegisterIndices(sps_manager, evaluator);
  doRenumbering();
  cleanup();
}

