// authority: dcc/src/Transform/Sentient/RegisterInitialization.cpp:182
// original: void runOn(dataflow::ProgramUnitOp prog_unit, Liveness &liveness)
// rust home: crates/compiler/deeptools/src/transform/sentient/register_initialization/mod.rs
// ------------------------------------------------------------------------------------------------
void e458_runOn(dataflow::ProgramUnitOp prog_unit, Liveness &liveness)
{
    UniformGroupAnalyzer uga(prog_unit);
    uga.collectExclusiveGroupLeaders();

    SimpleCollector simple_collector(prog_unit, liveness, uga);
    SimpleEvaluator simple_evaluator;
    GreedySelector greedy_selector(prog_unit, liveness, dccExtContext());
    ConstantDecaySelector cd_selector(prog_unit, liveness, dccExtContext(),
                                      /* backtrack */ true);
    LinearDecaySelector ld_selector(prog_unit, liveness, dccExtContext(),
                                    /* backtrack */ true);
    PolynomialDecaySelector pd_selector(prog_unit, liveness, dccExtContext(),
                                        /* backtrack */ true);
    BisectSelector bisect_selector(prog_unit, liveness, dccExtContext());
    UniformGrouper uniform_grouper;
    Transformer transformer(prog_unit, liveness, uga);

    CollectorInterface *chosen_collector = nullptr;
    EvaluatorInterface *chosen_evaluator = nullptr;
    SelectorInterface *chosen_selector = nullptr;

    switch (collectorKind) {
      case dcc::reginit::CollectorKind::kSimple: {
        chosen_collector = &simple_collector;
        break;
      }
      default:
        DT_ERROR("unexpected collector kind");
    }

    switch (evaluatorKind) {
      case dcc::reginit::EvaluatorKind::kSimple: {
        chosen_evaluator = &simple_evaluator;
        break;
      }
      default:
        DT_ERROR("unexpected evaluator kind");
    }

    switch (selectorKind) {
      case dcc::reginit::SelectorKind::kGreedy: {
        chosen_selector = &greedy_selector;
        break;
      }
      case dcc::reginit::SelectorKind::kConstantDecay: {
        chosen_selector = &cd_selector;
        break;
      }
      case dcc::reginit::SelectorKind::kLinearDecay: {
        chosen_selector = &ld_selector;
        break;
      }
      case dcc::reginit::SelectorKind::kPolynomialDecay: {
        chosen_selector = &pd_selector;
        break;
      }
      case dcc::reginit::SelectorKind::kBisect: {
        chosen_selector = &bisect_selector;
        break;
      }
      default:
        DT_ERROR("unexpected selector kind");
    }

    Driver driver(*chosen_collector, *chosen_evaluator, *chosen_selector,
                  uniform_grouper, transformer, prog_unit, uga);
    driver.run();
  }

