// entry 459/656   level 2   scc 414   53 body lines
// unit: e459_computeNewRegisterIndices
// authority: dcc/src/Transform/Sentient/RegisterPacking.cpp:182
// original: void RegisterPackingPass::computeNewRegisterIndices( std::map<SentientRegType, std::vector<int>> &avoid_renumbering_regs)
// rust home: crates/compiler/deeptools/src/transform/sentient/register_packing/mod.rs
// ------------------------------------------------------------------------------------------------
void e459_computeNewRegisterIndices(
    std::map<SentientRegType, std::vector<int>> &avoid_renumbering_regs)
{
  for (auto &typed_reg_collec : reg_table) {
    SentientRegType reg_type = typed_reg_collec.getRegType();
    if (dccExtContext().getProgStitch() && (reg_type == SentientRegType::lbr ||
                                            reg_type == SentientRegType::ebr)) {
      for (auto &reg : typed_reg_collec.getRegistersList())
        reg.setNewRegisterIndex(reg.getOldRegisterIndex());
      continue;
    }
    // If a register is in the avoid renumbering list, update it with its
    // original value to prevent renumbering.
    for (auto no_renumbering_reg : avoid_renumbering_regs[reg_type]) {
      for (auto &reg : typed_reg_collec.getRegistersList())
        if (reg.getOldRegisterIndex() == no_renumbering_reg)
          reg.setNewRegisterIndex(reg.getOldRegisterIndex());
    }

    // Determines the next valid idx to use. Some idx values may not be valid
    // because some registers may be marked to avoid renumbering.
    auto getNextValidIdx = [](std::vector<int> &avoid_list, int idx) -> int {
      if (avoid_list.empty()) return idx;
      int curr_idx = idx, list_size = avoid_list.size();
      for (int i = 0; i < list_size;) {
        if (curr_idx == avoid_list[i]) {
          ++curr_idx;
          i = 0;
        } else
          ++i;
      }
      return curr_idx;
    };

    int idx = 0;
    for (auto &reg : typed_reg_collec.getRegistersList()) {
      idx = getNextValidIdx(avoid_renumbering_regs[reg_type], idx);
      if (reg.isHeaderPromoted() && !reg.hasSameValueInAllUnits()) {
        if (updateRegIndex(typed_reg_collec, reg, idx)) idx++;
      }
    }
    for (auto &reg : typed_reg_collec.getRegistersList()) {
      idx = getNextValidIdx(avoid_renumbering_regs[reg_type], idx);
      if (reg.isHeaderPromoted() && reg.hasSameValueInAllUnits()) {
        if (updateRegIndex(typed_reg_collec, reg, idx)) idx++;
      }
    }
    for (auto &reg : typed_reg_collec.getRegistersList()) {
      idx = getNextValidIdx(avoid_renumbering_regs[reg_type], idx);
      if (!reg.isHeaderPromoted()) {
        if (updateRegIndex(typed_reg_collec, reg, idx)) idx++;
      }
    }
  }
}

// ------------------------------------------------------------------------------------------------
// entry 460/656   level 2   scc 417   21 body lines
// unit: e460_runOnAllOps
// authority: dcc/src/Transform/Sentient/RegisterPacking.cpp:275
// original: void RegisterPackingPass::runOnAllOps(mlir::Operation *op)
// rust home: crates/compiler/deeptools/src/transform/sentient/register_packing/mod.rs
// ------------------------------------------------------------------------------------------------
void e460_runOnAllOps(mlir::Operation *op)
{
  SentientRegType reg_type;
  int reg_index;
  if (op->hasAttr("regIndex")) {
    DT_CHECK(op->hasAttr("regLocale"));
    std::tie(reg_type, reg_index) = getRegTypeAndIndex(op, 0);
    if (reg_type == SentientRegType::unknown) return;
    auto typed_reg_collec = getRegWithType(reg_table, reg_type);
    typed_reg_collec->getRegistersList().push_back(
        RegIndex(op->getResult(0), reg_index));
  } else if (op->hasAttr("regIndices")) {
    DT_CHECK(op->hasAttr("regLocales"));
    for (int i = 0; i < op->getNumResults(); i++) {
      std::tie(reg_type, reg_index) = getRegTypeAndIndex(op, i);
      if (reg_type == SentientRegType::unknown) continue;
      auto typed_reg_collec = getRegWithType(reg_table, reg_type);
      typed_reg_collec->getRegistersList().push_back(
          RegIndex(op->getResult(i), reg_index));
    }
  }
}

