// entry 461/656   level 2   scc 419   38 body lines
// unit: e461_runOnForOp
// authority: dcc/src/Transform/Sentient/RegisterPacking.cpp:333
// original: void RegisterPackingPass::runOnForOp(sentient::ForOp for_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/register_packing/mod.rs
// ------------------------------------------------------------------------------------------------
void e461_runOnForOp(sentient::ForOp for_op)
{
  if (!for_op) return;
  if (!for_op->hasAttr("regLocales") || !for_op->hasAttr("regIndices")) return;
  auto prog_headers = for_op.getProgramHeader();
  int num_lccr = for_op.getNumInductionVars();

  for (int idx = 0; idx < for_op.getNumRegionIterArgs(); idx++) {
    SentientRegType reg_type;
    int reg_index;
    std::tie(reg_type, reg_index) = getRegTypeAndIndex(for_op, num_lccr + idx);
    if (reg_type == SentientRegType::unknown) continue;

    auto typed_reg_collec = getRegWithType(reg_table, reg_type);
    bool is_header_promoted =
        for_op->hasAttr("programHeader") && idx < prog_headers.size() &&
        mlir::cast<BoolAttr>(prog_headers[idx]).getValue();

    fillTypedRegCollection(typed_reg_collec, for_op.getInitArgs()[idx],
                           for_op.getBody()->getArguments()[idx + num_lccr],
                           reg_index, is_header_promoted);
  }
  for (int idx = 0; idx < for_op.getNumResults(); idx++) {
    SentientRegType reg_type;
    int reg_index;
    std::tie(reg_type, reg_index) = getRegTypeAndIndex(
        for_op, num_lccr + for_op.getNumRegionIterArgs() + idx);
    if (reg_type == SentientRegType::unknown) continue;

    auto typed_reg_collec = getRegWithType(reg_table, reg_type);
    bool is_header_promoted =
        for_op->hasAttr("programHeader") && idx < prog_headers.size() &&
        mlir::cast<BoolAttr>(prog_headers[idx]).getValue();

    fillTypedRegCollection(typed_reg_collec, for_op.getInitArgs()[idx],
                           for_op.getResult(idx), reg_index,
                           is_header_promoted);
  }
}

