// entry 465/656   level 2   scc 449   65 body lines
// unit: e465_updateIfOpBasedOnParentIfOp
// authority: dcc/src/Transform/Sentient/RemoveRedundantConditionals.cpp:151
// original: void RedundantConditionalManager::updateIfOpBasedOnParentIfOp()
// rust home: crates/compiler/deeptools/src/transform/sentient/remove_redundant_conditionals/redundant_conditional_manager.rs
// ------------------------------------------------------------------------------------------------
void e465_updateIfOpBasedOnParentIfOp()
{
  if (isa<BlockArgument>(if_op_.getLhs()) ||
      isa<BlockArgument>(if_op_.getRhs()))
    return;
  OpBuilder builder(if_op_);
  auto parent_if_op =
      llvm::dyn_cast<sentient::IfOp>(non_const_side_.getDefiningOp());
  // If the predicate is not an EQ comparison between a parent IfOp's result and
  // a constant, skip this conditional.
  if (!parent_if_op || if_op_.getPredicate() != CmpIPredicate::eq) return;

  // If the parent conditional is a simple conditional consisting of
  // blocks of one operation each, get the values yielded at the result
  // index used in non_const_side_.
  auto result_idx = mlir::cast<OpResult>(non_const_side_).getResultNumber();
  auto ret_vals = getReturnValsIfSimpleConditional(parent_if_op, result_idx);
  if (!ret_vals.has_value()) return;

  if (ret_vals.value().first == ret_vals.value().second) {
    // If the parent conditional yields the same value
    // in both branches, then remove its uses with this value.
    Value result =
        parent_if_op.getThenRegion().front().getTerminator()->getOperand(
            result_idx);
    LLVM_DEBUG(llvm::dbgs()
               << "Replace the if op " << parent_if_op << "\nwith the value\n"
               << result << "\n");
    parent_if_op.getResult(result_idx).replaceAllUsesWith(result);
    if (parent_if_op.use_empty()) to_be_deleted_.push_back(parent_if_op);
    return;
  }

  // To be a candidate, the child conditional's predicate must compare the
  // parent conditional's result to one of the constants yielded in its two
  // branches.
  if (const_val_ != ret_vals.value().first &&
      const_val_ != ret_vals.value().second)
    return;

  // Replace the predicate of if_op by that of the parent IfOp
  // or its negation, as determined by the predicate of if_op.
  bool negate_parent_predicate = (const_val_ == ret_vals.value().second);

  LLVM_DEBUG(llvm::dbgs() << "Replace the predicate of the if op " << if_op_
                          << "\nwith the ");
  if (negate_parent_predicate) LLVM_DEBUG(llvm::dbgs() << "negation of the ");
  LLVM_DEBUG(llvm::dbgs() << "predicate of " << parent_if_op << "\n");

  if (negate_parent_predicate) {
    if_op_.setPredicate(
        dcc::utils::negatePredicate(parent_if_op.getPredicate()));
  } else {
    if_op_.setPredicate(parent_if_op.getPredicate());
  }

  if_op_.setOperand(0, parent_if_op.getOperand(0));
  if_op_.setOperand(1, parent_if_op.getOperand(1));

  if (StringAttr new_dbg_name = dataflow::utils::getNewDbgNameFromList(
          /*prefix*/ "RRC(", {parent_if_op, if_op_})) {
    setDbgNameAttr(if_op_, new_dbg_name);
  }
  // Remove the parent IfOp if it is dead.
  if (parent_if_op.use_empty()) to_be_deleted_.push_back(parent_if_op);
}

