// entry 467/656   level 2   scc 457   81 body lines
// unit: e467_replaceCorrelatedIterArgsInEquivClass
// authority: dcc/src/Transform/Sentient/ReuseLoopIteratorArguments.cpp:259
// original: void ReuseLoopIteratorArgumentsPass::replaceCorrelatedIterArgsInEquivClass( OpBuilder &const_builder, sentient::ForOp for_op, CorrelationAnalysisBase::CorrelatedEquivClassContainer *correlated_equiv_classes, const Liveness &liveness, bool check_users_liverange_conflicts)
// rust home: crates/compiler/deeptools/src/transform/sentient/reuse_loop_iterator_arguments/mod.rs
// ------------------------------------------------------------------------------------------------
void e467_replaceCorrelatedIterArgsInEquivClass(
    OpBuilder &const_builder, sentient::ForOp for_op,
    CorrelationAnalysisBase::CorrelatedEquivClassContainer
        *correlated_equiv_classes,
    const Liveness &liveness, bool check_users_liverange_conflicts)
{
  int n_iter_args = for_op.getNumRegionIterArgs();
  if (n_iter_args == 0) return;

  if (!correlated_equiv_classes || correlated_equiv_classes->isEmpty()) {
    return;
  }

  LLVM_DEBUG({
    llvm::dbgs() << "Analyze equivalence classes of iter args in the loop\n"
                 << for_op << "\n";
  });

  OpBuilder builder(for_op);
  builder.setInsertionPointToStart(for_op.getBody());

  // Collect valid replacements first, represented as
  // (iter_arg_to_replace, head_iter_arg, correlation)
  // NOTE: The areUsersLiverangesOverlapping check must be done before
  // any replacements are made as these introduce new AddOps which
  // should not be part of the check.
  llvm::SmallVector<std::tuple<BlockArgument, BlockArgument, int64_t>>
      replacements_to_perform;

  for (auto equiv_class :
       correlated_equiv_classes->getCorrelatedEquivClasses()) {
    auto head_iter_arg = equiv_class->getHeadInfo()->getIterArg();

    for (auto pair : equiv_class->getIterArgToCorrelation()) {
      auto correlated_iter_arg = pair.first;

      // Check for liverange conflicts if requested
      if (check_users_liverange_conflicts &&
          areUsersLiverangesOverlapping(head_iter_arg, correlated_iter_arg,
                                        liveness)) {
        LLVM_DEBUG({
          llvm::dbgs() << "Skipping replacement of " << correlated_iter_arg
                       << " with " << head_iter_arg
                       << " due to liverange conflicts\n";
        });
        continue;
      }

      replacements_to_perform.push_back(
          std::make_tuple(correlated_iter_arg, head_iter_arg, pair.second));
    }
  }

  // Perform all replacements
  for (const auto &replacement : replacements_to_perform) {
    auto iter_arg_to_replace = std::get<0>(replacement);
    auto head_iter_arg = std::get<1>(replacement);
    auto correlation_value = std::get<2>(replacement);

    LLVM_DEBUG({
      llvm::dbgs() << "Replace " << iter_arg_to_replace << " with "
                   << head_iter_arg << " plus an offset of "
                   << correlation_value << "\n";
    });

    auto correlation = sentient::ConstantOp::create(
        const_builder, for_op->getLoc(), iter_arg_to_replace.getType(),
        correlation_value);
    auto iter_arg_replacement = sentient::AddOp::create(
        builder, for_op->getLoc(), iter_arg_to_replace.getType(), head_iter_arg,
        correlation);

    // Copy attributes from iter_arg_to_replace if needed
    auto locales = for_op.getRegLocalesAttr();
    auto element_sizes = for_op->getAttr("element_sizes");
    if (locales && element_sizes) {
      int correlated_idx = iter_arg_to_replace.getArgNumber();
      iter_arg_replacement->setAttr("regLocale", locales[correlated_idx + 1]);
      iter_arg_replacement->setAttr(
          "element_size",
          mlir::cast<ArrayAttr>(element_sizes)[correlated_idx + 1]);
    }

    iter_arg_to_replace.replaceAllUsesWith(iter_arg_replacement.getResult());
  }
}

