// entry 468/656   level 2   scc 493   58 body lines
// unit: e468_processMergeableChain
// authority: dcc/src/Transform/Sentient/ScalarOpMergingAndHoisting.cpp:1645
// original: bool ScalarOpHoisting::processMergeableChain( Operation *input_to_chain, Operation *first_op_in_chain, const EvaluatedValue &merging_increment, SmallVector<OperationData> &ops_to_update)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_hoisting.rs
// ------------------------------------------------------------------------------------------------
bool e468_processMergeableChain(
    Operation *input_to_chain, Operation *first_op_in_chain,
    const EvaluatedValue &merging_increment,
    SmallVector<OperationData> &ops_to_update)
{
  // Checks if the new immutable address would exceed the IMM or LRF ranges.
  auto checkImmutableRange = [&](Operation *op, Value immutable_addr,
                                 int element_size) -> bool {
    const EvaluatedValue *immutable_addr_ev =
        &getEvaluator().evaluateValue(immutable_addr);
    const EvaluatedValue &new_immutable_ev =
        getEvaluator().evaluateSum(*immutable_addr_ev, merging_increment);

    if (!opt_context_.isImmutableValueInRange(
            new_immutable_ev, *immutable_addr_ev, element_size, op)) {
      return false;
    }

    ops_to_update.push_back(
        {op, &merging_increment, &getEvaluator().getConstant(0)});
    return true;
  };

  Operation *op = first_op_in_chain;
  while (op) {
    if (isa<sentient::AddOp, sentient::SubOp>(op)) {
      // TODO: Extend check to support other units and reg types.
      if (is_any_of(getComp(), LXLU, LXSU, L0LU, L0SU)) {
        DT_CHECK(op->hasAttr("element_size"));
        int element_size =
            mlir::cast<mlir::IntegerAttr>(op->getAttr("element_size")).getInt();
        if (doesValueExceedLRFRange(getDccExtContext().dsc_global_->sysDef,
                                    merging_increment, element_size, getComp(),
                                    getScale())) {
          LLVM_DEBUG(
              llvm::dbgs()
              << "[ScalarOpHoisting] Op not a mergeable chain candidate due to "
                 "immutable being pushed out of LRF range :\n"
              << *op << "\n\n");
          return false;
        }
      }
      ops_to_update.push_back(
          {op, &merging_increment, &getEvaluator().getConstant(0)});
      return true;
    } else if (isa<sentient::LoadAndSendOp, sentient::ReceiveAndStoreOp,
                   sentient::LoadComputeAndSendOp>(op)) {
      if (!is_any_of(getComp(), LXLU, LXSU, L0LU, L0SU)) return false;
      MemoryOpInfo mem_info(op);
      if (!checkImmutableRange(op, mem_info.immutable_addr_,
                               mem_info.element_size_))
        return false;

      if (dcc::utils::isUpdateMode(op)) return true;

      op = *op->getUsers().begin();
    } else {
      return true;
    }
  }
  return true;
}

