// entry 469/656   level 2   scc 502   29 body lines
// unit: e469_hoistForLinearChain
// authority: dcc/src/Transform/Sentient/ScalarOpMergingAndHoisting.cpp:2034
// original: void ScalarOpHoisting::hoistForLinearChain( BlockArgument &main_iv, Operation *derived_iv, SmallVector<OperationData> &comp_ops)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_hoisting.rs
// ------------------------------------------------------------------------------------------------
void e469_hoistForLinearChain(
    BlockArgument &main_iv, Operation *derived_iv,
    SmallVector<OperationData> &comp_ops)
{
  int const_operand_idx = dcc::utils::getFirstConstOperandIndex(derived_iv);
  Value derived_iv_operand = derived_iv->getOperand(const_operand_idx);

  // When the derived_iv is hoisted in this form, the first composite
  // load/store in the chain swaps its immutable_addr with the derived_iv
  // increment. The increment attribute of the composite load/store is updated
  // appropriately. This allows the comp op to absorb the scalar op for each
  // iteration of the loop. The add will be updated at hoisting once
  // hoistCandidateOutOfLoop() is called.
  Operation *first_op = comp_ops.front().getOp();
  Value first_op_immutable_addr;
  if (auto las = dyn_cast<sentient::LoadAndSendOp>(first_op)) {
    first_op_immutable_addr = las.getImmutableAddr();
    las.getIncrementMutable().assign(derived_iv_operand);
  } else if (auto ras = dyn_cast<sentient::ReceiveAndStoreOp>(first_op)) {
    first_op_immutable_addr = ras.getImmutableAddr();
    ras.getIncrementMutable().assign(derived_iv_operand);
  } else if (auto lcas = dyn_cast<sentient::LoadComputeAndSendOp>(first_op)) {
    first_op_immutable_addr = lcas.getImmutableAddr();
    lcas.getIncrementMutable().assign(derived_iv_operand);
  } else {
    llvm_unreachable("Unexpected operation found!");
  }

  applyOperationData(comp_ops);

  hoistCandidateOutOfLoop(main_iv, derived_iv, first_op_immutable_addr);
}

