// entry 470/656   level 2   scc 518   67 body lines
// unit: e470_isCandidateForReordering
// authority: dcc/src/Transform/Sentient/ScalarOpReordering.cpp:462
// original: bool ScalarOpReorderingPass::isCandidateForReordering(Operation &op)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_reordering/mod.rs
// ------------------------------------------------------------------------------------------------
bool e470_isCandidateForReordering(Operation &op)
{
  if (!isa<sentient::CopyOp, sentient::AddOp, sentient::SubOp,
           dataflow::CreateMulticastGroupOp>(op)) {
    // Not a scalar op.
    return false;
  }
  DT_CHECK_MSG(op.getNumResults() == 1,
               "Scalar ops expected to have one result");
  Value result = op.getResult(0);
  Operation *op_first_use = getFirstUseWithinBlock(result);
  // Scalar ops with no uses are dead and should not be moved.
  if (!op_first_use) return false;

  // If op is already immediately before its first use, no further movement
  // is possible.
  if (Operation *next_op = op.getNextNode()) {
    for (auto operand : next_op->getOperands())
      if (operand == result) return false;
  }

  // Queue the non-constant operands of this scalar op.
  llvm::SmallVector<Value> non_const_operands;
  if (auto copy_op = llvm::dyn_cast<sentient::CopyOp>(op)) {
    if (!dcc::utils::isConstant<sentient::ConstantOp>(copy_op.getInp()))
      non_const_operands.push_back(copy_op.getInp());
  } else if (auto add_op = llvm::dyn_cast<sentient::AddOp>(op)) {
    if (!dcc::utils::isConstant<sentient::ConstantOp>(add_op.getInp1()))
      non_const_operands.push_back(add_op.getInp1());
    if (!dcc::utils::isConstant<sentient::ConstantOp>(add_op.getInp2()))
      non_const_operands.push_back(add_op.getInp2());
  } else if (auto sub_op = llvm::dyn_cast<sentient::SubOp>(op)) {
    if (!dcc::utils::isConstant<sentient::ConstantOp>(sub_op.getInp1()))
      non_const_operands.push_back(sub_op.getInp1());
    if (!dcc::utils::isConstant<sentient::ConstantOp>(sub_op.getInp2()))
      non_const_operands.push_back(sub_op.getInp2());
  }

  // If op only has constant operands then it is a candidate.
  if (non_const_operands.empty()) return true;

  // If the ancestor of the scalar op's first use within the block does not
  // dominate the ancestor of one operand's last use within the block then
  // moving the scalar op would extend the live range of that operand.
  // E.g.
  // %c1 = sentient.scalar_constant {value = 1 : si64} : index
  // for %arg0 = %c2 iter_args(%arg1 = %c0) {
  //   %0 = ...
  //   %1 = scalar_add %0, %c1
  //   ...
  //   load %1 ... // first use of %1
  //   yield %1
  // }
  // If %0 has no uses besides %1 (or all its uses occur before the load),
  // then moving %1 to right before the load would extend the live range of
  // %0.
  // We only allow iteration arguments' live ranges to be extended this way.

  Block *op_block = op.getBlock();
  for (auto v : non_const_operands) {
    if (!isa<BlockArgument>(v)) {
      Operation *operand_last_use = getLastUseWithinBlock(v, op_block);
      DT_CHECK_MSG(operand_last_use, "Op itself is a use of its operands");
      if (!dom_info_->dominates(op_first_use, operand_last_use)) return false;
    }
  }
  return true;
}

