// authority: dcc/src/Transform/Sentient/ScalarSimplifications.cpp:194
// original: void ScalarSimplificationsPass::simplifyConditionals( PropagationAnalysis& expr_prop_analysis, sentient::IfOp& if_op, OpBuilder& const_builder)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_simplifications/mod.rs
// ------------------------------------------------------------------------------------------------
void e471_simplifyConditionals(
    PropagationAnalysis& expr_prop_analysis, sentient::IfOp& if_op,
    OpBuilder& const_builder)
{
  PropagationAnalysis::ExprInfoMap* lhs_info =
      expr_prop_analysis.getAffineExpression(if_op.getLhs());
  PropagationAnalysis::ExprInfoMap* rhs_info =
      expr_prop_analysis.getAffineExpression(if_op.getRhs());

  // This situation can arise when other simplifications happened before
  // can stale the expr_prop_analysis or may not have information about
  // new operand created as part of the simplification
  if (lhs_info->empty() || rhs_info->empty()) return;

  // currently, uniformization only supports single DSC, so loop bound is always
  // constant and conditionals for all units should be the same.

  //  if (lhs_info->cannot_be_resolved_ || rhs_info->cannot_be_resolved_)
  //  return;

  // Create the affine expression subtracting the lhs and rhs expr.
  SmallVector<int64_t, 8> flat_expr;
  affine::FlatAffineValueConstraints local_vars_constraints;
  AffineExpr expr;

  // Set dimension values to the constraints
  SmallVector<Value, 4> all_args;

  PropagationAnalysis::ExprInfo* lhs_expr_info0 = lhs_info->getFirstExprInfo();
  PropagationAnalysis::ExprInfo* rhs_expr_info0 = rhs_info->getFirstExprInfo();
  if (if_op.getPredicate() == CmpIPredicate::sge ||
      if_op.getPredicate() == CmpIPredicate::eq) {
    expr = lhs_expr_info0->propagated_map_.getResult(0) -
           rhs_expr_info0->propagated_map_.getResult(0);
    all_args.append(lhs_expr_info0->propagated_args_);
    all_args.append(rhs_expr_info0->propagated_args_);
  } else if (if_op.getPredicate() == CmpIPredicate::sle) {
    expr = rhs_expr_info0->propagated_map_.getResult(0) -
           lhs_expr_info0->propagated_map_.getResult(0);
    all_args.append(rhs_expr_info0->propagated_args_);
    all_args.append(lhs_expr_info0->propagated_args_);
  } else if (if_op.getPredicate() == CmpIPredicate::sgt) {
    expr = lhs_expr_info0->propagated_map_.getResult(0) -
           rhs_expr_info0->propagated_map_.getResult(0) - 1;
    all_args.append(lhs_expr_info0->propagated_args_);
    all_args.append(rhs_expr_info0->propagated_args_);
  } else if (if_op.getPredicate() == CmpIPredicate::slt) {
    expr = rhs_expr_info0->propagated_map_.getResult(0) -
           lhs_expr_info0->propagated_map_.getResult(0) - 1;
    all_args.append(rhs_expr_info0->propagated_args_);
    all_args.append(lhs_expr_info0->propagated_args_);
  } else if (if_op.getPredicate() == CmpIPredicate::ne) {
    expr = lhs_expr_info0->propagated_map_.getResult(0) -
           rhs_expr_info0->propagated_map_.getResult(0);
    all_args.append(lhs_expr_info0->propagated_args_);
    all_args.append(rhs_expr_info0->propagated_args_);
  } else {
    return;
  }

  // Flatten the (lhs-rhs) expression
  if (!failed(getFlattenedAffineExpr(expr, all_args.size(), 0, &flat_expr,
                                     &local_vars_constraints))) {
    // Currently, MLIR doesn't have support to construct local variables
    // without explicit representation.
    if (local_vars_constraints.getNumLocalVars() > 0) {
      return;
    }

    // Create a set of constraints to solve for
    affine::FlatAffineValueConstraints constraints(
        2, all_args.size(), all_args.size() + 1, all_args.size(), 0, 0,
        all_args);

    constraints.setValues(0, all_args.size(), all_args);

    // Add basic constraint coming from the if_condition.
    if (is_any_of(if_op.getPredicate(), CmpIPredicate::eq, CmpIPredicate::ne)) {
      constraints.addEquality(flat_expr);
    } else {
      constraints.addInequality(flat_expr);
    }

    // Add constraints coming from the same propagated variables on the lhs
    //  and rhs of the if condition.
    // TODO: check if the lhs, rhs pair is part of the constraint
    // if not, no point in adding to the constraints
    // By disabling this, we might lose opportunities for simplification.
    // PC: I don't think we encounter them yet.
    /*
    for (int i = 0; i < lhs_expr_info0->propagated_args_.size(); i++) {
      auto lhs = lhs_expr_info0->propagated_args_[i];
      for (int j = 0; i < rhs_expr_info0->propagated_args_.size(); i++) {
        auto rhs = rhs_expr_info0->propagated_args_[j];
        if (lhs == rhs) {
          affine::FlatAffineValueConstraints local_constraint(
              0, 1, all_args.size() + 1, all_args.size(), 0, 0, all_args);
          local_constraint.setValues(0, all_args.size(), all_args);
          local_constraint.addBound(mlir::presburger::BoundType::EQ, i, 1);
          local_constraint.addBound(mlir::presburger::BoundType::EQ, j, -1);
          constraints.append(local_constraint);
        }
      }
    } */

    // Simplify the constraints!
    constraints.removeRedundantConstraints();
    constraints.removeRedundantInequalities();
    constraints.removeTrivialRedundancy();

    if (constraints.getNumConstraints() > 1)
      return;
    else if (constraints.getNumConstraints() == 1) {
      // Transform the if_op
      OpBuilder builder(if_op);
      transformIfCondition(if_op, const_builder, constraints);
    } else {
      if_op->emitRemark("Opportunities to remove branch\n");
    }
  }
}

