// entry 472/656   level 2   scc 196   63 body lines
// unit: e472_createNewOpOrMap
// authority: dcc/src/Transform/Sentient/ScalarSimplifications.cpp:769
// original: Value sentient::createNewOpOrMap(OpBuilder& builder, std::vector<FlatExprType>& flat_exprs, SmallVector<unsigned>& indices, PropagationAnalysis& expr_prop_analysis, SmallVector<Value>& units, Operation* op, Type operand_type, Value query_key, PropagationAnalysis::ExprInfoMap* result_info, unsigned operand_idx)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_simplifications/sentient.rs
// ------------------------------------------------------------------------------------------------
Value e472_createNewOpOrMap(OpBuilder& builder,
                                 std::vector<FlatExprType>& flat_exprs,
                                 SmallVector<unsigned>& indices,
                                 PropagationAnalysis& expr_prop_analysis,
                                 SmallVector<Value>& units, Operation* op,
                                 Type operand_type, Value query_key,
                                 PropagationAnalysis::ExprInfoMap* result_info,
                                 unsigned operand_idx)
{
  unsigned num_flat_exprs = flat_exprs.size();
  auto& first_flat_expr = flat_exprs[0][0];
  unsigned first_flat_expr_size = first_flat_expr.size();

  // non-uniformization case or ExprInfos of all units are the identical.
  if (num_flat_exprs == 1 ||
      areFlatExprsAndArgsIdentical(flat_exprs, indices, result_info,
                                   operand_idx)) {
    if (first_flat_expr_size == 1) {
      return sentient::ConstantOp::create(builder, op->getLoc(), operand_type,
                                          first_flat_expr[0])
          .getOut();
    } else if (first_flat_expr_size == 3) {
      return result_info->getFirstExprInfo()->propagated_args_[operand_idx];
    } else if (first_flat_expr_size == 2) {
      if (operand_idx == 1) {
        return sentient::ConstantOp::create(builder, op->getLoc(), operand_type,
                                            first_flat_expr[operand_idx])
            .getOut();
      }
      return result_info->getFirstExprInfo()->propagated_args_[operand_idx];
    }
  }
  // create immutableMapOp and queryOp
  auto saved_insertion_pt = builder.saveInsertionPoint();
  builder.setInsertionPoint(op);
  SmallVector<Value> values;

  DT_CHECK_MSG(units.size() == num_flat_exprs,
               "Expecting a flattened expression for each unit");
  for (unsigned unit_idx = 0; unit_idx < units.size(); ++unit_idx) {
    unsigned expr_info_idx = indices[unit_idx];
    FlatExprType& cur_flat_expr = flat_exprs[unit_idx];

    if (first_flat_expr_size == 1) {
      auto const_op = sentient::ConstantOp::create(
          builder, op->getLoc(), operand_type, cur_flat_expr[0][0]);
      values.push_back(const_op.getOut());
    } else if (first_flat_expr_size == 3) {
      values.push_back(result_info->getExprInfoAt(expr_info_idx)
                           ->propagated_args_[operand_idx]);
    } else if (first_flat_expr_size == 2) {
      if (operand_idx == 1) {
        auto const_op = sentient::ConstantOp::create(
            builder, op->getLoc(), operand_type, cur_flat_expr[0][operand_idx]);
        values.push_back(const_op.getOut());
      } else {
        values.push_back(result_info->getExprInfoAt(expr_info_idx)
                             ->propagated_args_[operand_idx]);
      }
    }
  }
  auto map_op = uniform::DefImmutableMappingOp::create(
      builder, op->getLoc(), builder.getIndexType(), units, values);

  auto query_op = uniform::QueryMapOp::create(
      builder, op->getLoc(), builder.getIndexType(), map_op, query_key);

  // reset insertion point
  builder.restoreInsertionPoint(saved_insertion_pt);
  return query_op.getResult();
}

