// original: void runOn(sentient::CopyOp copy_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/sink_scalar_copy/mod.rs
// ------------------------------------------------------------------------------------------------
void e477_runOn(sentient::CopyOp copy_op)
{
    if (!isa<dataflow::ProgramUnitOp>(
            dcc::uniform::utils::getRegionOp(copy_op))) {
      LLVM_DEBUG(llvm::dbgs()
                 << "skipping copy_op because it's not in a global region: "
                 << copy_op << "\n");
      return;
    }
    auto use_info = new UsesInfo(copy_op);
    uses_info_list_.push_back(use_info);
    for (Operation *user : copy_op->getUsers()) {
      Operation *owner_of_region = nullptr;
      int region_index = -1;
      std::tie(owner_of_region, region_index) =
          dcc::uniform::utils::getRegionOpAndIndex(user);
      DT_CHECK((isa<dataflow::ProgramUnitOp, uniform::UniformizeRegionsOp,
                    uniform::EqualizePatternOp>(owner_of_region)) &&
               "copy_op is not owned by an expected region");
      use_info->addRegion(&owner_of_region->getRegions()[region_index]);
    }
    LLVM_DEBUG({
      llvm::dbgs() << "uses info collected:\n";
      use_info->dump(llvm::dbgs(), 1);
    });
  }

