// entry 480/656   level 2   scc 598   119 body lines
// unit: e480_FuseStoreAndForward
// authority: dcc/src/Transform/Sentient/StoreAndForwardFusion.cpp:434
// original: LogicalResult StoreAndForwardFusionPass::FuseStoreAndForward( mlir::Operation *op, std::vector<mlir::Operation *> &to_be_deleted)
// rust home: crates/compiler/deeptools/src/transform/sentient/store_and_forward_fusion/mod.rs
// ------------------------------------------------------------------------------------------------
LogicalResult e480_FuseStoreAndForward(
    mlir::Operation *op, std::vector<mlir::Operation *> &to_be_deleted)
{
  std::pair<bool, bool> trivialOps = {false, false};
  std::pair<mlir::ArrayAttr, mlir::ArrayAttr> opA_forwardings, opB_forwardings,
      opC_forwardings, result_forwardings;
  SentientPrecision trivial_op_result_precision, fusible_op_result_precision;

  bool fold_AB_mode = false;
  auto op_A_fold = dcc::utils::getFoldModeAttributeIfExists(op);
  auto op_B_fold = dcc::utils::getFoldModeAttributeIfExists(op->getNextNode());
  if (op_A_fold.has_value() && op_B_fold.has_value() &&
      op_A_fold.value() == SentientFoldMode::fold_AB_A &&
      op_B_fold.value() == SentientFoldMode::fold_AB_B) {
    fold_AB_mode = true;
  }
  if (op_A_fold.has_value() && op_A_fold.value() == SentientFoldMode::fold_AB_B)
    return LogicalResult::failure();

  trivialOps.first = fillOperandForTrivialOp(
      op, opA_forwardings.first, opB_forwardings.first, opC_forwardings.first,
      result_forwardings.first, trivial_op_result_precision);
  if (!trivialOps.first) return LogicalResult::failure();
  if (fold_AB_mode) {
    trivialOps.second = fillOperandForTrivialOp(
        op, opA_forwardings.second, opB_forwardings.second,
        opC_forwardings.second, result_forwardings.second,
        trivial_op_result_precision);
    if (!trivialOps.second) return LogicalResult::failure();
  }

  std::pair<mlir::Operation *, mlir::Operation *> fusible_ops;
  fusible_ops.first = findFusibleOp(op, to_be_deleted, fold_AB_mode);
  if (fusible_ops.first == op) return LogicalResult::failure();
  if (fold_AB_mode) {
    fusible_ops.second = findFusibleOp(op->getNextNode(), to_be_deleted,
                                       /* fold_AB_mode = */ true);
    if (fusible_ops.second == op) return LogicalResult::failure();
  }

  std::pair<mlir::ArrayAttr, mlir::ArrayAttr> opA_forwardings_fusible,
      opB_forwardings_fusible, opC_forwardings_fusible,
      result_forwardings_fusible;

  if (fillOperandForFusibleOp(
          fusible_ops.first, opA_forwardings_fusible.first,
          opB_forwardings_fusible.first, opC_forwardings_fusible.first,
          result_forwardings_fusible.first, fusible_op_result_precision)
          .failed())
    return LogicalResult::failure();

  if (fold_AB_mode &&
      fillOperandForFusibleOp(
          fusible_ops.second, opA_forwardings_fusible.second,
          opB_forwardings_fusible.second, opC_forwardings_fusible.second,
          result_forwardings_fusible.second, fusible_op_result_precision)
          .failed())
    return LogicalResult::failure();

  if (fusible_op_result_precision != trivial_op_result_precision)
    return LogicalResult::failure();

  std::pair<std::vector<mlir::Attribute>, std::vector<mlir::Attribute>>
      value_forwardings_for_fusibles, value_forwardings_for_trivials;

  appendValueForwarding(
      value_forwardings_for_fusibles.first, opA_forwardings_fusible.first,
      opB_forwardings_fusible.first, opC_forwardings_fusible.first,
      result_forwardings_fusible.first);
  appendValueForwarding(value_forwardings_for_trivials.first,
                        opA_forwardings.first, opB_forwardings.first,
                        opC_forwardings.first, result_forwardings.first);
  if (fold_AB_mode) {
    appendValueForwarding(
        value_forwardings_for_fusibles.second, opA_forwardings_fusible.second,
        opB_forwardings_fusible.second, opC_forwardings_fusible.second,
        result_forwardings_fusible.second);
    appendValueForwarding(value_forwardings_for_trivials.second,
                          opA_forwardings.second, opB_forwardings.second,
                          opC_forwardings.second, result_forwardings.second);
  }

  if (!isEligibleToFuse(value_forwardings_for_trivials.first,
                        value_forwardings_for_fusibles.first, op,
                        fusible_ops.first))
    return LogicalResult::failure();

  if (fold_AB_mode && !isEligibleToFuse(value_forwardings_for_trivials.second,
                                        value_forwardings_for_fusibles.second,
                                        op->getNextNode(), fusible_ops.second))
    return LogicalResult::failure();

  appendToVector(value_forwardings_for_trivials.first,
                 result_forwardings_fusible.first);
  if (fold_AB_mode)
    appendToVector(value_forwardings_for_trivials.second,
                   result_forwardings_fusible.second);

  if (updateFusibleOp(fusible_ops.first, value_forwardings_for_trivials.first)
          .failed())
    return LogicalResult::failure();

  if (fold_AB_mode &&
      updateFusibleOp(fusible_ops.second, value_forwardings_for_trivials.second)
          .failed())
    return LogicalResult::failure();

  if (StringAttr new_dbg_name = dataflow::utils::getNewDbgNameFromList(
          /*prefix*/ "SAFF(", {fusible_ops.first, op})) {
    setDbgNameAttr(fusible_ops.first, new_dbg_name);
  }

  to_be_deleted.push_back(op);
  if (fold_AB_mode) to_be_deleted.push_back(op->getNextNode());

  std::sort(to_be_deleted.begin(), to_be_deleted.end());
  auto duplicates = std::unique(to_be_deleted.begin(), to_be_deleted.end());
  to_be_deleted.erase(duplicates, to_be_deleted.end());

  return LogicalResult::success();
}

