// original: int AddressPinningAndTogglePass::computeOrGetNumberOfStreams()
// rust home: crates/compiler/deeptools/src/transform/sentient/address_pinning_and_toggle/mod.rs
// ------------------------------------------------------------------------------------------------
int e488_computeOrGetNumberOfStreams()
{
  // No need to recompute if already computed.
  if (num_streams_ >= 0) return num_streams_;
  llvm::SmallSet<const EvaluatedValue *, 4> set_of_streams;
  for (const DataTransferDescriptor *dtd : immut_data_transfer_descriptors_)
    for (const EvaluatedValue *ev : dtd->getBaseAddrList())
      set_of_streams.insert(ev);
  num_streams_ = set_of_streams.size();
  return num_streams_;
}

