// rust home: crates/compiler/deeptools/src/transform/sentient/address_pinning_and_toggle/integer_sequence_data_transfer_updater.rs
// ------------------------------------------------------------------------------------------------
void e490_updateVariableOffsetCalculation(
    const EvaluatedValue &new_immut_addr_ev)
{
  // Now that we've picked the pinned base addr, adjust the initializer of the
  // iter-arg responsible for the integer sequence.
  IntegerSequenceDescriptor &isq = dtd_.getIntegerSequenceDescriptor();
  // new_init = init - new_immut_addr_ev
  const EvaluatedValue &new_init =
      evaluator_.evaluateSub(isq.getInit(), new_immut_addr_ev);
  isq.getOuterLoop().setIterOperand(
      isq.getIterArgIndex(), createOffsetValue(&dtd_.getOperation(), new_init));
}

