// original: void IntegerSequenceDescriptor::dump() const
// rust home: crates/compiler/deeptools/src/transform/sentient/address_pinning_and_toggle/integer_sequence_descriptor.rs
// ------------------------------------------------------------------------------------------------
void e493_dump() const
{
  raw_ostream &os = llvm::dbgs();
  os << "Constant Integer Sequence Descriptor:\n";
  const char indent = '\t';
  if (!isValid()) {
    os << indent << "Invalid\n";
    return;
  }
  if (canBeSimplified()) os << indent << "(Simplified)\n";
  os << indent << "init:" << *init_ << ";\n " << indent << "stride:" << *stride_
     << ";\n"
     << indent << "size:" << size_ << "\n";
  BaseAddrListTy constants;
  getAllConstants(constants);
  os << indent << "Constants (" << constants.size() << ") [\n";
  llvm::interleave(
      constants, os, [&](const EvaluatedValue *ev) { os << indent << *ev; },
      ";\n");
  os << indent << "]\n";
}

