// original: void EnhancedDeadVariableEliminationPass::updateForOperation( ForOp &for_op, std::set<int> deleted_pos)
// rust home: crates/compiler/deeptools/src/transform/sentient/enhanced_dead_variable_elimination/mod.rs
// ------------------------------------------------------------------------------------------------
void e498_updateForOperation(
    ForOp &for_op, std::set<int> deleted_pos)
{
  bool delete_pos_provided = !deleted_pos.empty();
  llvm::SmallVector<int, 8> reg_indices;
  llvm::SmallVector<bool, 8> program_header;
  llvm::SmallVector<Value, 8> init_args;
  llvm::SmallVector<Attribute, 8> reg_locales;
  llvm::SmallVector<Attribute, 8> elem_sizes;
  llvm::SmallVector<int, 8> iter_arg_indices_left;
  int num_results = for_op.getNumResults();
  auto prev_elem_sizes = for_op->getAttr("element_sizes");
  // Does the ForOp already have regLocales assigned for both
  // iter args and results?
  bool locales_for_iter_args_and_results =
      (for_op.getRegLocales().size() == 1 + 2 * num_results);
  if (locales_for_iter_args_and_results) {
    // Attributes for induction variable
    if (!for_op.getRegIndices().empty()) {
      reg_indices.push_back(
          mlir::cast<IntegerAttr>(for_op.getRegIndices()[0]).getInt());
    }
    if (!for_op.getRegLocales().empty()) {
      reg_locales.push_back(
          mlir::cast<SentientRegTypeAttr>(for_op.getRegLocales()[0]));
    }
    if (prev_elem_sizes && !mlir::cast<ArrayAttr>(prev_elem_sizes).empty()) {
      elem_sizes.push_back(mlir::cast<ArrayAttr>(prev_elem_sizes)[0]);
    }
  }

  // Exclude the last operand (because it is induction variable)
  for (int i = 0; i < num_results; i++) {
    // Condition to remove one of the results
    // result not used and corresponding iter_arg doesn't have influence or
    // the result is in the provided deleted_pos list.
    auto iter_arg = for_op.getRegionIterArgs()[i];
    if (getInfluenceType(for_op.getResult(i)) == kNone &&
        getInfluenceType(iter_arg) == kNone && !delete_pos_provided) {
      deleted_pos.insert(i);
    } else if (!delete_pos_provided ||
               deleted_pos.find(i) == deleted_pos.end()) {
      auto iter_operand = for_op.getIterOperands()[i];
      init_args.push_back(iter_operand);
      iter_arg_indices_left.push_back(i);

      if (!for_op.getProgramHeader().empty()) {
        program_header.push_back(
            mlir::cast<BoolAttr>(for_op.getProgramHeader()[i]).getValue());
      }
    }
  }

  // If locales_for_iter_args_and_results is true, each iter arg #i corresponds
  // to two regIndices, regLocales and element_sizes at indices i+1 and
  // i+1+num_results. Otherwise, each iter arg corresponds to one of each.
  for (int offset = 0; offset <= num_results; offset += num_results) {
    for (int i : iter_arg_indices_left) {
      if (!for_op.getRegIndices().empty()) {
        if (locales_for_iter_args_and_results) {
          reg_indices.push_back(
              mlir::cast<IntegerAttr>(for_op.getRegIndices()[i + 1 + offset])
                  .getInt());
        } else {
          reg_indices.push_back(
              mlir::cast<IntegerAttr>(for_op.getRegIndices()[i]).getInt());
        }
      }

      if (!for_op.getRegLocales().empty()) {
        if (locales_for_iter_args_and_results) {
          reg_locales.push_back(mlir::cast<SentientRegTypeAttr>(
              for_op.getRegLocales()[i + 1 + offset]));
        } else {
          reg_locales.push_back(
              mlir::cast<SentientRegTypeAttr>(for_op.getRegLocales()[i]));
        }
      }

      if (prev_elem_sizes && !mlir::cast<ArrayAttr>(prev_elem_sizes).empty()) {
        if (locales_for_iter_args_and_results) {
          elem_sizes.push_back(
              mlir::cast<ArrayAttr>(prev_elem_sizes)[i + 1 + offset]);
        } else {
          elem_sizes.push_back(mlir::cast<ArrayAttr>(prev_elem_sizes)[i]);
        }
      }
    }
    if (!locales_for_iter_args_and_results) break;
  }

  // If there are no arguments to delete, return;
  if (deleted_pos.empty()) {
    return;
  }

  // Create a new for-op because number of results are changing
  OpBuilder builder(for_op);
  auto orig_dbg_name = getDbgNameAttr(for_op);
  auto new_for_op =
      ForOp::create(builder, for_op.getLoc(), for_op.getBound(), orig_dbg_name,
                    ArrayAttr::get(builder.getContext(), reg_locales),
                    llvm::ArrayRef<int>(reg_indices),
                    llvm::ArrayRef<bool>(program_header), init_args);
  if (prev_elem_sizes)
    new_for_op->setAttr("element_sizes",
                        ArrayAttr::get(builder.getContext(), elem_sizes));
  // create block corresponding to loop body
  IRMapping bv_map;
  auto *block = new Block();
  auto iv =
      block->addArgument(for_op.getInductionVar().getType(),
                         for_op.getInductionVar().getLoc());  // adding iv type
  bv_map.map(for_op.getInductionVar(), iv);

  // Adjust return value
  int result_count = 0;
  for (int i = 0; i < num_results; i++) {
    if (deleted_pos.find(i) == deleted_pos.end()) {
      for_op.getResult(i).replaceAllUsesWith(
          new_for_op.getResult(result_count));
      auto arg = block->addArgument(for_op.getResult(i).getType(),
                                    for_op.getResult(i).getLoc());
      bv_map.map(for_op.getRegionIterArgs()[i], arg);
      result_count++;
    } else {
      DT_CHECK_MSG(
          for_op.getResult(i).use_empty(),
          "The loop's results at the indices to be deleted should have no "
          "uses.");
    }
  }

  // clone the body
  new_for_op.getLoopBody().push_back(block);
  builder.setInsertionPointToStart(new_for_op.getBody());
  for (auto &it : for_op.getBody()->getOperations()) {
    builder.clone(it, bv_map);
  }

  // delete the old for-loop
  for_op.erase();
}

