// unit: e503_mapAllValues
// authority: dcc/src/Transform/Sentient/LiveRangeReduction.cpp:827
// original: void LiveRangeReductionPass::mapAllValues(PropagationAnalysis& expr_prop, Operation* unit_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/live_range_reduction/mod.rs
// ------------------------------------------------------------------------------------------------
void e503_mapAllValues(PropagationAnalysis& expr_prop,
                                          Operation* unit_op)
{
  // copy unit_name_index_map from expression propagation
  unit_name_to_index_map = expr_prop.getUnitIndexMap();
  unit_op->walk<WalkOrder::PreOrder>([&](Operation* op) {
    if (auto for_op = dyn_cast<sentient::ForOp>(op)) {
      auto iter_args_list = for_op.getRegionIterArgs();
      // scan iter_args in reserve order to preferably shorten the liveRange of
      // the first iter_arg. This is beneficial for kernel block loading case
      // where the first iter_arg is used first.
      for (auto iter_val = iter_args_list.rbegin();
           iter_val != iter_args_list.rend(); iter_val++) {
        addToMap(expr_prop, *iter_val);
      }
      // map constant operands. this is specially needed to optimize 8 blocks of
      // kernel block loading which have constant starting addresses (such as in
      // resnet conv4)
      for (auto operand : for_op.getOperands()) {
        if (isConstant<sentient::ConstantOp>(operand))
          addToMap(expr_prop, operand);
      }
    } else if (isa<sentient::YieldOp>(op)) {
      auto for_op = dyn_cast<sentient::ForOp>(op->getParentOp());
      if (for_op) {
        for (auto result : for_op.getResults()) {
          addToMap(expr_prop, result);
        }
      }
    } else if (isa<sentient::AddOp, sentient::SubOp,
                   sentient::ReceiveAndStoreOp, sentient::LoadAndSendOp,
                   sentient::LoadAndStoreOp, sentient::LoadAndExtractScalarOp,
                   sentient::LoadComputeAndSendOp>(op)) {
      SmallVector<Value> list = {op->getResults().begin(),
                                 op->getResults().end()};
      // scan reversely for the same reason described above.
      for (auto result = list.rbegin(); result != list.rend(); result++) {
        addToMap(expr_prop, *result);
      }
    } else if (isa<uniform::YieldOp>(op)) {
      auto uniformize_op =
          dyn_cast<uniform::UniformizeRegionsOp>(op->getParentOp());
      if (uniformize_op) {
        for (auto result : uniformize_op.getResults()) {
          addToMap(expr_prop, result);
        }
      }
    }
  });
}

