// unit: e504_optimizeUniformRegionYieldedValues
// authority: dcc/src/Transform/Sentient/LiveRangeReduction.cpp:1167
// original: void LiveRangeReductionPass::optimizeUniformRegionYieldedValues( ModuleOp module_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/live_range_reduction/mod.rs
// ------------------------------------------------------------------------------------------------
void e504_optimizeUniformRegionYieldedValues(
    ModuleOp module_op)
{
  SmallVector<Operation*> ops_to_be_delected;
  module_op.walk<WalkOrder::PreOrder>([&](Operation* op) {
    if (auto uniformize_op = dyn_cast<uniform::UniformizeRegionsOp>(op)) {
      auto num_regions = uniformize_op.getNumRegions();
      if (num_regions == 1) {
        for (int region_num = 0; region_num < num_regions; region_num++) {
          auto num_ops = uniformize_op.getRegion(region_num)
                             .front()
                             .getOperations()
                             .size();
          for (int op_num = 0; op_num < num_ops; op_num++) {
            Operation& curr_op = getOperationOfBlock(
                uniformize_op.getRegion(region_num).front(), op_num);
            if (curr_op.hasAttr("regLocale") &&
                is_any_of(mlir::dyn_cast<SentientRegTypeAttr>(
                              curr_op.getAttr("regLocale"))
                              .getValue(),
                          SentientRegType::lrf, SentientRegType::jcr) &&
                curr_op.use_empty()) {
              uniformize_op = addResultToYield(
                  uniformize_op, ops_to_be_delected, region_num, op_num);
            } else if (curr_op.hasAttr("regLocales") &&
                       isa<sentient::ForOp, sentient::IfOp>(curr_op) &&
                       curr_op.use_empty()) {
              for (int result_idx = 0; result_idx < curr_op.getResults().size();
                   result_idx++) {
                if (is_any_of(mlir::dyn_cast<SentientRegTypeAttr>(
                                  mlir::cast<ArrayAttr>(curr_op.getAttr(
                                      "regLocales"))[result_idx +
                                                     curr_op.getNumOperands()])
                                  .getValue(),
                              SentientRegType::lrf, SentientRegType::jcr))
                  uniformize_op =
                      addResultToYield(uniformize_op, ops_to_be_delected,
                                       region_num, op_num, result_idx);
              }
            }
          }
        }
        // if new uniformizeRegionOp is created, delete the original one.
        if (uniformize_op != op) ops_to_be_delected.push_back(op);
      }
    }
  });
  for (auto op : ops_to_be_delected) op->erase();
}

