// original: void LocalRegionSplittingForValueCommoningPass::transform( const lrs::UniformRegion &ur)
// rust home: crates/compiler/deeptools/src/transform/sentient/local_region_splitting_for_value_commoning/mod.rs
// ------------------------------------------------------------------------------------------------
void e505_transform(
    const lrs::UniformRegion &ur)
{
  // Create the new uniformized region op and replace the old one.
  OpBuilder builder(ur.getOriginalOp());
  llvm::SmallVector<mlir::Attribute> new_list_sizes;
  for (int i = 0; i < ur.numLocalRegions(); i++) {
    new_list_sizes.push_back(
        builder.getI32IntegerAttr(ur.getLocalRegion(i).getUnits().size()));
  }
  mlir::TypeRange result_types = ur.getOriginalOp().getResultTypes();
  auto new_uniform_op = mlir::uniform::UniformizeRegionsOp::create(
      builder, ur.getOriginalOp()->getLoc(), result_types,
      ur.getOriginalOp().getUnits(),
      ArrayAttr::get(builder.getContext(), new_list_sizes),
      ur.getOriginalOp().getRegIndicesAttr(),
      ur.getOriginalOp().getRegLocalesAttr(), ur.numLocalRegions());
  for (int i = 0; i < ur.numLocalRegions(); i++) {
    auto &new_block = new_uniform_op.getRegion(i).emplaceBlock();
    new_block.addArgument(builder.getIndexType(), new_uniform_op->getLoc());
    const lrs::LocalRegion &local_region = ur.getLocalRegion(i);
    IRMapping bv_map;
    bv_map.map(
        const_cast<Region &>(local_region.getOriginalRegion()).getArgument(0),
        new_uniform_op.getRegion(i).getArgument(0));
    OpBuilder region_builder(new_uniform_op.getRegion(i));
    for (Operation &op :
         const_cast<Region &>(local_region.getOriginalRegion()).getOps()) {
      Operation *cloned_op = region_builder.clone(op, bv_map);
    }
  }
  ur.getOriginalOp()->replaceAllUsesWith(new_uniform_op);
  ur.getOriginalOp()->erase();

  // Rewrite maps to remove inapplicable keys and their corresponding
  // values.
  SmallVector<Operation *> to_be_deleted;
  new_uniform_op->walk<WalkOrder::PreOrder>(
      [&](uniform::DefImmutableMappingOp map_op) {
        dcc::utils::pruneOutOfScopeEntries(map_op, to_be_deleted);
      });
  for (Operation *op : to_be_deleted) op->erase();
  to_be_deleted.clear();

  // Perform commoning for copy_ops that have constant operands (no maps)
  SmallVector<sentient::CopyOp> copy_ops;
  using ElementSizeTy = uint8_t;
  DenseMap<std::tuple<size_t /* const value */, SentientRegType /* locale */,
                      ElementSizeTy /* element size */>,
           sentient::CopyOp>
      copy_op_aliases;
  new_uniform_op->walk<WalkOrder::PreOrder>([&](sentient::CopyOp copy_op) {
    auto const_op =
        llvm::dyn_cast<sentient::ConstantOp>(copy_op.getInp().getDefiningOp());
    if (!const_op) return WalkResult::advance();
    copy_ops.push_back(copy_op);
    const ElementSizeTy esize =
        mlir::cast<::mlir::IntegerAttr>(
            dcc::utils::getAttr(copy_op.getResult(), "element_size"))
            .getInt();
    auto tuple_key = std::make_tuple(
        const_op.getValue(), sentient::getValueRegLocale(copy_op.getResult()),
        esize);
    copy_op_aliases.insert(std::make_pair(tuple_key, copy_op));
    return WalkResult::advance();
  });

  for (sentient::CopyOp copy_op : copy_ops) {
    auto const_op =
        llvm::cast<sentient::ConstantOp>(copy_op.getInp().getDefiningOp());
    const ElementSizeTy esize =
        mlir::cast<::mlir::IntegerAttr>(
            dcc::utils::getAttr(copy_op.getResult(), "element_size"))
            .getInt();
    auto tuple_key = std::make_tuple(
        const_op.getValue(), sentient::getValueRegLocale(copy_op.getResult()),
        esize);
    auto it = copy_op_aliases.find(tuple_key);
    if (it != copy_op_aliases.end()) {
      if (it->getSecond() == copy_op) continue;
      if (failed(dcc::utils::moveToCommonDominator(it->getSecond(), copy_op))) {
        copy_op->emitError("failed to move copy op to common dominator");
        signalPassFailure();
        return;
      }
      copy_op->replaceAllUsesWith(it->getSecond());
      copy_op->erase();
    }
  }

  // TODO: Perform commoning of copy_ops that have maps as operands (more
  // expensive). Only need this if we do an actual clustering.
}

