// rust home: crates/compiler/deeptools/src/transform/sentient/loop_rolling/mod.rs
// ------------------------------------------------------------------------------------------------
void e509_insertNextInstr(Block::iterator instr)
{
    Operation *op = &*instr;
    op_to_index_.insert(std::make_pair(op, size_));
    ++size_;
    end_ = instr;
    // Note: LoadAndExtractScalarOp and LoadComputeAndSendOp ignored as they
    //       should never provide rolling opportunities.
    if ((!is_L3_case_ && !isa<sentient::ConstantOp, uniform::QueryMapOp,
                              uniform::DefImmutableMappingOp>(op)) ||
        isa<sentient::LoadAndSendOp, sentient::ReceiveAndStoreOp,
            sentient::LoadAndStoreOp>(op)) {
      if (!first_rollable_op_) first_rollable_op_ = op;
      last_rollable_op_ = op;
    }
  }

