// original: void MulticastCanonicalizationPass::processConditional( sentient::ReceiveAndStoreOp ras, sentient::IfOp top_if_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/multicast_canonicalization/mod.rs
// ------------------------------------------------------------------------------------------------
void e516_processConditional(
    sentient::ReceiveAndStoreOp ras, sentient::IfOp top_if_op)
{
  std::map<sentient::IfOp, std::map<int, int>> results_index_map;

  // Lambda to process `yield` operations during traversal of the IfOp
  // structure.
  auto visitYield = [&](sentient::YieldOp old_yield) {
    IfOp parent_if = dyn_cast<IfOp>(old_yield->getParentOp());
    if (!parent_if) return;
    LLVM_DEBUG(llvm::dbgs() << "old yield: " << old_yield << "\n");

    // Vectors to hold operands of the old and new yield.
    std::vector<Value> operands, new_operands;
    for (auto operand : old_yield.getOperands()) {
      operands.push_back(operand);
      if (isa<BlockArgument>(operand)) continue;
      int old_result_index = operands.size() - 1;
      int new_result_index =
          old_yield.getOperands().size() + new_operands.size();
      if (auto multicast = dyn_cast<dataflow::CreateMulticastGroupOp>(
              operand.getDefiningOp())) {
        new_operands.push_back(multicast.getProducer());
        DT_CHECK((results_index_map[parent_if].find(old_result_index) ==
                      results_index_map[parent_if].end() ||
                  results_index_map[parent_if][old_result_index] ==
                      new_result_index) &&
                 "mismatch between this and a previously computed index");
        results_index_map[parent_if][old_result_index] = new_result_index;
      } else if (auto query_map =
                     dyn_cast<uniform::QueryMapOp>(operand.getDefiningOp())) {
        if (llvm::none_of(
                dcc::uniform::utils::getListOfValueOpsFromUniformMapping(
                    query_map),
                [](Value v) {
                  return !isa<BlockArgument>(v) &&
                         isa<dataflow::CreateMulticastGroupOp>(
                             v.getDefiningOp());
                }))
          continue;
        uniform::QueryMapOp new_query = createNewProducerQMap(query_map);
        DT_CHECK_MSG(new_query,
                     "unable to create a producer map. perhaps the input map "
                     "is not uniformly multicast ops");
        new_operands.push_back(new_query.getResult());
        DT_CHECK((results_index_map[parent_if].find(old_result_index) ==
                      results_index_map[parent_if].end() ||
                  results_index_map[parent_if][old_result_index] ==
                      new_result_index) &&
                 "mismatch between this and a previously computed index");
        results_index_map[parent_if][old_result_index] = new_result_index;
      } else if (auto if_op =
                     dyn_cast<sentient::IfOp>(operand.getDefiningOp())) {
        if (results_index_map.find(if_op) == results_index_map.end()) continue;
        if (results_index_map[if_op].find(old_result_index) ==
            results_index_map[if_op].end())
          continue;  // not one of the results we are interested in.
        new_operands.push_back(
            if_op.getResult(results_index_map[if_op][old_result_index]));
      }
    }
    if (!new_operands.empty()) {
      OpBuilder builder(old_yield);
      operands.insert(operands.end(), new_operands.begin(), new_operands.end());
      auto new_yield =
          sentient::YieldOp::create(builder, old_yield.getLoc(), operands);
      LLVM_DEBUG(llvm::dbgs() << "new yield: " << new_yield << "\n\n");
      old_yield->erase();
    }
  };

  // Lambda to process `if` operations during traversal of the IfOp structure.
  auto visitIf = [&](sentient::IfOp old_if_op) {
    auto result_types =
        old_if_op.getThenRegion().front().getTerminator()->getOperandTypes();
    // If the yield of an if-op didn't need replacement, the if-op need not
    // get replaced.
    if (result_types.size() == old_if_op.getNumResults()) return;

    auto new_if_op = dcc::sentient::utils::cloneIfOp(old_if_op, result_types);
    results_index_map[new_if_op] = results_index_map[old_if_op];

    for (int i = 0; i < old_if_op->getNumResults(); i++)
      old_if_op.getResult(i).replaceAllUsesWith(new_if_op.getResult(i));
    if (old_if_op != top_if_op) old_if_op->erase();

    LLVM_DEBUG(llvm::dbgs() << "new if: " << new_if_op << "\n\n");
  };

  top_if_op->walk<WalkOrder::PostOrder>([&](Operation *op) {
    if (auto old_yield = dyn_cast<sentient::YieldOp>(op)) {
      visitYield(old_yield);
    } else if (auto old_if_op = dyn_cast<sentient::IfOp>(op)) {
      visitIf(old_if_op);
    }
  });

  if (ras.getProducer().getDefiningOp() == top_if_op) {
    LLVM_DEBUG(llvm::dbgs() << "Did not replace producer if-op (because did "
                               "not identify as a multicast scenario).\n");
    return;
  }

  top_if_op->erase();

  auto new_if_op = dyn_cast<sentient::IfOp>(ras.getProducer().getDefiningOp());
  DEBUG_WITH_TYPE(VerboseDebug, llvm::dbgs() << "new (top-level) if-op: "
                                             << new_if_op << "\n");

  // Now find all ReceiveAndStoreOps that used the old producer, and update them
  // accordingly.
  Value tmp = ras.getProducer();
  int multicast_index = dcc::utils::getIndexOfOperationResults(tmp);
  DT_CHECK_MSG(multicast_index >= 0, "expected a non-negative index");
  DT_CHECK(results_index_map[new_if_op].find(multicast_index) !=
               results_index_map[new_if_op].end() &&
           "no mapping exists for the result index");
  int producer_index = results_index_map[new_if_op][multicast_index];
  // List of ReceiveAndStoreOps with this producer.
  llvm::SmallVector<sentient::ReceiveAndStoreOp> ras_list;
  for (auto &use : tmp.getUses()) {
    if (auto receive_and_store =
            llvm::dyn_cast<ReceiveAndStoreOp>(use.getOwner()))
      ras_list.push_back(receive_and_store);
  }
  for (auto receive_and_store : ras_list) {
    receive_and_store.getProducerMutable().assign(
        new_if_op.getResult(producer_index));
    receive_and_store.getMulticastInfoMutable().assign(tmp);
  }
}

