// entry 517/656   level 3   scc 369   38 body lines
// unit: e517_getSource
// authority: dcc/src/Transform/Sentient/OldRegisterInitialization.cpp:1144
// original: void RegisterInitCandidatePromoter::getSource( mlir::Value core, mlir::Value val, OpBuilder &const_builder, dcc::utils::UnitsAndTheirValues &results)
// rust home: crates/compiler/deeptools/src/transform/sentient/old_register_initialization/register_init_candidate_promoter.rs
// ------------------------------------------------------------------------------------------------
void e517_getSource(
    mlir::Value core, mlir::Value val, OpBuilder &const_builder,
    dcc::utils::UnitsAndTheirValues &results)
{
  if (isa<BlockArgument>(val)) {
    auto arg = mlir::cast<BlockArgument>(val);
    auto for_op = dyn_cast<sentient::ForOp>(arg.getOwner()->getParentOp());
    mlir::Value src = for_op.getIterOperands()[arg.getArgNumber() - 1];
    constructValues(src, core, results);
  } else {
    auto copy_op = val.getDefiningOp<sentient::CopyOp>();
    DT_CHECK(copy_op);
    auto copy_inp = copy_op.getInp();
    int old_size = results.size();
    constructValues(copy_inp, core, results);
    for (int i = old_size; i < results.size(); i++) {
      mlir::Value src = results.values()[i];
      if (isa<mlir::func::FuncOp>(src.getDefiningOp()->getParentOp())) continue;
      mlir::Value new_src = nullptr;
      if (isa<dataflow::CreateMulticastGroupOp>(src.getDefiningOp())) {
        IRMapping mapper;
        auto cmgop = src.getDefiningOp<dataflow::CreateMulticastGroupOp>();
        auto producer =
            const_builder.clone(*cmgop.getProducer().getDefiningOp())
                ->getResult(0);
        mapper.map(cmgop.getProducer(), producer);
        for (auto consumer : cmgop.getConsumers()) {
          auto new_consumer =
              const_builder.clone(*consumer.getDefiningOp())->getResult(0);
          mapper.map(consumer, new_consumer);
        }
        new_src =
            const_builder.clone(*src.getDefiningOp(), mapper)->getResult(0);
      } else
        new_src = const_builder.clone(*src.getDefiningOp())->getResult(0);
      src.replaceAllUsesWith(new_src);
      to_be_erased_.insert(src.getDefiningOp());
      results.replaceValue(i, new_src);
    }
  }
}

