// entry 518/656   level 3   scc 373   17 body lines
// unit: e518_replace
// authority: dcc/src/Transform/Sentient/OldRegisterInitialization.cpp:1184
// original: void RegisterInitCandidatePromoter::replace(mlir::Value val, mlir::Value copy_op_result)
// rust home: crates/compiler/deeptools/src/transform/sentient/old_register_initialization/register_init_candidate_promoter.rs
// ------------------------------------------------------------------------------------------------
void e518_replace(mlir::Value val,
                                            mlir::Value copy_op_result)
{
  if (isa<BlockArgument>(val)) {
    auto arg = mlir::cast<BlockArgument>(val);
    auto for_op = dyn_cast<sentient::ForOp>(arg.getOwner()->getParentOp());
    for_op->setOperand(arg.getArgNumber(), copy_op_result);
    copy_op_result.getDefiningOp<sentient::CopyOp>()->setAttr(
        "element_size", mlir::cast<ArrayAttr>(for_op->getAttr(
                            "element_sizes"))[arg.getArgNumber()]);
  } else {
    val.replaceAllUsesWith(copy_op_result);
    copy_op_result.getDefiningOp<sentient::CopyOp>()->setAttr(
        "element_size",
        val.getDefiningOp<sentient::CopyOp>()->getAttr("element_size"));
    to_be_erased_.insert(val.getDefiningOp<sentient::CopyOp>());
  }
  all_replacement_pairs_.emplace_back(val, copy_op_result);
}

