// entry 520/656   level 3   scc 384   67 body lines
// unit: e520_processDataID
// authority: dcc/src/Transform/Sentient/PortAssignment.cpp:93
// original: void PortAssignmentPass::processDataID(int data_id, StringRef operand_value, Operation *current_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/port_assignment/mod.rs
// ------------------------------------------------------------------------------------------------
void e520_processDataID(int data_id, StringRef operand_value,
                                       Operation *current_op)
{
  // Sometimes, we can data_id being -1; in that case, don't process them.
  if (data_id < 0) return;

  // Store all operations with this operand.
  operand_to_owners_[data_id].push_back(current_op);

  // Now, get the existing live range from the operand_to_liverange_
  operand_to_liverange_.insert(std::make_pair(data_id, LiveRange()));
  // Get the first owner
  auto &src_op = operand_to_owners_[data_id][0];

  int label_for_region = INT_MAX;
  auto region_op = dcc::uniform::utils::getRegionOp(src_op);
  if (region_op &&
      isa<mlir::uniform::UniformizeRegionsOp, mlir::uniform::EqualizePatternOp>(
          region_op)) {
    label_for_region = op_to_index_[region_op];
  }

  // Union with the new Live range (data_producer to current op).
  // If the current op is from the same block --> peace!
  if (current_op->getBlock() == src_op->getBlock()) {
    operand_to_liverange_[data_id].unionWith(LiveRange(LabeledRange(
        op_to_index_[src_op], op_to_index_[current_op], label_for_region)));
  } else {
    // otherwise, Check the current op ancestor who is in the same block
    // as of the data_producer.
    // If ancestor is for-loop, liverange is throughout.
    // If not, traverse from ancestor to the current op chain, and see where
    // to take the live range?
    auto parent_op = current_op->getParentOp();

    // We know that this loop breaks because we know that src_op is before the
    // parent_op in the ancestor chain.
    // src_op came from the preorder traversal.
    while (src_op->getBlock() != parent_op->getBlock()) {
      parent_op = parent_op->getParentOp();
    }

    if (isa<sentient::ForOp>(parent_op)) {
      auto for_op = llvm::dyn_cast<sentient::ForOp>(parent_op);
      auto yield_op = for_op.getBody()->getTerminator();
      operand_to_liverange_[data_id].unionWith(LiveRange(LabeledRange(
          op_to_index_[src_op], op_to_index_[yield_op], label_for_region)));
    } else if (isa<sentient::IfOp>(parent_op)) {
      auto if_op = llvm::dyn_cast<sentient::IfOp>(parent_op);
      if (if_op.getElseRegion().empty()) {
        auto yield_op = if_op.getThenRegion().front().getTerminator();
        operand_to_liverange_[data_id].unionWith(LiveRange(LabeledRange(
            op_to_index_[src_op], op_to_index_[yield_op], label_for_region)));
      } else {
        // TODO: Check for this case.
        DT_ERROR("yet to handle the live range case");
      }
    } else if (auto uniform_op =
                   llvm::dyn_cast<uniform::UniformizeRegionsOp>(parent_op)) {
      auto yield_op = uniform_op.getBody()->getTerminator();
      operand_to_liverange_[data_id].unionWith(LiveRange(LabeledRange(
          op_to_index_[src_op], op_to_index_[yield_op], label_for_region)));
    } else {
      parent_op->emitError("Unable to compute live range\n");
      signalPassFailure();
      return;
    }
  }
}

