// entry 521/656   level 3   scc 410   16 body lines
// unit: e521_runOnOperation
// authority: dcc/src/Transform/Sentient/RegisterInitialization.cpp:261
// original: void RegisterInitializationPass::runOnOperation()
// rust home: crates/compiler/deeptools/src/transform/sentient/register_initialization/mod.rs
// ------------------------------------------------------------------------------------------------
void e521_runOnOperation()
{
  if (DisableThisPass) return;
  ModuleOp module_op = getOperation();
  module_op.walk<WalkOrder::PreOrder>([&](dataflow::ProgramUnitOp prog_unit) {
    if (opts_.OptLevel == 0) {
      InstructionEstimator &instruction_estimator =
          getChildAnalysis<InstructionEstimator>(prog_unit);
      if (instruction_estimator.haveIbuffSpace(dccExtContext(), prog_unit)) {
        return;
      }
    }
    Liveness &liveness = getChildAnalysis<Liveness>(prog_unit);
    runOn(prog_unit, liveness);
  });
  markAnalysesPreserved<Liveness>();
}

// ------------------------------------------------------------------------------------------------
// entry 522/656   level 3   scc 421   21 body lines
// unit: e522_runOnProgramUnitOp
// authority: dcc/src/Transform/Sentient/RegisterPacking.cpp:388
// original: void RegisterPackingPass::runOnProgramUnitOp(dataflow::ProgramUnitOp unit)
// rust home: crates/compiler/deeptools/src/transform/sentient/register_packing/mod.rs
// ------------------------------------------------------------------------------------------------
void e522_runOnProgramUnitOp(dataflow::ProgramUnitOp unit)
{
  std::map<SentientRegType, std::vector<int>> avoid_renumbering_regs;
  unit->walk<WalkOrder::PreOrder>([&](Operation *op) {
    // LoadAndExtractScalarOps need to have their data result occupy LRF0 per
    // the ISA.
    if (isa<sentient::LoadAndExtractScalarOp>(op))
      avoid_renumbering_regs[SentientRegType::lrf].push_back(0);

    if (op->hasAttr("regIndex") || op->hasAttr("regIndices")) {
      if (auto copy_op = llvm::dyn_cast<sentient::CopyOp>(op)) {
        runOnCopyOp(copy_op);
      } else if (auto for_op = llvm::dyn_cast<sentient::ForOp>(op)) {
        runOnForOp(for_op);
      } else {
        runOnAllOps(op);
      }
    }
  });
  computeNewRegisterIndices(avoid_renumbering_regs);
  doRenumbering();
}

