// ------------------------------------------------------------------------------------------------
// entry 525/656   level 3   scc 445   11 body lines
// unit: e525_runOnOperation
// authority: dcc/src/Transform/Sentient/RematerializationPass.cpp:163
// original: void RematerializationPass::runOnOperation()
// rust home: crates/compiler/deeptools/src/transform/sentient/rematerialization_pass/mod.rs
// ------------------------------------------------------------------------------------------------
void e525_runOnOperation()
{
  if (DisableThisPass) return;
  ModuleOp module = getOperation();
  // Iterate through each program unit
  module->walk<WalkOrder::PreOrder>([&](dataflow::ProgramUnitOp unit_op) {
    dom_info_ = new DominanceInfo(unit_op);
    runOn(unit_op);
    delete dom_info_;
    return WalkResult::skip();
  });
}

