// entry 527/656   level 3   scc 468   38 body lines
// unit: e527_collectSymbolUsage
// authority: dcc/src/Transform/Sentient/ScalarCopyInsertionForSymbols.cpp:236
// original: void ScalarCopyInsertionForSymbolsPass::collectSymbolUsage( dataflow::ProgramUnitOp unit)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_copy_insertion_for_symbols/mod.rs
// ------------------------------------------------------------------------------------------------
void e527_collectSymbolUsage(
    dataflow::ProgramUnitOp unit)
{
  DT_CHECK(symbol_to_usage_.empty());
  DT_CHECK(symbolic_locales_.empty());
  auto collectUsage = [this, unit](Value sym) {
    for (OpOperand &use : sym.getUses()) {
      Operation *user = use.getOwner();
      // skip uses that are symbolic scalar_copy ops, since we don't want to
      // chain them to yet another scalar_copy op
      if (isa<sentient::CopyOp>(user)) continue;
      // copy op should be associated with query not the map, so skip uses in
      // maps.
      if (isa<symbol::SymbolImmutableMappingOp>(user) ||
          isa<uniform::DefImmutableMappingOp>(user))
        continue;
      // only collect symbols belonging to this unit
      auto use_unit = user->getParentOfType<dataflow::ProgramUnitOp>();
      DT_CHECK(use_unit);
      if (use_unit != unit) continue;
      const SentientRegType locale = getLocale(use);
      DT_CHECK(locale != SentientRegType::unknown);
      if ((locale == SentientRegType::jcr || locale == SentientRegType::lccr) &&
          dcc::utils::getParentOfType<uniform::UniformizeRegionsOp,
                                      uniform::EqualizePatternOp>(*user)) {
        // Usually the register init pass promotes scalar_copy's across uniform
        // regions and uniformizes them by creating corresponding map/query ops.
        // However it doesn't consider JCRs. Since doing uniformization in this
        // pass adds overhead and since there is no usecase for it, we skip such
        // scenarios for now.
        LLVM_DEBUG(user->emitWarning("skipped JCR use inside local region!"));
        continue;
      }
      symbolic_locales_.insert(locale);
      symbol_to_usage_[sym][locale].push_back(&use);
    }
  };
  for (Value sym : symbols_) collectUsage(sym);
  for (Value sym_q : symbol_queries_) collectUsage(sym_q);
}

