// original: void ScalarOpMerging::buildBlock( Operation *merge_candidate, std::unordered_set<Operation *> &analyzed_ops)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_merging.rs
// ------------------------------------------------------------------------------------------------
void e528_buildBlock(
    Operation *merge_candidate, std::unordered_set<Operation *> &analyzed_ops)
{
  int remaining_ibuff = ibuff_space_;
  // Track the value the merge_candidate will take on as it merges through each
  // operation.
  const EvaluatedValue *merging_increment = &getEvaluator().getConstant(0);
  ScalarOpMergingBlock block;
  Operation *analyze_op = merge_candidate;
  Region *parent_region = merge_candidate->getParentRegion();
  while (analyze_op) {
    analyzed_ops.insert(analyze_op);
    if (!analyze_op->use_empty() && !analyze_op->hasOneUse()) break;

    // Operations are analyzed through operand chains. To minimize complexity,
    // only analyze Operations in the same Region.
    if (analyze_op->getParentRegion() != parent_region) break;

    // Build the block of Operations with eligible features. Keep track of the
    // input Value feeding the linear chain (the Value from outside the block
    // feeding the first Operation). Keep track of the immutable_addrs of comp
    // mem ops. If an immutable goes out of range of IMM field range, the
    // operation is not eligible.
    if (auto add_op = dyn_cast<sentient::AddOp>(analyze_op)) {
      int const_operand_idx = dcc::utils::getFirstConstOperandIndex(analyze_op);
      if (const_operand_idx == -1) break;
      Value operand = analyze_op->getOperand(const_operand_idx);
      const EvaluatedValue &operand_ev = getEvaluator().evaluateValue(operand);

      merging_increment =
          &getEvaluator().evaluateSum(*merging_increment, operand_ev);
      // Confirm the new merging increment would fit in LRF.
      // Note: If element_size cannot be determined, we cannot safely check the
      // new value fits.
      if (!add_op->hasAttr("element_size")) break;
      int element_size =
          mlir::cast<mlir::IntegerAttr>(add_op->getAttr("element_size"))
              .getInt();
      if (doesValueExceedLRFRange(getDccExtContext().dsc_global_->sysDef,
                                  *merging_increment, element_size, getComp(),
                                  getScale())) {
        LLVM_DEBUG(llvm::dbgs()
                   << "[ScalarOpMerging] Op not a candidate due to "
                      "constant operand being pushed out of LRF range :\n"
                   << *analyze_op << "\n\n");
        break;
      }

      // The modification to the op is zero because this op will be deleted
      // during merging.
      block.addOpToBlock(
          {analyze_op, &getEvaluator().getConstant(0), merging_increment},
          /*is_add_or_sub*/ true);
      if (analyze_op != merge_candidate) block.setEnablesMerging();

      Value input_value = const_operand_idx == 0 ? add_op->getOperand(1)
                                                 : add_op->getOperand(0);
      block.setInputValueToBlock(input_value);
      analyze_op = input_value.getDefiningOp();
    } else if (auto sub_op = dyn_cast<sentient::SubOp>(analyze_op)) {
      // To simplify calculations, subs are treated as adds so the increment
      // value will be equal to the opposite constant.
      if (!dcc::utils::isConstant<sentient::ConstantOp>(sub_op.getInp2()))
        break;
      const EvaluatedValue &sub_inp2_ev =
          getEvaluator().evaluateValue(sub_op.getInp2());
      merging_increment =
          &getEvaluator().evaluateSub(*merging_increment, sub_inp2_ev);

      // Confirm the new merging increment would fit in LRF.
      // Note: If element_size cannot be determined, we cannot safely check the
      // new value fits.
      if (!sub_op->hasAttr("element_size")) break;
      int element_size =
          mlir::cast<mlir::IntegerAttr>(sub_op->getAttr("element_size"))
              .getInt();
      if (doesValueExceedLRFRange(getDccExtContext().dsc_global_->sysDef,
                                  *merging_increment, element_size, getComp(),
                                  getScale())) {
        LLVM_DEBUG(llvm::dbgs()
                   << "[ScalarOpMerging] Op not a candidate due to "
                      "constant operand being pushed out of LRF range :\n"
                   << *analyze_op << "\n\n");
        break;
      }

      // The modification to the op is zero because this op will be deleted
      // during merging.
      block.addOpToBlock(
          {analyze_op, &getEvaluator().getConstant(0), merging_increment},
          /*is_add_or_sub*/ true);
      if (analyze_op != merge_candidate) block.setEnablesMerging();

      Value input_value = sub_op.getInp1();
      block.setInputValueToBlock(input_value);
      analyze_op = input_value.getDefiningOp();
    } else if (isa<sentient::LoadAndSendOp, sentient::ReceiveAndStoreOp,
                   sentient::LoadComputeAndSendOp>(analyze_op)) {
      MemoryOpInfo mem_info(analyze_op);
      int required_ibuff = 0;
      if (isa<sentient::LoadAndSendOp>(analyze_op))
        required_ibuff =
            calculateIBuffRequired<sentient::LoadAndSendOp>(analyze_op);
      else if (isa<sentient::ReceiveAndStoreOp>(analyze_op))
        required_ibuff =
            calculateIBuffRequired<sentient::ReceiveAndStoreOp>(analyze_op);
      // LoadComputeAndSendOp: required_ibuff remains 0 (no burst/IL)

      auto immutable_addr_op = mem_info.immutable_addr_.getDefiningOp();
      if (!immutable_addr_op) break;

      // If the memory op contains burst or IL fields, the operation would
      // need to be unrolled before transformation. Calculate how much IBuff
      // would be required to unroll the operation. If there is not enough, the
      // block ends here.
      if (mem_info.burst_ > 1 || mem_info.il_ > 0) {
        if (DisableFieldUnrolling) break;

        if (!isa<sentient::ConstantOp, sentient::CopyOp>(immutable_addr_op))
          break;

        if (required_ibuff > remaining_ibuff) {
          LLVM_DEBUG(llvm::dbgs() << "[FieldUnrolling] Cannot field unroll "
                                     "following op due to IBuff constraint:\n"
                                  << *analyze_op << "\n\n");
          break;
        }

        FieldUnrollData unroll_candidate(analyze_op, required_ibuff);
        const EvaluatedValue *unroll_merging_increment = merging_increment;
        if (!isFieldUnrollCandidate(unroll_candidate, unroll_merging_increment))
          break;
        merging_increment = unroll_merging_increment;
        remaining_ibuff -= required_ibuff;
        // Immutables are stored in the FieldUnrollData object for Field
        // Unrolling candidates.
        block.addOpToBlock(
            {analyze_op, &getEvaluator().getConstant(0), merging_increment});
        block.addUnrollCandidate(unroll_candidate);
      } else {
        DT_CHECK_MSG(dcc::utils::isConstant<sentient::ConstantOp>(
                         mem_info.immutable_addr_),
                     "Expect constant immutable address");
        DT_CHECK_MSG(
            dcc::utils::isConstant<sentient::ConstantOp>(mem_info.increment_),
            "Expect constant increment");
        const EvaluatedValue &immutable_addr_ev =
            getEvaluator().evaluateValue(mem_info.immutable_addr_);
        // New immutable will be:
        //   immutable - increment - merging_increment
        // New merging increment will be:
        //   immutable - (immutable - increment - merging_increment)
        const EvaluatedValue &increment_ev =
            getEvaluator().evaluateValue(mem_info.increment_);
        const EvaluatedValue &new_immutable_addr_ev =
            getEvaluator().evaluateSub(
                getEvaluator().evaluateSub(immutable_addr_ev, increment_ev),
                *merging_increment);
        // We only merge if the immutable exceeds IMM range if the original
        // immutable already exceeds the range, and if the new immutable fits in
        // LRF width.
        if (!opt_context_.isImmutableValueInRange(
                new_immutable_addr_ev, immutable_addr_ev,
                mem_info.element_size_, analyze_op)) {
          break;
        }

        merging_increment = &getEvaluator().evaluateSub(immutable_addr_ev,
                                                        new_immutable_addr_ev);
        block.addOpToBlock(
            {analyze_op, &new_immutable_addr_ev, merging_increment});
      }

      block.setInputValueToBlock(mem_info.mutable_addr_);
      analyze_op = mem_info.mutable_addr_.getDefiningOp();
    } else
      break;
  }

  if (block.getBlockOps().size() > 1) blocks_.push_back(block);
}

