// entry 529/656   level 3   scc 495   13 body lines
// unit: e529_processForOpResult
// authority: dcc/src/Transform/Sentient/ScalarOpMergingAndHoisting.cpp:1484
// original: bool ScalarOpHoisting::processForOpResult( sentient::ForOp *for_op, int result_idx, const EvaluatedValue &adjustment_increment, SmallVector<OperationData> &ops_to_update)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_hoisting.rs
// ------------------------------------------------------------------------------------------------
bool e529_processForOpResult(
    sentient::ForOp *for_op, int result_idx,
    const EvaluatedValue &adjustment_increment,
    SmallVector<OperationData> &ops_to_update)
{
  Value result = for_op->getResult(result_idx);
  if (result.use_empty()) return true;

  // If there is a mergeable chain of operations for every use of the result,
  // the additional adjustment add can be merged.
  for (auto user : result.getUsers()) {
    if (!isMergeableOpOrChain(*for_op, user)) return false;
    processMergeableChain(*for_op, user, adjustment_increment, ops_to_update);
  }

  return true;
}

