// entry 530/656   level 3   scc 501   38 body lines
// unit: e530_processForDerivedIVElimination
// authority: dcc/src/Transform/Sentient/ScalarOpMergingAndHoisting.cpp:1843
// original: bool ScalarOpHoisting::processForDerivedIVElimination(BlockArgument &main_iv, Operation *derived_iv)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_hoisting.rs
// ------------------------------------------------------------------------------------------------
bool e530_processForDerivedIVElimination(BlockArgument &main_iv,
                                                      Operation *derived_iv)
{
  if (!is_any_of(getComp(), LXLU, LXSU, L0LU, L0SU)) {
    LLVM_DEBUG(llvm::dbgs() << "[ScalarOpHoisting] Skipping DerivedIV "
                               "Elimination - only support in LX/L0\n");
    return false;
  }
  LLVM_DEBUG(
      llvm::dbgs() << "[ScalarOpHoisting] Attempting DerivedIV Elimination\n");

  int const_operand_idx = dcc::utils::getFirstConstOperandIndex(derived_iv);

  // If the derived_iv is a SubOp, it should be in the form
  // derived_iv = B - constant. If it is a SubOp, adjust the modifier so it
  // matches the form derived_iv = B + (constant * -1).
  const EvaluatedValue *modifier =
      &getEvaluator().evaluateValue(derived_iv->getOperand(const_operand_idx));
  if (isa<sentient::SubOp>(derived_iv)) {
    if (const_operand_idx == 0) return false;
    modifier = &getEvaluator().evaluateMultiplyByConst(*modifier, -1);
  }

  SmallVector<OperationData> ops_to_update;
  for (auto user : derived_iv->getUsers()) {
    if (!isMergeableOpOrChain(derived_iv, user)) return false;

    if (!processMergeableChain(derived_iv, user, *modifier, ops_to_update))
      return false;
  }

  applyOperationData(ops_to_update);
  derived_iv->getResult(0).replaceAllUsesWith(main_iv);
  derived_iv->erase();

  ++num_hoists_executed_per_unit;
  LLVM_DEBUG(
      llvm::dbgs() << "[ScalarOpHoisting] Completed DerivedIV Elimination\n");
  return true;
}

