// entry 531/656   level 3   scc 519   165 body lines
// unit: e531_findAndProcessCandidates
// authority: dcc/src/Transform/Sentient/ScalarOpReordering.cpp:207
// original: void ScalarOpReorderingPass::findAndProcessCandidates( dataflow::ProgramUnitOp unit_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_reordering/mod.rs
// ------------------------------------------------------------------------------------------------
void e531_findAndProcessCandidates(
    dataflow::ProgramUnitOp unit_op)
{
  // Create a priority queue of candidate scalar ops for each locale, sorted by
  // the liverange endpoint index of their last use, furthest index first.
  // Two scalar ops with the same liverange endpoint and locale should be sorted
  // in their original operation order within the block (earlier operation
  // first). Reason: Moving scalar ops whose liverange ends later in the code
  // have the highest potential register pressure benefit.
  auto cmp = [this](Operation *left, Operation *right) {
    unsigned left_liverange_endpt = getLiverangeEndPt(left);
    unsigned right_liverange_endpt = getLiverangeEndPt(right);
    if (left_liverange_endpt < right_liverange_endpt) return true;
    unsigned left_idx = op_to_idx_[left];
    unsigned right_idx = op_to_idx_[right];
    return (left_liverange_endpt == right_liverange_endpt &&
            left_idx > right_idx);
  };

  // Collect candidates in per-locale buckets.
  std::array<std::optional<std::priority_queue<
                 Operation *, std::vector<Operation *>, decltype(cmp)>>,
             getMaxEnumValForSentientRegType() + 1>
      locale_to_candidates;
  unit_op->walk<WalkOrder::PreOrder>([&](Operation *op) {
    if (!isCandidateForReordering(*op)) return mlir::WalkResult::advance();
    auto reg_locale = sentient::getValueRegLocale(op->getResult(0));
    auto &candidates = locale_to_candidates[static_cast<size_t>(reg_locale)];
    if (!candidates.has_value()) candidates.emplace(cmp);
    candidates.value().push(op);
    return mlir::WalkResult::advance();
  });

  for (int i = 0; i <= getMaxEnumValForSentientRegType(); ++i) {
    auto reg_locale = static_cast<SentientRegType>(i);
    auto &optional_candidates = locale_to_candidates[i];
    if (!optional_candidates.has_value()) continue;
    auto &candidates = optional_candidates.value();

    // Keep track of candidates which are no longer in the list,
    // so they may be re-inserted if needed.
    llvm::SmallPtrSet<Operation *, 8> visited;

    // Process the candidates for this locale. Note we might move a candidate to
    // right before its first use, and later move that use; so we need to
    // re-insert the moved candidate's operands in the list to be processed if
    // they are scalar ops. E.g.
    // %1 = scalar_add ...
    // ...
    // %2 = scalar_add %1, ... // first use of %1
    // ...
    // %3 = load_and_send mutable_addr (%2), ... // first use of %2
    // <later use of %1>
    // Assuming %1 and %2 are candidates for reordering, %1 would be moved
    // before its first use, and then %2 would be moved before its first use:
    // ...
    // %1 = scalar_add ...
    // ...
    // %2 = scalar_add %1, ... // first use of %1
    // %3 = load_and_send mutable_addr (%2), ... // first use of %2
    // Now %1 could be moved again, if it would be reinserted in the worklist.
    while (!candidates.empty()) {
      Operation *cur_op = candidates.top();
      candidates.pop();
      visited.insert(cur_op);
      // Get the liverange endpoint of the next candidate. This is guaranteed to
      // be the furthest liverange endpoint from among the remaining candidates.
      unsigned next_candidate_liverange_end = 0;
      if (!candidates.empty()) {
        next_candidate_liverange_end = getLiverangeEndPt(candidates.top());
      }

      Value cur_val = cur_op->getResult(0);
      if (cur_val.hasOneUse()) {
        Operation *result_user = *cur_val.user_begin();
        DT_CHECK(result_user);
        if (result_user->getBlock() == cur_op->getBlock()) {
          // result_user is within the same block as op, so movement is
          // horizontal.
          cur_op->moveBefore(result_user);
          LLVM_DEBUG(llvm::dbgs() << "Move single-use scalar op horizontally "
                                     "close to its only use:\n"
                                  << *cur_op << "\n");
        } else {
          // Move the candidate as close as possible to its use, moving it into
          // loops only if register pressure is high.
          bool has_free_regs =
              !ForceAllowMovementWithinLoops && localeHasFreeRegs(reg_locale);

          // Determine the insertion point by walking the ancestor chain between
          // result_user and cur_val:
          // - If register pressure is not high, move cur_op to right before
          // the outermost loop in this ancestor chain.
          // - If locale has no free registers, move cur_op to right before the
          // unique loop L satisfying:
          // 1. All remaining candidates' liverange endpoints precede L (so this
          // movement gives us the best possible register pressure benefit).
          // 2. L is the outermost loop in the ancestor chain satisfying
          // property 1 (so that moving cur_op within L would give us no further
          // register pressure reduction).
          // E.g.
          // %0 = scalar_add ... // top remaining candidate
          // %1 = scalar_add ... // cur_op
          // for %arg0 = 2 {
          // ...
          //   if (...) {
          //     <last use of %0>
          //     if (...) {
          //       for %arg1 = 2 { <--- cur_op will be moved before this loop
          //          <use of %1>
          Operation *insert_before = result_user;
          for (Operation *parent_op = result_user->getParentOp(); parent_op;
               parent_op = parent_op->getParentOp()) {
            if (isa<sentient::ForOp>(parent_op)) {
              if (has_free_regs) {
                insert_before = parent_op;
              } else {
                auto loop_idx = op_to_idx_[parent_op];
                // If the next candidate's liverange ends strictly before this
                // loop then cur_op does not need to be moved inside.
                if (next_candidate_liverange_end < loop_idx)
                  insert_before = parent_op;
                else
                  break;
              }
            }
            if (parent_op->getBlock() == cur_op->getBlock()) break;
          }
          cur_op->moveBefore(insert_before);
          if (has_free_regs)
            LLVM_DEBUG(llvm::dbgs() << "Move scalar op closer to its only use, "
                                       "avoiding movement within loops:\n"
                                    << *cur_op << "\n");
          else
            LLVM_DEBUG(llvm::dbgs()
                       << "Register pressure is high. Move scalar op closer to "
                          "its only use, allowing movement within loops:\n"
                       << *cur_op << "\n");
        }
      } else {
        // If op has multiple uses, move the candidate horizontally to right
        // before the ancestor of its first use within its block.
        Operation *op_first_use = getFirstUseWithinBlock(cur_val);
        LLVM_DEBUG(llvm::dbgs()
                   << "Move multi-use scalar op within its block to be "
                      "closer to its first use:\n"
                   << *cur_op << "\n");
        cur_op->moveBefore(op_first_use);
      }
      // Cache may be stale due to the op move.
      val_to_first_use_in_block_cache_.clear();
      // Re-insert the moved candidate's operands into the list only if they are
      // candidates which have already been processed. This avoids having
      // duplicate candidates in the list.
      for (auto operand : cur_op->getOperands()) {
        Operation *operand_op = operand.getDefiningOp();
        if (!operand_op || !isCandidateForReordering(*operand_op)) continue;
        if (visited.contains(operand_op)) {
          candidates.push(operand_op);
          // Remove from visit since this candidate was re-inserted in the
          // queue.
          visited.erase(operand_op);
        }
      }
    }
  }
}

