// authority: dcc/src/Transform/Sentient/ScalarSimplifications.cpp:315
// original: void ScalarSimplificationsPass::simplifyBinaryOperation( OpBuilder& builder, Operation* op, Type operand_type, PropagationAnalysis& expr_prop_analysis, std::vector<mlir::Operation*>& tobe_deleted)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_simplifications/mod.rs
// ------------------------------------------------------------------------------------------------
void e532_simplifyBinaryOperation(
    OpBuilder& builder, Operation* op, Type operand_type,
    PropagationAnalysis& expr_prop_analysis,
    std::vector<mlir::Operation*>& tobe_deleted)
{
  PropagationAnalysis::ExprInfoMap* expr_info_map =
      expr_prop_analysis.getAffineExpression(op->getResult(0));
  // This situation can arise when other simplifications happened before
  // can stale the expr_prop_analysis or may not have information about
  // new operand created as part of the simplification
  if (expr_info_map->empty()) return;

  // get indices of valid units and query key
  Value query_key;
  SmallVector<Value> units;
  SmallVector<unsigned> indices;
  if (getQueryKeyAndUnitsFromParentRegion(op, query_key, units).failed()) {
    op->emitOpError("can't find parentOp");
    signalPassFailure();
    return;
  }
  selectIndicesForUnits(units, indices, expr_prop_analysis.getUnitIndexMap());

  // for uniformization, create a vector to hold flattened exprs for the current
  // list of units
  std::vector<FlatExprType> flat_exprs;

  for (auto idx : indices) {
    PropagationAnalysis::ExprInfo* expr_info =
        expr_info_map->getExprInfoAt(idx);
    DT_CHECK_MSG(expr_info, "Expecting valid ExprInfo for unit");

    if (expr_info->propagated_args_.size() > 2) return;
    if (expr_info->propagated_map_.getNumResults() > 1) return;
    affine::FlatAffineValueConstraints constraints;
    FlatExprType flat_expr;
    if (getFlattenedAffineExprs(expr_info->propagated_map_, &flat_expr,
                                &constraints)
            .failed()) {
      return;
    } else {
      // Currently, MLIR doesn't have support to construct local variables
      // without explicit representation.
      if (constraints.getNumLocalVars() > 0) return;
      flat_exprs.push_back(flat_expr);
    }
  }

  if (areAllExprsValidToTransform(flat_exprs, indices, expr_info_map)) {
    auto& first_flat_expr_coeffs = flat_exprs[0][0];
    if (first_flat_expr_coeffs.size() == 1) {
      // constant
      auto new_operand =
          createNewOpOrMap(builder, flat_exprs, indices, expr_prop_analysis,
                           units, op, operand_type, query_key, expr_info_map);
      expr_prop_analysis.setExprInfoMapForValue(new_operand, expr_info_map);
      op->getResult(0).replaceAllUsesWith(new_operand);
      op->dropAllUses();
      tobe_deleted.push_back(op);
    } else if (first_flat_expr_coeffs.size() == 3) {
      // 1 * variable + 1 * variable + constant --> constant has to be zero.
      Value operand0, operand1;
      operand0 = createNewOpOrMap(builder, flat_exprs, indices,
                                  expr_prop_analysis, units, op, operand_type,
                                  query_key, expr_info_map, 0);
      operand1 = createNewOpOrMap(builder, flat_exprs, indices,
                                  expr_prop_analysis, units, op, operand_type,
                                  query_key, expr_info_map, 1);
      DT_CHECK(isa<sentient::AddOp>(op));
      op->setOperand(0, operand0);
      op->setOperand(1, operand1);
    } else {
      // 1 * variable + constant --> variable coefficient has to be 1.
      if (first_flat_expr_coeffs[1] != 0) {
        auto operand0 = createNewOpOrMap(
            builder, flat_exprs, indices, expr_prop_analysis, units, op,
            operand_type, query_key, expr_info_map, 0);
        auto operand1 = createNewOpOrMap(
            builder, flat_exprs, indices, expr_prop_analysis, units, op,
            operand_type, query_key, expr_info_map, 1);
        op->setOperand(0, operand0);
        op->setOperand(1, operand1);
      } else {
        auto operand0 = createNewOpOrMap(
            builder, flat_exprs, indices, expr_prop_analysis, units, op,
            operand_type, query_key, expr_info_map, 0);
        op->getResult(0).replaceAllUsesWith(operand0);
        op->dropAllUses();
        tobe_deleted.push_back(op);
      }
    }
  }
}

