// entry 533/656   level 3   scc 526   93 body lines
// unit: e533_simplifyLoadStoreOperation
// authority: dcc/src/Transform/Sentient/ScalarSimplifications.cpp:408
// original: void ScalarSimplificationsPass::simplifyLoadStoreOperation( PropagationAnalysis& expr_prop_analysis, OpBuilder& builder, Operation* op)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_simplifications/mod.rs
// ------------------------------------------------------------------------------------------------
void e533_simplifyLoadStoreOperation(
    PropagationAnalysis& expr_prop_analysis, OpBuilder& builder,
    Operation* op)
{
  // get indices of valid units and query key
  Value query_key;
  SmallVector<Value> units;
  SmallVector<unsigned> indices;
  if (getQueryKeyAndUnitsFromParentRegion(op, query_key, units).failed()) {
    op->emitOpError("can't find parentOp");
    signalPassFailure();
    return;
  }
  selectIndicesForUnits(units, indices, expr_prop_analysis.getUnitIndexMap());

  // Lambda to create a simplified value to replace the operand with. If a
  // simplified value cannot be calculated, empty value is returned.
  auto getSimplifiedValue = [&](Value val) -> Value {
    if (dcc::utils::isSymbol(val)) return Value();
    PropagationAnalysis::ExprInfoMap* expr_info_map =
        expr_prop_analysis.getAffineExpression(val);
    std::vector<FlatExprType> flat_exprs;
    // This situation can arise when other simplifications happened before
    // can stale the expr_prop_analysis or may not have information about
    // new operand created as part of the simplification
    if (!expr_info_map->empty()) {
      for (auto idx : indices) {
        PropagationAnalysis::ExprInfo* expr_info =
            expr_info_map->getExprInfoAt(idx);
        DT_CHECK_MSG(expr_info, "Expecting valid ExprInfo for unit");
        if (expr_info->propagated_args_.size() > 1 ||
            expr_info->propagated_map_.getNumDims() > 1)
          return Value();
        affine::FlatAffineValueConstraints constraints;
        FlatExprType flat_expr;
        if (getFlattenedAffineExprs(expr_info->propagated_map_, &flat_expr,
                                    &constraints)
                .failed()) {
          return Value();
        } else {
          // Currently, MLIR doesn't have support to construct local variables
          // without explicit representation.
          if (constraints.getNumLocalVars() > 0) return Value();
          flat_exprs.push_back(flat_expr);
        }
      }
      if (areAllExprsValidToTransform(flat_exprs, indices, expr_info_map,
                                      true)) {
        // We want either constants or direct variable
        PropagationAnalysis::ExprInfo* first_expr_info =
            expr_info_map->getFirstExprInfo();
        if (first_expr_info->propagated_map_.getNumDims() == 1) {
          return first_expr_info->propagated_args_[0];
        } else {
          return createNewOpOrMap(builder, flat_exprs, indices,
                                  expr_prop_analysis, units, op, val.getType(),
                                  query_key, expr_info_map);
        }
      }
    }
    return Value();
  };

  if (auto load_op = llvm::dyn_cast<sentient::LoadAndSendOp>(op)) {
    Value rv = getSimplifiedValue(load_op.getMutableAddr());
    if (rv) load_op.getMutableAddrMutable().assign(rv);
    rv = getSimplifiedValue(load_op.getImmutableAddr());
    if (rv) load_op.getImmutableAddrMutable().assign(rv);
  } else if (auto store_op = llvm::dyn_cast<sentient::ReceiveAndStoreOp>(op)) {
    Value rv = getSimplifiedValue(store_op.getMutableAddr());
    if (rv) store_op.getMutableAddrMutable().assign(rv);
    rv = getSimplifiedValue(store_op.getImmutableAddr());
    if (rv) store_op.getImmutableAddrMutable().assign(rv);
  } else if (auto ls_op = llvm::dyn_cast<sentient::LoadAndStoreOp>(op)) {
    Value rv = getSimplifiedValue(ls_op.getSrcMutableAddr());
    if (rv) ls_op.getSrcMutableAddrMutable().assign(rv);
    rv = getSimplifiedValue(ls_op.getSrcImmutableAddr());
    if (rv) ls_op.getSrcImmutableAddrMutable().assign(rv);
    rv = getSimplifiedValue(ls_op.getDstMutableAddr());
    if (rv) ls_op.getDstMutableAddrMutable().assign(rv);
    rv = getSimplifiedValue(ls_op.getDstImmutableAddr());
    if (rv) ls_op.getDstImmutableAddrMutable().assign(rv);
  } else if (auto extract_op =
                 llvm::dyn_cast<sentient::LoadAndExtractScalarOp>(op)) {
    Value rv = getSimplifiedValue(extract_op.getMutableAddr());
    if (rv) extract_op.getMutableAddrMutable().assign(rv);
    rv = getSimplifiedValue(extract_op.getImmutableAddr());
    if (rv) extract_op.getImmutableAddrMutable().assign(rv);
  } else if (auto load_compute_op =
                 dyn_cast<sentient::LoadComputeAndSendOp>(op)) {
    Value rv = getSimplifiedValue(load_compute_op.getMutableAddr());
    if (rv) load_compute_op.getMutableAddrMutable().assign(rv);
    rv = getSimplifiedValue(load_compute_op.getImmutableAddr());
    if (rv) load_compute_op.getImmutableAddrMutable().assign(rv);
  }
}

// ------------------------------------------------------------------------------------------------
// entry 534/656   level 3   scc 199   183 body lines
// unit: e534_lightWeightSimplifyBinaryArithmetic
// authority: dcc/src/Transform/Sentient/ScalarSimplifications.cpp:504
// original: void sentient::lightWeightSimplifyBinaryArithmetic( OpBuilder& builder, PropagationAnalysis& expr_prop_analysis, Operation* op, std::vector<mlir::Operation*>& tobe_deleted)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_simplifications/sentient.rs
// ------------------------------------------------------------------------------------------------
void e534_lightWeightSimplifyBinaryArithmetic(
    OpBuilder& builder, PropagationAnalysis& expr_prop_analysis, Operation* op,
    std::vector<mlir::Operation*>& tobe_deleted)
{
  // TODO: Add if-dead branch elimination if required
  // TODO: (copy from the sentient canonicalization)
  if (isa<sentient::AddOp, sentient::SubOp>(op)) {
    auto result = op->getResult(0);
    // check if any of the operand is a constant and its value being zero.
    auto checkOperand = [&](int i) {
      if (!mlir::isa<BlockArgument>(op->getOperand(i))) {
        if (auto const_op = llvm::dyn_cast<sentient::ConstantOp>(
                op->getOperand(i).getDefiningOp())) {
          if (const_op.getValue() == 0) {
            result.replaceAllUsesWith(op->getOperand(1 - i));
            op->dropAllUses();
            tobe_deleted.push_back(op);
            return LogicalResult::success();
          }
        }
      }

      return LogicalResult::failure();
    };

    LogicalResult simplified = LogicalResult::failure();
    if (isa<sentient::AddOp>(op)) {
      simplified = checkOperand(0);
      if (simplified.failed()) {
        simplified = checkOperand(1);
      }

      if (simplified.succeeded()) return;
    }

    PropagationAnalysis::ExprInfoMap* expr_info_map =
        expr_prop_analysis.getAffineExpression(result);

    // This situation can arise when other simplifications happened before
    // can stale the expr_prop_analysis or may not have information about
    // new operand created as part of the simplification
    if (expr_info_map->empty()) return;

    Value query_key;
    SmallVector<Value> units;
    SmallVector<unsigned> unit_indices;
    std::vector<FlatExprType> flat_exprs;
    if (getQueryKeyAndUnitsFromParentRegion(op, query_key, units).failed()) {
      op->emitOpError("can't find parentOp");
      return;
    }
    selectIndicesForUnits(units, unit_indices,
                          expr_prop_analysis.getUnitIndexMap());

    // to determine whether result is constant
    bool is_the_result_constant = true;
    for (auto idx : unit_indices) {
      PropagationAnalysis::ExprInfo* expr_info =
          expr_info_map->getExprInfoAt(idx);
      DT_CHECK_MSG(expr_info, "Expecting valid ExprInfo for unit");
      if (!expr_info->cannot_be_resolved_ &&
          expr_info->propagated_args_.empty() &&
          expr_info->propagated_map_.getNumResults() == 1) {
        affine::FlatAffineValueConstraints constraints;
        FlatExprType flat_expr;
        void(getFlattenedAffineExprs(expr_info->propagated_map_, &flat_expr,
                                     &constraints));
        flat_exprs.push_back(flat_expr);
      } else {
        is_the_result_constant = false;
        break;
      }
    }

    // the value yields to be a constant.
    if (is_the_result_constant) {
      if (!result.use_empty()) {
        auto new_op = createNewOpOrMap(
            builder, flat_exprs, unit_indices, expr_prop_analysis, units, op,
            result.getType(), query_key, expr_info_map);
        expr_prop_analysis.setExprInfoMapForValue(new_op, expr_info_map);
        result.replaceAllUsesWith(new_op);
        op->dropAllUses();
      }

      tobe_deleted.push_back(op);
    } else {
      // specific optimization to merge add_ops.
      {
        // TODO: The following can be cleaned up or made it more generic
        // considering position of operands and also considering SUB operations.
        // In addition, we shouldn't use expression propagation information
        // because using that information could disrupt the changes done
        // by live range reduction.
        // merge add operations
        // x = ADD a, c0
        // y = ADD x, c1
        // --> y = ADD a, c0+c1

        auto add_op = llvm::dyn_cast<sentient::AddOp>(op);
        if (!add_op) return;

        // first operand coming from add operation
        auto lhs = add_op.getInp1();
        auto rhs = add_op.getInp2();

        if (mlir::isa<BlockArgument>(lhs) || mlir::isa<BlockArgument>(rhs))
          return;

        // LHS comes from add operation
        auto lhs_add_op = llvm::dyn_cast<sentient::AddOp>(lhs.getDefiningOp());
        if (!lhs_add_op) return;

        // Get RHS constant values or return if non-constant
        std::vector<int64_t> rhs_consts;
        if (auto rhs_const_op =
                llvm::dyn_cast<sentient::ConstantOp>(rhs.getDefiningOp())) {
          rhs_consts.push_back(rhs_const_op.getValue());
        } else if (auto query_map =
                       dyn_cast<uniform::QueryMapOp>(rhs.getDefiningOp())) {
          DT_CHECK_MSG(isConstant<sentient::ConstantOp>(query_map),
                       "Expecting non-symbolic RHS of IfOp condition");
          rhs_consts = dcc::uniform::utils::getConstantTargetValues(query_map);
        }
        if (rhs_consts.empty()) return;

        auto lhs_add_op_const = lhs_add_op.getInp2();

        // Get LHS def op second operand constant values or return if
        // non-constant
        std::vector<int64_t> lhs_add_op_consts;
        if (auto lhs_add_op_const_op = llvm::dyn_cast<sentient::ConstantOp>(
                lhs_add_op_const.getDefiningOp())) {
          lhs_add_op_consts.push_back(lhs_add_op_const_op.getValue());
        } else if (auto query_map = dyn_cast<uniform::QueryMapOp>(
                       lhs_add_op_const.getDefiningOp())) {
          DT_CHECK_MSG(isConstant<sentient::ConstantOp>(query_map),
                       "Expecting non-symbolic LHS of IfOp condition");
          lhs_add_op_consts = dcc::uniform::utils::getConstantTargetValues(
              lhs_add_op_const.getDefiningOp<uniform::QueryMapOp>());
        }
        if (lhs_add_op_consts.empty()) return;

        // LHS def op has a single use
        if (!lhs_add_op->hasOneUse()) return;

        std::vector<int64_t> final_consts;
        auto element_num =
            std::max(lhs_add_op_consts.size(), rhs_consts.size());
        DT_CHECK(lhs_add_op_consts.size() == 1 ||
                 lhs_add_op_consts.size() == element_num);
        DT_CHECK(rhs_consts.size() == 1 || rhs_consts.size() == element_num);
        for (size_t idx = 0; idx < element_num; idx++) {
          final_consts.push_back(
              lhs_add_op_consts[std::min(idx, lhs_add_op_consts.size() - 1)] +
              rhs_consts[std::min(idx, rhs_consts.size() - 1)]);
        }

        Operation* new_op;
        OpBuilder local_builder(op);
        if (element_num == 1) {
          new_op = sentient::ConstantOp::create(
              local_builder, op->getLoc(), result.getType(), final_consts[0]);
        } else {
          std::vector<Value> const_ops;
          for (size_t idx = 0; idx < element_num; idx++) {
            const_ops.push_back(sentient::ConstantOp::create(
                                    local_builder, op->getLoc(),
                                    result.getType(), final_consts[idx])
                                    .getResult());
          }
          auto map = mlir::uniform::DefImmutableMappingOp::create(
              local_builder, op->getLoc(), builder.getIndexType(), units,
              const_ops);
          new_op = mlir::uniform::QueryMapOp::create(
              local_builder, op->getLoc(), builder.getIndexType(), map,
              query_key);
        }
        add_op.getInp1Mutable().assign(lhs_add_op.getInp1());
        add_op.getInp2Mutable().assign(new_op->getResult(0));
        lhs_add_op->dropAllUses();
        tobe_deleted.push_back(lhs_add_op);
      }
    }
  }
}

