// entry 541/656   level 3   scc 599   24 body lines
// unit: e541_runOnOperation
// authority: dcc/src/Transform/Sentient/StoreAndForwardFusion.cpp:555
// original: void StoreAndForwardFusionPass::runOnOperation()
// rust home: crates/compiler/deeptools/src/transform/sentient/store_and_forward_fusion/mod.rs
// ------------------------------------------------------------------------------------------------
void e541_runOnOperation()
{
  if (DisableThisPass) return;
  ModuleOp module_op = getOperation();
  std::vector<mlir::Operation *> to_be_deleted;

  module_op.walk([&](dataflow::ProgramUnitOp unit_op) {
    auto compute_type = dcc::getUnitType(
        unit_op.getUnits()[0].getDefiningOp<dataflow::GetUnitOp>());
    if (is_any_of(compute_type, SFP, PE)) {
      InstructionEstimator &instruction_estimator =
          getChildAnalysis<InstructionEstimator>(unit_op);
      if (opts_.OptLevel == 0 &&
          instruction_estimator.haveIbuffSpace(dccExtContext(), unit_op)) {
        return;
      }
      unit_op.walk([&](mlir::Operation *op) {
        if (FuseStoreAndForward(op, to_be_deleted).succeeded()) {
          LLVM_DEBUG({ llvm::dbgs() << op->getName() << " is fused.\n"; });
        }
      });
    }
  });
  for (auto op : to_be_deleted) op->erase();
}

