// ------------------------------------------------------------------------------------------------
void e544_runOn(dataflow::ProgramUnitOp unit)
{
  dataflow::GetUnitOp curr_unit =
      (*unit.getUnits().begin()).getDefiningOp<dataflow::GetUnitOp>();
  auto comp = dcc::getUnitType(curr_unit);
  if (!is_any_of(comp, L3LU, L3SU)) return;
  unit->walk<WalkOrder::PreOrder>([&](Operation *op) { runOn(op); });
}

