// entry 546/656   level 3   scc 201   138 body lines
// unit: e546_findAndReplaceRedundantIterArgsUsedInConditions
// authority: dcc/src/Transform/Sentient/Utils.cpp:257
// original: LogicalResult findAndReplaceRedundantIterArgsUsedInConditions( mlir::sentient::ForOp loop, std::set<int> &iter_arg_indices_to_delete)
// rust home: crates/compiler/deeptools/src/transform/sentient/utils/mod.rs
// ------------------------------------------------------------------------------------------------
LogicalResult e546_findAndReplaceRedundantIterArgsUsedInConditions(
    mlir::sentient::ForOp loop, std::set<int> &iter_arg_indices_to_delete)
{
  // For any replaceable iterator argument found, keep track of its
  // index in order to remove it.
  for (int i = loop.getNumRegionIterArgs() - 1; i >= 0; i--) {
    Value init_val = loop.getInits()[i];
    Value loop_bound = loop.getBound();
    if (isa<BlockArgument>(init_val) || isa<BlockArgument>(loop_bound))
      continue;
    auto const_init_val =
        llvm::dyn_cast<mlir::sentient::ConstantOp>(init_val.getDefiningOp());
    auto const_loop_bound =
        llvm::dyn_cast<mlir::sentient::ConstantOp>(loop_bound.getDefiningOp());
    if (!const_init_val || !const_loop_bound) continue;

    // The init value must of the same type as the IV.
    if (init_val.getType() != loop.getInductionVar().getType()) continue;

    Operation *yield_op = loop.getLoopBody().front().getTerminator();
    Value yield_operand = yield_op->getOperand(i);
    auto yield_operand_op = yield_operand.getDefiningOp();
    if (!yield_operand_op || !isa<mlir::sentient::AddOp>(yield_operand_op))
      continue;

    auto add_op = llvm::dyn_cast<mlir::sentient::AddOp>(yield_operand_op);
    auto iter_arg = loop.getRegionIterArgs()[i];
    // Retrieve the stride from the YieldOp operand, which should be
    // iter_arg + step or step + iter_arg. Skip this iter arg if the stride
    // is not +/-1 or the YieldOp operand does not use the iter_arg.
    int64_t stride;
    if (add_op.getInp1() == iter_arg) {
      if (dcc::utils::isTargetConstant(add_op.getInp2(), 1))
        stride = 1;
      else if (dcc::utils::isTargetConstant(add_op.getInp2(), -1))
        stride = -1;
      else
        continue;
    } else if (add_op.getInp2() == iter_arg) {
      if (dcc::utils::isTargetConstant(add_op.getInp1(), 1))
        stride = 1;
      else if (dcc::utils::isTargetConstant(add_op.getInp1(), -1))
        stride = -1;
      else
        continue;
    } else
      continue;

    // The only uses of this iter arg must be in the corresponding YieldOp
    // operand or in conditional predicates where the non-iter arg side is a
    // ConstantOp.
    bool skip_iter_arg_replacement = false;
    // IfOps with iter_arg appearing in their predicate.
    llvm::SmallVector<mlir::sentient::IfOp, 4> list_of_if_ops;
    for (auto &use : iter_arg.getUses()) {
      if (auto sentient_if =
              llvm::dyn_cast<mlir::sentient::IfOp>(use.getOwner())) {
        Value non_iter_arg_side = (sentient_if.getLhs() == iter_arg)
                                      ? sentient_if.getRhs()
                                      : sentient_if.getLhs();
        if (isa<BlockArgument>(non_iter_arg_side) ||
            !isa<mlir::sentient::ConstantOp>(
                non_iter_arg_side.getDefiningOp())) {
          skip_iter_arg_replacement = true;
          break;
        }
        list_of_if_ops.push_back(sentient_if);
      } else if (use.getOwner() != yield_operand_op) {
        skip_iter_arg_replacement = true;
        break;
      }
    }
    if (skip_iter_arg_replacement) continue;

    OpBuilder builder(loop);
    builder.setInsertionPointToStart(loop.getBody(0));

    // In order for the iter arg to be replaced directly with the IV, the
    // corresponding predicates must be adjusted.
    int64_t adjustment_val =
        const_loop_bound.getValue() + stride * const_init_val.getValue();
    for (auto sentient_if : list_of_if_ops) {
      Value non_iter_arg_side = (sentient_if.getLhs() == iter_arg)
                                    ? sentient_if.getRhs()
                                    : sentient_if.getLhs();
      unsigned non_iter_arg_opnd_idx =
          (sentient_if.getLhs() == iter_arg) ? 1 : 0;
      auto const_op = llvm::dyn_cast<mlir::sentient::ConstantOp>(
          non_iter_arg_side.getDefiningOp());
      DT_CHECK_MSG(const_op,
                   "Expect non-iter arg side of predicate to be a ConstantOp");
      if (stride == -1) {
        if (adjustment_val == 0) {
          // iter_arg == IV so no adjustment needed.
        } else {
          // iter_arg is
          // IV-adjustment_val = IV-const_loop_bound+const_init_val
          // Change all comparisons involving the iter_arg as follows:
          // if (iter_arg <= c)
          // ==>
          // if (IV <= adjustment_val + c)
          Value updated_const = mlir::sentient::ConstantOp::create(
                                    builder, loop->getLoc(), const_op.getType(),
                                    adjustment_val + const_op.getValue())
                                    .getResult();
          sentient_if.setOperand(non_iter_arg_opnd_idx, updated_const);
        }
      } else {
        // iter_arg is
        // adjustment_val-IV = const_loop_bound+const_init_val-IV
        // Change all comparisons involving the iter_arg as follows:
        // if (iter_arg <= c)
        // ==>
        // if (adjustment_val - c <= IV)
        Value updated_const = mlir::sentient::ConstantOp::create(
                                  builder, loop->getLoc(), const_op.getType(),
                                  adjustment_val - const_op.getValue())
                                  .getResult();
        sentient_if.setOperand(non_iter_arg_opnd_idx, loop.getInductionVar());
        sentient_if.setOperand(1 - non_iter_arg_opnd_idx, updated_const);
      }
    }
    iter_arg.replaceAllUsesWith(loop.getInductionVar());
    iter_arg_indices_to_delete.insert(i);
    yield_op->eraseOperand(i);
    // Remove the add operation if it has no other uses.
    if (add_op->use_empty()) add_op.erase();

    // Replace the ForOp result by init + stride * loop_bound.
    builder.setInsertionPoint(loop);
    Value result_val =
        mlir::sentient::ConstantOp::create(
            builder, loop->getLoc(), init_val.getType(),
            const_init_val.getValue() + stride * const_loop_bound.getValue())
            .getResult();
    loop.getResult(i).replaceAllUsesWith(result_val);
  }
  if (iter_arg_indices_to_delete.empty()) return LogicalResult::failure();
  return LogicalResult::success();
}

