// ------------------------------------------------------------------------------------------------
void e551_updateConstantMutableAddr(
    const EvaluatedValue &new_immut_addr_ev)
{
  ToggleDescriptor &toggle = dtd_.getToggleDescriptor();
  DT_CHECK(
      dcc::utils::isConstant<sentient::ConstantOp>(mutable_addr_[0].get()) &&
      "Expect constant mutable addr");
  // original mutable address
  const EvaluatedValue &const_ma_ev =
      evaluator_.evaluateValue(mutable_addr_[0].get());

  // new_x = toggle.getX() + const_ma_ev - new_immut_addr_ev;
  const EvaluatedValue &new_x = evaluator_.evaluateSub(
      evaluator_.evaluateSum(toggle.getX(), const_ma_ev), new_immut_addr_ev);
  // new_x = toggle.getY() + const_ma_ev - new_immut_addr_ev;
  const EvaluatedValue &new_y = evaluator_.evaluateSub(
      evaluator_.evaluateSum(toggle.getY(), const_ma_ev), new_immut_addr_ev);
  // new_c1 = new_x + new_y
  const EvaluatedValue &new_c1 = evaluator_.evaluateSum(new_x, new_y);
  DEBUG_WITH_TYPE(VerboseDebug,
                  llvm::dbgs() << "new_x = " << new_x << "\nnew_y = " << new_y
                               << ", new_c1 = " << new_c1 << "\n");
  DT_CHECK_MSG(!ps_manager_.overflowsRegister(new_c1, element_size_),
               "LAR/EAR overflow detected");
  DT_CHECK_MSG(toggle_sub_, "expected valid toggle_sub");
  toggle_sub_.getInp1Mutable().assign(
      createOffsetValue(&dtd_.getOperation(), new_c1));
  toggle.getOuterLoop().setIterOperand(
      toggle.getIterArgIndex(), createOffsetValue(&dtd_.getOperation(), new_y));
  mutable_addr_.assign(toggle_sub_.getResult());
}

