// unit: e552_ToggleDescriptor
// authority: dcc/src/Transform/Sentient/AddressPinningAndToggle.cpp:2642
// original: ToggleDescriptor::ToggleDescriptor(ExpressionEvaluator &evaluator, Value base_addr) : DynamicPatternDescriptorBase(PatternKind::kToggle, evaluator)
// rust home: crates/compiler/deeptools/src/transform/sentient/address_pinning_and_toggle/toggle_descriptor.rs
// ------------------------------------------------------------------------------------------------
e552_ToggleDescriptor(ExpressionEvaluator &evaluator,
                                   Value base_addr)
    : DynamicPatternDescriptorBase(PatternKind::kToggle, evaluator)
{
  if (isa<BlockArgument>(base_addr)) {
    DEBUG_WITH_TYPE(
        VerboseDebug,
        llvm::dbgs() << "Expected toggle, but base addr is a block argument\n");
    return;
  }

  auto sub = base_addr.getDefiningOp<sentient::SubOp>();
  if (!sub) {
    DEBUG_WITH_TYPE(VerboseDebug,
                    llvm::dbgs() << "Expected toggle, but didn't find sub\n");
    return;
  }
  auto iter_arg = dyn_cast<BlockArgument>(sub.getInp2());
  if (!(iter_arg &&
        dcc::utils::isConstant<sentient::ConstantOp>(sub.getInp1()))) {
    DEBUG_WITH_TYPE(
        VerboseDebug,
        llvm::dbgs()
            << "Expected toggle, but didn't find sub of the right form\n");
    return;
  }
  auto loop = dyn_cast<sentient::ForOp>(iter_arg.getOwner()->getParentOp());
  if (!loop) {
    DEBUG_WITH_TYPE(VerboseDebug, llvm::dbgs()
                                      << "Expected toggle, but operand of "
                                         "sub is not a loop iterator\n");
    return;
  }
  std::tie(outer_loop_, iter_arg_index_, std::ignore) =
      dcc::utils::getOutermostConstInitialization(iter_arg);

  if (iter_arg_index_ < 0) {
    DEBUG_WITH_TYPE(VerboseDebug,
                    llvm::dbgs() << "Expected toggle, but iter arg init "
                                    "value does not resolve to a constant\n");
    invalidate();
    return;
  }

  int iter_arg_index = dcc::utils::getIndexOfLoopRegionIterArgs(iter_arg);
  auto yield = dyn_cast<sentient::YieldOp>(loop.getBody(0)->getTerminator());
  DT_CHECK_MSG(yield, "expected terminator of loop body to be a yield");
  if (yield.getOperand(iter_arg_index) != base_addr) {
    DEBUG_WITH_TYPE(VerboseDebug,
                    llvm::dbgs()
                        << "Expected toggle, but yield operand doesn't "
                           "match result of sub\n");
    invalidate();
    return;
  }

  c1_ = &evaluator_.evaluateValue(sub.getInp1());
  int num_non_yield_feeding_uses = dcc::utils::getNumUsersExcept(
      base_addr, [&](Operation *op) { return op == yield; });
  DT_CHECK_MSG(
      num_non_yield_feeding_uses == 1,
      "base_addr should only be used in memory op and to feed the yield op");

  DEBUG_WITH_TYPE(VerboseDebug,
                  llvm::dbgs() << "Found toggle between these values:\nX:\n"
                               << getX() << "\nY:\n"
                               << getY() << "\n");
  // If the two values being toggled are identical, then it's not really a
  // toggle.
  setCanBeSimplified(getX() == getY());
}

