void e553_dump() const
{
  raw_ostream &os = llvm::dbgs();
  os << "Toggle Descriptor:\n";
  const char indent = '\t';
  if (!isValid()) {
    os << indent << "Invalid\n";
    return;
  }
  if (canBeSimplified()) os << indent << "(Simplified)\n";
  os << indent << "X = " << getX() << "\n";
  os << indent << "Y = " << getY() << "\n";
  os << indent << "c1 = " << getC1() << "\n";
  os << indent << "outer loop at level ("
     << dcc::utils::getLoopNestLevel<sentient::ForOp>(outer_loop_) << ")\n";
  os << indent << "iter arg index of outer loop: " << iter_arg_index_ << "\n";
}

