// entry 554/656   level 4   scc 103   100 body lines
// unit: e554_runOnOperation
// authority: dcc/src/Transform/Sentient/AddressRegisterPrecisionAssignment.cpp:449
// original: void AddressRegisterPrecisionAssignmentPass::runOnOperation()
// rust home: crates/compiler/deeptools/src/transform/sentient/address_register_precision_assignment/mod.rs
// ------------------------------------------------------------------------------------------------
void e554_runOnOperation()
{
  ModuleOp module_op = getOperation();
  SmallVector<dataflow::ProgramUnitOp, 4> units;

  // Collect the units where this assignment has to be done
  module_op.walk<WalkOrder::PreOrder>([&](dataflow::ProgramUnitOp unit) {
    auto unit_type =
        unit.getUnits()[0].getDefiningOp<dataflow::GetUnitOp>().getType();
    auto record = EnumsConversion::stringToSenComponents.find(unit_type.str());
    if (record != EnumsConversion::stringToSenComponents.end()) {
      if (is_any_of(EnumsConversion::senCompToGenericComp.at(record->second),
                    L0LU, L0SU, LXLU, LXSU, L3LU, L3SU)) {
        units.push_back(unit);
      }
    }
  });

  // Traverse through the IR, initial each Op record in the dictionary, and
  // capture the load and store operations.
  // Note that we cannot merge the initial_ops calculation with adding it to
  // worklist because the use of load/stores may not be already initialized
  // because of preorder walk.
  SmallVector<Operation *> initial_ops;
  for (auto &unit : units) {
    unit.walk<WalkOrder::PreOrder>([&](Operation *op) {
      if (!isa<sentient::LoadAndSendOp, sentient::ReceiveAndStoreOp,
               sentient::LoadAndStoreOp, sentient::LoadAndExtractScalarOp,
               sentient::LoadComputeAndSendOp, sentient::CopyOp,
               sentient::ForOp, sentient::IfOp, sentient::AddOp,
               sentient::SubOp, mlir::uniform::UniformizeRegionsOp>(op))
        return;
      initializePrecision(op);
      if (isa<sentient::LoadAndSendOp, sentient::ReceiveAndStoreOp,
              sentient::LoadAndStoreOp, sentient::LoadAndExtractScalarOp,
              sentient::LoadComputeAndSendOp>(op))
        initial_ops.push_back(op);
    });
  }

  // Initialize the worklist with load and store operations because
  // we know the precision/element_size information.
  for (auto &op : initial_ops) {
    if (auto load_op = llvm::dyn_cast<sentient::LoadAndSendOp>(op)) {
      addToWorkListAndAssignPrecision(load_op.getResult(),
                                      load_op.getElementSize(), load_op);
    } else if (auto store_op =
                   llvm::dyn_cast<sentient::ReceiveAndStoreOp>(op)) {
      addToWorkListAndAssignPrecision(store_op.getResult(),
                                      store_op.getElementSize(), store_op);
    } else if (auto load_store_op =
                   llvm::dyn_cast<sentient::LoadAndStoreOp>(op)) {
      addToWorkListAndAssignPrecision(load_store_op.getResult(0),
                                      load_store_op.getElementSize(),
                                      load_store_op);
      addToWorkListAndAssignPrecision(load_store_op.getResult(1),
                                      load_store_op.getElementSize(),
                                      load_store_op);
    } else if (auto load_extract_op =
                   llvm::dyn_cast<sentient::LoadAndExtractScalarOp>(op)) {
      addToWorkListAndAssignPrecision(load_extract_op.getResult(0),
                                      load_extract_op.getElementSize(),
                                      load_extract_op);
      addToWorkListAndAssignPrecision(load_extract_op.getResult(1),
                                      load_extract_op.getElementSize(),
                                      load_extract_op);
    } else if (auto load_compute_op =
                   llvm::dyn_cast<sentient::LoadComputeAndSendOp>(op)) {
      // For LoadComputeAndSendOps the src_element_size indicates how the
      // address should be calculated.
      addToWorkListAndAssignPrecision(load_compute_op.getResult(),
                                      load_compute_op.getSrcElementSize(),
                                      load_compute_op);
    }
  }

  // Process the worklist.
  while (!worklist_.empty()) {
    auto val = worklist_.front();
    worklist_.pop();
    if (failed(processAddressSSAValue(val))) {
      signalPassFailure();
      break;
    }
  }

  // Assign the precisions into the sentient operations.
  for (auto &record : assignments_) {
    if (isa<sentient::ForOp, sentient::IfOp,
            mlir::uniform::UniformizeRegionsOp>(record.first) ||
        record.second.size() > 1) {
      OpBuilder builder(record.first);
      record.first->setAttr("element_sizes",
                            builder.getI32ArrayAttr(record.second));
    } else {
      OpBuilder builder(record.first);
      record.first->setAttr("element_size",
                            builder.getI32IntegerAttr(record.second.front()));
    }
  }
}

