// entry 556/656   level 4   scc 155   70 body lines
// unit: e556_deuniform
// authority: dcc/src/Transform/Sentient/Deuniform.cpp:375
// original: mlir::dataflow::ProgramUnitOp DeuniformPass::deuniform( mlir::dataflow::ProgramUnitOp prog_unit, std::vector<mlir::dataflow::GetUnitOp> &set_of_units)
// rust home: crates/compiler/deeptools/src/transform/sentient/deuniform/mod.rs
// ------------------------------------------------------------------------------------------------
mlir::dataflow::ProgramUnitOp e556_deuniform(
    mlir::dataflow::ProgramUnitOp prog_unit,
    std::vector<mlir::dataflow::GetUnitOp> &set_of_units)
{
  OpBuilder prog_unit_builder(prog_unit);
  std::vector<mlir::Value> new_units;
  for (auto unit : set_of_units) {
    for (auto fold : unit.getResults()) {
      new_units.push_back(fold);
    }
  }

  mlir::dataflow::ProgramUnitOp new_prog_unit;
  if (prog_unit.getPrecision().has_value())
    new_prog_unit = mlir::dataflow::ProgramUnitOp::create(
        prog_unit_builder, prog_unit.getLoc(), new_units,
        prog_unit.getPrecisionAttr());
  else
    new_prog_unit = mlir::dataflow::ProgramUnitOp::create(
        prog_unit_builder, prog_unit.getLoc(), new_units);

  OpBuilder builder(new_prog_unit.getBodyRegion());
  IRMapping bv_map;
  bv_map.map(prog_unit.getBody()->getArguments(),
             new_prog_unit.getBody()->getArguments());
  for (auto &it : prog_unit.getBody()->getOperations()) {
    if (!isa<mlir::dataflow::ReturnOp>(it)) builder.clone(it, bv_map);
  }
  DT_CHECK(new_prog_unit.getUnits().size() > 0);
  std::vector<mlir::Operation *> to_be_deleted, new_ops;
  new_prog_unit.walk<WalkOrder::PreOrder>([&](mlir::Operation *op) {
    if (std::find(new_ops.begin(), new_ops.end(), op) == new_ops.end()) {
      if (auto query_map_op = llvm::dyn_cast<mlir::uniform::QueryMapOp>(op)) {
        builder.setInsertionPointAfter(op);
        auto new_query_map_op = duplicateAndUpdateEntriesOfQueryMap(
            query_map_op, new_units, builder);
        new_ops.push_back(new_query_map_op);
        query_map_op.replaceAllUsesWith(new_query_map_op.getOperation());
        auto map_op = query_map_op.getMap().getDefiningOp();
        to_be_deleted.push_back(query_map_op);
        int num_users = 0;
        for (auto user : map_op->getUsers()) num_users++;
        if (num_users <= 1) to_be_deleted.push_back(map_op);
      } else if (auto uniform_op =
                     llvm::dyn_cast<mlir::uniform::UniformizeRegionsOp>(op)) {
        builder.setInsertionPointAfter(op);
        auto new_op = duplicateAndUpdateRegionsOfLocalRegionOps(
            uniform_op, new_units, builder, to_be_deleted);
        if (new_op) {
          DT_CHECK(isa<mlir::uniform::UniformizeRegionsOp>(new_op));
          uniform_op.replaceAllUsesWith(new_op);
          to_be_deleted.push_back(uniform_op);
          new_ops.push_back(new_op);
        }
        return mlir::WalkResult::skip();
      } else if (auto eq_pattern_op =
                     llvm::dyn_cast<mlir::uniform::EqualizePatternOp>(op)) {
        builder.setInsertionPointAfter(op);
        auto new_op = duplicateAndUpdateRegionsOfLocalRegionOps(
            eq_pattern_op, new_units, builder, to_be_deleted);
        if (new_op) {
          DT_CHECK(isa<mlir::uniform::EqualizePatternOp>(new_op));
          to_be_deleted.push_back(eq_pattern_op);
          new_ops.push_back(new_op);
        }
        return mlir::WalkResult::skip();
      }
    }
    return mlir::WalkResult::advance();
  });
  for (auto op : to_be_deleted) op->erase();
  return new_prog_unit;
}

