// entry 557/656   level 4   scc 167   57 body lines
// unit: e557_exploreOperation
// authority: dcc/src/Transform/Sentient/EnhancedDeadVariableElimination.cpp:367
// original: void EnhancedDeadVariableEliminationPass::exploreOperation(Operation *op)
// rust home: crates/compiler/deeptools/src/transform/sentient/enhanced_dead_variable_elimination/mod.rs
// ------------------------------------------------------------------------------------------------
void e557_exploreOperation(Operation *op)
{
  // explore its region before exploring itself
  for (auto &region : op->getRegions()) {
    // Sometimes, there could be empty blocks inside the region.
    if (!region.empty()) {
      exploreBlock(&region.front());
    }
  }

  if (op->getNumResults() == 0) {
    // If it's an yield op, then remove operand early so that before SSA
    // variables will not have any uses.
    // Perform deletion in the reverse way since the list gets updated
    if (isa<sentient::YieldOp, uniform::YieldOp>(op)) {
      for (int i = op->getNumOperands() - 1; i >= 0; i--) {
        Operation *parent_op = op->getParentOp();
        if (auto for_op = llvm::dyn_cast<sentient::ForOp>(parent_op)) {
          // If the parent for-op iterator argument and corresponding result
          // have no influence, then also we can safely remove this operand
          // even though it has an influence. We are only removing the
          // operand, but not the definition.
          if (getInfluenceType(for_op.getResult(i)) == kNone &&
              getInfluenceType(for_op.getRegionIterArgs()[i]) == kNone)
            op->eraseOperand(i);
        } else if (getInfluenceType(parent_op->getResult(i)) == kNone) {
          // For an IfOp or UniformizeRegionsOp parent, if the result has no
          // influence, then we can safely remove this operand.
          op->eraseOperand(i);
        }
      }
    }

    return;
  }

  // Check for operations that we are interested to delete.
  if (!dcc::utils::mayHaveSideEffects(op)) {
    bool may_be_deleted = true;
    // Check if the results have influence on subsequent operations
    for (unsigned i = 0; i < op->getNumResults(); ++i) {
      auto result = op->getResult(i);
      if (getInfluenceType(result) != kNone) {
        may_be_deleted = false;
        break;
      }
    }

    if (op->use_empty() && may_be_deleted) op->erase();
  } else if (auto for_op = llvm::dyn_cast<sentient::ForOp>(op)) {
    updateForOperation(for_op);
  } else if (auto if_op = llvm::dyn_cast<sentient::IfOp>(op)) {
    updateIfOperation(if_op);
  } else if (auto uniform_op =
                 llvm::dyn_cast<uniform::UniformizeRegionsOp>(op)) {
    updateUniformizeRegionsOperation(uniform_op);
  }
}

// ------------------------------------------------------------------------------------------------
// entry 558/656   level 4   scc 167   23 body lines
// unit: e558_exploreBlock
// authority: dcc/src/Transform/Sentient/EnhancedDeadVariableElimination.cpp:426
// original: void EnhancedDeadVariableEliminationPass::exploreBlock(Block *block)
// rust home: crates/compiler/deeptools/src/transform/sentient/enhanced_dead_variable_elimination/mod.rs
// ------------------------------------------------------------------------------------------------
void e558_exploreBlock(Block *block)
{
  auto &operations = block->getOperations();
  if (operations.empty()) {
    return;
  }

  llvm::SmallVector<mlir::Operation *, 8> ops_in_reverse;

  // Traverse in reverse order and add it to the list
  auto eit = operations.rend();
  for (auto it = operations.rbegin(); it != eit; ++it) {
    auto &op = *it;
    ops_in_reverse.push_back(&op);
  }

  // process each operation
  // The reason for adding into a separate list is that some of the operations
  // are going to be deleted and operating directly over getOperations
  // results in segfaults.
  for (auto &op : ops_in_reverse) {
    exploreOperation(op);
  }
}

