// entry 560/656   level 4   scc 216   28 body lines
// unit: e560_reduceLiveRange
// authority: dcc/src/Transform/Sentient/LiveRangeReduction.cpp:885
// original: void LiveRangeReductionPass::reduceLiveRange(PropagationAnalysis& expr_prop, Operation* unit_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/live_range_reduction/mod.rs
// ------------------------------------------------------------------------------------------------
void e560_reduceLiveRange(PropagationAnalysis& expr_prop,
                                             Operation* unit_op)
{
  // find dominance info starting from unit_op
  DominanceInfo dominance_info(unit_op);

  // traverse through ssa_value_list_ to do live range reduction on all SSA
  // values
  for (int i = 0; i < ssa_value_list_.size(); i++) {
    auto& ssa_list = ssa_value_list_[i];
    for (int current_value_index = 1; current_value_index < ssa_list.size();
         current_value_index++) {
      int dominant_value_index;
      // no update on iter_arg ssa
      if (mlir::isa<BlockArgument>(ssa_list[current_value_index])) continue;
      auto result = findDominantValue(ssa_list, current_value_index,
                                      dominant_value_index, dominance_info);
      if (result.succeeded()) {
        auto result = reconstructOperation(ssa_list, current_value_index,
                                           dominant_value_index);
        if (result.failed()) {
          auto op = ssa_list[current_value_index].getDefiningOp();
          op->emitError("Failed in reconstructing the following operation!");
          op->dump();
          signalPassFailure();
        }
      }
    }
  }
}

