// entry 561/656   level 4   scc 232   19 body lines
// unit: e561_run
// authority: dcc/src/Transform/Sentient/LocalRegionSplittingForValueCommoning.cpp:252
// original: void LocalRegionSplittingForValueCommoningPass::run( const SentientRegType locale, const SenComponents comp)
// rust home: crates/compiler/deeptools/src/transform/sentient/local_region_splitting_for_value_commoning/mod.rs
// ------------------------------------------------------------------------------------------------
void e561_run(
    const SentientRegType locale, const SenComponents comp)
{
  // collect all uniformized regions:
  SmallVector<uniform::UniformizeRegionsOp> uniform_regions_ops;
  program_unit_->walk<WalkOrder::PreOrder>(
      [&](uniform::UniformizeRegionsOp ur) {
        uniform_regions_ops.push_back(ur);
      });
  // For each one analyze it to find out what local regions need replacing
  // (and how ie clustering). Form an abstraction to represent the desired
  // outcome, then create a new uniformized region using the original(old) one
  // as template to clone from, and once done replace and remove it.
  for (uniform::UniformizeRegionsOp uniform : uniform_regions_ops) {
    lrs::UniformRegion new_uniform(uniform);
    if (analyze(new_uniform, locale, comp)) {
      LLVM_DEBUG(new_uniform.dump());
      transform(new_uniform);
    }
  }
}

