        LLVM_DEBUG(llvm::dbgs()
                   << "found a perfect nest of candidates with depth "
                   << loops.size() << '\n');

        // Make sure all operands of all candidate loops are defined above the
        // outermost one SmallVector<unsigned, 4>
        // This condition is no longer required because the operands of for-op
        // 1. Bound being constant (doesn't matter where it is defined)
        // 2. Iterator arguments (we considered that in the getCandidate loops).
        //        for (unsigned i = 0, e = loops.size(); i < e; ++i) {
        //          if (!areValuesDefinedAbove(loops[i].getOperands(),
