// entry 566/656   level 4   scc 298   117 body lines
// unit: e566_getSavedCycleAndIbuffCost
// authority: dcc/src/Transform/Sentient/LoopSplittingAndUnrolling.cpp:335
// original: std::pair<int, int> LoopSplittingAndUnrollingPass::getSavedCycleAndIbuffCost( dcc::LoopNode *loop, InstructionEstimatorImpl &ie, dataflow::ProgramUnitOp &unit, std::pair<int, int> &is_splitting)
// rust home: crates/compiler/deeptools/src/transform/sentient/loop_splitting_and_unrolling/mod.rs
// ------------------------------------------------------------------------------------------------
std::pair<int, int> e566_getSavedCycleAndIbuffCost(
    dcc::LoopNode *loop, InstructionEstimatorImpl &ie,
    dataflow::ProgramUnitOp &unit, std::pair<int, int> &is_splitting)
{
  if (is_splitting.first == 0 and is_splitting.second == 0) {
    if (can_not_split_.find(loop->getOperation()) != can_not_split_.end()) {
      // previously marked as not splittable return highest cost
      return {1, INT_MAX};
    }
  } else {
    if (can_not_unroll_.find(loop->getOperation()) != can_not_unroll_.end()) {
      // previously marked as not unrollable return highest cost
      return {1, INT_MAX};
    }
  }
  int saved_cycles_, iBuff_cost_;
  auto for_op = llvm::dyn_cast<sentient::ForOp>(loop->getOperation());
  auto bound =
      for_op.getBound().getDefiningOp<sentient::ConstantOp>().getValue();
  if (is_splitting.first == 0 && is_splitting.second == 0 && ifOpUsesIV(loop)) {
    // Finds optimal N way split
    int index, nway_split, num_if_op;
    std::tie(index, nway_split, num_if_op, iBuff_cost_) =
        findOptimalNWaySplits(loop, ie, unit);
    if (index == 0 && nway_split == 0)
      // set high ibuff cost so it does not consider splitting
      return {1, INT_MAX};
    // Considering each IfOp takes 2 cycle
    saved_cycles_ = 2 * bound * (num_if_op);
    // calculate split gain/loss
    auto parent = loop->getParentLoop();
    // calculating saved cycles.
    // If statement saving calculation started from it's linked loop.
    while (parent->getOperation()) {
      auto parent_for_op =
          llvm::dyn_cast<sentient::ForOp>(parent->getOperation());
      if (auto const_op =
              parent_for_op.getBound().getDefiningOp<sentient::ConstantOp>())
        saved_cycles_ *= const_op.getValue();
      else
        // TODO: how much cycle we save when bound not constant?
        ;
      parent = parent->getParentLoop();
    }
  } else if (is_splitting.first == 0 && is_splitting.second == 0 &&
             !ifOpUsesIV(loop)) {
    // set high ibuff cost so it does not consider splitting
    return {1, INT_MAX};
  } else {
    // calculate loop unrolling gain/loss, by unroll factor
    saved_cycles_ = 1;
    auto cop = for_op.getBound().getDefiningOp<sentient::ConstantOp>();
    iBuff_cost_ =
        ie.getEstimatedInstructionCount(dccExtContext(), for_op.getBody()) *
        cop.getValue();
    auto parent = loop->getParentLoop();
    while (parent->getOperation()) {
      auto parent_for_op =
          llvm::dyn_cast<sentient::ForOp>(parent->getOperation());
      if (auto const_op =
              parent_for_op.getBound().getDefiningOp<sentient::ConstantOp>())
        saved_cycles_ *= const_op.getValue();
      else
        // TODO: how much cycle we save when bound not constant?
        ;
      parent = parent->getParentLoop();
    }

    // Removing loops with size 1.
    if (cop && cop.getValue() == 1) return {saved_cycles_, -2};

    // Tweaking heuristics only for loop unrolling.
    bool is_sfp_pe = false, is_pt = false, is_lxlu_lxsu = false,
         is_l3lu_l3su = false, is_l0lu_l0su = false;
    for (const auto &get_unit_op : unit.getUnits()) {
      auto comp =
          dcc::getUnitType(get_unit_op.getDefiningOp<dataflow::GetUnitOp>());
      if (is_any_of(comp, SFP, PE)) {
        is_sfp_pe = true;
        saved_cycles_ -= std::ceil(iBuff_cost_ / 2.0);
        break;
      } else if (is_any_of(comp, PT)) {
        is_pt = true;
        saved_cycles_ -= std::ceil(iBuff_cost_ / 4.0);
        break;
      } else if (is_any_of(comp, LXLU, LXSU)) {
        is_lxlu_lxsu = true;
        saved_cycles_ -= std::ceil(iBuff_cost_ / 4.0);
        break;
      } else if (is_any_of(comp, L3LU, L3SU)) {
        is_l3lu_l3su = true;
        saved_cycles_ -= std::ceil(iBuff_cost_ / 4.0);
        break;
      } else if (is_any_of(comp, L0LU, L0LUROW0, L0SU)) {
        is_l0lu_l0su = true;
        saved_cycles_ -= std::ceil(iBuff_cost_ / 4.0);
        break;
      }
    }

    // setting minimum threshold of saved_cycles_ / iBuff_cost_
    // PT is priority because flits for PT are added separately.
    // SFP and PE are important because to reduce space and enable program
    // stitching LXLU and LXSU are important because they are on critical path
    // of a total binary size for compute ops.
    // L0LUROW0 could be on the critical path if LXLU programs are restricted
    // on the unrolling.
    // L3LU and L3SU to further restrict in case of data-ops as they could
    // be on the critical path of a total binary size.
    if (is_pt || is_sfp_pe || is_lxlu_lxsu || is_l0lu_l0su || is_l3lu_l3su) {
      int min_cycles = (is_pt) ? 10 : 25;  // min threshold
      if (saved_cycles_ < min_cycles) {
        // set high ibuff cost so it does not consider splitting
        return {1, INT_MAX};
      }
    }
  }

  return {saved_cycles_, iBuff_cost_};
}

