// entry 568/656   level 4   scc 310   49 body lines
// unit: e568_computePeelingInfo
// authority: dcc/src/Transform/Sentient/MultiDimLoopPeeling.cpp:351
// original: std::pair<sentient::ForOp, LoopPeelingManager::PeelingType> LoopPeelingManager::computePeelingInfo(sentient::IfOp if_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/multi_dim_loop_peeling/loop_peeling_manager.rs
// ------------------------------------------------------------------------------------------------
std::pair<sentient::ForOp, LoopPeelingManager::PeelingType>
e568_computePeelingInfo(sentient::IfOp if_op)
{
  // If one side is an IV and the other a constant, retrieve the
  // constant and ForOp info.
  auto tuple = getOrCreateTupleForIV(if_op.getLhs());
  sentient::ConstantOp const_side = nullptr;
  bool rhs_is_const = true;
  if (!isa<BlockArgument>(if_op.getRhs()))
    const_side =
        llvm::dyn_cast<sentient::ConstantOp>(if_op.getRhs().getDefiningOp());

  if (!std::get<0>(tuple) || !const_side) {
    tuple = getOrCreateTupleForIV(if_op.getRhs());
    if (!isa<BlockArgument>(if_op.getLhs())) {
      const_side =
          llvm::dyn_cast<sentient::ConstantOp>(if_op.getLhs().getDefiningOp());
      rhs_is_const = false;
    }
  }
  // Do not peel if loop has bound 0 or 1. The loop will be simplified/removed
  // by LightweightSimplifications.
  if (!std::get<0>(tuple) || !const_side || std::get<1>(tuple) <= 1) {
    return {nullptr, LoopPeelingManager::PeelingType::kNoPeeling};
  }

  // Determine the peeling type from the comparison.
  sentient::ForOp for_op = llvm::dyn_cast<sentient::ForOp>(std::get<0>(tuple));
  int64_t first_val = std::get<1>(tuple);
  int64_t last_val = std::get<2>(tuple);
  DT_CHECK_MSG(last_val == 1, "All induction variables' last value is 1");
  // Predicate of the comparison with the iv on the LHS, constant on the RHS.
  auto predicate = rhs_is_const
                       ? if_op.getPredicate()
                       : dcc::utils::reversePredicate(if_op.getPredicate());
  if (const_side.getValue() == first_val &&
      is_any_of(predicate, CmpIPredicate::sge, CmpIPredicate::eq,
                CmpIPredicate::ne, CmpIPredicate::slt))
    return {for_op, LoopPeelingManager::PeelingType::kFirstIterOnly};
  else if (const_side.getValue() == first_val - 1 &&
           is_any_of(predicate, CmpIPredicate::sgt, CmpIPredicate::sle))
    return {for_op, LoopPeelingManager::PeelingType::kFirstIterOnly};
  else if (const_side.getValue() == last_val &&
           is_any_of(predicate, CmpIPredicate::sgt, CmpIPredicate::eq,
                     CmpIPredicate::ne, CmpIPredicate::sle))
    return {for_op, LoopPeelingManager::PeelingType::kLastIterOnly};
  else if (const_side.getValue() == last_val + 1 &&
           is_any_of(predicate, CmpIPredicate::sge, CmpIPredicate::slt))
    return {for_op, LoopPeelingManager::PeelingType::kLastIterOnly};
  return {nullptr, LoopPeelingManager::PeelingType::kNoPeeling};
}

