// authority: dcc/src/Transform/Sentient/MulticastCanonicalization.cpp:327
// original: void MulticastCanonicalizationPass::runOn(sentient::ReceiveAndStoreOp ras)
// rust home: crates/compiler/deeptools/src/transform/sentient/multicast_canonicalization/mod.rs
// ------------------------------------------------------------------------------------------------
void e569_runOn(sentient::ReceiveAndStoreOp ras)
{
  if (isa<BlockArgument>(ras.getProducer())) return;

  // skip if multicast info is already set.
  if (ras.getMulticastInfo()) return;

  if (auto direct_multicast = dyn_cast<dataflow::CreateMulticastGroupOp>(
          ras.getProducer().getDefiningOp())) {
    LLVM_DEBUG(llvm::dbgs() << "-----------------------------------------\n"
                            << "direct multicast producer operand:"
                            << ras.getProducer() << "\n");

    processDirectMulticast(ras, direct_multicast);

    LLVM_DEBUG(llvm::dbgs()
               << "new producer operand:" << ras.getProducer() << "\n"
               << "new multicast_info operand:" << ras.getMulticastInfo()
               << "\n-----------------------------------------\n");
  } else if (auto q_map = dyn_cast<uniform::QueryMapOp>(
                 ras.getProducer().getDefiningOp())) {
    if (llvm::all_of(
            dcc::uniform::utils::getListOfValueOpsFromUniformMapping(q_map),
            [](Value v) {
              return !isa<BlockArgument>(v) &&
                     isa<dataflow::CreateMulticastGroupOp>(v.getDefiningOp());
            }))
      processQMapOfDirectMulticast(ras, q_map);
  } else if (auto top_if_op =
                 dyn_cast<sentient::IfOp>(ras.getProducer().getDefiningOp())) {
    LLVM_DEBUG(llvm::dbgs()
               << "-----------------------------------------\n"
               << "analyzing producer if-op:" << top_if_op << "\n");

    processConditional(ras, top_if_op);

    LLVM_DEBUG(llvm::dbgs()
               << "new producer result index: "
               << dcc::utils::getIndexOfOperationResults(ras.getProducer())
               << "\nnew multicast result index: "
               << dcc::utils::getIndexOfOperationResults(ras.getMulticastInfo())
               << "\n-----------------------------------------\n");
  }
}

