// unit: e571_runOpRerolling
// authority: dcc/src/Transform/Sentient/OpRerolling.cpp:1008
// original: void OpRerollingPass::runOpRerolling(Operation *op, bool merge_xrf_into_mac)
// rust home: crates/compiler/deeptools/src/transform/sentient/op_rerolling/mod.rs
// ------------------------------------------------------------------------------------------------
void e571_runOpRerolling(Operation *op, bool merge_xrf_into_mac)
{
  dataflow::ProgramUnitOp unit_op =
      isa<dataflow::ProgramUnitOp>(op)
          ? llvm::dyn_cast<dataflow::ProgramUnitOp>(op)
          : op->getParentOfType<dataflow::ProgramUnitOp>();
  DT_CHECK(unit_op.getUnits().size() >= 1);
  auto unit_type = dcc::getUnitType(
      unit_op.getUnits()[0].getDefiningOp<dataflow::GetUnitOp>());

  if (is_any_of(unit_type, SFP, PE, PT, LX, L0, LXLU, LXSU, L0LU, L0SU)) {
    // DD2 hardware bug: Hardware seems to behave incorrectly in presence
    // of implicit tile size granularity smaller than burst size. There are two
    // source of burst opportunities - 1) OpRerolling, 2) Loop Elimination via
    // Rerolling, and 3) Composite loads/stores. We are guaranteed that burst
    // from composite load/store wouldn't go beyond implicit tile size. Hence,
    // we are restricting no rerolling of LDST operations within L0LU and L0SU
    // for DD2 by disabling in OpRerolling and LEVR passes.
    if (dccExtContext().getArch() == RCUDD1A_ISA &&
        is_any_of(unit_type, L0, L0LU, L0SU))
      return;
    op->walk<WalkOrder::PostOrder>(
        [&](Block *bb) { processOneBlock(unit_type, bb); });
  }

  // after rerolling ops, merge scalar_add/sub to its preceding mac
  if (unit_type == PT && merge_xrf_into_mac) {
    mergeScalarOpIntoMac(unit_op.getBody());
  }
}

