// entry 575/656   level 4   scc 451   28 body lines
// unit: e575_runOnOperation
// authority: dcc/src/Transform/Sentient/RemoveRedundantConditionals.cpp:295
// original: void RemoveRedundantConditionalsPass::runOnOperation()
// rust home: crates/compiler/deeptools/src/transform/sentient/remove_redundant_conditionals/mod.rs
// ------------------------------------------------------------------------------------------------
void e575_runOnOperation()
{
  if (DisableThisPass) return;
  LLVM_DEBUG(llvm::dbgs() << "Remove Redundant Conditionals Pass\n");
  ModuleOp module_op = getOperation();
  module_op.walk<WalkOrder::PreOrder>([&](dataflow::ProgramUnitOp unit_op) {
    Operation *unit = unit_op.getOperation();
    dcc::ConditionalTree tree(*unit);
    tree.compute();
    if (tree.empty()) return;

    llvm::SmallVector<Operation *, 4> to_be_deleted;

    auto simplify = [&](dcc::CondNode *n) -> dcc::CondNode * {
      if (n->isThenNode() || n->isElseNode() || !n->getOperation())
        return nullptr;
      auto if_op = llvm::dyn_cast<sentient::IfOp>(n->getOperation());
      if (if_op) {
        RedundantConditionalManager instance(if_op, to_be_deleted);
        instance.processIfOp();
      }
      return nullptr;
    };

    dcc::CondNode::walk<OperationNode::WalkOrder::kPostOrder>(tree.getRoot(),
                                                              simplify);
    for (auto op : to_be_deleted) op->erase();
  });
}

// ------------------------------------------------------------------------------------------------
// entry 576/656   level 4   scc 471   67 body lines
// unit: e576_runOn
// authority: dcc/src/Transform/Sentient/ScalarCopyInsertionForSymbols.cpp:148
// original: void ScalarCopyInsertionForSymbolsPass::runOn(dataflow::ProgramUnitOp unit)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_copy_insertion_for_symbols/mod.rs
// ------------------------------------------------------------------------------------------------
void e576_runOn(dataflow::ProgramUnitOp unit)
{
  DEBUG_WITH_TYPE(VerboseDebug, {
    llvm::dbgs() << "Register Pressure before pessimizing liveness:\n";
    RegisterPressureAnalysis &rp =
        getChildAnalysis<RegisterPressureAnalysis>(unit);
    rp.setDccContext(dccExtContext());
    rp.computeRegisterPressureForAllLocales();
    rp.dump();
  });

  // Overall algorithm:
  // 1. collect all scalar_copy's and outermost loop ops.
  // 2. collect a list of symbols and mappings from symbol to list
  //    of locales and uses.
  // 3. for each locale that is symbolic, modify liveness to assume
  //    (conservatively) that all
  //   3.1 scalar_copy's of the corresponding locale are promoted to header
  //   3.2 iterargs of the outermost loops with matching locale are promoted
  //       to header
  // 4. analyze register pressure for all symbolic locales + JCRs given the
  //    pessimized liveness.
  // 5. choosen candidates based on profitability criteria (eg num uses, etc)
  //    and number of available registers for the given locale.
  // 6. for chosen candidates create scalar_copy's and replace the uses
  //    that match the candidate locales.

  // Symbols are only expected at function scope after specialized
  // canonicalization
  LLVM_DEBUG(llvm::dbgs() << "num global symbols (seen so far):"
                          << symbols_.size() << "\n");
  collectOpsOfInterest(unit);
  LLVM_DEBUG(
      llvm::dbgs() << "num query_symbol ops:" << symbol_queries_.size() << "\n"
                   << "num scalar_copy ops:" << scalar_copy_ops_.size() << "\n"
                   << "num outermost loops:" << outermost_loops_.size()
                   << "\n");
  collectSymbolUsage(unit);
  LLVM_DEBUG({
    dumpSymbolicLocales();
    dumpSymbolUsageInfo();
  });

  // Obtain liveness and pessimize it. Note that since this pass does not
  // preserve liveness, the changes made in the liveness object will not affect
  // downstream transformations.
  Liveness liveness = getChildAnalysis<Liveness>(unit);
  pessimizeLiveness(liveness);

  // Analyze register pressure using the pessimized liveness
  RegisterPressure rp(unit, liveness, &dccExtContext());
  DEBUG_WITH_TYPE(VerboseDebug, {
    llvm::dbgs() << "Register Pressure after pessimizing liveness:\n";
    rp.computeRegisterPressureForAllLocales();
    rp.dump();
  });

  CandidateListTy candidates;
  collectCandidates(unit, candidates, rp);
  LLVM_DEBUG({
    llvm::dbgs()
        << "Selected the following candidates for copy-op insertion:\n";
    dumpCandidates(candidates);
  });

  insertCopyOpsForCandidates(unit, candidates);
  return;
}

// ------------------------------------------------------------------------------------------------
// entry 577/656   level 4   scc 487   26 body lines
// unit: e577_collectBlocks
// authority: dcc/src/Transform/Sentient/ScalarOpMergingAndHoisting.cpp:869
// original: void ScalarOpMerging::collectBlocks()
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_merging.rs
// ------------------------------------------------------------------------------------------------
void e577_collectBlocks()
{
  // Operations are analyzed through operand chains, not sequentially. Keep
  // track of analyzed Operations in the Region to avoid analyzing Operations
  // multiple times.
  std::unordered_set<Operation *> analyzed_ops;

  // Search bottom up for a scalar add/sub operating on a constant. This
  // Operation will be the merging candidate. Attempt to build a Scalar Op
  // Merging block from this merging candidate.
  for (auto block_it = region_.rbegin(); block_it != region_.rend();
       ++block_it) {
    for (auto op_it = block_it->rbegin(); op_it != block_it->rend(); ++op_it) {
      Operation *op = &*op_it;

      // If the operation has already been analyzed, skip it.
      // TODO: Replace with contains() when supported (C++20 feature).
      if (analyzed_ops.find(op) != analyzed_ops.end()) continue;
      analyzed_ops.insert(op);

      if (isa<sentient::AddOp, sentient::SubOp>(op))
        buildBlock(op, analyzed_ops);
      else
        continue;
    }
  }
}

