// ------------------------------------------------------------------------------------------------
void e579_runOn(dataflow::ProgramUnitOp unit_op)
{
  dataflow::GetUnitOp get_unit_op = dyn_cast_or_null<dataflow::GetUnitOp>(
      unit_op.getUnits().front().getDefiningOp());
  DT_CHECK_MSG(get_unit_op, "Cannot determine GetUnitOp!");
  SenComponents unit_comp = dcc::getUnitType(get_unit_op);
  unit_op_ = unit_op;
  // Skip the transformation if the ReorderInIncludedUnitsOnly flag is on
  // and if the pass's include list does not contain this unit's type.
  if (ReorderInIncludedUnitsOnly && opts_.isIncludeList() &&
      opts_.getInclExclList().count(unit_comp) == 0)
    return;

  computeOpIndexing(unit_op);
  findAndProcessCandidates(unit_op);
}

