// entry 580/656   level 4   scc 200   25 body lines
// unit: e580_runOldLightWeightSimplifications
// authority: dcc/src/Transform/Sentient/ScalarSimplifications.cpp:690
// original: LogicalResult sentient::runOldLightWeightSimplifications(Operation* op)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_simplifications/sentient.rs
// ------------------------------------------------------------------------------------------------
LogicalResult e580_runOldLightWeightSimplifications(Operation* op)
{
  PropagationAnalysis prop_analysis(op);
  if (failed(prop_analysis.isPropagationSuccessful())) {
    return LogicalResult::failure();
  }

  OpBuilder builder(op);
  if (op->getNumRegions() > 0) {
    if (isa<uniform::UniformizeRegionsOp, uniform::EqualizePatternOp>(op))
      op = op->getParentOp();
    builder.setInsertionPointToStart(&op->getRegion(0).front());
  }

  std::vector<mlir::Operation*> tobe_deleted;
  op->walk<WalkOrder::PreOrder>([&](Operation* op) {
    lightWeightSimplifyBinaryArithmetic(builder, prop_analysis, op,
                                        tobe_deleted);
  });

  for (auto tmp_op : tobe_deleted) {
    tmp_op->erase();
  }

  return LogicalResult::success();
}

// ------------------------------------------------------------------------------------------------
// entry 581/656   level 4   scc 527   54 body lines
// unit: e581_runOnOperation
// authority: dcc/src/Transform/Sentient/ScalarSimplifications.cpp:872
// original: void ScalarSimplificationsPass::runOnOperation()
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_simplifications/mod.rs
// ------------------------------------------------------------------------------------------------
void e581_runOnOperation()
{
  if (DisableThisPass) return;
  ModuleOp module_op = getOperation();
  PropagationAnalysis& expr_prop_analysis = getAnalysis<PropagationAnalysis>();

  if (failed(expr_prop_analysis.isPropagationSuccessful())) {
    module_op->emitError("Unable to perform expression propagation");
    signalPassFailure();
  }

  module_op->walk<WalkOrder::PreOrder>([&](dataflow::ProgramUnitOp unit) {
    InstructionEstimator& instruction_estimator =
        getChildAnalysis<InstructionEstimator>(unit);
    if (opts_.OptLevel == 0 &&
        instruction_estimator.haveIbuffSpace(dccExtContext(), unit)) {
      return;
    }
    OpBuilder const_builder(unit);
    const_builder.setInsertionPointToStart(unit.getBody(0));
    unit->walk<WalkOrder::PreOrder>([&](Operation* op) {
      if (auto if_op = llvm::dyn_cast<sentient::IfOp>(op)) {
        simplifyConditionals(expr_prop_analysis, if_op, const_builder);
      }
    });

    // TODO: Enable for PT and fix the live range reduction pass by considering
    // MacOP involing XRF pointers.
    //    if
    //    (!unit.units()[0].getDefiningOp<dataflow::GetUnitOp>().type().contains(
    //            "PT")) {
    const_builder.setInsertionPointToStart(unit.getBody(0));
    std::vector<mlir::Operation*> tobe_deleted;
    unit->walk<WalkOrder::PreOrder>([&](Operation* op) {
      if (auto add_op = llvm::dyn_cast<sentient::AddOp>(op)) {
        // add_op->dump();
        simplifyBinaryOperation(const_builder, add_op,
                                add_op.getInp1().getType(), expr_prop_analysis,
                                tobe_deleted);
      } else if (auto sub_op = llvm::dyn_cast<sentient::SubOp>(op)) {
        simplifyBinaryOperation(const_builder, sub_op,
                                sub_op.getInp1().getType(), expr_prop_analysis,
                                tobe_deleted);
      } else if (isa<sentient::LoadAndSendOp, sentient::ReceiveAndStoreOp,
                     sentient::LoadAndStoreOp, sentient::LoadAndExtractScalarOp,
                     sentient::LoadComputeAndSendOp>(op)) {
        simplifyLoadStoreOperation(expr_prop_analysis, const_builder, op);
      }
    });

    for (auto op : tobe_deleted) op->erase();
  });

  markAnalysesPreserved<PropagationAnalysis>();
}

