// entry 585/656   level 4   scc 618   35 body lines
// unit: e585_runOnOperation
// authority: dcc/src/Transform/Sentient/TransformForExposedPipeline.cpp:341
// original: void TransformForExposedPipelinePass::runOnOperation()
// rust home: crates/compiler/deeptools/src/transform/sentient/transform_for_exposed_pipeline/mod.rs
// ------------------------------------------------------------------------------------------------
void e585_runOnOperation()
{
  if (DisableThisPass) return;
  ModuleOp module_op = getOperation();

  std::vector<dataflow::ProgramUnitOp> pt_units;
  module_op.walk<WalkOrder::PreOrder>([&](dataflow::ProgramUnitOp unit_op) {
    auto comp = dcc::getUnitType(
        unit_op.getUnits()[0].getDefiningOp<dataflow::GetUnitOp>());
    if (comp == PT) pt_units.push_back(unit_op);
  });

  for (auto &unit : pt_units) {
    // Traverse the IR and clean up an sentient.nop operations inserted.
    std::vector<sentient::NOPOp> nop_ops;
    unit.walk<WalkOrder::PreOrder>(
        [&](sentient::NOPOp nop_op) { nop_ops.push_back(nop_op); });
    for (auto &nop_op : nop_ops) {
      nop_op->erase();
    }

    // Perform analysis and insert nop operations
    auto precision = unit.getPrecision();
    int cycles = sentient::getCyclesForExposedPipeline(
        precision->str(), dccExtContext().getArch());

    // Covering the exiting FMA operation
    cycles -= 1;
    TimeStamp ts_analyzer(unit);
    computeDependencies(dccExtContext(), ts_analyzer, cycles, precision->str());
    if (!dependencies_with_min_gap_.empty()) {
      insertNOPOperations(cycles);
    }
    cleanUp();  // clear lists including dependencies_with_min_gap_
  }
}

