// rust home: crates/compiler/deeptools/src/transform/sentient/address_pinning_and_toggle/mod.rs
// ------------------------------------------------------------------------------------------------
const EvaluatedValue &e590_getMax() const
{
    DT_CHECK_MSG(pattern_desc_, "Expect valid pattern descriptor");
    auto &ev = pattern_desc_->getMax();
    const EvaluatedValue &burst_incr =
        evaluator_.getConstant(increment_via_burst_);
    auto &ev_sum_with_burst = evaluator_.evaluateSum(ev, burst_incr);

    // The maximum is the pattern's maximum value if total_chain_increment_ < 0
    // otherwise it is their sum.
    if (total_chain_increment_ < 0) return ev_sum_with_burst;
    const EvaluatedValue &total_incr_ev =
        evaluator_.getConstant(total_chain_increment_);
    return evaluator_.evaluateSum(ev_sum_with_burst, total_incr_ev);
  }

