void e593_initializeDescriptor()
{
  Value &base_addr = getOriginalBaseAddrSSA();
  BaseAddrListTy &base_addrs = getBaseAddrList();

  while (auto copy_op =
             dyn_cast_or_null<sentient::CopyOp>(base_addr.getDefiningOp()))
    base_addr = copy_op.getInp();

  // If base addr is a symbol or a query map of symbols, don't initialize and
  // return.
  if (dcc::utils::isSymbol(base_addr)) {
    pattern_desc_ = nullptr;
    return;
  }

  // Two cases resulting in a SimpleConstantDescriptor:
  // 1. base_addr is constant (either ConstantOp or QueryMapOp with constant
  // values)
  // 2. base_addr = scalar_add %c1, %c2 where %c2 is a ConstantOp and %c1 is
  // either a ConstantOp or the end of a chain of CopyOps beginning with a
  // ConstantOp.
  if (dcc::utils::isConstant<sentient::ConstantOp>(base_addr)) {
    const EvaluatedValue &base_addr_ev = evaluator_.evaluateValue(base_addr);
    base_addrs.push_back(&base_addr_ev);
    auto sc_desc = new SimpleConstantDescriptor(evaluator_, base_addr_ev);
    pattern_desc_ = sc_desc;
    LLVM_DEBUG(sc_desc->dump());
    return;
  }

  if (auto add_op =
          dyn_cast_or_null<sentient::AddOp>(base_addr.getDefiningOp())) {
    if (dcc::utils::isConstant<sentient::ConstantOp>(add_op.getInp2())) {
      const EvaluatedValue &right_summand_ev =
          evaluator_.evaluateValue(add_op.getInp2());
      Value left_summand = add_op.getInp1();
      while (auto copy_op = dyn_cast_or_null<sentient::CopyOp>(
                 left_summand.getDefiningOp()))
        left_summand = copy_op.getInp();
      if (dcc::utils::isConstant<sentient::ConstantOp>(left_summand)) {
        const EvaluatedValue &left_summand_ev =
            evaluator_.evaluateValue(left_summand);
        // left_summand + right_summand
        const EvaluatedValue &sum_ev =
            evaluator_.evaluateSum(left_summand_ev, right_summand_ev);
        base_addrs.push_back(&sum_ev);
        auto sc_desc = new SimpleConstantDescriptor(evaluator_, sum_ev);
        pattern_desc_ = sc_desc;
        LLVM_DEBUG(sc_desc->dump());
        return;
      }
    }
  }

  // Otherwise, try to fit the pattern into one of:
  // IntegerSequenceDescriptor, DiscreteIntegerSetDescriptor,
  // LoopingChainMutableAddrDescriptor, ConditionalConstantDescriptor, or
  // ToggleDescriptor.
  // Note: If this data transfer is part but not head of a looping chain and
  // is_base_addr_mutable_ is true then it will not end up with a valid pattern
  // descriptor.
  // Note: LoadAndExtractScalarOp ignored as it is not supported outside LX.
  if (isa<BlockArgument>(base_addr)) {
    auto isq_desc = new IntegerSequenceDescriptor(evaluator_, base_addr);
    pattern_desc_ = isq_desc;
    if (isq_desc->isValid()) {
      isq_desc->getAllConstants(base_addrs);
      if (isq_desc->canBeSimplified()) {
        DT_CHECK(base_addrs.size() == 1);
        LLVM_DEBUG(llvm::dbgs() << "Found a fake integer sequence base addr "
                                   "and simplified it to a simple constant.\n");
      }
      LLVM_DEBUG(isq_desc->dump());
      return;
    }
    LLVM_DEBUG(
        llvm::dbgs()
        << "block argument base_addr not recognized as integer sequence!\n");
    delete isq_desc;
    auto dis_desc = new DiscreteIntegerSetDescriptor(evaluator_, base_addr);
    pattern_desc_ = dis_desc;
    if (dis_desc->isValid()) {
      base_addrs.push_back(&dis_desc->getInit());
      if (dis_desc->canBeSimplified()) {
        LLVM_DEBUG(llvm::dbgs()
                   << "Found a fake discrete integer set base addr "
                      "and simplified it to a simple constant.\n");
      }
      LLVM_DEBUG(dis_desc->dump());
      return;
    }
    delete dis_desc;
    if (is_base_addr_mutable_) {
      auto lcma_desc = new LoopingChainMutableAddrDescriptor(
          evaluator_, base_addr, op_,
          dcc::utils::getMutableAddrResultIndex(op_, getMemoryUnit()));
      pattern_desc_ = lcma_desc;
      if (lcma_desc->isValid()) {
        base_addrs.push_back(&lcma_desc->getInit());
        if (lcma_desc->canBeSimplified()) {
          LLVM_DEBUG(llvm::dbgs()
                     << "Found a looping chain mutable address "
                        "and simplified it to a simple constant.\n");
        }
        LLVM_DEBUG(lcma_desc->dump());
        DT_CHECK(isValid() && pattern_desc_ &&
                 isa<const LoopingChainMutableAddrDescriptor>(pattern_desc_));
        return;
      }
      delete lcma_desc;
    }
    pattern_desc_ = nullptr;
  } else if (isa<sentient::ReceiveAndStoreOp, sentient::LoadAndSendOp,
                 sentient::LoadAndStoreOp, sentient::ForOp>(
                 base_addr.getDefiningOp())) {
    DT_CHECK_MSG(is_base_addr_mutable_,
                 "Do not expect memory op result as immutable addr");
    LLVM_DEBUG(llvm::dbgs()
               << "Part of chain. No pattern descriptor created.\n");
    return;
  } else if (HandleConditionalConstants &&
             isa<sentient::IfOp>(base_addr.getDefiningOp())) {
    auto cc_desc = new ConditionalConstantDescriptor(evaluator_, base_addr);
    pattern_desc_ = cc_desc;
    if (cc_desc->isValid()) {
      cc_desc->getAllConstants(base_addrs);
      if (cc_desc->canBeSimplified()) {
        DT_CHECK(base_addrs.size() == 1);
        LLVM_DEBUG(llvm::dbgs()
                   << "Found a fake conditional constant base addr "
                      "and simplified it to a simple constant.\n");
      }
      LLVM_DEBUG(cc_desc->dump());
      return;
    } else {
      LLVM_DEBUG(llvm::dbgs() << "Conditional base_addr not recognized as a "
                                 "conditional all-constant pattern!\n");
      delete cc_desc;
      pattern_desc_ = nullptr;
    }
  }

  auto toggle_desc = new ToggleDescriptor(evaluator_, base_addr);
  if (AssertOnUnexpectedPatterns)
    DT_CHECK(toggle_desc->isValid());
  else if (!toggle_desc->isValid()) {
    LLVM_DEBUG(llvm::dbgs() << "Skipping due to invalid toggle!\n");
    delete toggle_desc;
    return;
  }
  pattern_desc_ = toggle_desc;

  // In case of fake toggle, we simplify it by storing only one base addr.
  base_addrs.push_back(&toggle_desc->getX());
  if (toggle_desc->canBeSimplified())
    LLVM_DEBUG(llvm::dbgs()
               << "Found a fake toggle and simplified it to a non-toggle.\n");
  else
    base_addrs.push_back(&toggle_desc->getY());
  return;
}

