// entry 595/656   level 5   scc 156   30 body lines
// unit: e595_deuniform
// authority: dcc/src/Transform/Sentient/Deuniform.cpp:448
// original: std::vector<mlir::dataflow::ProgramUnitOp> DeuniformPass::deuniform( mlir::dataflow::ProgramUnitOp prog_unit, std::vector<std::vector<mlir::dataflow::GetUnitOp>> &set_of_unit_collection)
// rust home: crates/compiler/deeptools/src/transform/sentient/deuniform/mod.rs
// ------------------------------------------------------------------------------------------------
std::vector<mlir::dataflow::ProgramUnitOp> e595_deuniform(
    mlir::dataflow::ProgramUnitOp prog_unit,
    std::vector<std::vector<mlir::dataflow::GetUnitOp>>
        &set_of_unit_collection)
{
  std::vector<mlir::dataflow::ProgramUnitOp> deuniformed_prog_units;
  std::vector<mlir::dataflow::GetUnitOp> units_in_collection, rest_of_units;
  for (auto &unit_ops : set_of_unit_collection) {
    for (auto &unit_op : unit_ops) {
      if (std::find(units_in_collection.begin(), units_in_collection.end(),
                    unit_op) == units_in_collection.end()) {
        units_in_collection.push_back(unit_op);
      } else {
        prog_unit.emitError("duplication in list of unit collections");
        signalPassFailure();
        return deuniformed_prog_units;
      }
    }
  }
  for (auto unit_v : prog_unit.getUnits()) {
    auto unit_op = unit_v.getDefiningOp<mlir::dataflow::GetUnitOp>();
    DT_CHECK(unit_op);
    if (std::find(units_in_collection.begin(), units_in_collection.end(),
                  unit_op) == units_in_collection.end())
      rest_of_units.push_back(unit_op);
  }
  if (rest_of_units.size() > 0) {
    set_of_unit_collection.push_back(rest_of_units);
  }
  for (auto &units : set_of_unit_collection)
    deuniformed_prog_units.push_back(deuniform(prog_unit, units));

  return deuniformed_prog_units;
}

