// ------------------------------------------------------------------------------------------------
void e601_runOn(ModuleOp module_op)
{
  llvm::SmallVector<dataflow::ProgramUnitOp> unit_list;
  module_op->walk<WalkOrder::PreOrder>([&](dataflow::ProgramUnitOp unit) {
    InstructionEstimator &instruction_estimator =
        getChildAnalysis<InstructionEstimator>(unit);
    if (opts_.OptLevel == 0 &&
        instruction_estimator.haveIbuffSpace(dccExtContext(), unit)) {
      return;
    }
    unit_list.push_back(unit);
  });
  for (dataflow::ProgramUnitOp unit : unit_list) runLoopMerging(unit);
}

