// original: bool LoopPeelingManager::findCandidates(sentient::ForOp for_op)
// rust home: crates/compiler/deeptools/src/transform/sentient/multi_dim_loop_peeling/loop_peeling_manager.rs
// ------------------------------------------------------------------------------------------------
bool e604_findCandidates(sentient::ForOp for_op)
{
  LLVM_DEBUG(llvm::dbgs() << "Search for candidates inside:\n"
                          << for_op << "\n");
  DT_CHECK_MSG(loop_to_peeling_type_.empty(), "Expecting empty list");

  // Analyze every condition within for_op.
  for_op->walk<WalkOrder::PostOrder>([&](sentient::IfOp if_op) {
    // Determine the peeling info from if_op's comparison.
    sentient::ForOp inner_for_op = nullptr;
    PeelingType p_type = PeelingType::kNoPeeling;
    std::tie(inner_for_op, p_type) = computePeelingInfo(if_op);
    LLVM_DEBUG(llvm::dbgs() << "Analyzing condition:\n");
    LLVM_DEBUG(llvm::dbgs() << if_op << "\n");
    if (!inner_for_op || p_type == PeelingType::kNoPeeling) {
      // If the comparison is not between an iv of a ForOp and its first
      // or last iteration or that ForOp has iter args, ignore it.
      LLVM_DEBUG(llvm::dbgs().indent(2)
                 << "Not a peeling opportunity. Skip.\n");
      return WalkResult::advance();
    }

    LLVM_DEBUG(llvm::dbgs().indent(2)
               << "Is a peeling opportunity: " + stringifyPeelingType(p_type) +
                      "\n");
    insertOrUpdatePeelingType(inner_for_op, p_type);
    return WalkResult::advance();
  });

  return (!loop_to_peeling_type_.empty());
}

