    Liveness liveness00 = liveness_;
    liveness00.updateLiveRangesForProgramHeaderPromotion(copy_op);
    SentientRegType locale = sentient::getValueRegLocale(copy_op);
    gc.buildGraphs(dcc_ext_ctx_, liveness00, unit_, locale);
    gc.createSameColorEdgeEqClasses(liveness00, locale);
    gc.buildHyperGraph(locale);
