      auto [pop, coreunit] = dcc::utils::getUniformationOpAndRegionIterArg(
          nullptr, use.getOwner());
      uniform::UniformizeRegionsOp uniform_op =
          dyn_cast<uniform::UniformizeRegionsOp>(pop);
