        std::optional<int> region_idx_opt =
            dcc::uniform::utils::getRegionIndexForUnit(uniform_op,
                                                       uvs.units()[index]);
        DT_CHECK(region_idx_opt.has_value());
        auto region_idx = region_idx_opt.value();
        auto &region = uniform_op.getRegion(region_idx);
        auto op = use.getOwner();
