// ------------------------------------------------------------------------------------------------
void e607_runOnOperation()
{
  if (DisableThisPass) return;
  ModuleOp module_op = getOperation();
  module_op.walk<WalkOrder::PostOrder>([&](dataflow::ProgramUnitOp unit_op) {
    InstructionEstimator &instruction_estimator =
        getChildAnalysis<InstructionEstimator>(unit_op);
    if (opts_.OptLevel == 0 &&
        instruction_estimator.haveIbuffSpace(dccExtContext(), unit_op)) {
      return;
    }
    runOpRerolling(unit_op, true);
  });
}

