// entry 608/656   level 5   scc 391   37 body lines
// unit: e608_buildGraphEdges
// authority: dcc/src/Transform/Sentient/PortAssignment.cpp:644
// original: void PortAssignmentPass::buildGraphEdges(dataflow::ProgramUnitOp &unit)
// rust home: crates/compiler/deeptools/src/transform/sentient/port_assignment/mod.rs
// ------------------------------------------------------------------------------------------------
void e608_buildGraphEdges(dataflow::ProgramUnitOp &unit)
{
  computePortLiveRange(unit);
  for (auto &record1 : operand_to_liverange_) {
    for (auto &record2 : operand_to_liverange_) {
      if (record1.getSecond().overlaps(record2.getSecond(),
                                       /*half_open_range=*/false)) {
        auto node1_idx = record1.getFirst();
        auto node2_idx = record2.getFirst();
        if (std::find(dummy_nodes_.begin(), dummy_nodes_.end(), node1_idx) !=
                dummy_nodes_.end() &&
            std::find(dummy_nodes_.begin(), dummy_nodes_.end(), node2_idx) !=
                dummy_nodes_.end()) {
          continue;
        }
        if (node1_idx != node2_idx &&
            std::find(reuse_nodes_.begin(), reuse_nodes_.end(), node1_idx) !=
                reuse_nodes_.end() &&
            std::find(reuse_nodes_.begin(), reuse_nodes_.end(), node2_idx) !=
                reuse_nodes_.end()) {
          for (auto op1 : operand_to_owners_[node1_idx]) {
            for (auto op2 : operand_to_owners_[node2_idx]) {
              if (op1 == op2) {
                reuse_nodes_per_op_.push_back({node1_idx, node2_idx});
                break;
              }
            }
          }
        }
        port_assignment_graph_.getOrAddNode(node1_idx);
        port_assignment_graph_.getOrAddNode(node2_idx);
        if (node1_idx != node2_idx) {
          port_assignment_graph_.addBidirectionalEdge(node1_idx, node2_idx);
        }
      }
    }
  }
}

