// original: void RegisterTypeAssignmentPass::runOn(dataflow::ProgramUnitOp unit)
// rust home: crates/compiler/deeptools/src/transform/sentient/register_type_assignment/mod.rs
// ------------------------------------------------------------------------------------------------
void e609_runOn(dataflow::ProgramUnitOp unit)
{
  if (!worklist_.empty()) {
    llvm::errs() << "Register type assignment internal worklist "
                    "is not empty before processing a unit";
    signalPassFailure();
  }

  // Assing local class variables.
  current_unit_ = unit;
  current_unit_type_ = dcc::getUnitType(
      current_unit_.getUnits()[0].getDefiningOp<dataflow::GetUnitOp>());

  // Main steps involved in the overall algorithm
  //  Initialize the worklist with assignment of regTypes to SSA variables
  //  that are known ahead and doesn't require propagation.
  initializeWorkList();

  // With the items in worklist, keep propagating their registerTypes to
  // parent operations and update their locales/types if needed.
  // Iterate till you reach the fixed point, i.e., no more entries in
  // the worklist.
  processWorkList();

  // printAssignments();

  // After the propagation is done, assign the register types to the operations
  // in the IR.
  updateProgramUnit();

  // update function level operations
  // GetUnitOps used in YieldOps need to have a locale associated to them so
  // the correct assign instruction can be inserted.
  if (is_any_of(current_unit_type_, L3LU, L3SU)) {
    for (auto get_unit_op :
         unit->getParentOfType<func::FuncOp>().getOps<dataflow::GetUnitOp>()) {
      if (get_unit_op->getUses().empty()) continue;
      if (assignments_.find(get_unit_op.getResult(0)) == assignments_.end())
        continue;
      // look for a use that belongs to the current unit and is a yield or copy
      // op.
      if (llvm::none_of(get_unit_op->getUses(), [&](OpOperand& use) {
            return (use.getOwner()
                        ->getParentOfType<dataflow::ProgramUnitOp>() == unit) &&
                   isa<YieldOp, CopyOp, uniform::DefImmutableMappingOp>(
                       use.getOwner());
          }))
        continue;
      auto locale = SentientRegTypeAttr::get(
          get_unit_op->getContext(),
          symbolizeSentientRegType(getLocaleAsString(get_unit_op.getResult(0)))
              .value());
      get_unit_op->setAttr(sentient::getRegLocaleAttrStrName(), locale);
    }
  }
}

