// entry 610/656   level 5   scc 472   17 body lines
// unit: e610_runOnOperation
// authority: dcc/src/Transform/Sentient/ScalarCopyInsertionForSymbols.cpp:130
// original: void ScalarCopyInsertionForSymbolsPass::runOnOperation()
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_copy_insertion_for_symbols/mod.rs
// ------------------------------------------------------------------------------------------------
void e610_runOnOperation()
{
  if (DisableThisPass) return;
  if (opts_.OptLevel == 0 || opts_.OptLevel == 1) return;
  mlir::ModuleOp module_op = getOperation();
  module_op->walk<WalkOrder::PreOrder>([&](Operation *op) {
    if (auto create_sym = dyn_cast<symbol::CreateSymbolOp>(op)) {
      // we should see all symbols before program_unit ops due to the
      // pre-order traversal.
      symbols_.push_back(create_sym->getResult(0));
    } else if (auto unit = dyn_cast<dataflow::ProgramUnitOp>(op)) {
      runOn(unit);
      clear();
      return WalkResult::skip();
    }
    return WalkResult::advance();
  });
}

