void e611_runScalarOpMerging()
{
  collectBlocks();
  if (blocks_.empty()) return;

  // Order blocks with respect to their benefit vs IBuff impact and mark
  // operations in the blocks for Field Unrolling.
  markFieldUnrollingCandidates();

  for (auto &block : blocks_) doScalarOpMerging(block);
}

