// original: bool ScalarOpHoisting::processForLinearChain(BlockArgument &main_iv, Operation *derived_iv)
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_hoisting.rs
// ------------------------------------------------------------------------------------------------
bool e612_processForLinearChain(BlockArgument &main_iv,
                                             Operation *derived_iv)
{
  if (!is_any_of(getComp(), LXLU, LXSU, L0LU, L0SU)) {
    LLVM_DEBUG(llvm::dbgs() << "[ScalarOpHoisting] Skipping Linear Chain "
                               "Hoisting - only support in LX/L0\n");
    return false;
  }
  LLVM_DEBUG(
      llvm::dbgs() << "[ScalarOpHoisting] Attempting Linear Chain Hoisting\n");

  if (!derived_iv->hasOneUse() || !main_iv.hasOneUse()) return false;
  auto main_yield = for_op_->getBody()->getTerminator();
  // The index of the main IV iter_arg adjusted to match yield operands.
  int main_iv_idx = main_iv.getArgNumber() - 1;

  int const_operand_idx = dcc::utils::getFirstConstOperandIndex(derived_iv);

  // If the derived_iv is a SubOp, it should be in the form
  // derived_iv = B - constant. If it is a SubOp, adjust the offset_adjustment
  // so it matches the form derived_iv = B + (constant * -1).
  const EvaluatedValue *offset_adjustment =
      &getEvaluator().evaluateValue(derived_iv->getOperand(const_operand_idx));
  if (isa<sentient::SubOp>(derived_iv)) {
    if (const_operand_idx == 0) return false;
    offset_adjustment =
        &getEvaluator().evaluateMultiplyByConst(*offset_adjustment, -1);
  }

  // Track if the first composite load/store in the chain has been encountered.
  // The first composite load/store Operation in the linear chain will require
  // different update rules than others since it will absorb the add for the
  // chain.
  bool first_comp_op_found = false;

  // Store the comp ops and track the value the increment should have after
  // transformation.
  SmallVector<OperationData> comp_ops;

  Operation *op = *derived_iv->getUsers().begin();
  Operation *prev_op = derived_iv;
  while (op) {
    // If the current operation matches the yield, the end of the chain has been
    // reached as long as the yield operand matching the main_iv index is the
    // last op in the chain.
    if (op == main_yield) {
      if (op->getOperand(main_iv_idx) == prev_op->getResult(0)) break;
      return false;
    }
    if (!op->hasOneUse()) return false;

    // Operations are analyzed through use chains. To minimize complexity, only
    // analyze Operations in the same Region.
    if (op->getParentRegion()->getParentOp() != *for_op_) return false;

    if (isa<sentient::LoadAndSendOp, sentient::ReceiveAndStoreOp,
            sentient::LoadComputeAndSendOp>(op)) {
      MemoryOpInfo mem_info(op);

      if (!dcc::utils::isConstant<sentient::ConstantOp>(
              mem_info.immutable_addr_))
        return false;
      const EvaluatedValue *immutable_addr_ev =
          &getEvaluator().evaluateValue(mem_info.immutable_addr_);

      if (mem_info.mutable_addr_.getDefiningOp() != prev_op) return false;

      // Memory operations with non-zero increment attributes would have
      // been handled in processForDerivedIVElimination().
      if (dcc::utils::isUpdateMode(op)) return false;

      // Calculate what the value of the increment should be after hoisting.
      if (!first_comp_op_found) {
        // If this is the first composite op in the chain, it's increment will
        // swap with the merging candidate to absorb the effect of the scalar op
        // for the rest of the chain. This composite op increment attribute
        // will later be updated appropriately.
        if (mem_info.burst_ > 1 || mem_info.il_ > 1) return false;

        // Check if offset_adjustment will fit in the IMM field (or LRF field if
        // it was already out of IMM range). If not, cannot hoist.
        if (!opt_context_.isImmutableValueInRange(*offset_adjustment,
                                                  *immutable_addr_ev,
                                                  mem_info.element_size_, op)) {
          return false;
        }

        comp_ops.push_back(
            {op, offset_adjustment, &getEvaluator().getConstant(0), true});
        immutable_addr_ev =
            &getEvaluator().evaluateMultiplyByConst(*immutable_addr_ev, -1);
        offset_adjustment = immutable_addr_ev;
        first_comp_op_found = true;
      } else {
        // Check if the new immutable will fit in the IMM field. If not, cannot
        // hoist.
        const EvaluatedValue &new_immutable_ev =
            getEvaluator().evaluateSum(*immutable_addr_ev, *offset_adjustment);
        // Check if offset_adjustment will fit in the IMM field (or LRF field if
        // it was already out of IMM range). If not, cannot hoist.
        if (!opt_context_.isImmutableValueInRange(new_immutable_ev,
                                                  *immutable_addr_ev,
                                                  mem_info.element_size_, op)) {
          return false;
        }

        comp_ops.push_back(
            {op, offset_adjustment, &getEvaluator().getConstant(0)});
      }

      prev_op = op;
      op = *op->getUsers().begin();
    } else
      return false;
  }

  if (comp_ops.empty()) return false;

  // When the merging candidate scalar op is hoisted out of the candidate ForOp,
  // the result of the candidate ForOp will need to be adjusted by the opposite
  // of the merging increment. If it is not possible or profitable to do so,
  // hoisting should not be done.
  if (!adjustCandidateForOpResult(main_iv, *offset_adjustment)) return false;

  hoistForLinearChain(main_iv, derived_iv, comp_ops);

  ++num_hoists_executed_per_unit;
  LLVM_DEBUG(
      llvm::dbgs() << "[ScalarOpHoisting] Completed Linear Chain Hoisting\n");
  return true;
}

