// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_hoisting.rs
// ------------------------------------------------------------------------------------------------
bool e613_processForGenericHoisting(BlockArgument &main_iv,
                                                 Operation *derived_iv)
{
  LLVM_DEBUG(
      llvm::dbgs() << "[ScalarOpHoisting] Attempting Generic Hoisting\n");

  int const_operand_idx = dcc::utils::getFirstConstOperandIndex(derived_iv);

  // If the derived_iv is a SubOp, it should be in the form
  // derived_iv = B - constant. If it is a SubOp, modify the adjustment so
  // it matches the form derived_iv = B + (constant * -1).
  Value derived_iv_operand = derived_iv->getOperand(const_operand_idx);
  const EvaluatedValue *adjustment =
      &getEvaluator().evaluateValue(derived_iv_operand);
  if (isa<sentient::SubOp>(derived_iv)) {
    if (const_operand_idx == 0) return false;
    adjustment = &getEvaluator().evaluateMultiplyByConst(*adjustment, -1);
  }

  // There needs to be an operation feeding the yield that can absorb the
  // required adjustments from hoisting.
  auto main_yield = for_op_->getBody()->getTerminator();
  // The index of the main IV iter_arg adjusted to match yield operands.
  int main_iv_idx = main_iv.getArgNumber() - 1;
  auto op_feeding_yield = main_yield->getOperand(main_iv_idx).getDefiningOp();
  if (!op_feeding_yield) return false;

  int const_idx = dcc::utils::getFirstConstOperandIndex(op_feeding_yield);
  if (const_idx == -1) return false;

  // Update the yield result. If the op feeding the yield is a sub and its first
  // operand is the constant, the adjustment will need to be applied with the
  // opposite sign.
  SmallVector<OperationData> ops_to_update;
  if (isa<sentient::SubOp>(op_feeding_yield) && const_idx == 0) {
    ops_to_update.push_back(
        {op_feeding_yield,
         &getEvaluator().evaluateMultiplyByConst(*adjustment, -1),
         &getEvaluator().getConstant(0)});
  } else if (isa<sentient::AddOp>(op_feeding_yield))
    ops_to_update.push_back(
        {op_feeding_yield, adjustment, &getEvaluator().getConstant(0)});
  else
    return false;

  // If the add or sub feeding the yield of the candidate loop has multiple
  // users, the other users need to be mergeable operations/chains. They will
  // need to be modified by the value opposite the constant value of the
  // derived_iv.
  for (auto user : op_feeding_yield->getUsers()) {
    if (user == main_yield) continue;

    if (!isMergeableOpOrChain(op_feeding_yield, user)) return false;
    ops_to_update.push_back(
        {user, &getEvaluator().evaluateMultiplyByConst(*adjustment, -1),
         &getEvaluator().getConstant(0)});
  }

  // Every other use of the main_iv will need to be adjusted once the derived_iv
  // is hoisted. It will be adjusted by the value opposite the constant value of
  // the derived_iv.
  for (auto user : main_iv.getUsers()) {
    if (user == derived_iv) continue;
    ops_to_update.push_back(
        {user, &getEvaluator().evaluateMultiplyByConst(*adjustment, -1),
         &getEvaluator().getConstant(0)});
  }

  // Verify the result of the candidate ForOp can be absorbed/ignored or that
  // there is enough IBUFF to create an add operation to adjust it.
  if (!adjustCandidateForOpResult(
          main_iv, getEvaluator().evaluateMultiplyByConst(*adjustment, -1)))
    return false;

  // Hoist the derived_iv out of the loop and apply the modifications to the
  // operations.
  applyOperationData(ops_to_update);
  hoistCandidateOutOfLoop(main_iv, derived_iv, derived_iv_operand);

  ++num_hoists_executed_per_unit;
  LLVM_DEBUG(llvm::dbgs() << "[ScalarOpHoisting] Completed Generic Hoisting\n");
  return true;
}

