// authority: dcc/src/Transform/Sentient/AddressPinningAndToggle.cpp:1675
// original: void AddressPinningAndTogglePass::computeAddressInfoList(SenComponents comp)
// rust home: crates/compiler/deeptools/src/transform/sentient/address_pinning_and_toggle/mod.rs
// ------------------------------------------------------------------------------------------------
void e614_computeAddressInfoList(SenComponents comp)
{
  auto &sys_def = dccExtContext().dsc_global_->sysDef;
  unsigned kBitWidthOfMutAddrRegister =
      sys_def.regInfoPerUnit.at(comp).at(RegType::EAR).bitSize;
  AddrTy max_mut_addr_val =
      (0x1 << kBitWidthOfMutAddrRegister) * sys_def.bytesPerStick;

  DEBUG_WITH_TYPE(VerboseDebug, llvm::dbgs()
                                    << "Printing immutable addr, min mutable "
                                       "addr, max mutable addr values:\n");
  for (auto pair : llvm::zip(immut_data_transfer_descriptors_.getSortedList(),
                             mut_data_transfer_descriptors_.getSortedList())) {
    auto immut_dtd = std::get<0>(pair);
    auto mut_dtd = std::get<1>(pair);
    const EvaluatedValue *min_mut_addr_ev = nullptr;
    const EvaluatedValue *max_mut_addr_ev = nullptr;
    if (mut_dtd->isValid()) {
      min_mut_addr_ev = &mut_dtd->getMin();
      max_mut_addr_ev = &mut_dtd->getMax();
    } else if (immut_data_transfer_descriptors_.isPartOfSomeChain(*immut_dtd) &&
               !immut_data_transfer_descriptors_.isHeadOfChain(*immut_dtd)) {
      // Nothing to do, as the increment of this data transfer is tracked in
      // the chain's head.
      continue;
    } else {
      LLVM_DEBUG(immut_dtd->getOperation().emitWarning(
          "The HBM transfer that does not fall into one of the "
          "recognized mutable address patterns so conservatively "
          "setting min, max values to 0, maxEAR respectively."));
      min_mut_addr_ev = &evaluator_.getConstant(0);
      max_mut_addr_ev = &evaluator_.getConstant(max_mut_addr_val);
    }
    for (const EvaluatedValue *immut_addr_ev : immut_dtd->getBaseAddrList()) {
      int elem_size = dcc::sentient::utils::getElementSizeOfMemOp(
          immut_dtd->getOperation());
      // Convert to byte-addressable EvaluatedValues by multiplying by
      // elem_size and dividing by 8.
      const EvaluatedValue &ba_immut_addr_ev = evaluator_.evaluateDivideByConst(
          evaluator_.evaluateMultiplyByConst(*immut_addr_ev, elem_size), 8);
      const EvaluatedValue &ba_min_mut_addr_ev =
          evaluator_.evaluateDivideByConst(
              evaluator_.evaluateMultiplyByConst(*min_mut_addr_ev, elem_size),
              8);
      const EvaluatedValue &ba_max_mut_addr_ev =
          evaluator_.evaluateDivideByConst(
              evaluator_.evaluateMultiplyByConst(*max_mut_addr_ev, elem_size),
              8);
      DEBUG_WITH_TYPE(VerboseDebug,
                      llvm::dbgs()
                          << "ba_immut_addr_ev: " << ba_immut_addr_ev
                          << "\nmin_addr_ev: " << ba_min_mut_addr_ev
                          << "\nmax_addr_ev: " << ba_max_mut_addr_ev << "\n\n");
      bool is_toggle = immut_dtd->isToggle();
      ev_addr_info_list_.push_back(DynamicPinningSchemeManager::EVAddressInfo(
          &ba_immut_addr_ev, &ba_max_mut_addr_ev, is_toggle,
          immut_dtd->getRegionOp(), immut_dtd->getRegionNum()));
    }
  }
}

