// ------------------------------------------------------------------------------------------------
void e621_runOnOperation()
{
  ModuleOp module_op = getOperation();
  std::vector<mlir::Operation *> to_be_deleted;
  module_op.walk([&](dataflow::ProgramUnitOp prog_unit_op) {
    std::vector<mlir::dataflow::ProgramUnitOp> new_prog_unit_ops;
    std::vector<std::vector<dataflow::GetUnitOp>> new_units;
    if (DeuniformaionSize == Deuniformaion::Full) {
      for (auto unit : prog_unit_op.getUnits()) {
        auto unit_op =
            llvm::dyn_cast<dataflow::GetUnitOp>(unit.getDefiningOp());
        DT_CHECK(unit_op);
        new_units.push_back({unit_op});
      }
    } else {
      prog_unit_op.walk([&](mlir::Operation *op) {
        if (isa<uniform::UniformizeRegionsOp, uniform::EqualizePatternOp>(op)) {
          for (int region_idx = 0; region_idx < op->getNumRegions();
               region_idx++) {
            std::vector<mlir::Value> units_of_region =
                dcc::uniform::utils::getUnitsOfRegion(op, region_idx);
            dcc::uniform::utils::expandAllGroupsToUnits(units_of_region);
            std::vector<dataflow::GetUnitOp> unit_op_of_region;
            for (auto unit : units_of_region) {
              auto unit_op =
                  llvm::dyn_cast<dataflow::GetUnitOp>(unit.getDefiningOp());
              DT_CHECK(unit_op);
              if (!existsInCollection(unit_op, new_units))
                unit_op_of_region.push_back(unit_op);
            }
            if (unit_op_of_region.size() > 0)
              new_units.push_back(unit_op_of_region);
          }
        }
      });
    }
    new_prog_unit_ops = deuniform(prog_unit_op, new_units);
    for (auto new_prog_unit_op : new_prog_unit_ops)
      simplifyProgramUnitOp(new_prog_unit_op);
    to_be_deleted.push_back(prog_unit_op);
  });
  for (auto op : to_be_deleted) op->erase();
}

