// ------------------------------------------------------------------------------------------------
void e633_runOnOperation()
{
    if (DisableThisPass) return;
    mlir::ModuleOp module_op = getOperation();
    for (auto func : module_op.getOps<mlir::func::FuncOp>()) {
      for (auto const_op : func.getOps<sentient::ConstantOp>()) {
        initializeAssignmentForAnOperation(const_op);
      }
      for (auto sym_op : func.getOps<symbol::CreateSymbolOp>()) {
        initializeAssignmentForAnOperation(sym_op);
      }
      for (auto get_unit_op : func.getOps<dataflow::GetUnitOp>()) {
        initializeAssignmentForAnOperation(get_unit_op);
      }
    }
    module_op->walk<WalkOrder::PreOrder>(
        [&](dataflow::ProgramUnitOp unit) { runOn(unit); });
  }

