// entry 635/656   level 6   scc 505   61 body lines
// unit: e635_runScalarOpHoisting
// authority: dcc/src/Transform/Sentient/ScalarOpMergingAndHoisting.cpp:2184
// original: void ScalarOpHoisting::runScalarOpHoisting()
// rust home: crates/compiler/deeptools/src/transform/sentient/scalar_op_merging_and_hoisting/scalar_op_hoisting.rs
// ------------------------------------------------------------------------------------------------
void e635_runScalarOpHoisting()
{
  // idx is manually manipulated in the loop. If a candidate is hoisted for the
  // current basic IV it may have created new opportunities so candidates for
  // the basic IV need to be evaluated again.
  for (auto idx = 0; idx < for_op_->getNumRegionIterArgs();) {
    // If the number of hoists was already hit, return.
    if (MaxHoists != -1 && num_hoists_executed_per_unit >= MaxHoists) return;

    auto iter_arg = for_op_->getRegionIterArgs()[idx];

    llvm::SmallVector<Operation *, 2> hoisting_candidates;
    for (Operation *main_iv_user : iter_arg.getUsers()) {
      // Hoisting candidates are adds or subs with one constant operand.
      if (isa<sentient::AddOp, sentient::SubOp>(main_iv_user) &&
          (dcc::utils::getFirstConstOperandIndex(main_iv_user) != -1)) {
        hoisting_candidates.push_back(main_iv_user);
      } else {
        hoisting_candidates.clear();
        break;
      }

      // If the parent is an IfOp, the user is not a candidate.
      if (isa<sentient::IfOp>(main_iv_user->getParentOp())) {
        hoisting_candidates.clear();
        break;
      }
    }

    // Going through the candidates one by one, trying to hoist. When a
    // candidate is successfully hoisted, recalculate candidates and users.
    bool reanalyze_candidates = false;
    for (auto hoisting_candidate : hoisting_candidates) {
      // If one of the users of the candidate is a YieldOp, the candidate cannot
      // be hoist because hoisting it would require adding an operation back to
      // adjust the yield op again.
      bool skip_candidate = false;
      for (auto candidate_user : hoisting_candidate->getUsers()) {
        if (isa<sentient::YieldOp>(candidate_user)) {
          skip_candidate = true;
          break;
        }
      }
      if (skip_candidate) continue;

      // Try to hoist the candidate. Order of analysis for hoisting is:
      // 1. Try to fully absorb the candidate into its users.
      // 2. Check for the special case where there is one candidate and it
      //    feeds a linear chain all the way to the yield of the candidate
      //    loop.
      // 3. Check if the candidate can be hoisted by other means.
      if (processForDerivedIVElimination(iter_arg, hoisting_candidate) ||
          processForLinearChain(iter_arg, hoisting_candidate) ||
          processForGenericHoisting(iter_arg, hoisting_candidate)) {
        reanalyze_candidates = true;
        break;
      }
    }

    if (!reanalyze_candidates) ++idx;
  }
}

