// entry 637/656   level 7   scc 61   41 body lines
// unit: e637_collectDataTransfers
// authority: dcc/src/Transform/Sentient/AddressPinningAndToggle.cpp:1395
// original: bool AddressPinningAndTogglePass::collectDataTransfers( SenComponents comp, Operation *op, SenComponents memory_unit, Operation *region_op, int region_num)
// rust home: crates/compiler/deeptools/src/transform/sentient/address_pinning_and_toggle/mod.rs
// ------------------------------------------------------------------------------------------------
bool e637_collectDataTransfers(
    SenComponents comp, Operation *op, SenComponents memory_unit,
    Operation *region_op, int region_num)
{
  // Note: LoadAndExtractScalarOp, LoadComputeAndSendOp are ignored as they are
  // not supported outside LX.
  if (!isa<sentient::LoadAndSendOp, sentient::ReceiveAndStoreOp,
           sentient::LoadAndStoreOp>(op))
    return false;
  if (memory_unit == HBM &&
      !isa<sentient::LoadAndSendOp, sentient::ReceiveAndStoreOp>(op)) {
    auto load_and_store = dyn_cast<LoadAndStoreOp>(op);
    if (dcc::getUnitType(load_and_store.getSrc().getDefiningOp()) == HBM) {
      int increment = llvm::dyn_cast<sentient::ConstantOp>(
                          load_and_store.getSrcInc().getDefiningOp())
                          .getValue();
      immut_data_transfer_descriptors_.insert(new HBMDataTransferDescriptor(
          comp, *op, evaluator_, /*is_base_addr_mutable*/ false, 0, region_op,
          region_num));
      mut_data_transfer_descriptors_.insert(new HBMDataTransferDescriptor(
          comp, *op, evaluator_, /*is_base_addr_mutable*/ true, increment,
          region_op, region_num));
      return true;
    } else if (dcc::getUnitType(load_and_store.getDst().getDefiningOp()) ==
               HBM) {
      int increment = llvm::dyn_cast<sentient::ConstantOp>(
                          load_and_store.getDstInc().getDefiningOp())
                          .getValue();
      immut_data_transfer_descriptors_.insert(new HBMDataTransferDescriptor(
          comp, *op, evaluator_, /*is_base_addr_mutable*/ false, 0, region_op,
          region_num));
      mut_data_transfer_descriptors_.insert(new HBMDataTransferDescriptor(
          comp, *op, evaluator_, /*is_base_addr_mutable*/ true, increment,
          region_op, region_num));
      return true;
    }
  } else if (memory_unit == LX) {
    immut_data_transfer_descriptors_.insert(new LXDataTransferDescriptor(
        comp, *op, evaluator_, region_op, region_num));
    return true;
  }

  return false;
}

