void e643_runOnOperation()
{
  if (DisableThisPass) return;
  ModuleOp module_op = getOperation();
  module_op.walk<WalkOrder::PreOrder>([&](dataflow::ProgramUnitOp unit_op) {
    dataflow::GetUnitOp get_unit_op = dyn_cast_or_null<dataflow::GetUnitOp>(
        unit_op.getUnits()[0].getDefiningOp());
    DT_CHECK_MSG(get_unit_op, "Cannot determine GetUnitOp!");

    auto unit_comp = dcc::getUnitType(get_unit_op);
    if (is_any_of(unit_comp, SFP, PE, PT)) {
      InstructionEstimatorImpl ie =
          getChildAnalysis<UnderEstimateInstructionEstimator>(unit_op);

      // A builder used for inserting ConstantOps
      OpBuilder const_builder(unit_op);

      dcc::LoopTree<sentient::ForOp, dataflow::ProgramUnitOp> loop_tree(
          unit_op);
      if (loop_tree.empty()) return;

      // Run LoopPeeling on each top-level loop.
      for (dcc::LoopNode *n = loop_tree.getRoot()->getFirstChild(); n;
           n = n->getNextSibling()) {
        if (auto for_op =
                llvm::dyn_cast_or_null<sentient::ForOp>(n->getOperation())) {
          LoopPeelingManager lpm(dcc_ext_ctx_, opts_, const_builder, ie,
                                 for_op);
          lpm.run();
        }
      }
    }
  });
  if (opts_.OptLevel == 0) markAnalysesPreserved<InstructionEstimator>();
}

