// ------------------------------------------------------------------------------------------------
void e645_runOnOperation()
{
  ModuleOp module_op = getOperation();
  module_op.walk([&](dataflow::ProgramUnitOp unit) {
    std::string unit_type =
        unit.getUnits()[0].getDefiningOp<dataflow::GetUnitOp>().getType().str();
    auto record = EnumsConversion::stringToSenComponents.find(unit_type);
    if (record != EnumsConversion::stringToSenComponents.end()) {
      if (EnumsConversion::senCompToGenericComp.at(record->second) == PT) {
        doPortAssignments(unit, PT);
      } else if (record->second == PE) {
        doPortAssignments(unit, PE);
      } else if (record->second == SFP) {
        doPortAssignments(unit, SFP);
      }
    } else {
      unit->emitError("Unknown unit for port assignment");
      signalPassFailure();
      return;
    }
  });
}

