// entry 647/656   level 8   scc 62   39 body lines
// unit: e647_CollectDataTransfersAndComputeMaxStreams
// authority: dcc/src/Transform/Sentient/AddressPinningAndToggle.cpp:1293
// original: void AddressPinningAndTogglePass::CollectDataTransfersAndComputeMaxStreams( dataflow::ProgramUnitOp unit, SenComponents comp, SenComponents memory_unit)
// rust home: crates/compiler/deeptools/src/transform/sentient/address_pinning_and_toggle/mod.rs
// ------------------------------------------------------------------------------------------------
void e647_CollectDataTransfersAndComputeMaxStreams(
    dataflow::ProgramUnitOp unit, SenComponents comp,
    SenComponents memory_unit)
{
  int common_transfers = 0;
  llvm::DenseMap<mlir::Value, int> per_unit_transfer_counts;
  unit->walk<WalkOrder::PreOrder>([&](Operation *op) {
    if (auto uniform_op =
            llvm::dyn_cast<mlir::uniform::UniformizeRegionsOp>(op)) {
      for (int i = 0; i < uniform_op.getNumRegions(); i++) {
        llvm::SmallVector<Value> units = uniform_op.getRegionUnitList(i);
        auto &region = uniform_op.getRegion(i);
        int region_transfers = 0;
        region.walk<WalkOrder::PreOrder>([&](Operation *oper) {
          if (collectDataTransfers(comp, oper, memory_unit, uniform_op, i)) {
            region_transfers++;
          }
        });

        for (auto tmp_unit : units) {
          per_unit_transfer_counts[tmp_unit] += region_transfers;
        }
      }

      return WalkResult::skip();
    }

    if (collectDataTransfers(comp, op, memory_unit, unit, 0)) {
      common_transfers++;
    }

    return WalkResult::advance();
  });

  int max_streams = 0;
  for (auto &entry : per_unit_transfer_counts) {
    max_streams = std::max(max_streams, entry.second + common_transfers);
  }
  if (per_unit_transfer_counts.empty()) max_streams = common_transfers;

  num_streams_ = max_streams;
}

