// rust home: crates/compiler/deeptools/src/transform/sentient/address_pinning_and_toggle/mod.rs
// ------------------------------------------------------------------------------------------------
void e653_processDataTransfer(
    DataTransferDescriptor &dtd, const PinningSchemeManager &ps_manager,
    mlir::MutableOperandRange mutable_addr,
    mlir::MutableOperandRange immutable_addr, uint32_t element_size)
{
  DT_CHECK(mutable_addr.size() == immutable_addr.size() &&
           mutable_addr.size() == 1);
  if (dtd.isToggle() && !dtd.canBeSimplified())
    processToggle(dtd, ps_manager, mutable_addr, immutable_addr, element_size);
  else if (dtd.isConditionalConstant() && !dtd.canBeSimplified())
    processConditionalConstant(dtd, ps_manager, mutable_addr, immutable_addr,
                               element_size);
  else if (dtd.isIntegerSequence() && !dtd.canBeSimplified())
    processIntegerSequence(dtd, ps_manager, mutable_addr, immutable_addr,
                           element_size);
  else if (!dtd.canBeSimplified() &&
           computeOrGetNumberOfStreams() <= ps_manager.getMaxNumRegisters() &&
           (ps_manager.getMemoryUnit() == HBM ||
            !dccExtContext().getProgStitch()) &&
           !ForceAddressPinning) {
    LLVM_DEBUG(llvm::dbgs()
               << "Skipping addr pinning for data transfer because number of "
                  "streams is "
                  "less than or equal to the number of available registers\n");
  } else if (dtd.isValid())
    processSimpleConstant(dtd, ps_manager, mutable_addr, immutable_addr,
                          element_size);
  else
    DT_CHECK_MSG(!AssertOnUnexpectedPatterns, "Unexpected pattern");
}

